INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('G36maid/ctf-arsenal/forensics-tools', 'forensics-tools', 'G36maid', 'ctf-arsenal', 'community', 'forensics-tools G36maid ctf-arsenal community The forensics-tools skill provides a CTF toolkit for agents with templates and scripts for exploitation, web security, and forensics. It benefits AI agents working with digital forensics and cybersecurity. Forensics-Tools是一款用于数字取证分析的工具包，提供文件分析、网络安全和加密技术等功能 Forensics-Toolsは、ファイル分析、ネットワークセキュリティ、暗号技術など、デジタルフォレンジック分析のためのツールキットです Forensics-Tools는 디지털 포렌식 분석을 위한 도구 키트로, 파일 분석, 네트워크 보안, 암호화 기술 등을 제공합니다 La habilidad de forensia digital ofrece plantillas y scripts para la explotación, seguridad web, ICS/SCADA, criptografía y forensia La compétence de forensique numérique propose des modèles et des scripts pour l''exploitation, la sécurité web, ICS/SCADA, la cryptographie et la forensique Die Fähigkeit der digitalen Forensik bietet Vorlagen und Skripte für die Ausnutzung, Web-Sicherheit, ICS/SCADA, Kryptographie und Forensik As ferramentas de forense são utilizadas para análise de arquivos suspeitos e extração de dados ocultos. Elas incluem binwalk para extração de arquivos incorporados. Инструменты форензики используются для анализа подозрительных файлов и извлечения скрытых данных. Они включают binwalk для извлечения встроенных файлов. تستخدم أدوات الفورينزية لتحليل الملفات المشبوهة واستخراج البيانات المخفية. تشمل أدوات مثل binwalk لاستخراج الملفات المضمنة. how to use forensics-tools forensics-tools setup guide digital forensics toolkit binwalk tutorial steganography detection tools network PCAP file analysis forensics-tools alternative forensics-tools install CTF toolkit for AI agents 数字取证 文件分析 网络安全 加密技术 Forensics-Tools Binwalk 高熵数据 文件签名 Extracts embedded files using Binwalk Analyzes network PCAP files for hidden data Detects steganography in images and audio files Scans for high-entropy data indicating encryption or compression Works with file signatures and magic bytes for identification Forensics-tools is a digital forensics toolkit for analyzing suspicious files, extracting hidden data, and detecting steganography, featuring tools like Binwalk for embedded file extraction.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('allthingslinux/atl.services/alerting-oncall', 'community', 'allthingslinux', 'atl.services', 'allthingslinux/atl.services', 'alerting-oncall', 0, 0, 65, '2026-03-08T01:57:15.418Z', '2026-03-08T02:07:19.906Z', 'e7db5397b5a0565df06c03eb8f341ed2e4afa2291c9db3d703578ab700520dac', '{"id":"allthingslinux/atl.services/alerting-oncall","name":"alerting-oncall","description":{"en":"The Alerting-OnCall skill helps developers configure alerting rules and thresholds, on-call rotations, and incident response workflows for production systems. It benefits developers and operations teams using monitoring systems like Prometheus and on-call platforms like PagerDuty.","zh":"Alerting-OnCall技能用于配置生产系统的有效警报和值班管理，包括设置警报规则和阈值、配置值班轮换和时间表等","ja":"Alerting-OnCallスキルは、プロダクションシステムの効果的なアラートとオンコール管理を設定するために使用され、包括的なアラートルールとしきい値の設定、オンコールローテーションとスケジュールの設定など","ko":"Alerting-OnCall 스킬은 생산 시스템의 효과적인 알림 및 근무 관리를 구성하는 데 사용되며, 알림 규칙 및閾値 설정, 근무轮換 및 일정 설정 등","es":"Configura reglas de alertas y umbrales para sistemas de producción con nuestra herramienta de alertas y llamadas","fr":"Configurez des règles d''alerte et des seuils pour les systèmes de production avec notre outil d''alerte et d''appel","de":"Konfigurieren Sie Alertregeln und Schwellenwerte für Produktionssysteme mit unserem Alerting- und On-Call-Tool","pt":"Configure alertas eficazes e gerencie escalas de plantão com nossa solução de alerting-oncall, compatível com Prometheus, Datadog e outras plataformas de monitoramento","ru":"Настройте эффективные оповещения и управляйте дежурствами с помощью нашего решения alerting-oncall, совместимого с Prometheus, Datadog и другими системами мониторинга","ar":"إعداد تنبيهات فعالة وإدارة خدمات الدوريات باستخدام حلنا alerting-oncall، المتوافق مع Prometheus وDatadog ومنصات مراقبة أخرى"},"seo":{"title":{"en":"Alerting-OnCall: Setup Guide for AI Agents","zh":"Alerting-OnCall Setup Guide - AIエージェント配置指南","ja":"Alerting-OnCall ベストプラクティス - AIエージェントの導入","ko":"Alerting-OnCall 구축 가이드 - AI 에이전트 설정","es":"Herramientas de alertas y llamadas: Guía de configuración","fr":"Outils d''alerte et d''appel: Meilleures pratiques","de":"Alerting- und On-Call-Tools: Einrichtungsleitfaden","pt":"Guia de Configuração de Alertas e Escalas de Plantão com ...","ru":"Настройка оповещений и дежурств с помощью ИИ Агентов","ar":"دليل إعداد تنبيهات وخدمات الدوريات باستخدام أدوات الذكاء ..."},"description":{"en":"Discover how to configure effective alerting and on-call management for production systems with Alerting-OnCall. Learn how to reduce alert fatigue and manage...","zh":"配置有效的警报和值班管理，减少警报疲劳，实现高效的事件响应工作流","ja":"効果的なアラートとオンコール管理を設定し、アラート疲労を減らし、インシデント対応ワークフローを最適化","ko":"효과적인 알림 및 근무 관리를 구성하고 알림 피로를 줄이며事件 응답 워크플로우를 최적화","es":"Configura sistemas de alertas y gestión de llamadas efectivos con nuestras herramientas de alertas y llamadas","fr":"Configurez des systèmes d''alerte et de gestion d''appel efficaces avec nos outils d''alerte et d''appel","de":"Richten Sie effektive Alerting- und On-Call-Systeme mit unseren Alerting- und On-Call-Tools ein","pt":"Aprenda a configurar alertas eficazes e gerenciar escalas de plantão com nossas ferramentas de IA, reduzindo a fadiga de alertas e melhorando a resposta a in...","ru":"Узнайте, как настроить эффективные оповещения и управлять дежурствами с помощью ИИ Агентов, снижая усталость от оповещений и улучшая реагирование на инциденты","ar":"تعرف على كيفية إعداد تنبيهات فعالة وإدارة خدمات الدوريات باستخدام أدوات الذكاء الاصطناعي، وتقليل إجهاد التنبيهات وتحسين استجابة الحوادث"},"definition":{"en":"Alerting-OnCall is a skill that enables effective alerting and on-call management for production systems, reducing alert fatigue and streamlining incident response workflows.","zh":"Alerting-OnCall是指配置生产系统的有效警报和值班管理，以确保事件响应工作流的高效运作","ja":"Alerting-OnCallは、プロダクションシステムの効果的なアラートとオンコール管理を設定することにより、インシデント対応ワークフローの効率的な運用を確保する","ko":"Alerting-OnCall은 생산 시스템의 효과적인 알림 및 근무 관리를 구성하여 이벤트 응답 워크플로우의 효율적인 운영을 보장","es":"Alertas y llamadas: tecnología para gestionar alertas y llamadas en sistemas de producción","fr":"Alerte et appel: technologie pour gérer les alertes et les appels dans les systèmes de production","de":"Alerting und On-Call: Technologie zur Verwaltung von Alerting und On-Call in Produktionsystemen","pt":"O alerting-oncall é uma solução de gerenciamento de alertas e escalas de plantão que ajuda a reduzir a fadiga de alertas e melhorar a resposta a incidentes","ru":"Alerting-oncall - это решение для управления оповещениями и дежурствами, помогающее снижать усталость от оповещений и улучшать реагирование на инциденты","ar":"التنبيه والدوريات هو حل لإدارة التنبيهات وخدمات الدوريات الذي يساعد على تقليل إجهاد التنبيهات وتحسين استجابة الحوادث"},"features":{"en":["Configures alerting rules and thresholds for monitoring systems like Prometheus and Datadog","Sets up on-call rotations and schedules using platforms like PagerDuty and Opsgenie","Implements alert routing and escalation to reduce alert fatigue","Manages incident response workflows using communication channels like Slack","Integrates with on-call platforms like Grafana OnCall for seamless incident management"],"zh":["设置警报规则和阈值","配置值班轮换和时间表","实现警报路由和升级","减少警报疲劳","管理事件响应工作流"],"ja":["アラートルールとしきい値の設定","オンコールローテーションとスケジュールの設定","アラートルーティングとエスカレーションの実装","アラート疲労の減少","インシデント対応ワークフローの管理"],"ko":["알림 규칙 및閾値 설정","근무轮換 및 일정 설정","알림 路由 및 에스컬레이션 구현","알림 피로 감소","이벤트 응답 워크플로우 관리"],"es":["Configuración de reglas de alertas y umbrales","Gestión de llamadas y rotaciones","Enrutamiento y escalada de alertas","Reducción de la fatiga de alertas","Integración con Prometheus, Datadog y otros"],"fr":["Configuration de règles d''alerte et de seuils","Gestion des appels et des rotations","Acheminement et escalation des alertes","Réduction de la fatigue d''alerte","Intégration avec Prometheus, Datadog et autres"],"de":["Konfiguration von Alertregeln und Schwellenwerten","Verwaltung von On-Call und Rotationen","Alertweiterleitung und -escalation","Reduzierung von Alertmüdigkeit","Integration mit Prometheus, Datadog und anderen"],"pt":["Configuração de regras de alerta e limiares personalizados","Integração com plataformas de monitoramento como Prometheus e Datadog","Gerenciamento de escalas de plantão e rotas de alerta","Redução da fadiga de alertas com notificações personalizadas","Implementação de fluxos de trabalho de resposta a incidentes"],"ru":["Настройка индивидуальных правил оповещений и порогов","Интеграция с системами мониторинга seperti Prometheus и Datadog","Управление дежурствами и маршрутами оповещений","Снижение усталости от оповещений с помощью персонализированных уведомлений","Реализация рабочих процессов реагирования на инциденты"],"ar":["إعداد قواعد تنبيهات وحدود مخصصة","التكامل مع منصات مراقبة مثل Prometheus وDatadog","إدارة خدمات الدوريات وطرق التنبيه","تقليل إجهاد التنبيهات مع التنبيهات المخصصة","تنفيذ سير عمل استجابة الحوادث"]},"keywords":{"en":["how to use Alerting-OnCall","Alerting-OnCall setup guide","Alerting-OnCall vs PagerDuty","Alerting-OnCall alternative to Opsgenie","configuring alerting rules with Prometheus","on-call management with Alerting-OnCall","reducing alert fatigue with Alerting-OnCall","Alerting-OnCall install","Alerting-OnCall tutorial"],"zh":["AIエージェント","警报管理","值班管理","事件响应","Alerting-OnCall","生产系统监控","Prometheus","Datadog","PagerDuty","Opsgenie"],"ja":["AIエージェント","アラート管理","オンコール管理","インシデント対応","Alerting-OnCall","プロダクションシステム監視","Prometheus","Datadog","PagerDuty","Opsgenie"],"ko":["AI 에이전트","알림 관리","근무 관리","이벤트 응답","Alerting-OnCall","생산 시스템 모니터링","Prometheus","Datadog","PagerDuty","Opsgenie"],"es":["herramientas de alertas","gestión de llamadas","alertas y llamadas","configuración de alertas","reducción de la fatiga de alertas","integración con Prometheus","integración con Datadog"],"fr":["outils d''alerte","gestion des appels","alerte et appel","configuration d''alerte","réduction de la fatigue d''alerte","intégration avec Prometheus","intégration avec Datadog"],"de":["Alerting-Tools","On-Call-Verwaltung","Alerting und On-Call","Alertkonfiguration","Reduzierung von Alertmüdigkeit","Integration mit Prometheus","Integration mit Datadog"],"pt":["alertas eficazes","gerenciamento de escalas de plantão","redução da fadiga de alertas","resposta a incidentes","ferramentas de IA para monitoramento","Prometheus","Datadog","configuração de alertas"],"ru":["эффективные оповещения","управление дежурствами","снижение усталости от оповещений","реагирование на инциденты","ИИ Агенты для мониторинга","Prometheus","Datadog","настройка оповещений"],"ar":["تنبيهات فعالة","إدارة خدمات الدوريات","تقليل إجهاد التنبيهات","استجابة الحوادث","أدوات الذكاء الاصطناعي للمراقبة","Prometheus","Datadog","إعداد التنبيهات"]}},"owner":"allthingslinux","repo":"atl.services","repoPath":"allthingslinux/atl.services","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.418Z","topics":[],"category":"community","skillMd":{"name":"alerting-oncall","description":"Set up alerting rules, configure on-call rotations, and manage incident response workflows. Integrate with PagerDuty, Opsgenie, or Grafana OnCall for alert routing and escalation. Use when implementing alerting strategies and on-call management for production systems.","version":"1.0","bodyPreview":"# Alerting & On-Call\n\nConfigure effective alerting and on-call management for production systems.\n\n## When to Use This Skill\n\nUse this skill when:\n- Setting up alerting rules and thresholds\n- Configuring on-call rotations and schedules\n- Implementing alert routing and escalation\n- Reducing alert fatigue\n- Managing incident response workflows\n\n## Prerequisites\n\n- Monitoring system (Prometheus, Datadog, etc.)\n- On-call platform (PagerDuty, Opsgenie, Grafana OnCall)\n- Communication channels (Slack,","body":"# Alerting & On-Call\n\nConfigure effective alerting and on-call management for production systems.\n\n## When to Use This Skill\n\nUse this skill when:\n- Setting up alerting rules and thresholds\n- Configuring on-call rotations and schedules\n- Implementing alert routing and escalation\n- Reducing alert fatigue\n- Managing incident response workflows\n\n## Prerequisites\n\n- Monitoring system (Prometheus, Datadog, etc.)\n- On-call platform (PagerDuty, Opsgenie, Grafana OnCall)\n- Communication channels (Slack, email)\n\n## Alerting Best Practices\n\n### Alert Categories\n\n```yaml\n# Severity levels\ncritical:\n  - Service completely down\n  - Data loss imminent\n  - Security breach\n  response: Immediate page, wake people up\n\nhigh:\n  - Service degraded significantly\n  - Error rate above SLO\n  - Capacity near limit\n  response: Page during business hours, notify after hours\n\nmedium:\n  - Performance degradation\n  - Non-critical component failure\n  - Warning thresholds exceeded\n  response: Notify via Slack, review next business day\n\nlow:\n  - Informational alerts\n  - Capacity planning triggers\n  - Routine maintenance needed\n  response: Email notification, weekly review\n```\n\n### Alert Design Principles\n\n```yaml\n# Good alert characteristics\nalerts:\n  actionable:\n    - Every alert should require human action\n    - Include runbook links\n    - Clear remediation steps\n\n  relevant:\n    - Alert on symptoms, not causes\n    - Focus on user impact\n    - Avoid alerting on expected behavior\n\n  timely:\n    - Appropriate thresholds\n    - Suitable evaluation windows\n    - Account for normal variance\n\n  unique:\n    - No duplicate alerts\n    - Proper alert grouping\n    - Clear ownership\n```\n\n## Prometheus Alerting\n\n### Alert Rules\n\n```yaml\n# prometheus/rules/alerts.yml\ngroups:\n  - name: service_alerts\n    rules:\n      # High-level service health\n      - alert: ServiceDown\n        expr: up{job=\"myapp\"} == 0\n        for: 1m\n        labels:\n          severity: critical\n        annotations:\n          summary: \"Service {{ $labels.instance }} is down\"\n          description: \"{{ $labels.job }} on {{ $labels.instance }} has been down for more than 1 minute.\"\n          runbook_url: \"https://wiki.example.com/runbooks/service-down\"\n\n      # Error rate alert\n      - alert: HighErrorRate\n        expr: |\n          sum(rate(http_requests_total{status=~\"5..\"}[5m])) by (service)\n          / sum(rate(http_requests_total[5m])) by (service) > 0.05\n        for: 5m\n        labels:\n          severity: critical\n        annotations:\n          summary: \"High error rate for {{ $labels.service }}\"\n          description: \"Error rate is {{ $value | humanizePercentage }} for the last 5 minutes\"\n\n      # Latency alert (SLO-based)\n      - alert: HighLatency\n        expr: |\n          histogram_quantile(0.95, \n            sum(rate(http_request_duration_seconds_bucket[5m])) by (le, service)\n          ) > 0.5\n        for: 5m\n        labels:\n          severity: high\n        annotations:\n          summary: \"P95 latency above 500ms for {{ $labels.service }}\"\n```\n\n### Alertmanager Configuration\n\n```yaml\n# alertmanager.yml\nglobal:\n  resolve_timeout: 5m\n  slack_api_url: ''https://hooks.slack.com/services/xxx''\n  pagerduty_url: ''https://events.pagerduty.com/v2/enqueue''\n\ntemplates:\n  - ''/etc/alertmanager/templates/*.tmpl''\n\nroute:\n  receiver: ''default-receiver''\n  group_by: [''alertname'', ''service'']\n  group_wait: 30s\n  group_interval: 5m\n  repeat_interval: 4h\n  \n  routes:\n    # Critical alerts go to PagerDuty\n    - match:\n        severity: critical\n      receiver: ''pagerduty-critical''\n      group_wait: 0s\n      repeat_interval: 1h\n\n    # High severity during business hours\n    - match:\n        severity: high\n      receiver: ''slack-high''\n      active_time_intervals:\n        - business-hours\n\n    # Route by team\n    - match_re:\n        team: platform.*\n      receiver: ''platform-team''\n\nreceivers:\n  - name: ''default-receiver''\n    slack_configs:\n      - channel: ''#alerts''\n        send_resolved: true\n\n  - name: ''pagerduty-critical''\n    pagerduty_configs:\n      - service_key: ''xxx''\n        severity: critical\n        description: ''{{ .CommonAnnotations.summary }}''\n        details:\n          firing: ''{{ template \"pagerduty.firing\" . }}''\n\n  - name: ''slack-high''\n    slack_configs:\n      - channel: ''#alerts-high''\n        title: ''{{ .CommonAnnotations.summary }}''\n        text: ''{{ .CommonAnnotations.description }}''\n        actions:\n          - type: button\n            text: ''Runbook''\n            url: ''{{ .CommonAnnotations.runbook_url }}''\n          - type: button\n            text: ''Dashboard''\n            url: ''{{ .CommonAnnotations.dashboard_url }}''\n\n  - name: ''platform-team''\n    slack_configs:\n      - channel: ''#platform-alerts''\n\ntime_intervals:\n  - name: business-hours\n    time_intervals:\n      - weekdays: [''monday:friday'']\n        times:\n          - start_time: ''09:00''\n            end_time: ''17:00''\n\ninhibit_rules:\n  - source_match:\n      severity: critical\n    target_match:\n      severity: high\n    equal: [''service'']\n```\n\n## PagerDuty Integration\n\n### Service Configuration\n\n```yaml\n# Terraform example\nresource \"pagerduty_service\" \"myapp\" {\n  name                    = \"MyApp Production\"\n  description             = \"Production application service\"\n  escalation_policy       = pagerduty_escalation_policy.default.id\n  alert_creation          = \"create_alerts_and_incidents\"\n  auto_resolve_timeout    = 14400  # 4 hours\n  acknowledgement_timeout = 600    # 10 minutes\n\n  incident_urgency_rule {\n    type    = \"use_support_hours\"\n    \n    during_support_hours {\n      type    = \"constant\"\n      urgency = \"high\"\n    }\n    \n    outside_support_hours {\n      type    = \"constant\"\n      urgency = \"low\"\n    }\n  }\n}\n\nresource \"pagerduty_escalation_policy\" \"default\" {\n  name      = \"Default Escalation\"\n  num_loops = 2\n\n  rule {\n    escalation_delay_in_minutes = 10\n    target {\n      type = \"schedule_reference\"\n      id   = pagerduty_schedule.primary.id\n    }\n  }\n\n  rule {\n    escalation_delay_in_minutes = 15\n    target {\n      type = \"user_reference\"\n      id   = pagerduty_user.manager.id\n    }\n  }\n}\n```\n\n### Schedule Configuration\n\n```yaml\nresource \"pagerduty_schedule\" \"primary\" {\n  name      = \"Primary On-Call\"\n  time_zone = \"America/New_York\"\n\n  layer {\n    name                         = \"Weekly Rotation\"\n    start                        = \"2024-01-01T00:00:00-05:00\"\n    rotation_virtual_start       = \"2024-01-01T00:00:00-05:00\"\n    rotation_turn_length_seconds = 604800  # 1 week\n    users                        = [for user in pagerduty_user.oncall : user.id]\n  }\n\n  # Override layer for holidays\n  layer {\n    name                         = \"Holiday Coverage\"\n    start                        = \"2024-01-01T00:00:00-05:00\"\n    rotation_virtual_start       = \"2024-01-01T00:00:00-05:00\"\n    rotation_turn_length_seconds = 86400\n    users                        = [pagerduty_user.holiday_coverage.id]\n\n    restriction {\n      type              = \"daily_restriction\"\n      start_time_of_day = \"00:00:00\"\n      duration_seconds  = 86400\n      start_day_of_week = 0  # Sunday\n    }\n  }\n}\n```\n\n## Grafana OnCall\n\n### Integration Setup\n\n```yaml\n# docker-compose.yml addition\nservices:\n  oncall:\n    image: grafana/oncall\n    environment:\n      - SECRET_KEY=your-secret-key\n      - BASE_URL=http://oncall:8080\n      - GRAFANA_API_URL=http://grafana:3000\n    ports:\n      - \"8080:8080\"\n```\n\n### Escalation Chain\n\n```yaml\n# Example escalation chain structure\nescalation_chains:\n  - name: \"Production Critical\"\n    steps:\n      - step: 1\n        type: notify\n        persons:\n          - \"@oncall-primary\"\n        wait_delay: 0\n        \n      - step: 2\n        type: notify\n        persons:\n          - \"@oncall-secondary\"\n        wait_delay: 5m\n        \n      - step: 3\n        type: notify\n        persons:\n          - \"@engineering-manager\"\n        wait_delay: 10m\n        \n      - step: 4\n        type: trigger_action\n        action: \"escalate_to_incident_commander\"\n        wait_delay: 15m\n```\n\n## Alert Templates\n\n### Slack Alert Template\n\n```go\n{{ define \"slack.title\" }}\n[{{ .Status | toUpper }}{{ if eq .Status \"firing\" }}:{{ .Alerts.Firing | len }}{{ end }}] {{ .CommonLabels.alertname }}\n{{ end }}\n\n{{ define \"slack.text\" }}\n{{ range .Alerts }}\n*Alert:* {{ .Annotations.summary }}\n*Severity:* {{ .Labels.severity }}\n*Description:* {{ .Annotations.description }}\n*Runbook:* {{ .Annotations.runbook_url }}\n{{ end }}\n{{ end }}\n```\n\n### PagerDuty Details Template\n\n```go\n{{ define \"pagerduty.firing\" }}\n{{ range .Alerts.Firing }}\nAlert: {{ .Labels.alertname }}\nService: {{ .Labels.service }}\nInstance: {{ .Labels.instance }}\nValue: {{ .Annotations.value }}\nStarted: {{ .StartsAt.Format \"2006-01-02 15:04:05\" }}\n{{ end }}\n{{ end }}\n```\n\n## On-Call Best Practices\n\n### Rotation Guidelines\n\n```yaml\non_call_guidelines:\n  rotation_length: 1 week\n  handoff_time: \"10:00 AM Monday\"\n  \n  responsibilities:\n    - Monitor alerts during shift\n    - Respond within SLA (critical: 5min, high: 15min)\n    - Document incidents\n    - Handoff unresolved issues\n    \n  support:\n    - Secondary on-call for backup\n    - Clear escalation path\n    - Manager availability for major incidents\n    \n  wellness:\n    - Maximum 1 week on-call per month\n    - Comp time after high-alert periods\n    - No-interrupt recovery day after shift\n```\n\n### Runbook Template\n\n```markdown\n# Alert: High Error Rate\n\n## Summary\nError rate has exceeded the threshold of 5% for the service.\n\n## Impact\nUsers may experience errors when accessing the application.\n\n## Investigation Steps\n1. Check service logs: `kubectl logs -l app=myapp -n production`\n2. Review recent deployments: `kubectl rollout history deployment/myapp`\n3. Check database connectivity: `kubectl exec -it myapp -- nc -zv postgres 5432`\n4. Review error traces in APM dashboard\n\n## Remediation\n### If caused by recent deployment:\n```bash\nkubectl rollout undo deployment/myapp -n production\n```\n\n### If database related:\n```bash\nkubectl delete pod -l app=postgres -n production\n```\n\n## Escalation\nIf not resolved within 15 minutes, escalate to:\n- Database team: @db-oncall\n- Platform team: @platform-oncall\n```\n\n## Alert Fatigue Reduction\n\n### Strategies\n\n```yaml\nfatigue_reduction:\n  aggregate_alerts:\n    - Group related alerts\n    - Use inhibit rules\n    - Implement alert correlation\n    \n  tune_thresholds:\n    - Base on SLOs, not arbitrary values\n    - Account for normal variance\n    - Use appropriate evaluation windows\n    \n  automate_responses:\n    - Auto-remediation for known issues\n    - Self-healing infrastructure\n    - Automated scaling\n    \n  regular_review:\n    - Weekly alert review\n    - Remove unused alerts\n    - Update thresholds based on data\n```\n\n## Common Issues\n\n### Issue: Alert Storm\n**Problem**: Too many alerts firing simultaneously\n**Solution**: Implement proper grouping and inhibition rules\n\n### Issue: Missed Alerts\n**Problem**: Critical alerts not reaching on-call\n**Solution**: Test escalation policies, verify contact methods\n\n### Issue: False Positives\n**Problem**: Alerts firing without actual issues\n**Solution**: Tune thresholds, increase evaluation windows\n\n## Best Practices\n\n- Define clear severity levels\n- Every alert needs a runbook\n- Test on-call notifications regularly\n- Review and tune alerts weekly\n- Implement proper escalation paths\n- Use alert grouping and inhibition\n- Track alert metrics (MTTR, frequency)\n- Practice incident response regularly\n\n## Related Skills\n\n- [prometheus-grafana](../prometheus-grafana/) - Monitoring setup\n- [incident-response](../../../security/operations/incident-response/) - Incident handling\n- [runbook-automation](../../../compliance/continuity/runbook-automation/) - Runbook creation\n"},"lastSynced":"2026-03-08T02:07:19.906Z","agentAnalysis":{"suitability":{"en":"Perfect for Operations Agents needing advanced alerting and on-call management for production systems using Prometheus and PagerDuty.","zh":"适用于需要使用Prometheus和PagerDuty为生产系统提供高级警报和值班管理的运维代理。","ja":"PrometheusとPagerDutyを使用して生産システムの高度なアラートとオンコール管理を必要とするオペレーションズエージェントに適しています。","ko":"프로메테우스와 패저デューティ를 사용하여 프로덕션 시스템의 고급 알림 및 온콜 관리가 필요한 운영 에이전트에게 적합합니다.","es":"Perfecto para agentes de operaciones que necesitan alertas avanzadas y gestión de llamadas para sistemas de producción que utilizan Prometheus y PagerDuty.","fr":"Parfait pour les agents d''opérations ayant besoin d''alertes avancées et de gestion des appels pour les systèmes de production utilisant Prometheus et PagerDuty.","de":"Perfekt für Operations-Agents, die erweiterte Alarmierung und On-Call-Management für Produktionsysteme mit Prometheus und PagerDuty benötigen.","pt":"Perfeito para Agentes de Operações que necessitam de alertas avançados e gerenciamento de chamadas para sistemas de produção que usam Prometheus e PagerDuty.","ru":"Идеально подходит для операционных агентов, которым необходимы продвинутые оповещения и управление вызовами для производственных систем, использующих Prometheus и PagerDuty.","ar":"مثالي للوكلاء التشغيليين الذين يحتاجون إلى إشعارات متقدمة وإدارة المكالمات لأنظمة الإنتاج التي تستخدم Prometheus و PagerDuty."},"recommendation":{"en":"Empowers agents to configure effective alerting rules and thresholds, manage on-call rotations, and implement incident response workflows using protocols like alert routing and escalation, reducing alert fatigue by integrating with communication channels like Slack.","zh":"赋予代理配置有效的警报规则和阈值，管理值班轮换，实现事件响应工作流，使用诸如警报路由和升级的协议，并通过将其与Slack等通信渠道集成来减少警报疲劳。","ja":"エージェントが有効なアラートルールとしきい値を構成し、オンコールのローテーションとスケジュールを管理し、インシデントレスポンスワークフローを実装し、アラートルーティングやエスカレーションのようなプロトコルを使用し、Slackなどのコミュニケーションチャンネルと統合することでアラート疲労を軽減する。","ko":"에이전트가 효과적인 알림 규칙 및 임계값을 구성하고, 온콜轮换 및 스케줄을 관리하며, 이벤트 응답 워크플로우를 구현하고, 알림 라우팅 및 에스컬레이션과 같은 프로토콜을 사용하여 슬랙과 같은 커뮤니케이션 채널을 통합하여 알림 피로를 줄일 수 있습니다.","es":"Habilita a los agentes a configurar reglas de alertas efectivas y umbrales, gestionar rotaciones de llamadas y implementar flujos de trabajo de respuesta a incidentes utilizando protocolos como enrutamiento de alertas y escalada, reduciendo la fatiga de las alertas mediante la integración con canales de comunicación como Slack.","fr":"Permet aux agents de configurer des règles d''alerte efficaces et des seuils, de gérer les rotations d''appels et de mettre en œuvre des flux de travail de réponse aux incidents en utilisant des protocoles tels que l''acheminement des alertes et l''escalade, en réduisant la fatigue des alertes en intégrant des canaux de communication comme Slack.","de":"Ermächtigt die Agenten, effektive Alarmregeln und Schwellenwerte zu konfigurieren, On-Call-Rotationen und -Zeitpläne zu verwalten und Workflows für die Reaktion auf Incidents mithilfe von Protokollen wie Alert-Weiterleitung und -Escalation zu implementieren, wodurch die Alarmmüdigkeit durch die Integration mit Kommunikationskanälen wie Slack reduziert wird.","pt":"Habilita os agentes a configurar regras de alerta eficazes e limiares, gerenciar rotações de chamadas e implementar fluxos de trabalho de resposta a incidentes usando protocolos como roteamento de alertas e escalação, reduzindo a fadiga de alertas ao integrar com canais de comunicação como Slack.","ru":"Наделяет агентов возможностью настраивать эффективные правила оповещения и пороги, управлять вахтовым обслуживанием и реализовывать рабочие процессы реагирования на инциденты с использованием таких протоколов, как маршрутизация оповещений и эскалация, снижая усталость от оповещений за счет интеграции с каналами связи, такими как Slack.","ar":"يمنح الوكلاء القدرة على تكوين قواعد إشعار فعالة وعتبات، وإدارة دوارات المكالمات وتنفيذ سير عمل استجابة للحوادث باستخدام بروتوكولات مثل маршруطة الإشعارات وتعزيزها، وتقليل إرهاق الإشعارات من خلال التكامل مع قنوات الاتصال مثل Slack."},"useCases":{"en":["Configuring alerting rules and thresholds for production systems","Automating on-call rotations and schedules using PagerDuty","Implementing alert routing and escalation workflows","Optimizing incident response workflows to reduce downtime"],"zh":["为生产系统配置警报规则和阈值","使用PagerDuty自动化值班轮换和日程","实现警报路由和升级工作流","优化事件响应工作流以减少停机时间"],"ja":["生産システムのアラートルールとしきい値を構成する","PagerDutyを使用してオンコールのローテーションとスケジュールを自動化する","アラートルーティングとエスカレーションのワークフローを実装する","インシデントレスポンスワークフローを最適化してダウンタイムを減らす"],"ko":["프로덕션 시스템을 위한 알림 규칙 및 임계값을 구성하는 것","패저デューティ를 사용하여 온콜轮换 및 스케줄을 자동화하는 것","알림 라우팅 및 에스컬레이션 워크플로우를 구현하는 것","이벤트 응답 워크플로우를 최적화하여 다운타임을 줄이는 것"],"es":["Configuración de reglas de alertas y umbrales para sistemas de producción","Automatización de rotaciones y horarios de llamadas utilizando PagerDuty","Implementación de flujos de trabajo de enrutamiento y escalada de alertas","Optimización de flujos de trabajo de respuesta a incidentes para reducir el tiempo de inactividad"],"fr":["Configuration de règles d''alerte et de seuils pour les systèmes de production","Automatisation des rotations et des plannings d''appels en utilisant PagerDuty","Mise en œuvre de flux de travail d''acheminement et d''escalade d''alertes","Optimisation des flux de travail de réponse aux incidents pour réduire le temps d''arrêt"],"de":["Konfiguration von Alarmregeln und Schwellenwerten für Produktionsysteme","Automatisierung von On-Call-Rotationen und -Zeitplänen mithilfe von PagerDuty","Implementierung von Workflows für die Weiterleitung und Escalation von Alarmen","Optimierung von Workflows für die Reaktion auf Incidents, um die Ausfallzeit zu reduzieren"],"pt":["Configurando regras de alerta e limiares para sistemas de produção","Automatizando rotações de chamadas e horários usando PagerDuty","Implementando fluxos de trabalho de roteamento e escalação de alertas","Otimizando fluxos de trabalho de resposta a incidentes para reduzir o tempo de inatividade"],"ru":["Настройка правил оповещения и порогов для производственных систем","Автоматизация вахтового обслуживания и графиков с помощью PagerDuty","Реализация рабочих процессов маршрутизации и эскалации оповещений","Оптимизация рабочих процессов реагирования на инциденты для снижения времени простоя"],"ar":["تكوين قواعد الإشعار وعتباتها لأنظمة الإنتاج","تأتمة دوارات المكالمات والجدول الزمني باستخدام PagerDuty","تنفيذ سير عمل маршروطة الإشعارات وتعزيزها","تحسين سير عمل استجابة للحوادث لتقليل وقت التوقف"]},"limitations":{"en":["Requires a monitoring system like Prometheus or Datadog","Needs an on-call platform such as PagerDuty or Opsgenie","Dependent on communication channels like Slack for alert notifications"],"zh":["需要像Prometheus或Datadog这样的监控系统","需要像PagerDuty或Opsgenie这样的值班平台","依赖于Slack等通信渠道进行警报通知"],"ja":["PrometheusまたはDatadogのようなモニタリングシステムが必要","PagerDutyまたはOpsgenieのようなオンコールプラットフォームが必要","アラート通知にはSlackなどのコミュニケーションチャンネルに依存する"],"ko":["프로메테우스 또는 데이타독과 같은 모니터링 시스템이 필요합니다","패저デューティ 또는 옵스지니와 같은 온콜 플랫폼이 필요합니다","알림通知에는 슬랙과 같은 커뮤니케이션 채널에 의존합니다"],"es":["Requiere un sistema de monitoreo como Prometheus o Datadog","Necesita una plataforma de llamadas como PagerDuty u Opsgenie","Dependiente de canales de comunicación como Slack para las notificaciones de alertas"],"fr":["Nécessite un système de surveillance tel que Prometheus ou Datadog","A besoin d''une plate-forme d''appels telle que PagerDuty ou Opsgenie","Dépendante de canaux de communication tels que Slack pour les notifications d''alertes"],"de":["Benötigt ein Überwachungssystem wie Prometheus oder Datadog","Benötigt eine On-Call-Plattform wie PagerDuty oder Opsgenie","Abhängig von Kommunikationskanälen wie Slack für Alarmbenachrichtigungen"],"pt":["Exige um sistema de monitoramento como Prometheus ou Datadog","Precisa de uma plataforma de chamadas como PagerDuty ou Opsgenie","Dependente de canais de comunicação como Slack para notificações de alertas"],"ru":["Требует системы мониторинга, такой как Prometheus или Datadog","Требует платформы вызовов, такой как PagerDuty или Opsgenie","Зависит от каналов связи, таких как Slack, для уведомлений об оповещениях"],"ar":["يتطلب نظام مراقبة مثل Prometheus أو Datadog","يحتاج إلى منصة مكالمات مثل PagerDuty أو Opsgenie","يعتمد على قنوات الاتصال مثل Slack لإخطارات الإشعارات"]},"version":4},"contentHash":"e7db5397b5a0565df06c03eb8f341ed2e4afa2291c9db3d703578ab700520dac","qualityScore":65}');
