INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('allthingslinux/atl.services/alerting-oncall', 'alerting-oncall', 'allthingslinux', 'atl.services', 'community', 'alerting-oncall allthingslinux atl.services community The Alerting-OnCall skill helps developers configure alerting rules and thresholds, on-call rotations, and incident response workflows for production systems. It benefits developers and operations teams using monitoring systems like Prometheus and on-call platforms like PagerDuty. Alerting-OnCall技能用于配置生产系统的有效警报和值班管理，包括设置警报规则和阈值、配置值班轮换和时间表等 Alerting-OnCallスキルは、プロダクションシステムの効果的なアラートとオンコール管理を設定するために使用され、包括的なアラートルールとしきい値の設定、オンコールローテーションとスケジュールの設定など Alerting-OnCall 스킬은 생산 시스템의 효과적인 알림 및 근무 관리를 구성하는 데 사용되며, 알림 규칙 및閾値 설정, 근무轮換 및 일정 설정 등 Configura reglas de alertas y umbrales para sistemas de producción con nuestra herramienta de alertas y llamadas Configurez des règles d''alerte et des seuils pour les systèmes de production avec notre outil d''alerte et d''appel Konfigurieren Sie Alertregeln und Schwellenwerte für Produktionssysteme mit unserem Alerting- und On-Call-Tool Configure alertas eficazes e gerencie escalas de plantão com nossa solução de alerting-oncall, compatível com Prometheus, Datadog e outras plataformas de monitoramento Настройте эффективные оповещения и управляйте дежурствами с помощью нашего решения alerting-oncall, совместимого с Prometheus, Datadog и другими системами мониторинга إعداد تنبيهات فعالة وإدارة خدمات الدوريات باستخدام حلنا alerting-oncall، المتوافق مع Prometheus وDatadog ومنصات مراقبة أخرى how to use Alerting-OnCall Alerting-OnCall setup guide Alerting-OnCall vs PagerDuty Alerting-OnCall alternative to Opsgenie configuring alerting rules with Prometheus on-call management with Alerting-OnCall reducing alert fatigue with Alerting-OnCall Alerting-OnCall install Alerting-OnCall tutorial AIエージェント 警报管理 值班管理 事件响应 Alerting-OnCall 生产系统监控 Prometheus Datadog PagerDuty Opsgenie Configures alerting rules and thresholds for monitoring systems like Prometheus and Datadog Sets up on-call rotations and schedules using platforms like PagerDuty and Opsgenie Implements alert routing and escalation to reduce alert fatigue Manages incident response workflows using communication channels like Slack Integrates with on-call platforms like Grafana OnCall for seamless incident management Alerting-OnCall is a skill that enables effective alerting and on-call management for production systems, reducing alert fatigue and streamlining incident response workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('regybean/ChatGBeanT/openrouter-typescript-sdk', 'community', 'regybean', 'ChatGBeanT', 'regybean/ChatGBeanT', 'openrouter-typescript-sdk', 0, 0, 65, '2026-03-08T01:57:15.464Z', '2026-03-08T02:09:20.437Z', 'f15f74cb7ba16a93465a78a9e1a009b06cd0847d38cf907ae6e2c3bd11e2cbe6', '{"id":"regybean/ChatGBeanT/openrouter-typescript-sdk","name":"openrouter-typescript-sdk","description":{"en":"The openrouter-typescript-sdk provides a comprehensive TypeScript interface for interacting with OpenRouter''s unified API, benefiting AI agents and developers. It enables access to 300+ AI models through a single, type-safe interface.","zh":"OpenRouter TypeScript SDK 是一个全面性的 TypeScript SDK，用于与 OpenRouter 的统一 API 交互，提供访问 300+ AI 模型的能力","ja":"OpenRouter TypeScript SDK は、OpenRouter の統一 API と相互作用するための包括的な TypeScript SDK です。300+ の AI モデルへのアクセスを提供します","ko":"OpenRouter TypeScript SDK는 OpenRouter의 통합 API와 상호 작용하기 위한 포괄적인 TypeScript SDK입니다. 300+ AI 모델에 대한 액세스를 제공합니다","es":"El SDK de TypeScript de OpenRouter ofrece acceso a 300+ modelos de IA a través de una interfaz segura y tipada. Con esta habilidad, los agentes de IA pueden aprovechar el patrón de llamada de modelo para la generación de texto, el uso de herramientas y las conversaciones de varios giros.","fr":"Le SDK TypeScript d''OpenRouter offre un accès à 300+ modèles d''IA via une interface sécurisée et typée. Avec cette compétence, les agents IA peuvent exploiter le modèle d''appel pour la génération de texte, l''utilisation d''outils et les conversations à plusieurs tours.","de":"Das TypeScript-SDK von OpenRouter bietet Zugriff auf 300+ KI-Modelle über eine sichere und typsichere Schnittstelle. Mit dieser Fähigkeit können KI-Agents den Call-Model-Muster für Textgenerierung, Tool-Nutzung und Mehrfach-Gespräche nutzen.","pt":"O OpenRouter TypeScript SDK é uma biblioteca completa para interagir com a API unificada do OpenRouter, fornecendo acesso a 300+ modelos de IA","ru":"OpenRouter TypeScript SDK - это комплексная библиотека для взаимодействия с унифицированным API OpenRouter, обеспечивающая доступ к 300+ моделям ИИ","ar":"OpenRouter TypeScript SDK هو مكتبة شاملة للتفاعل مع واجهة برمجة التطبيقات الموحدة من OpenRouter، ويوفر الوصول إلى 300+ نموذج الذكاء الاصطناعي"},"seo":{"title":{"en":"openrouter-typescript-sdk: Unified API Access for AI Agen...","zh":"OpenRouter TypeScript SDK 安装指南","ja":"OpenRouter TypeScript SDK 導入ガイド","ko":"OpenRouter TypeScript SDK 설정 가이드","es":"Guía de configuración de openrouter-typescript-sdk para A...","fr":"Guide de configuration de openrouter-typescript-sdk pour ...","de":"Einrichtungsleitfaden für openrouter-typescript-sdk für K...","pt":"Guia de Configuração do OpenRouter TypeScript SDK para Ag...","ru":"Настройка OpenRouter TypeScript SDK для ИИ Агентов","ar":"دليل إعداد OpenRouter TypeScript SDK لعمليات الإيمان بالذ..."},"description":{"en":"Unlock 300+ AI models with the openrouter-typescript-sdk. Get started with our setup guide and discover how to leverage the callModel pattern for text genera...","zh":"使用 OpenRouter TypeScript SDK 访问 300+ AI 模型，通过统一的、类型安全的接口实现文本生成、工具使用、流媒体和多回合对话","ja":"OpenRouter TypeScript SDK を使用して 300+ の AI モデルにアクセスし、統一されたタイプセーフなインターフェースでテキスト生成、ツールの使用、ストリーミング、多ターン会話を実現","ko":"OpenRouter TypeScript SDK를 사용하여 300+ AI 모델에 액세스하고, 통합된 유형 안전 인터페이스를 통해 텍스트 생성, 도구 사용, 스트리밍 및 다중 회선 대화를 구현","es":"Descubre cómo configurar openrouter-typescript-sdk para acceder a 300+ modelos de IA a través de una interfaz segura y tipada","fr":"Découvrez comment configurer openrouter-typescript-sdk pour accéder à 300+ modèles d''IA via une interface sécurisée et typée","de":"Erfahren Sie, wie Sie openrouter-typescript-sdk einrichten, um auf 300+ KI-Modelle über eine sichere und typsichere Schnittstelle zuzugreifen","pt":"Aprenda a configurar o OpenRouter TypeScript SDK para interagir com a API unificada e acessar 300+ modelos de IA","ru":"Узнайте, как настроить OpenRouter TypeScript SDK для взаимодействия с унифицированным API и доступа к 300+ моделям ИИ","ar":"تعرف على كيفية تمكين OpenRouter TypeScript SDK للتفاعل مع واجهة برمجة التطبيقات الموحدة ووصول إلى 300+ نموذج الذكاء الاصطناعي"},"definition":{"en":"openrouter-typescript-sdk is a TypeScript SDK for interacting with OpenRouter''s unified API, providing access to multiple AI models through a type-safe interface.","zh":"OpenRouter TypeScript SDK 是一个用于与 OpenRouter AI 平台交互的软件开发工具包","ja":"OpenRouter TypeScript SDK は、OpenRouter AI プラットフォームと相互作用するためのソフトウェア開発キットです","ko":"OpenRouter TypeScript SDK는 OpenRouter AI 플랫폼과 상호 작용하기 위한 소프트웨어 개발 키트입니다","es":"El openrouter-typescript-sdk es un conjunto de herramientas de desarrollo de software que permite a los agentes de IA interactuar con la API unificada de OpenRouter","fr":"Le openrouter-typescript-sdk est un ensemble d''outils de développement logiciel qui permet aux agents IA d''interagir avec l''API unifiée d''OpenRouter","de":"Das openrouter-typescript-sdk ist ein Software-Development-Kit, das es KI-Agents ermöglicht, mit der einheitlichen API von OpenRouter zu interagieren","pt":"O que é OpenRouter TypeScript SDK? É uma biblioteca de TypeScript para interagir com a API do OpenRouter","ru":"Что такое OpenRouter TypeScript SDK? Это библиотека TypeScript для взаимодействия с API OpenRouter","ar":"ما هو OpenRouter TypeScript SDK؟ هو مكتبة TypeScript للتفاعل مع واجهة برمجة التطبيقات من OpenRouter"},"features":{"en":["Provides access to 300+ AI models through a unified API","Supports the callModel pattern for text generation, tool usage, streaming, and multi-turn conversations","Offers a type-safe interface for interacting with OpenRouter''s API","Enables installation via npm using the @openrouter/sdk package","Requires API key initialization from openrouter.ai/settings/keys"],"zh":["支持 300+ AI 模型","统一的、类型安全的接口","实现文本生成、工具使用、流媒体和多回合对话","使用 callModel 模式","通过 npm 安装"],"ja":["300+ の AI モデルをサポート","統一されたタイプセーフなインターフェース","テキスト生成、ツールの使用、ストリーミング、多ターン会話を実現","callModel パターンを使用","npm 経由でインストール"],"ko":["300+ AI 모델 지원","통합된 유형 안전 인터페이스","텍스트 생성, 도구 사용, 스트리밍 및 다중 회선 대화를 구현","callModel 패턴 사용","npm을 통해 설치"],"es":["Acceso a 300+ modelos de IA","Interfaz segura y tipada","Patrón de llamada de modelo para la generación de texto","Uso de herramientas y conversaciones de varios giros","Instalación sencilla con npm","Inicialización con clave de API"],"fr":["Accès à 300+ modèles d''IA","Interface sécurisée et typée","Modèle d''appel pour la génération de texte","Utilisation d''outils et conversations à plusieurs tours","Installation simple avec npm","Initialisation avec clé d''API"],"de":["Zugriff auf 300+ KI-Modelle","Sichere und typsichere Schnittstelle","Call-Model-Muster für Textgenerierung","Tool-Nutzung und Mehrfach-Gespräche","Einfache Installation mit npm","Initialisierung mit API-Schlüssel"],"pt":["Acesso a 300+ modelos de IA","Interface de programação de tipo seguro","Padrão de chamada de modelo para geração de texto","Suporte a streaming e conversas de várias voltas","Instalação via npm com @openrouter/sdk"],"ru":["Доступ к 300+ моделям ИИ","Типобезопасный интерфейс программирования","Шаблон вызова модели для генерации текста","Поддержка потокового вещания и разговоров с несколькими поворотами","Установка через npm с @openrouter/sdk"],"ar":["الوصول إلى 300+ نموذج الذكاء الاصطناعي","واجهة برمجة آمنة من النوع","نمط呼وء نموذج للتشكيل النصي","دعم البث وال محادثات المتعددة","التثبيت عبر npm مع @openrouter/sdk"]},"keywords":{"en":["how to use openrouter-typescript-sdk","openrouter-typescript-sdk setup guide","openrouter-typescript-sdk alternative","openrouter-typescript-sdk vs other AI SDKs","install openrouter-typescript-sdk","openrouter-typescript-sdk tutorial","what is openrouter-typescript-sdk","openrouter-typescript-sdk documentation"],"zh":["OpenRouter TypeScript SDK","AI 模型","统一 API","类型安全","文本生成","工具使用","流媒体","多回合对话","callModel","npm"],"ja":["OpenRouter TypeScript SDK","AI モデル","統一 API","タイプセーフ","テキスト生成","ツールの使用","ストリーミング","多ターン会話","callModel","npm"],"ko":["OpenRouter TypeScript SDK","AI 모델","통합 API","유형 안전","텍스트 생성","도구 사용","스트리밍","다중 회선 대화","callModel","npm"],"es":["openrouter-typescript-sdk","Agentes de IA","Modelos de IA","API unificada","TypeScript","npm","Clave de API","Generación de texto","Uso de herramientas"],"fr":["openrouter-typescript-sdk","Agents IA","Modèles d''IA","API unifiée","TypeScript","npm","Clé d''API","Génération de texte","Utilisation d''outils"],"de":["openrouter-typescript-sdk","KI-Agents","KI-Modelle","Einheitliche API","TypeScript","npm","API-Schlüssel","Textgenerierung","Tool-Nutzung"],"pt":["OpenRouter TypeScript SDK","Agentes de IA","API unificada","Modelos de IA","TypeScript","npm","Instalação OpenRouter","Configuração OpenRouter"],"ru":["OpenRouter TypeScript SDK","ИИ Агенты","Унифицированный API","Модели ИИ","TypeScript","npm","Установка OpenRouter","Настройка OpenRouter"],"ar":["OpenRouter TypeScript SDK","عمليات الإيمان بالذكاء الاصطناعي","واجهة برمجة التطبيقات الموحدة","نماذج الذكاء الاصطناعي","TypeScript","npm","تثبيت OpenRouter","إعداد OpenRouter"]}},"owner":"regybean","repo":"ChatGBeanT","repoPath":"regybean/ChatGBeanT","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.464Z","topics":[],"category":"community","skillMd":{"name":"openrouter-typescript-sdk","description":"Complete reference for integrating with 300+ AI models through the OpenRouter TypeScript SDK using the callModel pattern","version":"1.0.0","bodyPreview":"# OpenRouter TypeScript SDK\n\nA comprehensive TypeScript SDK for interacting with OpenRouter''s unified API, providing access to 300+ AI models through a single, type-safe interface. This skill enables AI agents to leverage the `callModel` pattern for text generation, tool usage, streaming, and multi-turn conversations.\n\n---\n\n## Installation\n\n```bash\nnpm install @openrouter/sdk\n```\n\n## Setup\n\nGet your API key from [openrouter.ai/settings/keys](https://openrouter.ai/settings/keys), then initialize:","body":"# OpenRouter TypeScript SDK\n\nA comprehensive TypeScript SDK for interacting with OpenRouter''s unified API, providing access to 300+ AI models through a single, type-safe interface. This skill enables AI agents to leverage the `callModel` pattern for text generation, tool usage, streaming, and multi-turn conversations.\n\n---\n\n## Installation\n\n```bash\nnpm install @openrouter/sdk\n```\n\n## Setup\n\nGet your API key from [openrouter.ai/settings/keys](https://openrouter.ai/settings/keys), then initialize:\n\n```typescript\nimport OpenRouter from ''@openrouter/sdk'';\n\nconst client = new OpenRouter({\n  apiKey: process.env.OPENROUTER_API_KEY\n});\n```\n\n---\n\n## Authentication\n\nThe SDK supports two authentication methods: API keys for server-side applications and OAuth PKCE flow for user-facing applications.\n\n### API Key Authentication\n\nThe primary authentication method uses API keys from your OpenRouter account.\n\n#### Obtaining an API Key\n\n1. Visit [openrouter.ai/settings/keys](https://openrouter.ai/settings/keys)\n2. Create a new API key\n3. Store securely in an environment variable\n\n#### Environment Setup\n\n```bash\nexport OPENROUTER_API_KEY=sk-or-v1-your-key-here\n```\n\n#### Client Initialization\n\n```typescript\nimport OpenRouter from ''@openrouter/sdk'';\n\nconst client = new OpenRouter({\n  apiKey: process.env.OPENROUTER_API_KEY\n});\n```\n\nThe client automatically uses this key for all subsequent requests:\n\n```typescript\n// API key is automatically included\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Hello!''\n});\n```\n\n#### Get Current Key Metadata\n\nRetrieve information about the currently configured API key:\n\n```typescript\nconst keyInfo = await client.apiKeys.getCurrentKeyMetadata();\nconsole.log(''Key name:'', keyInfo.name);\nconsole.log(''Created:'', keyInfo.createdAt);\n```\n\n#### API Key Management\n\nProgrammatically manage API keys:\n\n```typescript\n// List all keys\nconst keys = await client.apiKeys.list();\n\n// Create a new key\nconst newKey = await client.apiKeys.create({\n  name: ''Production API Key''\n});\n\n// Get a specific key by hash\nconst key = await client.apiKeys.get({\n  hash: ''sk-or-v1-...''\n});\n\n// Update a key\nawait client.apiKeys.update({\n  hash: ''sk-or-v1-...'',\n  requestBody: {\n    name: ''Updated Key Name''\n  }\n});\n\n// Delete a key\nawait client.apiKeys.delete({\n  hash: ''sk-or-v1-...''\n});\n```\n\n### OAuth Authentication (PKCE Flow)\n\nFor user-facing applications where users should control their own API keys, OpenRouter supports OAuth with PKCE (Proof Key for Code Exchange). This flow allows users to generate API keys through a browser authorization flow without your application handling their credentials.\n\n#### createAuthCode\n\nGenerate an authorization code and URL to start the OAuth flow:\n\n```typescript\nconst authResponse = await client.oAuth.createAuthCode({\n  callbackUrl: ''https://myapp.com/auth/callback''\n});\n\n// authResponse contains:\n// - authorizationUrl: URL to redirect the user to\n// - code: The authorization code for later exchange\n\nconsole.log(''Redirect user to:'', authResponse.authorizationUrl);\n```\n\n**Parameters:**\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| `callbackUrl` | `string` | Yes | Your application''s callback URL after user authorization |\n\n**Browser Redirect:**\n\n```typescript\n// In a browser environment\nwindow.location.href = authResponse.authorizationUrl;\n\n// Or in a server-rendered app, return a redirect response\nres.redirect(authResponse.authorizationUrl);\n```\n\n#### exchangeAuthCodeForAPIKey\n\nAfter the user authorizes your application, they are redirected back to your callback URL with an authorization code. Exchange this code for an API key:\n\n```typescript\n// In your callback handler\nconst code = req.query.code;  // From the redirect URL\n\nconst apiKeyResponse = await client.oAuth.exchangeAuthCodeForAPIKey({\n  code: code\n});\n\n// apiKeyResponse contains:\n// - key: The user''s API key\n// - Additional metadata about the key\n\nconst userApiKey = apiKeyResponse.key;\n\n// Store securely for this user''s future requests\nawait saveUserApiKey(userId, userApiKey);\n```\n\n**Parameters:**\n\n| Parameter | Type | Required | Description |\n|-----------|------|----------|-------------|\n| `code` | `string` | Yes | The authorization code from the OAuth redirect |\n\n#### Complete OAuth Flow Example\n\n```typescript\nimport OpenRouter from ''@openrouter/sdk'';\nimport express from ''express'';\n\nconst app = express();\nconst client = new OpenRouter({\n  apiKey: process.env.OPENROUTER_API_KEY  // Your app''s key for OAuth operations\n});\n\n// Step 1: Initiate OAuth flow\napp.get(''/auth/start'', async (req, res) => {\n  const authResponse = await client.oAuth.createAuthCode({\n    callbackUrl: ''https://myapp.com/auth/callback''\n  });\n\n  // Store any state needed for the callback\n  req.session.oauthState = { /* ... */ };\n\n  // Redirect user to OpenRouter authorization page\n  res.redirect(authResponse.authorizationUrl);\n});\n\n// Step 2: Handle callback and exchange code\napp.get(''/auth/callback'', async (req, res) => {\n  const { code } = req.query;\n\n  if (!code) {\n    return res.status(400).send(''Authorization code missing'');\n  }\n\n  try {\n    const apiKeyResponse = await client.oAuth.exchangeAuthCodeForAPIKey({\n      code: code as string\n    });\n\n    // Store the user''s API key securely\n    await saveUserApiKey(req.session.userId, apiKeyResponse.key);\n\n    res.redirect(''/dashboard?auth=success'');\n  } catch (error) {\n    console.error(''OAuth exchange failed:'', error);\n    res.redirect(''/auth/error'');\n  }\n});\n\n// Step 3: Use the user''s API key for their requests\napp.post(''/api/chat'', async (req, res) => {\n  const userApiKey = await getUserApiKey(req.session.userId);\n\n  // Create a client with the user''s key\n  const userClient = new OpenRouter({\n    apiKey: userApiKey\n  });\n\n  const result = userClient.callModel({\n    model: ''openai/gpt-5-nano'',\n    input: req.body.message\n  });\n\n  const text = await result.getText();\n  res.json({ response: text });\n});\n```\n\n### Security Best Practices\n\n1. **Environment Variables**: Store API keys in environment variables, never in code\n2. **Key Rotation**: Rotate keys periodically using the key management API\n3. **Environment Separation**: Use different keys for development, staging, and production\n4. **OAuth for Users**: Use the OAuth PKCE flow for user-facing apps to avoid handling user credentials\n5. **Secure Storage**: Store user API keys encrypted in your database\n6. **Minimal Scope**: Create keys with only the permissions needed\n\n---\n\n## Core Concepts: callModel\n\nThe `callModel` function is the primary interface for text generation. It provides a unified, type-safe way to interact with any supported model.\n\n### Basic Usage\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Explain quantum computing in one sentence.'',\n});\n\nconst text = await result.getText();\n```\n\n### Key Benefits\n\n- **Type-safe parameters** with full IDE autocomplete\n- **Auto-generated from OpenAPI specs** - automatically updates with new models\n- **Multiple consumption patterns** - text, streaming, structured data\n- **Automatic tool execution** with multi-turn support\n\n---\n\n## Input Formats\n\nThe SDK accepts flexible input types for the `input` parameter:\n\n### String Input\nA simple string becomes a user message:\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Hello, how are you?''\n});\n```\n\n### Message Arrays\nFor multi-turn conversations:\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: [\n    { role: ''user'', content: ''What is the capital of France?'' },\n    { role: ''assistant'', content: ''The capital of France is Paris.'' },\n    { role: ''user'', content: ''What is its population?'' }\n  ]\n});\n```\n\n### Multimodal Content\nIncluding images and text:\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: [\n    {\n      role: ''user'',\n      content: [\n        { type: ''text'', text: ''What is in this image?'' },\n        { type: ''image_url'', image_url: { url: ''https://example.com/image.png'' } }\n      ]\n    }\n  ]\n});\n```\n\n### System Instructions\nUse the `instructions` parameter for system-level guidance:\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  instructions: ''You are a helpful coding assistant. Be concise.'',\n  input: ''How do I reverse a string in Python?''\n});\n```\n\n---\n\n## Response Methods\n\nThe result object provides multiple methods for consuming the response:\n\n| Method | Purpose |\n|--------|---------|\n| `getText()` | Get complete text after all tools complete |\n| `getResponse()` | Full response object with token usage |\n| `getTextStream()` | Stream text deltas as they arrive |\n| `getReasoningStream()` | Stream reasoning tokens (for o1/reasoning models) |\n| `getToolCallsStream()` | Stream tool calls as they complete |\n\n### getText()\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Write a haiku about coding''\n});\n\nconst text = await result.getText();\nconsole.log(text);\n```\n\n### getResponse()\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Hello!''\n});\n\nconst response = await result.getResponse();\nconsole.log(''Text:'', response.text);\nconsole.log(''Token usage:'', response.usage);\n```\n\n### getTextStream()\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Write a short story''\n});\n\nfor await (const delta of result.getTextStream()) {\n  process.stdout.write(delta);\n}\n```\n\n---\n\n## Tool System\n\nCreate strongly-typed tools using Zod schemas for automatic validation and type inference.\n\n### Defining Tools\n\n```typescript\nimport { tool } from ''@openrouter/sdk'';\nimport { z } from ''zod'';\n\nconst weatherTool = tool({\n  name: ''get_weather'',\n  description: ''Get current weather for a location'',\n  inputSchema: z.object({\n    location: z.string().describe(''City name''),\n    units: z.enum([''celsius'', ''fahrenheit'']).optional().default(''celsius'')\n  }),\n  outputSchema: z.object({\n    temperature: z.number(),\n    conditions: z.string(),\n    humidity: z.number()\n  }),\n  execute: async (params) => {\n    // Implement weather fetching logic\n    return {\n      temperature: 22,\n      conditions: ''Sunny'',\n      humidity: 45\n    };\n  }\n});\n```\n\n### Using Tools with callModel\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''What is the weather in Paris?'',\n  tools: [weatherTool]\n});\n\nconst text = await result.getText();\n// The SDK automatically executes the tool and continues the conversation\n```\n\n### Tool Types\n\n#### Regular Tools\nStandard execute functions that return a result:\n\n```typescript\nconst calculatorTool = tool({\n  name: ''calculate'',\n  description: ''Perform mathematical calculations'',\n  inputSchema: z.object({\n    expression: z.string()\n  }),\n  execute: async ({ expression }) => {\n    return { result: eval(expression) };\n  }\n});\n```\n\n#### Generator Tools\nYield progress events using `eventSchema`:\n\n```typescript\nconst searchTool = tool({\n  name: ''web_search'',\n  description: ''Search the web'',\n  inputSchema: z.object({ query: z.string() }),\n  eventSchema: z.object({\n    type: z.literal(''progress''),\n    message: z.string()\n  }),\n  outputSchema: z.object({ results: z.array(z.string()) }),\n  execute: async function* ({ query }) {\n    yield { type: ''progress'', message: ''Searching...'' };\n    yield { type: ''progress'', message: ''Processing results...'' };\n    return { results: [''Result 1'', ''Result 2''] };\n  }\n});\n```\n\n#### Manual Tools\nSet `execute: false` to handle tool calls yourself:\n\n```typescript\nconst manualTool = tool({\n  name: ''user_confirmation'',\n  description: ''Request user confirmation'',\n  inputSchema: z.object({ message: z.string() }),\n  execute: false\n});\n```\n\n---\n\n## Multi-Turn Conversations with Stop Conditions\n\nControl automatic tool execution with stop conditions:\n\n```typescript\nimport { stepCountIs, maxCost, hasToolCall } from ''@openrouter/sdk'';\n\nconst result = client.callModel({\n  model: ''openai/gpt-5.2'',\n  input: ''Research this topic thoroughly'',\n  tools: [searchTool, analyzeTool],\n  stopWhen: [\n    stepCountIs(10),      // Stop after 10 turns\n    maxCost(1.00),        // Stop if cost exceeds $1.00\n    hasToolCall(''finish'') // Stop when ''finish'' tool is called\n  ]\n});\n```\n\n### Available Stop Conditions\n\n| Condition | Description |\n|-----------|-------------|\n| `stepCountIs(n)` | Stop after n turns |\n| `maxCost(amount)` | Stop when cost exceeds amount |\n| `hasToolCall(name)` | Stop when specific tool is called |\n\n### Custom Stop Conditions\n\n```typescript\nconst customStop = (context) => {\n  return context.messages.length > 20;\n};\n\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Complex task'',\n  tools: [myTool],\n  stopWhen: customStop\n});\n```\n\n---\n\n## Dynamic Parameters\n\nCompute parameters based on conversation context:\n\n```typescript\nconst result = client.callModel({\n  model: (ctx) => ctx.numberOfTurns > 3 ? ''openai/gpt-4'' : ''openai/gpt-4o-mini'',\n  temperature: (ctx) => ctx.numberOfTurns > 1 ? 0.3 : 0.7,\n  input: ''Hello!''\n});\n```\n\n### Context Object Properties\n\n| Property | Type | Description |\n|----------|------|-------------|\n| `numberOfTurns` | number | Current turn count |\n| `messages` | array | All messages so far |\n| `instructions` | string | Current system instructions |\n| `totalCost` | number | Accumulated cost |\n\n---\n\n## nextTurnParams: Context Injection\n\nTools can modify parameters for subsequent turns, enabling skills and context-aware behavior:\n\n```typescript\nconst skillTool = tool({\n  name: ''load_skill'',\n  description: ''Load a specialized skill'',\n  inputSchema: z.object({\n    skill: z.string().describe(''Name of the skill to load'')\n  }),\n  nextTurnParams: {\n    instructions: (params, context) => {\n      const skillInstructions = loadSkillInstructions(params.skill);\n      return `${context.instructions}\\n\\n${skillInstructions}`;\n    }\n  },\n  execute: async ({ skill }) => {\n    return { loaded: skill };\n  }\n});\n```\n\n### Use Cases for nextTurnParams\n\n- **Skill Systems**: Dynamically load specialized capabilities\n- **Context Accumulation**: Build up context over multiple turns\n- **Mode Switching**: Change model behavior mid-conversation\n- **Memory Injection**: Add retrieved context to instructions\n\n---\n\n## Generation Parameters\n\nControl model behavior with these parameters:\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Write a creative story'',\n  temperature: 0.7,        // Creativity (0-2, default varies by model)\n  maxOutputTokens: 1000,   // Maximum tokens to generate\n  topP: 0.9,               // Nucleus sampling parameter\n  frequencyPenalty: 0.5,   // Reduce repetition\n  presencePenalty: 0.5,    // Encourage new topics\n  stop: [''\\n\\n'']           // Stop sequences\n});\n```\n\n---\n\n## Streaming\n\nAll streaming methods support concurrent consumers from a single result object:\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Write a detailed explanation''\n});\n\n// Consumer 1: Stream text to console\nconst textPromise = (async () => {\n  for await (const delta of result.getTextStream()) {\n    process.stdout.write(delta);\n  }\n})();\n\n// Consumer 2: Get full response simultaneously\nconst responsePromise = result.getResponse();\n\n// Both run concurrently\nconst [, response] = await Promise.all([textPromise, responsePromise]);\nconsole.log(''\\n\\nTotal tokens:'', response.usage.totalTokens);\n```\n\n### Streaming Tool Calls\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Search for information about TypeScript'',\n  tools: [searchTool]\n});\n\nfor await (const toolCall of result.getToolCallsStream()) {\n  console.log(`Tool called: ${toolCall.name}`);\n  console.log(`Arguments: ${JSON.stringify(toolCall.arguments)}`);\n  console.log(`Result: ${JSON.stringify(toolCall.result)}`);\n}\n```\n\n---\n\n## Format Conversion\n\nConvert between ecosystem formats for interoperability:\n\n### OpenAI Format\n\n```typescript\nimport { fromChatMessages, toChatMessage } from ''@openrouter/sdk'';\n\n// OpenAI messages → OpenRouter format\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: fromChatMessages(openaiMessages)\n});\n\n// Response → OpenAI chat message format\nconst response = await result.getResponse();\nconst chatMsg = toChatMessage(response);\n```\n\n### Claude Format\n\n```typescript\nimport { fromClaudeMessages, toClaudeMessage } from ''@openrouter/sdk'';\n\n// Claude messages → OpenRouter format\nconst result = client.callModel({\n  model: ''anthropic/claude-3-opus'',\n  input: fromClaudeMessages(claudeMessages)\n});\n\n// Response → Claude message format\nconst response = await result.getResponse();\nconst claudeMsg = toClaudeMessage(response);\n```\n\n---\n\n## Responses API Message Shapes\n\nThe SDK uses the **OpenResponses** format for messages. Understanding these shapes is essential for building robust agents.\n\n### Message Roles\n\nMessages contain a `role` property that determines the message type:\n\n| Role | Description |\n|------|-------------|\n| `user` | User-provided input |\n| `assistant` | Model-generated responses |\n| `system` | System instructions |\n| `developer` | Developer-level directives |\n| `tool` | Tool execution results |\n\n### Text Message\n\nSimple text content from user or assistant:\n\n```typescript\ninterface TextMessage {\n  role: ''user'' | ''assistant'';\n  content: string;\n}\n```\n\n### Multimodal Message (Array Content)\n\nMessages with mixed content types:\n\n```typescript\ninterface MultimodalMessage {\n  role: ''user'';\n  content: Array<\n    | { type: ''input_text''; text: string }\n    | { type: ''input_image''; imageUrl: string; detail?: ''auto'' | ''low'' | ''high'' }\n    | {\n        type: ''image'';\n        source: {\n          type: ''url'' | ''base64'';\n          url?: string;\n          media_type?: string;\n          data?: string\n        }\n      }\n  >;\n}\n```\n\n### Tool Function Call Message\n\nWhen the model requests a tool execution:\n\n```typescript\ninterface ToolCallMessage {\n  role: ''assistant'';\n  content?: null;\n  tool_calls?: Array<{\n    id: string;\n    type: ''function'';\n    function: {\n      name: string;\n      arguments: string;  // JSON-encoded arguments\n    };\n  }>;\n}\n```\n\n### Tool Result Message\n\nResult returned after tool execution:\n\n```typescript\ninterface ToolResultMessage {\n  role: ''tool'';\n  tool_call_id: string;\n  content: string;  // JSON-encoded result\n}\n```\n\n### Non-Streaming Response Structure\n\nThe complete response object from `getResponse()`:\n\n```typescript\ninterface OpenResponsesNonStreamingResponse {\n  output: Array<ResponseMessage>;\n  usage?: {\n    inputTokens: number;\n    outputTokens: number;\n    cachedTokens?: number;\n  };\n  finishReason?: string;\n  warnings?: Array<{\n    type: string;\n    message: string\n  }>;\n  experimental_providerMetadata?: Record<string, unknown>;\n}\n```\n\n### Response Message Types\n\nOutput messages in the response array:\n\n```typescript\n// Text/content message\ninterface ResponseOutputMessage {\n  type: ''message'';\n  role: ''assistant'';\n  content: string | Array<ContentPart>;\n  reasoning?: string;  // For reasoning models (o1, etc.)\n}\n\n// Tool result in output\ninterface FunctionCallOutputMessage {\n  type: ''function_call_output'';\n  call_id: string;\n  output: string;\n}\n```\n\n### Parsed Tool Call\n\nWhen tool calls are parsed from the response:\n\n```typescript\ninterface ParsedToolCall {\n  id: string;\n  name: string;\n  arguments: unknown;  // Validated against inputSchema\n}\n```\n\n### Tool Execution Result\n\nAfter a tool completes execution:\n\n```typescript\ninterface ToolExecutionResult {\n  toolCallId: string;\n  toolName: string;\n  result: unknown;                  // Validated against outputSchema\n  preliminaryResults?: unknown[];   // From generator tools\n  error?: Error;\n}\n```\n\n### Step Result (for Stop Conditions)\n\nAvailable in custom stop condition callbacks:\n\n```typescript\ninterface StepResult {\n  stepType: ''initial'' | ''continue'';\n  text: string;\n  toolCalls: ParsedToolCall[];\n  toolResults: ToolExecutionResult[];\n  response: OpenResponsesNonStreamingResponse;\n  usage?: {\n    inputTokens: number;\n    outputTokens: number;\n    cachedTokens?: number;\n  };\n  finishReason?: string;\n  warnings?: Array<{ type: string; message: string }>;\n  experimental_providerMetadata?: Record<string, unknown>;\n}\n```\n\n### TurnContext\n\nAvailable to tools and dynamic parameter functions:\n\n```typescript\ninterface TurnContext {\n  numberOfTurns: number;                     // Turn count (1-indexed)\n  turnRequest?: OpenResponsesRequest;        // Current request being made\n  toolCall?: OpenResponsesFunctionToolCall;  // Current tool call (in tool context)\n}\n```\n\n---\n\n## Event Shapes\n\nThe SDK provides multiple streaming methods that yield different event types.\n\n### Response Stream Events\n\nThe `getFullResponsesStream()` method yields these event types:\n\n```typescript\ntype EnhancedResponseStreamEvent =\n  | ResponseCreatedEvent\n  | ResponseInProgressEvent\n  | OutputTextDeltaEvent\n  | OutputTextDoneEvent\n  | ReasoningDeltaEvent\n  | ReasoningDoneEvent\n  | FunctionCallArgumentsDeltaEvent\n  | FunctionCallArgumentsDoneEvent\n  | ResponseCompletedEvent\n  | ToolPreliminaryResultEvent;\n```\n\n### Event Type Reference\n\n| Event Type | Description | Payload |\n|------------|-------------|---------|\n| `response.created` | Response object initialized | `{ response: ResponseObject }` |\n| `response.in_progress` | Generation has started | `{}` |\n| `response.output_text.delta` | Text chunk received | `{ delta: string }` |\n| `response.output_text.done` | Text generation complete | `{ text: string }` |\n| `response.reasoning.delta` | Reasoning chunk (o1 models) | `{ delta: string }` |\n| `response.reasoning.done` | Reasoning complete | `{ reasoning: string }` |\n| `response.function_call_arguments.delta` | Tool argument chunk | `{ delta: string }` |\n| `response.function_call_arguments.done` | Tool arguments complete | `{ arguments: string }` |\n| `response.completed` | Full response complete | `{ response: ResponseObject }` |\n| `tool.preliminary_result` | Generator tool progress | `{ toolCallId: string; result: unknown }` |\n\n### Text Delta Event\n\n```typescript\ninterface OutputTextDeltaEvent {\n  type: ''response.output_text.delta'';\n  delta: string;\n}\n```\n\n### Reasoning Delta Event\n\nFor reasoning models (o1, etc.):\n\n```typescript\ninterface ReasoningDeltaEvent {\n  type: ''response.reasoning.delta'';\n  delta: string;\n}\n```\n\n### Function Call Arguments Delta Event\n\n```typescript\ninterface FunctionCallArgumentsDeltaEvent {\n  type: ''response.function_call_arguments.delta'';\n  delta: string;\n}\n```\n\n### Tool Preliminary Result Event\n\nFrom generator tools that yield progress:\n\n```typescript\ninterface ToolPreliminaryResultEvent {\n  type: ''tool.preliminary_result'';\n  toolCallId: string;\n  result: unknown;  // Matches the tool''s eventSchema\n}\n```\n\n### Response Completed Event\n\n```typescript\ninterface ResponseCompletedEvent {\n  type: ''response.completed'';\n  response: OpenResponsesNonStreamingResponse;\n}\n```\n\n### Tool Stream Events\n\nThe `getToolStream()` method yields:\n\n```typescript\ntype ToolStreamEvent =\n  | { type: ''delta''; content: string }\n  | { type: ''preliminary_result''; toolCallId: string; result: unknown };\n```\n\n### Example: Processing Stream Events\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Analyze this data'',\n  tools: [analysisTool]\n});\n\nfor await (const event of result.getFullResponsesStream()) {\n  switch (event.type) {\n    case ''response.output_text.delta'':\n      process.stdout.write(event.delta);\n      break;\n\n    case ''response.reasoning.delta'':\n      console.log(''[Reasoning]'', event.delta);\n      break;\n\n    case ''response.function_call_arguments.delta'':\n      console.log(''[Tool Args]'', event.delta);\n      break;\n\n    case ''tool.preliminary_result'':\n      console.log(`[Progress: ${event.toolCallId}]`, event.result);\n      break;\n\n    case ''response.completed'':\n      console.log(''\\n[Complete]'', event.response.usage);\n      break;\n  }\n}\n```\n\n### Message Stream Events\n\nThe `getNewMessagesStream()` yields OpenResponses format updates:\n\n```typescript\ntype MessageStreamUpdate =\n  | ResponsesOutputMessage        // Text/content updates\n  | OpenResponsesFunctionCallOutput;  // Tool results\n```\n\n### Example: Tracking New Messages\n\n```typescript\nconst result = client.callModel({\n  model: ''openai/gpt-5-nano'',\n  input: ''Research this topic'',\n  tools: [searchTool]\n});\n\nconst allMessages: MessageStreamUpdate[] = [];\n\nfor await (const message of result.getNewMessagesStream()) {\n  allMessages.push(message);\n\n  if (message.type === ''message'') {\n    console.log(''Assistant:'', message.content);\n  } else if (message.type === ''function_call_output'') {\n    console.log(''Tool result:'', message.output);\n  }\n}\n```\n\n---\n\n## API Reference\n\n### Client Methods\n\nBeyond `callModel`, the client provides access to other API endpoints:\n\n```typescript\nconst client = new OpenRouter({\n  apiKey: process.env.OPENROUTER_API_KEY\n});\n\n// List available models\nconst models = await client.models.list();\n\n// Chat completions (alternative to callModel)\nconst completion = await client.chat.send({\n  model: ''openai/gpt-5-nano'',\n  messages: [{ role: ''user'', content: ''Hello!'' }]\n});\n\n// Legacy completions format\nconst legacyCompletion = await client.completions.generate({\n  model: ''openai/gpt-5-nano'',\n  prompt: ''Once upon a time''\n});\n\n// Usage analytics\nconst activity = await client.analytics.getUserActivity();\n\n// Credit balance\nconst credits = await client.credits.getCredits();\n\n// API key management\nconst keys = await client.apiKeys.list();\n```\n\n---\n\n## Error Handling\n\nThe SDK provides specific error types with actionable messages:\n\n```typescript\ntry {\n  const result = await client.callModel({\n    model: ''openai/gpt-5-nano'',\n    input: ''Hello!''\n  });\n  const text = await result.getText();\n} catch (error) {\n  if (error.statusCode === 401) {\n    console.error(''Invalid API key - check your OPENROUTER_API_KEY'');\n  } else if (error.statusCode === 402) {\n    console.error(''Insufficient credits - add credits at openrouter.ai'');\n  } else if (error.statusCode === 429) {\n    console.error(''Rate limited - implement backoff retry'');\n  } else if (error.statusCode === 503) {\n    console.error(''Model temporarily unavailable - try again or use fallback'');\n  } else {\n    console.error(''Unexpected error:'', error.message);\n  }\n}\n```\n\n### Error Status Codes\n\n| Code | Meaning | Action |\n|------|---------|--------|\n| 400 | Bad request | Check request parameters |\n| 401 | Unauthorized | Verify API key |\n| 402 | Payment required | Add credits |\n| 429 | Rate limited | Implement exponential backoff |\n| 500 | Server error | Retry with backoff |\n| 503 | Service unavailable | Try alternative model |\n\n---\n\n## Complete Example: Agent with Tools\n\n```typescript\nimport OpenRouter, { tool, stepCountIs } from ''@openrouter/sdk'';\nimport { z } from ''zod'';\n\nconst client = new OpenRouter({\n  apiKey: process.env.OPENROUTER_API_KEY\n});\n\n// Define tools\nconst searchTool = tool({\n  name: ''web_search'',\n  description: ''Search the web for information'',\n  inputSchema: z.object({\n    query: z.string().describe(''Search query'')\n  }),\n  outputSchema: z.object({\n    results: z.array(z.object({\n      title: z.string(),\n      snippet: z.string(),\n      url: z.string()\n    }))\n  }),\n  execute: async ({ query }) => {\n    // Implement actual search\n    return {\n      results: [\n        { title: ''Example'', snippet: ''Example result'', url: ''https://example.com'' }\n      ]\n    };\n  }\n});\n\nconst finishTool = tool({\n  name: ''finish'',\n  description: ''Complete the task with final answer'',\n  inputSchema: z.object({\n    answer: z.string().describe(''The final answer'')\n  }),\n  execute: async ({ answer }) => ({ answer })\n});\n\n// Run agent\nasync function runAgent(task: string) {\n  const result = client.callModel({\n    model: ''openai/gpt-5-nano'',\n    instructions: ''You are a helpful research assistant. Use web_search to find information, then use finish to provide your final answer.'',\n    input: task,\n    tools: [searchTool, finishTool],\n    stopWhen: [\n      stepCountIs(10),\n      hasToolCall(''finish'')\n    ]\n  });\n\n  // Stream progress\n  for await (const toolCall of result.getToolCallsStream()) {\n    console.log(`[${toolCall.name}] ${JSON.stringify(toolCall.arguments)}`);\n  }\n\n  return await result.getText();\n}\n\n// Usage\nconst answer = await runAgent(''What are the latest developments in quantum computing?'');\nconsole.log(''Final answer:'', answer);\n```\n\n---\n\n## Best Practices\n\n### 1. Prefer callModel Over Direct API Calls\nThe `callModel` pattern provides automatic tool execution, type safety, and multi-turn handling.\n\n### 2. Use Zod for Tool Schemas\nZod provides runtime validation and excellent TypeScript inference:\n\n```typescript\nimport { z } from ''zod'';\n\nconst schema = z.object({\n  name: z.string().min(1),\n  age: z.number().int().positive()\n});\n```\n\n### 3. Implement Stop Conditions\nAlways set reasonable limits to prevent runaway costs:\n\n```typescript\nstopWhen: [stepCountIs(20), maxCost(5.00)]\n```\n\n### 4. Handle Errors Gracefully\nImplement retry logic for transient failures:\n\n```typescript\nasync function callWithRetry(params, maxRetries = 3) {\n  for (let i = 0; i < maxRetries; i++) {\n    try {\n      return await client.callModel(params).getText();\n    } catch (error) {\n      if (error.statusCode === 429 || error.statusCode >= 500) {\n        await sleep(Math.pow(2, i) * 1000);\n        continue;\n      }\n      throw error;\n    }\n  }\n}\n```\n\n### 5. Use Streaming for Long Responses\nStreaming provides better UX and allows early termination:\n\n```typescript\nfor await (const delta of result.getTextStream()) {\n  // Process incrementally\n}\n```\n\n---\n\n## Additional Resources\n\n- **API Keys**: [openrouter.ai/settings/keys](https://openrouter.ai/settings/keys)\n- **Model List**: [openrouter.ai/models](https://openrouter.ai/models)\n- **GitHub Issues**: [github.com/OpenRouterTeam/typescript-sdk/issues](https://github.com/OpenRouterTeam/typescript-sdk/issues)\n\n---\n\n*SDK Status: Beta - Report issues on GitHub*\n"},"lastSynced":"2026-03-08T02:09:20.437Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing unified access to 300+ AI models through a type-safe interface.","zh":"适合需要通过类型安全接口统一访问300+ AI模型的AI代理。","ja":"300以上のAIモデルへの統一されたアクセスを必要とするAIエージェントに最適です。","ko":"300개 이상의 AI 모델에 대한 통일된 접근을 필요로 하는 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan acceso unificado a más de 300 modelos de IA a través de una interfaz segura de tipos.","fr":"Parfait pour les agents IA ayant besoin d''un accès unifié à plus de 300 modèles d''IA via une interface sécurisée de types.","de":"Perfekt für KI-Agents, die einen einheitlichen Zugriff auf über 300 KI-Modelle durch eine typsichere Schnittstelle benötigen.","pt":"Perfeito para Agentes de IA que necessitam de acesso unificado a mais de 300 modelos de IA através de uma interface type-safe.","ru":"Идеально подходит для ИИ-агентов, которым требуется унифицированный доступ к более чем 300 моделям ИИ через типобезопасный интерфейс.","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يحتاجون إلى وصول موحد إلى أكثر من 300 نموذج ذكاء اصطناعي من خلال واجهة type-safe."},"recommendation":{"en":"Empowers agents to leverage the `callModel` pattern for text generation, tool usage, streaming, and multi-turn conversations using OpenRouter''s unified API and TypeScript SDK, enabling seamless interaction with a wide range of AI models.","zh":"赋予代理使用`callModel`模式进行文本生成、工具使用、流媒体和多回合对话的能力，使用OpenRouter的统一API和TypeScript SDK，从而实现与广泛的AI模型的无缝交互。","ja":"OpenRouterの統一APIとTypeScript SDKを使用して、`callModel`パターンを利用し、テキスト生成、ツールの使用、ストリーミング、複数回の会話を行うことができるため、幅広いAIモデルとのシームレスなやり取りを可能にします。","ko":"OpenRouter의 통일된 API와 TypeScript SDK를 사용하여 `callModel` 패턴을 활용하여 텍스트 생성, 툴 사용, 스트리밍, 다회 대화를 할 수 있으므로 광범위한 AI 모델과 무결점 상호작용을 가능하게 합니다.","es":"Habilita a los agentes a aprovechar el patrón `callModel` para la generación de texto, el uso de herramientas, la transmisión y las conversaciones de varias vueltas utilizando la API unificada de OpenRouter y el SDK de TypeScript, lo que permite una interacción sin problemas con una amplia gama de modelos de IA.","fr":"Permet aux agents d''exploiter le modèle `callModel` pour la génération de texte, l''utilisation d''outils, la diffusion et les conversations à plusieurs tours en utilisant l''API unifiée d''OpenRouter et le SDK TypeScript, permettant ainsi une interaction transparente avec une large gamme de modèles d''IA.","de":"Ermächtigt Agents, das `callModel`-Muster für Texterstellung, Toolnutzung, Streaming und Mehrfachgespräche unter Verwendung der einheitlichen OpenRouter-API und des TypeScript-SDKs zu nutzen, wodurch eine nahtlose Interaktion mit einer breiten Palette von KI-Modellen ermöglicht wird.","pt":"Permite que os agentes aproveitem o padrão `callModel` para geração de texto, uso de ferramentas, streaming e conversas multi-turn usando a API unificada e o TypeScript SDK do OpenRouter, permitindo uma interação perfeita com uma ampla gama de modelos de IA.","ru":"Позволяет агентам использовать шаблон `callModel` для генерации текста, использования инструментов, потоковой передачи и многоходовых бесед с использованием унифицированного API OpenRouter и TypeScript SDK, обеспечивая беспрерывное взаимодействие с широким спектром моделей ИИ.","ar":"يمكن الوكلاء من الاستفادة من نمط `callModel` لتوليد النص، واستخدام الأدوات، والبث المباشر (streaming)، والمحادثات متعددة الجولات باستخدام واجهة برمجة التطبيقات (API) الموحدة من OpenRouter ومجموعة تطوير البرامج (SDK) الخاصة بـ TypeScript، مما يمكن التفاعل السلس مع مجموعة واسعة من نماذج الذكاء الاصطناعي."},"useCases":{"en":["Automating text generation tasks across multiple AI models","Integrating tool usage and streaming capabilities into agent workflows","Facilitating multi-turn conversations with users through a unified API","Accessing and utilizing 300+ AI models for diverse applications"],"zh":["跨多个AI模型自动执行文本生成任务","将工具使用和流媒体功能集成到代理工作流中","通过统一API与用户进行多回合对话","访问和利用300+ AI模型进行多样化应用"],"ja":["複数のAIモデルを横断してテキスト生成タスクを自動化する","ツールの使用とストリーミング機能をエージェントのワークフローに統合する","統一APIを使用してユーザーと複数回の会話を行う","300以上のAIモデルにアクセスして利用し、多様なアプリケーションを実現する"],"ko":["여러 AI 모델을跨越하여 텍스트 생성 작업을 자동화한다","툴 사용과 스트리밍 기능을 에이전트 워크플로에 통합한다","통일된 API를 사용하여 사용자와 다회 대화를 한다","300개 이상의 AI 모델에 접근하여 다양하게 활용한다"],"es":["Automatizar tareas de generación de texto en varios modelos de IA","Integrar capacidades de uso de herramientas y transmisión en flujos de trabajo de agentes","Facilitar conversaciones de varias vueltas con usuarios a través de una API unificada","Acceder y utilizar más de 300 modelos de IA para aplicaciones diversas"],"fr":["Automatiser les tâches de génération de texte sur plusieurs modèles d''IA","Intégrer les capacités d''utilisation d''outils et de diffusion dans les flux de travail des agents","Faciliter les conversations à plusieurs tours avec les utilisateurs via une API unifiée","Accéder et utiliser plus de 300 modèles d''IA pour des applications diverses"],"de":["Automatisierung von Texterstellungsaufgaben über mehrere KI-Modelle hinweg","Integration von Toolnutzungs- und Streamingfunktionen in Agenten-Workflows","Erleichterung von Mehrfachgesprächen mit Benutzern über eine einheitliche API","Zugriff auf und Nutzung von über 300 KI-Modellen für verschiedene Anwendungen"],"pt":["Automatização de tarefas de geração de texto em vários modelos de IA","Integração de uso de ferramentas e capacidades de streaming em fluxos de trabalho de agentes","Facilitação de conversas multi-turn com usuários por meio de uma API unificada","Acesso e utilização de mais de 300 modelos de IA para diversas aplicações"],"ru":["Автоматизация задач генерации текста с использованием нескольких моделей ИИ","Интеграция использования инструментов и возможностей потоковой передачи в рабочие процессы агентов","Обеспечение многоходовых бесед с пользователями через унифицированный API","Доступ и использование более чем 300 моделей ИИ для различных приложений"],"ar":["أتمتة مهام توليد النص عبر نماذج ذكاء اصطناعي متعددة","دمج قدرات استخدام الأدوات والبث المباشر (streaming) في سير عمل الوكلاء","تسهيل المحادثات متعددة الجولات مع المستخدمين من خلال واجهة برمجة تطبيقات (API) موحدة","الوصول إلى أكثر من 300 نموذج ذكاء اصطناعي واستخدامها لتطبيقات متنوعة"]},"limitations":{"en":["Requires an OpenRouter API key","Dependent on OpenRouter''s unified API and TypeScript SDK","Limited to models available through OpenRouter''s platform"],"zh":["需要OpenRouter API密钥","依赖于OpenRouter的统一API和TypeScript SDK","仅限于OpenRouter平台上可用的模型"],"ja":["OpenRouter APIキーが必要","OpenRouterの統一APIとTypeScript SDKに依存する","OpenRouterプラットフォームで利用可能なモデルに限定される"],"ko":["OpenRouter API 키가 필요하다","OpenRouter의 통일된 API와 TypeScript SDK에 의존한다","OpenRouter 플랫폼에서 사용 가능한 모델만 사용할 수 있다"],"es":["Requiere una clave de API de OpenRouter","Depende de la API unificada de OpenRouter y del SDK de TypeScript","Limitado a los modelos disponibles a través de la plataforma de OpenRouter"],"fr":["Nécessite une clé d''API d''OpenRouter","Dépend de l''API unifiée d''OpenRouter et du SDK TypeScript","Limité aux modèles disponibles via la plateforme d''OpenRouter"],"de":["Benötigt einen OpenRouter-API-Schlüssel","Hängt von der einheitlichen OpenRouter-API und dem TypeScript-SDK ab","Begrenzt auf Modelle, die über die OpenRouter-Plattform verfügbar sind"],"pt":["Requer uma chave de API do OpenRouter","Dependente da API unificada e do TypeScript SDK do OpenRouter","Limitado aos modelos disponíveis na plataforma do OpenRouter"],"ru":["Требуется ключ API OpenRouter","Зависит от унифицированного API OpenRouter и TypeScript SDK","Ограничено моделями, доступными на платформе OpenRouter"],"ar":["يتطلب مفتاح واجهة برمجة تطبيقات (API) من OpenRouter","يعتمد على واجهة برمجة التطبيقات (API) الموحدة من OpenRouter ومجموعة تطوير البرامج (SDK) الخاصة بـ TypeScript","يقتصر على النماذج المتاحة عبر منصة OpenRouter"]},"version":4},"contentHash":"f15f74cb7ba16a93465a78a9e1a009b06cd0847d38cf907ae6e2c3bd11e2cbe6","qualityScore":65}');
