INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('regybean/ChatGBeanT/openrouter-typescript-sdk', 'openrouter-typescript-sdk', 'regybean', 'ChatGBeanT', 'community', 'openrouter-typescript-sdk regybean ChatGBeanT community The openrouter-typescript-sdk provides a comprehensive TypeScript interface for interacting with OpenRouter''s unified API, benefiting AI agents and developers. It enables access to 300+ AI models through a single, type-safe interface. OpenRouter TypeScript SDK 是一个全面性的 TypeScript SDK，用于与 OpenRouter 的统一 API 交互，提供访问 300+ AI 模型的能力 OpenRouter TypeScript SDK は、OpenRouter の統一 API と相互作用するための包括的な TypeScript SDK です。300+ の AI モデルへのアクセスを提供します OpenRouter TypeScript SDK는 OpenRouter의 통합 API와 상호 작용하기 위한 포괄적인 TypeScript SDK입니다. 300+ AI 모델에 대한 액세스를 제공합니다 El SDK de TypeScript de OpenRouter ofrece acceso a 300+ modelos de IA a través de una interfaz segura y tipada. Con esta habilidad, los agentes de IA pueden aprovechar el patrón de llamada de modelo para la generación de texto, el uso de herramientas y las conversaciones de varios giros. Le SDK TypeScript d''OpenRouter offre un accès à 300+ modèles d''IA via une interface sécurisée et typée. Avec cette compétence, les agents IA peuvent exploiter le modèle d''appel pour la génération de texte, l''utilisation d''outils et les conversations à plusieurs tours. Das TypeScript-SDK von OpenRouter bietet Zugriff auf 300+ KI-Modelle über eine sichere und typsichere Schnittstelle. Mit dieser Fähigkeit können KI-Agents den Call-Model-Muster für Textgenerierung, Tool-Nutzung und Mehrfach-Gespräche nutzen. O OpenRouter TypeScript SDK é uma biblioteca completa para interagir com a API unificada do OpenRouter, fornecendo acesso a 300+ modelos de IA OpenRouter TypeScript SDK - это комплексная библиотека для взаимодействия с унифицированным API OpenRouter, обеспечивающая доступ к 300+ моделям ИИ OpenRouter TypeScript SDK هو مكتبة شاملة للتفاعل مع واجهة برمجة التطبيقات الموحدة من OpenRouter، ويوفر الوصول إلى 300+ نموذج الذكاء الاصطناعي how to use openrouter-typescript-sdk openrouter-typescript-sdk setup guide openrouter-typescript-sdk alternative openrouter-typescript-sdk vs other AI SDKs install openrouter-typescript-sdk openrouter-typescript-sdk tutorial what is openrouter-typescript-sdk openrouter-typescript-sdk documentation OpenRouter TypeScript SDK AI 模型 统一 API 类型安全 文本生成 工具使用 流媒体 多回合对话 callModel npm Provides access to 300+ AI models through a unified API Supports the callModel pattern for text generation, tool usage, streaming, and multi-turn conversations Offers a type-safe interface for interacting with OpenRouter''s API Enables installation via npm using the @openrouter/sdk package Requires API key initialization from openrouter.ai/settings/keys openrouter-typescript-sdk is a TypeScript SDK for interacting with OpenRouter''s unified API, providing access to multiple AI models through a type-safe interface.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chenjiongwei/zjsy/digital-brain', 'community', 'chenjiongwei', 'zjsy', 'chenjiongwei/zjsy', 'digital-brain', 0, 0, 65, '2026-03-08T01:57:15.513Z', '2026-03-08T02:10:29.633Z', '39ed6cd20dd787b6c71397aa0f75619887ed774c0fd390439d8e535f54bb3544', '{"id":"chenjiongwei/zjsy/digital-brain","name":"digital-brain","description":{"en":"Digital-brain is a structured personal operating system for managing digital presence, knowledge, and goals with AI assistance, designed for founders and content creators. It uses progressive disclosure for efficient task management.","zh":"数字大脑是一种用于管理数字存在、知识、关系和目标的结构化个人操作系统，具有AI辅助功能。它适用于公开建立的创始人、内容创作者和寻求AI辅助个人管理的技术专业人员","ja":"デジタルブレインは、AIアシスト機能を備えた、デジタル存在、知識、関係、目標を管理するための構造化されたパーソナルオペレーティングシステムです。公開で構築する創業者、オーディエンスを育てているコンテンツクリエイター、AIアシストによるパーソナルマネジメントを求めるテクノロジーに精通した専門家向けに設計されています","ko":"디지털 브레인은 디지털 존재, 지식, 관계, 목표를 관리하는 구조화된 개인 운영 체제로 AI 보조 기능을 제공합니다. 공개적으로 구축하는 창업자, 오디언스를 키우는 콘텐츠 크리에이터, AI 보조 개인 관리를 찾는 기술에精通한 전문가들을 위해 설계되었습니다","es":"Digital Brain es un sistema operativo personal que gestiona tu presencia digital con asistencia de AI. Está diseñado para fundadores, creadores de contenido y profesionales técnicos","fr":"Digital Brain est un système d''exploitation personnel qui gère votre présence numérique avec assistance IA. Il est conçu pour les fondateurs, les créateurs de contenu et les professionnels techniques","de":"Digital Brain ist ein persönliches Betriebssystem, das Ihre digitale Präsenz mit KI-Unterstützung verwaltet. Es ist für Gründer, Content-Ersteller und technische Fachleute konzipiert","pt":"O Digital Brain é um sistema de operação pessoal que gerencia presença digital, conhecimento, relacionamentos e metas com assistência de IA. Desenvolvido para fundadores que constroem em público, criadores de conteúdo e profissionais de tecnologia","ru":"Цифровой Мозг - это личная операционная система, которая управляет цифровым присутствием, знаниями, отношениями и целями с помощью ИИ Агентов. Разработана для основателей, создающих в öffentliche, создателей контента и технических специалистов","ar":"المخ الرقمي هو نظام تشغيل شخصي يدير التواجد الرقمي والمعرفة والعلاقات والأهداف بالذكاء الاصطناعي. تم تطويره لمؤسسي الشركات التي تبني بشكل عام، ومُطوّري المحتوى والمختصين في مجال التكنولوجيا"},"seo":{"title":{"en":"Digital-Brain: Structured Personal Operating System Setup...","zh":"数字大脑设置指南 - AI工具","ja":"デジタルブレイン設定ガイド - AIエージェント","ko":"디지털 브레인 설정 가이드 - AI 에이전트","es":"Digital Brain: Guía de configuración para gestión de pres...","fr":"Digital Brain: Guide de mise en route pour la gestion de ...","de":"Digital Brain: Einrichtungsleitfaden für digitale Präsenz...","pt":"Digital Brain: Guia de Configuração de Sistemas de Operaç...","ru":"Цифровой Мозг: Руководство по Настройке Личной Операционн...","ar":"المخ الرقمي: دليل إعداد نظام تشغيل شخصي بالذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of digital-brain, a personal OS for founders and creators. Learn how to activate and use progressive disclosure for AI-assisted man...","zh":"数字大脑是一种结构化的个人操作系统，用于管理数字存在、知识、关系和目标，具有AI辅助功能。了解如何设置和使用","ja":"デジタルブレインは、AIアシスト機能を備えた、デジタル存在、知識、関係、目標を管理するための構造化されたパーソナルオペレーティングシステムです。設定方法と使用法を学びましょう","ko":"디지털 브레인은 디지털 존재, 지식, 관계, 목표를 관리하는 구조화된 개인 운영 체제로 AI 보조 기능을 제공합니다. 설정 방법과 사용 방법을 알아보세요","es":"Aprende a configurar Digital Brain, un sistema operativo personal estructurado para gestionar tu presencia digital con asistencia de AI. Descubre cómo optimi...","fr":"Découvrez comment configurer Digital Brain, un système d''exploitation personnel structuré pour gérer votre présence numérique avec assistance IA. Améliorez v...","de":"Erfahren Sie, wie Sie Digital Brain einrichten, ein strukturiertes persönliches Betriebssystem für die Verwaltung Ihrer digitalen Präsenz mit KI-Unterstützun...","pt":"Aprenda a configurar o Digital Brain, um sistema de operação pessoal estruturado para gerenciar presença digital, conhecimento, relacionamentos e metas com a...","ru":"Узнайте, как настроить Цифровой Мозг, структурированную личную операционную систему для управления цифровым присутствием, знаниями, отношениями и целями с по...","ar":"تعلم كيفية إعداد المخ الرقمي، نظام تشغيل شخصي منظم لادارة التواجد الرقمي والمعرفة والعلاقات والأهداف بالذكاء الاصطناعي"},"definition":{"en":"Digital-brain is a personal operating system that utilizes AI assistance for managing digital presence, knowledge, relationships, and goals.","zh":"数字大脑是一种AI辅助的个人操作系统","ja":"デジタルブレインは、AIアシスト機能を備えたパーソナルオペレーティングシステムです","ko":"디지털 브레인은 AI 보조 기능을 갖춘 개인 운영 체제입니다","es":"Digital Brain es un sistema operativo personal que utiliza la asistencia de AI para gestionar la presencia digital","fr":"Digital Brain est un système d''exploitation personnel qui utilise l''assistance IA pour gérer la présence numérique","de":"Digital Brain ist ein persönliches Betriebssystem, das die KI-Unterstützung zur Verwaltung der digitalen Präsenz nutzt","pt":"O Digital Brain é um sistema de operação pessoal que utiliza assistência de IA para gerenciar presença digital, conhecimento, relacionamentos e metas","ru":"Цифровой Мозг - это личная операционная система, которая использует помощь ИИ Агентов для управления цифровым присутствием, знаниями, отношениями и целями","ar":"المخ الرقمي هو نظام تشغيل شخصي يستخدم الذكاء الاصطناعي لإدارة التواجد الرقمي والمعرفة والعلاقات والأهداف"},"features":{"en":["Utilizes progressive disclosure for efficient task management","Designed for founders building in public and content creators growing their audience","Supports module-specific instructions in each subdirectory''s .md file","Loads only necessary components for the current task","Activates AI-assisted personal management for tech-savvy professionals","Manages digital presence, knowledge, relationships, and goals in a structured manner"],"zh":["结构化的个人操作系统","AI辅助功能","数字存在管理","知识管理","关系管理","目标管理"],"ja":["構造化されたパーソナルオペレーティングシステム","AIアシスト機能","デジタル存在管理","知識管理","関係管理","目標管理"],"ko":["구조화된 개인 운영 체제","AI 보조 기능","디지털 존재 관리","지식 관리","관계 관리","목표 관리"],"es":["Gestión de presencia digital con asistencia de AI","Diseñado para fundadores y creadores de contenido","Utiliza la técnica de progresive disclosure","Carga solo lo necesario para la tarea actual","Incluye instrucciones específicas en cada subdirectorio"],"fr":["Gestion de la présence numérique avec assistance IA","Conçu pour les fondateurs et les créateurs de contenu","Utilise la technique de progressive disclosure","Ne charge que ce qui est nécessaire pour la tâche en cours","Inclut des instructions spécifiques dans chaque sous-répertoire"],"de":["Verwaltung der digitalen Präsenz mit KI-Unterstützung","Konzipiert für Gründer und Content-Ersteller","Nutzt die Technik der progressiven Disclosure","Lädt nur das Notwendige für die aktuelle Aufgabe","Enthält spezifische Anweisungen in jedem Unterordner"],"pt":["Gerenciamento de presença digital com assistência de IA","Organização de conhecimento e relacionamentos","Definição de metas e objetivos com suporte de IA","Utilização de progressive disclosure para carregar apenas o necessário","Suporte a desenvolvedores e criadores de conteúdo"],"ru":["Управление цифровым присутствием с помощью ИИ Агентов","Организация знаний и отношений","Определение целей и задач с поддержкой ИИ","Использование прогрессивного раскрытия для загрузки только необходимого","Поддержка разработчиков и создателей контента"],"ar":["إدارة التواجد الرقمي بالذكاء الاصطناعي","تنظيم المعرفة والعلاقات","تعريف الأهداف والغايات بدعم من الذكاء الاصطناعي","استخدام الإفصاح التدريجي لتحميل ما هو ضروري فقط","دعم المطورين ومطوّري المحتوى"]},"keywords":{"en":["how to use digital-brain","what is digital-brain","digital-brain alternative","digital-brain vs personal OS","digital-brain install guide","digital-brain setup for founders","digital-brain AI assistance","progressive disclosure in digital-brain","digital-brain for content creators","digital-brain personal management"],"zh":["数字大脑","AI工具","个人操作系统","数字存在管理","知识管理","关系管理","目标管理","AI辅助功能"],"ja":["デジタルブレイン","AIエージェント","パーソナルオペレーティングシステム","デジタル存在管理","知識管理","関係管理","目標管理","AIアシスト機能"],"ko":["디지털 브레인","AI 에이전트","개인 운영 체제","디지털 존재 관리","지식 관리","관계 관리","목표 관리","AI 보조 기능"],"es":["Digital Brain","asistencia de AI","gestión de presencia digital","fundadores","creadores de contenido","progresive disclosure","sistema operativo personal","productividad"],"fr":["Digital Brain","assistance IA","gestion de la présence numérique","fondateurs","créateurs de contenu","progressive disclosure","système d''exploitation personnel","productivité"],"de":["Digital Brain","KI-Unterstützung","Verwaltung der digitalen Präsenz","Gründer","Content-Ersteller","progressive Disclosure","persönliches Betriebssystem","Produktivität"],"pt":["Digital Brain","IA","sistema de operação pessoal","gerenciamento de presença digital","organização de conhecimento","definição de metas","progressive disclosure","desenvolvedores","criadores de conteúdo"],"ru":["Цифровой Мозг","ИИ Агенты","личная операционная система","управление цифровым присутствием","организация знаний","определение целей","прогрессивное раскрытие","разработчики","создатели контента"],"ar":["المخ الرقمي","الذكاء الاصطناعي","نظام تشغيل شخصي","إدارة التواجد الرقمي","تنظيم المعرفة","تعريف الأهداف","الإفصاح التدريجي","المطورون","مطوّرو المحتوى"]}},"owner":"chenjiongwei","repo":"zjsy","repoPath":"chenjiongwei/zjsy","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.513Z","topics":[],"category":"community","skillMd":{"name":"digital-brain","description":"This skill should be used when the user asks to write a post, check my voice, look up contact, prepare for meeting, weekly review, track goals, or mentions personal brand, content creation, network management, or voice consistency.","version":"1.0.0","bodyPreview":"# Digital Brain\n\nA structured personal operating system for managing digital presence, knowledge, relationships, and goals with AI assistance. Designed for founders building in public, content creators growing their audience, and tech-savvy professionals seeking AI-assisted personal management.\n\n**Important**: This skill uses progressive disclosure. Module-specific instructions are in each subdirectory''s `.md` file. Only load what''s needed for the current task.\n\n## When to Activate\n\nActivate thi","body":"# Digital Brain\n\nA structured personal operating system for managing digital presence, knowledge, relationships, and goals with AI assistance. Designed for founders building in public, content creators growing their audience, and tech-savvy professionals seeking AI-assisted personal management.\n\n**Important**: This skill uses progressive disclosure. Module-specific instructions are in each subdirectory''s `.md` file. Only load what''s needed for the current task.\n\n## When to Activate\n\nActivate this skill when the user:\n\n- Requests content creation (posts, threads, newsletters) - load identity/voice.md first\n- Asks for help with personal brand or positioning\n- Needs to look up or manage contacts/relationships\n- Wants to capture or develop content ideas\n- Requests meeting preparation or follow-up\n- Asks for weekly reviews or goal tracking\n- Needs to save or retrieve bookmarked resources\n- Wants to organize research or learning materials\n\n**Trigger phrases**: \"write a post\", \"my voice\", \"content ideas\", \"who is [name]\", \"prepare for meeting\", \"weekly review\", \"save this\", \"my goals\"\n\n## Core Concepts\n\n### Progressive Disclosure Architecture\n\nThe Digital Brain follows a three-level loading pattern:\n\n| Level | When Loaded | Content |\n|-------|-------------|---------|\n| **L1: Metadata** | Always | This SKILL.md overview |\n| **L2: Module Instructions** | On-demand | `[module]/[MODULE].md` files |\n| **L3: Data Files** | As-needed | `.jsonl`, `.yaml`, `.md` data |\n\n### File Format Strategy\n\nFormats chosen for optimal agent parsing:\n\n- **JSONL** (`.jsonl`): Append-only logs - ideas, posts, contacts, interactions\n- **YAML** (`.yaml`): Structured configs - goals, values, circles\n- **Markdown** (`.md`): Narrative content - voice, brand, calendar, todos\n- **XML** (`.xml`): Complex prompts - content generation templates\n\n### Append-Only Data Integrity\n\nJSONL files are **append-only**. Never delete entries:\n- Mark as `\"status\": \"archived\"` instead of deleting\n- Preserves history for pattern analysis\n- Enables \"what worked\" retrospectives\n\n## Detailed Topics\n\n### Module Overview\n\n```\ndigital-brain/\n├── identity/     → Voice, brand, values (READ FIRST for content)\n├── content/      → Ideas, drafts, posts, calendar\n├── knowledge/    → Bookmarks, research, learning\n├── network/      → Contacts, interactions, intros\n├── operations/   → Todos, goals, meetings, metrics\n└── agents/       → Automation scripts\n```\n\n### Identity Module (Critical for Content)\n\n**Always read `identity/voice.md` before generating any content.**\n\nContains:\n- `voice.md` - Tone, style, vocabulary, patterns\n- `brand.md` - Positioning, audience, content pillars\n- `values.yaml` - Core beliefs and principles\n- `bio-variants.md` - Platform-specific bios\n- `prompts/` - Reusable generation templates\n\n### Content Module\n\nPipeline: `ideas.jsonl` → `drafts/` → `posts.jsonl`\n\n- Capture ideas immediately to `ideas.jsonl`\n- Develop in `drafts/` using `templates/`\n- Log published content to `posts.jsonl` with metrics\n- Plan in `calendar.md`\n\n### Network Module\n\nPersonal CRM with relationship tiers:\n- `inner` - Weekly touchpoints\n- `active` - Bi-weekly touchpoints\n- `network` - Monthly touchpoints\n- `dormant` - Quarterly reactivation checks\n\n### Operations Module\n\nProductivity system with priority levels:\n- P0: Do today, blocking\n- P1: This week, important\n- P2: This month, valuable\n- P3: Backlog, nice to have\n\n## Practical Guidance\n\n### Content Creation Workflow\n\n```\n1. Read identity/voice.md (REQUIRED)\n2. Check identity/brand.md for topic alignment\n3. Reference content/posts.jsonl for successful patterns\n4. Use content/templates/ as starting structure\n5. Draft matching voice attributes\n6. Log to posts.jsonl after publishing\n```\n\n### Pre-Meeting Preparation\n\n```\n1. Look up contact: network/contacts.jsonl\n2. Get history: network/interactions.jsonl\n3. Check pending: operations/todos.md\n4. Generate brief with context\n```\n\n### Weekly Review Process\n\n```\n1. Run: python agents/scripts/weekly_review.py\n2. Review metrics in operations/metrics.jsonl\n3. Check stale contacts: agents/scripts/stale_contacts.py\n4. Update goals progress in operations/goals.yaml\n5. Plan next week in content/calendar.md\n```\n\n## Examples\n\n### Example: Writing an X Post\n\n**Input**: \"Help me write a post about AI agents\"\n\n**Process**:\n1. Read `identity/voice.md` → Extract voice attributes\n2. Check `identity/brand.md` → Confirm \"ai_agents\" is a content pillar\n3. Reference `content/posts.jsonl` → Find similar successful posts\n4. Draft post matching voice patterns\n5. Suggest adding to `content/ideas.jsonl` if not publishing immediately\n\n**Output**: Post draft in user''s authentic voice with platform-appropriate format.\n\n### Example: Contact Lookup\n\n**Input**: \"Prepare me for my call with Sarah Chen\"\n\n**Process**:\n1. Search `network/contacts.jsonl` for \"Sarah Chen\"\n2. Get recent entries from `network/interactions.jsonl`\n3. Check `operations/todos.md` for pending items with Sarah\n4. Compile brief: role, context, last discussed, follow-ups\n\n**Output**: Pre-meeting brief with relationship context.\n\n## Guidelines\n\n1. **Voice First**: Always read `identity/voice.md` before any content generation\n2. **Append Only**: Never delete from JSONL files - archive instead\n3. **Update Timestamps**: Set `updated` field when modifying tracked data\n4. **Cross-Reference**: Knowledge informs content, network informs operations\n5. **Log Interactions**: Always log meetings/calls to `interactions.jsonl`\n6. **Preserve History**: Past content in `posts.jsonl` informs future performance\n\n## Integration\n\nThis skill integrates context engineering principles:\n\n- **context-fundamentals** - Progressive disclosure, attention budget management\n- **memory-systems** - JSONL for persistent memory, structured recall\n- **tool-design** - Scripts in `agents/scripts/` follow tool design principles\n- **context-optimization** - Module separation prevents context bloat\n\n## References\n\nInternal references:\n- [Identity Module](./identity/IDENTITY.md) - Voice and brand details\n- [Content Module](./content/CONTENT.md) - Content pipeline docs\n- [Network Module](./network/NETWORK.md) - CRM documentation\n- [Operations Module](./operations/OPERATIONS.md) - Productivity system\n- [Agent Scripts](./agents/AGENTS.md) - Automation documentation\n\nExternal resources:\n- [Agent Skills for Context Engineering](https://github.com/muratcankoylan/Agent-Skills-for-Context-Engineering)\n- [Anthropic Context Engineering Guide](https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents)\n\n---\n\n## Skill Metadata\n\n**Created**: 2024-12-29\n**Last Updated**: 2024-12-29\n**Author**: Murat Can Koylan\n**Version**: 1.0.0\n"},"lastSynced":"2026-03-08T02:10:29.633Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Cursor, Windsurf, and Claude Code needing structured personal operating systems for managing digital presence and knowledge","zh":"非常适合像 Cursor、Windsurf 和 Claude Code 这样的 AI Agent，它们需要结构化的个人操作系统来管理数字存在和知识","ja":"Cursor、Windsurf、Claude Code などの AI エージェントに最適で、デジタル存在と知識を管理するための構造化されたパーソナルオペレーティングシステムが必要です","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에게 적합하며, 디지털 존재와 지식을 관리하기 위한 구조화된 개인 운영 체제가 필요합니다","es":"Perfecto para agentes de IA como Cursor, Windsurf y Claude Code que necesitan sistemas operativos personales estructurados para gestionar la presencia digital y el conocimiento","fr":"Parfait pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin de systèmes d''exploitation personnels structurés pour gérer la présence numérique et les connaissances","de":"Perfekt für KI-Agents wie Cursor, Windsurf und Claude Code, die strukturierte persönliche Betriebssysteme für die Verwaltung der digitalen Präsenz und des Wissens benötigen","pt":"Perfeito para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de sistemas operacionais pessoais estruturados para gerenciar presença digital e conhecimento","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которым необходимы структурированные личные операционные системы для управления цифровым присутствием и знаниями","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يحتاجون إلى أنظمة تشغيل شخصية منظمة لإدارة الحضور الرقمي والمعرفة"},"recommendation":{"en":"Empowers agents to manage digital presence, knowledge, and goals with AI assistance, utilizing progressive disclosure for efficient task management and providing a comprehensive framework for founders and content creators, leveraging modules and subdirectories with specific instructions in .md files","zh":"赋予代理管理数字存在、知识和目标的能力，利用 AI 助手和渐进式披露进行高效的任务管理，并为创始人和内容创作者提供一个全面性的框架，利用模块和子目录中的特定指令在 .md 文件中","ja":"エージェントがデジタル存在、知識、目標を管理する能力を持ち、AI アシスタントとプログレッシブ開示を使用してタスク管理を効率化し、創設者とコンテンツクリエイターのための包括的なフレームワークを提供し、モジュールとサブディレクトリ内の特定の指示を .md ファイルに記載する","ko":"에이전트가 디지털 존재, 지식, 목표를 관리할 수 있는 능력을 부여하며, AI 어시스턴트와渐进式 공개를 사용하여 태스크 관리를 효율화하고, 설립자와 콘텐츠 창작자를 위한 포괄적인 프레임워크를 제공하며, 모듈과 서브 디렉토리 내의 특정 지침을 .md 파일에 작성함으로써","es":"Habilita a los agentes a gestionar la presencia digital, el conocimiento y los objetivos con asistencia de IA, utilizando la divulgación progresiva para una gestión de tareas eficiente y proporcionando un marco integral para fundadores y creadores de contenido, aprovechando módulos y subdirectorios con instrucciones específicas en archivos .md","fr":"Permet aux agents de gérer la présence numérique, les connaissances et les objectifs avec une assistance IA, en utilisant la divulgation progressive pour une gestion de tâches efficace et en fournissant un cadre complet pour les fondateurs et les créateurs de contenu, en exploitant les modules et les sous-répertoires avec des instructions spécifiques dans des fichiers .md","de":"Ermöglicht es Agenten, die digitale Präsenz, das Wissen und die Ziele mit KI-Unterstützung zu verwalten, indem es progressive Offenlegung für eine effiziente Aufgabenverwaltung nutzt und ein umfassendes Framework für Gründer und Content-Ersteller bereitstellt, indem es Module und Unterverzeichnisse mit spezifischen Anweisungen in .md-Dateien nutzt","pt":"Habilita agentes a gerenciar presença digital, conhecimento e metas com assistência de IA, utilizando revelação progressiva para gerenciamento de tarefas eficiente e fornecendo um framework abrangente para fundadores e criadores de conteúdo, utilizando módulos e subdiretórios com instruções específicas em arquivos .md","ru":"Наделяет агентов возможностью управлять цифровым присутствием, знаниями и целями с помощью ИИ, используя прогрессивное раскрытие для эффективного управления задачами и предоставляя комплексную основу для основателей и создателей контента, использующих модули и подпапки с конкретными инструкциями в файлах .md","ar":"تمكّن الوكلاء من إدارة الحضور الرقمي والمعرفة والأهداف مع مساعدة الذكاء الاصطناعي، باستخدام الإفصاح التدريجي لإدارة المهام الفعالة وتوفير إطار شامل للمؤسسين ومصممي المحتوى، باستخدام الوحدات والنصوص الفرعية مع تعليمات محددة في ملفات .md"},"useCases":{"en":["Managing digital presence for founders building in public","Growing audience for content creators with AI-assisted personal management","Streamlining task management with progressive disclosure"],"zh":["为公开建设创始人管理数字存在","为内容创作者提供 AI 辅助的个人管理以增长受众","使用渐进式披露简化任务管理"],"ja":["オープンな構築を行う創設者のデジタル存在を管理する","コンテンツクリエイターのための AI アシスタントを使用したパーソナルマネジメントでオーディエンスを拡大する","プログレッシブ開示を使用してタスク管理を簡素化する"],"ko":["공개적으로 구축하는 창립자의 디지털 존재를 관리하기","콘텐츠 창작자를 위한 AI 어시스턴트를 사용한 개인 관리로 청중을 확대하기","渐进式 공개를 사용하여 태스크 관리를 간소화하기"],"es":["Gestionar la presencia digital para fundadores que construyen en público","Creecer la audiencia para creadores de contenido con gestión personal asistida por IA","Optimizar la gestión de tareas con divulgación progresiva"],"fr":["Gérer la présence numérique pour les fondateurs qui construisent en public","Faire croître l''audience pour les créateurs de contenu avec une gestion personnelle assistée par IA","Optimiser la gestion de tâches avec la divulgation progressive"],"de":["Verwalten der digitalen Präsenz für Gründer, die öffentlich aufbauen","Wachsen der Zielgruppe für Content-Ersteller mit KI-unterstützter persönlicher Verwaltung","Optimieren der Aufgabenverwaltung mit progressiver Offenlegung"],"pt":["Gerenciando presença digital para fundadores que constroem em público","Crescendo audiência para criadores de conteúdo com gerenciamento pessoal assistido por IA","Otimizando gerenciamento de tarefas com revelação progressiva"],"ru":["Управление цифровым присутствием для основателей, строящих публично","Рост аудитории для создателей контента с помощью личного управления, поддерживаемого ИИ","Оптимизация управления задачами с помощью прогрессивного раскрытия"],"ar":["إدارة الحضور الرقمي للمؤسسين الذين يبنون علنًا","زيادة الجمهور لمصممي المحتوى مع إدارة شخصية مدعومة بالذكاء الاصطناعي","تحسين إدارة المهام مع الإفصاح التدريجي"]},"limitations":{"en":["Requires module-specific instructions loaded from subdirectory .md files","Designed for tech-savvy professionals and founders"],"zh":["需要从子目录 .md 文件中加载模块特定的指令","针对技术精通的专业人员和创始人设计"],"ja":["サブディレクトリの .md ファイルからモジュール特有の指示を読み込む必要がある","テクノロジーに精通した専門家と創設者向けに設計されている"],"ko":["서브 디렉토리의 .md 파일에서 모듈 특정 지침을 로드해야 함","기술에 정통한 전문가와 창립자를 위해 설계됨"],"es":["Requiere instrucciones específicas de módulos cargadas desde archivos .md de subdirectorios","Diseñado para profesionales y fundadores con conocimientos técnicos"],"fr":["Nécessite des instructions spécifiques de modules chargées à partir de fichiers .md de sous-répertoires","Conçu pour les professionnels et les fondateurs ayant des connaissances techniques"],"de":["Benötigt modulspezifische Anweisungen, die aus .md-Dateien von Unterverzeichnissen geladen werden","Entworfen für technisch affine Fachleute und Gründer"],"pt":["Requer instruções específicas dos módulos carregadas a partir de arquivos .md de subdiretórios","Projetado para profissionais e fundadores com conhecimento técnico"],"ru":["Требует модульных инструкций, загруженных из файлов .md подпапок","Разработан для технически подкованных специалистов и основателей"],"ar":["يتطلب تعليمات محددة للوحدات المحملة من ملفات .md للنصوص الفرعية","مصمم للخبراء والمؤسسين ذوي الخبرة الفنية"]},"version":4},"contentHash":"39ed6cd20dd787b6c71397aa0f75619887ed774c0fd390439d8e535f54bb3544","qualityScore":65}');
