INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chenjiongwei/zjsy/digital-brain', 'digital-brain', 'chenjiongwei', 'zjsy', 'community', 'digital-brain chenjiongwei zjsy community Digital-brain is a structured personal operating system for managing digital presence, knowledge, and goals with AI assistance, designed for founders and content creators. It uses progressive disclosure for efficient task management. 数字大脑是一种用于管理数字存在、知识、关系和目标的结构化个人操作系统，具有AI辅助功能。它适用于公开建立的创始人、内容创作者和寻求AI辅助个人管理的技术专业人员 デジタルブレインは、AIアシスト機能を備えた、デジタル存在、知識、関係、目標を管理するための構造化されたパーソナルオペレーティングシステムです。公開で構築する創業者、オーディエンスを育てているコンテンツクリエイター、AIアシストによるパーソナルマネジメントを求めるテクノロジーに精通した専門家向けに設計されています 디지털 브레인은 디지털 존재, 지식, 관계, 목표를 관리하는 구조화된 개인 운영 체제로 AI 보조 기능을 제공합니다. 공개적으로 구축하는 창업자, 오디언스를 키우는 콘텐츠 크리에이터, AI 보조 개인 관리를 찾는 기술에精通한 전문가들을 위해 설계되었습니다 Digital Brain es un sistema operativo personal que gestiona tu presencia digital con asistencia de AI. Está diseñado para fundadores, creadores de contenido y profesionales técnicos Digital Brain est un système d''exploitation personnel qui gère votre présence numérique avec assistance IA. Il est conçu pour les fondateurs, les créateurs de contenu et les professionnels techniques Digital Brain ist ein persönliches Betriebssystem, das Ihre digitale Präsenz mit KI-Unterstützung verwaltet. Es ist für Gründer, Content-Ersteller und technische Fachleute konzipiert O Digital Brain é um sistema de operação pessoal que gerencia presença digital, conhecimento, relacionamentos e metas com assistência de IA. Desenvolvido para fundadores que constroem em público, criadores de conteúdo e profissionais de tecnologia Цифровой Мозг - это личная операционная система, которая управляет цифровым присутствием, знаниями, отношениями и целями с помощью ИИ Агентов. Разработана для основателей, создающих в öffentliche, создателей контента и технических специалистов المخ الرقمي هو نظام تشغيل شخصي يدير التواجد الرقمي والمعرفة والعلاقات والأهداف بالذكاء الاصطناعي. تم تطويره لمؤسسي الشركات التي تبني بشكل عام، ومُطوّري المحتوى والمختصين في مجال التكنولوجيا how to use digital-brain what is digital-brain digital-brain alternative digital-brain vs personal OS digital-brain install guide digital-brain setup for founders digital-brain AI assistance progressive disclosure in digital-brain digital-brain for content creators digital-brain personal management 数字大脑 AI工具 个人操作系统 数字存在管理 知识管理 关系管理 目标管理 AI辅助功能 Utilizes progressive disclosure for efficient task management Designed for founders building in public and content creators growing their audience Supports module-specific instructions in each subdirectory''s .md file Loads only necessary components for the current task Activates AI-assisted personal management for tech-savvy professionals Manages digital presence, knowledge, relationships, and goals in a structured manner Digital-brain is a personal operating system that utilizes AI assistance for managing digital presence, knowledge, relationships, and goals.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kundeng/windloop/spec-driven-dev', 'community', 'kundeng', 'windloop', 'kundeng/windloop', 'spec-driven-dev', 0, 0, 65, '2026-03-08T01:57:15.522Z', '2026-03-08T02:10:47.063Z', 'a2e96f0a7e6e5a38cc7ba9a766f1eab939ec3b545ab9c15ff79ec45d1470f8fd', '{"id":"kundeng/windloop/spec-driven-dev","name":"spec-driven-dev","description":{"en":"spec-driven-dev is a framework for Windsurf that enables autonomous development through specs. It benefits developers working on complex features, multi-step projects, and team collaborations.","zh":"Spec-Driven Dev是一种基于Spec的开发框架，通过`.windloop/specs/<name>/`或`.kiro/specs/<name>/`目录管理Spec","ja":"Spec-Driven DevはSpecベースの開発フレームワークで、`.windloop/specs/<name>/`または`.kiro/specs/<name>/`ディレクトリを使用してSpecを管理します","ko":"Spec-Driven Dev는 Spec 기반의 개발 프레임워크로서 `.windloop/specs/<name>/` 또는 `.kiro/specs/<name>/` 디렉토리를 통해 Spec를 관리합니다","es":"El framework de desarrollo autónomo dirigido por especificaciones para Windsurf permite una planificación estructurada y mejora la calidad de los proyectos","fr":"Le framework de développement autonome piloté par spécifications pour Windsurf permet une planification structurée et améliore la qualité des projets","de":"Das Framework für spezifikationsgetriebene autonome Entwicklung von Windsurf ermöglicht eine strukturierte Planung und verbessert die Qualität der Projekte","pt":"O spec-driven-dev é um framework de desenvolvimento autônomo baseado em especificações para Windsurf. Ele permite a criação de specs em um diretório específico","ru":"Spec-driven-dev — это фреймворк автономного развития на основе спецификаций для Windsurf. Он позволяет создавать спецификации в определенном каталоге","ar":"spec-driven-dev هو إطار عمل للتنمية المستقلة القائمة على المواصفات لمنصة Windsurf. يسمح بإنشاء مواصفات في دليل معين"},"seo":{"title":{"en":"spec-driven-dev: Autonomous Development Framework Setup G...","zh":"Spec-Driven Dev.setup Guide - AIエージェント开发框架","ja":"Spec-Driven Dev.ベストプラクティス - AIエージェント開発フレームワーク","ko":"Spec-Driven Dev.구성 가이드 - AI 에이전트 개발 프레임워크","es":"Guía de Configuración de Desarrollo Dirigido por Especifi...","fr":"Guide de Mise en Place du Développement Piloté par Spécif...","de":"Einrichtungsleitfaden für Spezifikationsgetriebene Entwic...","pt":"Guia de Configuração do spec-driven-dev para Desenvolvime...","ru":"Настройка ИИ Агентов: Руководство по spec-driven-dev","ar":"دليل إعداد العامل الذكي spec-driven-dev للتنمية المستقلة"},"description":{"en":"Unlock efficient development with spec-driven-dev. Discover how to leverage specs in .windloop/specs/ or .kiro/specs/ for streamlined collaboration and AI-as...","zh":"了解Spec-Driven Dev的技术细节，包括Spec目录和风格规范，提升开发效率和质量","ja":"Spec-Driven Devの技術的な詳細を学び、Specディレクトリとスタイルガイドを活用して開発効率と品質を向上させる","ko":"Spec-Driven Dev의 기술적인 세부 사항을 알아보고 Spec 디렉토리 및 스타일 가이드를 사용하여 개발 효율성 및 품질을 향상시키세요","es":"Aprende a utilizar el framework de desarrollo autónomo dirigido por especificaciones para Windsurf y mejora la calidad de tus proyectos","fr":"Découvrez comment utiliser le framework de développement autonome piloté par spécifications pour Windsurf et améliorez la qualité de vos projets","de":"Erfahren Sie, wie Sie das Framework für spezifikationsgetriebene autonome Entwicklung von Windsurf nutzen und die Qualität Ihrer Projekte verbessern","pt":"Aprenda a configurar o spec-driven-dev para desenvolvimento autônomo e melhore a qualidade do seu código com essa ferramenta de desenvolvimento baseada em es...","ru":"Узнайте, как настроить spec-driven-dev для автономного развития и улучшить качество вашего кода с помощью этого инструмента разработки на основе спецификаций...","ar":"تعلم كيفية إعداد العامل الذكي spec-driven-dev للتنمية المستقلة و تحسين جودة رمزك باستخدام أداة التطوير القائمة على المواصفات"},"definition":{"en":"spec-driven-dev is an autonomous development framework that utilizes specs in designated directories for efficient development and collaboration.","zh":"Spec-Driven Dev是一种开发框架，通过Spec来驱动开发过程","ja":"Spec-Driven Devは、Specを使用して開発プロセスを駆動する開発フレームワークです","ko":"Spec-Driven Dev는 Spec를 사용하여 개발 프로세스를 구동하는 개발 프레임워크입니다","es":"Desarrollo dirigido por especificaciones es un enfoque que utiliza especificaciones para guiar el proceso de desarrollo de software","fr":"Le développement piloté par spécifications est une approche qui utilise des spécifications pour guider le processus de développement de logiciels","de":"Spezifikationsgetriebene Entwicklung ist ein Ansatz, der Spezifikationen verwendet, um den Software-Entwicklungsprozess zu steuern","pt":"O que é spec-driven-dev? É um framework de desenvolvimento autônomo que utiliza specs para melhorar a qualidade do código","ru":"Что такое spec-driven-dev? Это фреймворк автономного развития, использующий спецификации для улучшения качества кода ИИ Агентов","ar":"ما هو spec-driven-dev? هو إطار عمل للتنمية المستقلة الذي يستخدم المواصفات لتحسين جودة الرمز"},"features":{"en":["Utilizes specs in .windloop/specs/<name>/ or .kiro/specs/<name>/ directories","Supports complex features with multiple components or integrations","Enables multi-step work with reduced rework costs","Facilitates AI-assisted development with structured planning","Enhances team collaboration through shared understanding and traceability","Allows for resuming work with ease"],"zh":["基于Spec的开发框架","通过`.windloop/specs/<name>/`或`.kiro/specs/<name>/`目录管理Spec","适用于复杂特性和多步骤工作","支持AI辅助开发和团队协作","提高开发效率和质量"],"ja":["Specベースの開発フレームワーク","`.windloop/specs/<name>/`または`.kiro/specs/<name>/`ディレクトリを使用してSpecを管理","複雑な特性や多段階の作業に適しています","AIアシスト開発やチームコラボレーションをサポート","開発効率と品質を向上させる"],"ko":["Spec 기반의 개발 프레임워크","`.windloop/specs/<name>/` 또는 `.kiro/specs/<name>/` 디렉토리를 통해 Spec를 관리","복잡한 특성 및 다단계 작업에 적합","AI 지원 개발 및 팀 협력을 지원","개발 효율성 및 품질을 향상"],"es":["Soporte para directorios de especificaciones como `.windloop/specs/<name>/` o `.kiro/specs/<name>/`","Formato de especificaciones estandarizado para proyectos de Windsurf","Desarrollo autónomo con planificación estructurada","Mejora de la calidad de los proyectos gracias a la planificación y seguimiento","Integración con tecnologías de desarrollo de software para Windsurf","Colaboración en equipo con seguimiento y trazabilidad"],"fr":["Prise en charge des répertoires de spécifications tels que `.windloop/specs/<name>/` ou `.kiro/specs/<name>/`","Format de spécifications standardisé pour les projets Windsurf","Développement autonome avec planification structurée","Amélioration de la qualité des projets grâce à la planification et au suivi","Intégration avec les technologies de développement de logiciels pour Windsurf","Collaboration d''équipe avec suivi et traçabilité"],"de":["Unterstützung für Spezifikationsverzeichnisse wie `.windloop/specs/<name>/` oder `.kiro/specs/<name>/`","Standardisiertes Spezifikationsformat für Windsurf-Projekte","Autonome Entwicklung mit strukturierter Planung","Qualitätsverbesserung der Projekte durch Planung und Verfolgung","Integration mit Software-Entwicklungstechnologien für Windsurf","Teamzusammenarbeit mit Verfolgung und Nachverfolgbarkeit"],"pt":["Suporte a specs em diretórios `.windloop/specs/<name>/` ou `.kiro/specs/<name>/`","Desenvolvimento autônomo baseado em especificações","Melhoria da qualidade do código com planejamento estruturado","Colaboração em equipe com entendimento compartilhado e rastreabilidade","Resumo de trabalho com reutilização de specs"],"ru":["Поддержка спецификаций в каталогах `.windloop/specs/<name>/` или `.kiro/specs/<name>/`","Автономное развитие на основе спецификаций","Улучшение качества кода с помощью структурированного планирования ИИ Агентов","Командная работа с общим пониманием и отслеживаемостью","Возобновление работы с повторным использованием спецификаций"],"ar":["دعم المواصفات في الدلائل `.windloop/specs/<name>/` أو `.kiro/specs/<name>/`","التنمية المستقلة القائمة على المواصفات","تحسين جودة الرمز باستخدام التخطيط الهيكلي","التعاون الفريق مع الفهم المشترك والتتبع","استئناف العمل مع إعادة استخدام المواصفات"]},"keywords":{"en":["how to use spec-driven-dev","spec-driven-dev alternative","spec-driven-dev setup guide","what is spec-driven-dev","spec-driven-dev vs windloop","spec-driven-dev install","autonomous development framework","spec-driven development for Windsurf","AI-assisted development with spec-driven-dev"],"zh":["Spec-Driven Dev","AIエージェント开发框架","Spec目录","风格规范","开发效率","开发质量","AI辅助开发","团队协作"],"ja":["Spec-Driven Dev","AIエージェント開発フレームワーク","Specディレクトリ","スタイルガイド","開発効率","開発品質","AIアシスト開発","チームコラボレーション"],"ko":["Spec-Driven Dev","AI 에이전트 개발 프레임워크","Spec 디렉토리","스타일 가이드","개발 효율성","개발 품질","AI 지원 개발","팀 협력"],"es":["desarrollo dirigido por especificaciones","framework de desarrollo autónomo","Windsurf","especificaciones de software","planificación estructurada","colaboración en equipo","mejora de la calidad","Herramientas de desarrollo de software","Agentes de IA para desarrollo de software"],"fr":["développement piloté par spécifications","framework de développement autonome","Windsurf","spécifications de logiciels","planification structurée","collaboration d''équipe","amélioration de la qualité","Outils de développement de logiciels","Agents d''IA pour le développement de logiciels"],"de":["spezifikationsgetriebene Entwicklung","Framework für autonome Entwicklung","Windsurf","Software-Spezifikationen","strukturierte Planung","Teamzusammenarbeit","Qualitätsverbesserung","Software-Entwicklungstools","KI-Agents für Software-Entwicklung"],"pt":["spec-driven-dev","desenvolvimento autônomo","especificações","Windsurf","desenvolvimento baseado em specs","melhoria da qualidade do código","colaboração em equipe","resumo de trabalho"],"ru":["spec-driven-dev","автономное развитие","спецификации","Windsurf","разработка на основе спецификаций ИИ Агентов","улучшение качества кода","командная работа","возобновление работы"],"ar":["spec-driven-dev","التنمية المستقلة","المواصفات","Windsurf","التنمية القائمة على المواصفات","تحسين جودة الرمز","التعاون الفريق","استئناف العمل"]}},"owner":"kundeng","repo":"windloop","repoPath":"kundeng/windloop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.522Z","topics":[],"category":"community","skillMd":{"name":"spec-driven-dev","description":"Spec-driven development workflow: requirements → design → tasks → implement loop. Use when planning features, implementing from specs, or resuming work. Commands: spec-plan, spec-go, spec-task, spec-audit, spec-status, spec-merge, spec-reset, spec-help. IMPORTANT: Never edit requirements.md, design.md, tasks.md, or progress.txt without first reading this skill and the relevant references/ doc.","version":"1.1.0","bodyPreview":"## Spec-Driven Development\n\nThis skill powers the windloop framework. Specs live in a **spec directory** — either `.windloop/specs/<name>/` or `.kiro/specs/<name>/`. The format is the same regardless of location.\n\n### When to Use\n\n- Complex features with multiple components or integrations\n- Multi-step work where rework costs are significant\n- AI-assisted development where structured planning improves output quality\n- Team collaboration requiring shared understanding and traceability\n- Resuming","body":"## Spec-Driven Development\n\nThis skill powers the windloop framework. Specs live in a **spec directory** — either `.windloop/specs/<name>/` or `.kiro/specs/<name>/`. The format is the same regardless of location.\n\n### When to Use\n\n- Complex features with multiple components or integrations\n- Multi-step work where rework costs are significant\n- AI-assisted development where structured planning improves output quality\n- Team collaboration requiring shared understanding and traceability\n- Resuming implementation across sessions\n\n### When NOT to Use\n\n- Simple bug fixes with obvious one-file solutions\n- Time-critical hotfixes requiring immediate action\n- Experimental prototypes for rapid throwaway iteration\n- Trivial changes with no ambiguity\n\n### Quick Start\n\n**New feature:**\n```\n/spec-plan my-feature create\n```\nCreates `requirements.md`, `design.md`, `tasks.md`, `progress.txt` in a new spec directory. Walk through requirements → design → tasks with approval gates between each phase.\n\n**Refine existing spec:**\n```\n/spec-plan my-feature refine\n```\nMerges redundant requirements, fixes stale paths, cascades renumbering, validates traceability.\n\n**Resume implementation:**\n```\n/spec-go my-feature\n```\nReads the spec, finds the next uncompleted task, implements it test-first, commits, and repeats.\n\n**Check progress:**\n```\n/spec-status\n```\n\n### Phase Gate Protocol\n\nEach phase requires **explicit user approval** before advancing:\n\n```\nRequirements ──[approve]──> Design ──[approve]──> Tasks ──[approve]──> Implement\n```\n\n- After generating `requirements.md`: ask *\"Do the requirements look good? Ready for design?\"*\n- After generating `design.md`: ask *\"Does the design look good? Ready for task breakdown?\"*\n- After generating `tasks.md`: ask *\"Do the tasks look good? Ready to implement?\"*\n- **Never skip a phase or combine phases.** If running `/spec-go` (autonomous mode), the user has pre-approved all phases by invoking the command.\n\n```mermaid\nstateDiagram-v2\n  [*] --> Requirements\n\n  Requirements --> ReviewReq : Complete\n  ReviewReq --> Requirements : Changes requested\n  ReviewReq --> Design : Approved\n\n  Design --> ReviewDesign : Complete\n  ReviewDesign --> Design : Changes requested\n  ReviewDesign --> Tasks : Approved\n\n  Tasks --> ReviewTasks : Complete\n  ReviewTasks --> Tasks : Changes requested\n  ReviewTasks --> Implement : Approved\n\n  Implement --> TaskDone : Task complete\n  TaskDone --> Implement : Next task\n  TaskDone --> [*] : All tasks done\n\n  state Implement {\n    [*] --> PickTask\n    PickTask --> Code\n    Code --> Test\n    Test --> Commit\n    Commit --> UpdateProgress\n  }\n```\n\n### Resume / Detection Protocol\n\nDetermine current phase by checking which files exist in SPEC_DIR:\n\n| Files present | Phase | Next action |\n|---------------|-------|-------------|\n| None | New | `/spec-plan <name> create` — start with requirements |\n| `requirements.md` only | Design needed | Generate `design.md`, then ask for approval |\n| `requirements.md` + `design.md` | Tasks needed | Generate `tasks.md`, then ask for approval |\n| All 3 + unchecked tasks | Implementation | `/spec-go` or `/spec-task` — pick next unchecked task |\n| All tasks checked | Done | `/spec-merge` — merge branch, clean up |\n\nWhen resuming, **always re-read** `requirements.md`, `design.md`, and `tasks.md` before acting.\n\n### Quality Checklists\n\n**Requirements checklist** (validate before advancing to design):\n- [ ] All user roles identified\n- [ ] Normal, edge, and error cases covered\n- [ ] Every criterion uses WHEN/SHALL (EARS) format\n- [ ] Requirements are testable and measurable\n- [ ] No conflicting requirements\n\n**Design checklist** (validate before advancing to tasks):\n- [ ] All requirements addressed in design\n- [ ] Component responsibilities and interfaces specified\n- [ ] Correctness properties defined with test approaches\n- [ ] Error handling covers expected failures\n- [ ] Diagrams match system complexity\n\n**Tasks checklist** (validate before implementing):\n- [ ] Every requirement traced to ≥1 task\n- [ ] Tasks ordered to respect dependencies\n- [ ] Tests are separate tasks (not embedded)\n- [ ] Each task is independently completable\n- [ ] Scope is appropriate (30 min – 2 hours each)\n\n### Spec Lifecycle\n\n```\nidea → requirements.md (why) → design.md (what + how) → tasks.md (steps) → [implement loop] → done\n```\n\nThe traceability chain:\n- **requirements.md** — requirements as user stories with WHEN/SHALL acceptance criteria — the *why*\n- **design.md** — architecture, tech stack, constraints, testing strategy, correctness properties — the *what + how*\n- **tasks.md** — implementation tasks referencing requirements and properties — the *steps*\n- **progress.txt** — auto-updated log\n- **steering/** *(optional)* — project-level context: product vision, repo structure, tech decisions. Read-only priors that inform all spec work.\n\n### Workflow References\n\nDetailed instructions for each command live in `references/` alongside this file. When a command is invoked, read the corresponding reference document.\n\n### Commands\n\n| Command | Reference | Purpose |\n|---------|-----------|---------|\n| `/spec-help` | [spec-help.md](references/spec-help.md) | Onboarding guide |\n| `/spec-plan <name> [create\\|refine]` | [spec-plan.md](references/spec-plan.md) | Create or refine a spec |\n| `/spec-audit <name>` | [spec-audit.md](references/spec-audit.md) | Validate spec consistency |\n| `/spec-go <name>` | [spec-go.md](references/spec-go.md) | Autonomous implement loop |\n| `/spec-task <name> <task>` | [spec-task.md](references/spec-task.md) | Implement single task |\n| `/spec-merge <name>` | [spec-merge.md](references/spec-merge.md) | Merge parallel branches, resolve conflicts, verify |\n| `/spec-status` | [spec-status.md](references/spec-status.md) | Progress dashboard |\n| `/spec-reset <name>` | [spec-reset.md](references/spec-reset.md) | Clear progress for re-run |\n\n### Spec Resolution\n\nWhen a command receives a spec name SPEC, resolve its directory:\n\n1. `.windloop/specs/SPEC/` — if exists, use it\n2. `.kiro/specs/SPEC/` — if exists, use it\n3. Neither → error\n\nWhen no name is given, list directories in `.windloop/specs/` and `.kiro/specs/`. If exactly one spec exists, use it automatically.\n\nLet **SPEC_DIR** be the resolved directory.\n\n### Rules\n\n1. **One session per working tree**: use worktrees or branches to isolate parallel work.\n2. **Resolve the spec** using the Spec Resolution rules above.\n3. Read `requirements.md` AND `design.md` before implementing. If `steering/` exists, read it too.\n4. **When in doubt, stop and re-anchor to the spec**: if there is any chance the next action could deviate from spec-driven development (unclear scope, missing task, ambiguous acceptance criteria, tempting “quick fix”, undocumented refactor), STOP and re-read `requirements.md`, `design.md`, `tasks.md`, and the relevant workflow in `references/` (typically `references/spec-go.md` or `references/spec-task.md`) before proceeding. If it still isn’t clearly supported by the spec, ask the user to refine the spec (via `/spec-plan ... refine`) instead of guessing.\n5. Check task dependencies — never skip ahead.\n6. **Tests are separate tasks**: property tests and E2E tests each get their own task. Don''t embed test work inside implementation tasks.\n7. Run tests after implementation; fix up to 3 times before BLOCKED.\n8. Commit per task: `feat(<spec>/<task>): [description]`\n9. Update `tasks.md` (checkbox) and `progress.txt` (log line) after each task.\n10. Keep changes minimal and focused.\n\n### Common Pitfalls\n\n**Vague requirements:**\n- Bad: \"System should be fast\"\n- Good: \"WHEN user submits search THEN system SHALL return results within 2 seconds\"\n\n**Implementation details in requirements:**\n- Bad: \"System shall use Redis for caching\"\n- Good: \"WHEN user requests frequently accessed data THEN system SHALL return cached results\"\n\n**Skipping phases:**\n- Bad: Jump straight to tasks.md without requirements or design\n- Good: Complete each phase, get approval, then advance\n\n**Monolithic tasks:**\n- Bad: \"Implement the entire authentication system\" (one task)\n- Good: Break into 30-min–2-hour tasks with clear boundaries and test coverage\n\n**Missing error cases:**\n- Bad: Only documenting the happy path\n- Good: Include WHEN/IF statements for all error conditions and edge cases\n\n**Embedding tests in implementation tasks:**\n- Bad: \"Implement user model and write all tests\" (one task)\n- Good: Separate tasks: \"Implement user model\" → \"Write property test for user validation\"\n\n### Scaffolding\n\nWhen `/spec-plan` creates a new spec, it must create a **per-spec subdirectory** — never put spec files directly in `.windloop/specs/` or `.kiro/specs/`.\n\n**If `.kiro/` exists:**\n1. Create `.kiro/specs/` if it doesn''t exist\n2. Create `.kiro/specs/<name>/` — this is the spec directory\n3. Create all spec files inside `.kiro/specs/<name>/`\n\n**Otherwise:**\n1. Create `.windloop/specs/` if it doesn''t exist\n2. Create `.windloop/specs/<name>/` — this is the spec directory\n3. Create all spec files inside `.windloop/specs/<name>/`\n\nThe spec directory must contain:\n```\n.windloop/specs/<name>/    # or .kiro/specs/<name>/\n  requirements.md\n  design.md\n  tasks.md\n  progress.txt\n```\n\n**Common mistake**: placing spec files directly in `.windloop/specs/` or `.kiro/specs/` without the `<name>/` subdirectory. Each spec MUST have its own subdirectory.\n\n### Steering Docs (optional)\n\nSteering docs provide project-level context that applies across all specs. They live at the root of the spec area:\n\n- `.windloop/steering/` or `.kiro/steering/`\n\nNote: steering docs live at the root (`.windloop/steering/`, not `.windloop/specs/steering/`).\n\n| File | Purpose |\n|------|--------|\n| `product.md` | Product vision, target users, key goals |\n| `structure.md` | Repo layout, module boundaries, naming conventions |\n| `tech.md` | Tech stack decisions, version constraints, deployment targets |\n\n**Rules:**\n- Steering docs are **read-only context** — never modify them during task execution.\n- When they exist, **always** read them during planning (`spec-plan`) and before implementing (`spec-go`, `spec-task`).\n- They are not scaffolded automatically — the user creates them when ready.\n- They inform requirements, design decisions, and coding conventions but are not part of the traceability chain.\n\nIf the host project has an `AGENTS.md`, append the windloop snippet (see below). If not, create it.\n\n### AGENTS.md Snippet\n\n```markdown\n## Windloop\n\nThis project uses spec-driven development. Specs live in `.windloop/specs/` or `.kiro/specs/`.\nRead the `spec-driven-dev` skill before modifying any spec files.\nRun `/spec-help` for the full command list.\n```\n\n### Spec Refinement Principles\n\nWhen running `/spec-plan <name> refine`:\n\n1. **Merge redundant requirements**: combine duplicates into the earlier/more natural location.\n2. **Separate what from how**: move implementation details from Requirements to Constraints.\n3. **Collapse over-specified sub-requirements**: individual assertions become acceptance criteria on tasks, not separate requirements.\n4. **Demote aspirational items**: untestable patterns become Notes, not requirements.\n5. **Merge overlapping properties**: if one is a subset of another, merge and renumber.\n6. **Cascade renumbering**: update ALL references in design.md and tasks.md after merging/removing.\n7. **Validate traceability**: every requirement → ≥1 property → ≥1 task. Flag orphans.\n8. **Present tense for done work**: completed requirements describe the system as-is.\n9. **Sync derived documents**: update README, architecture docs, etc. if affected.\n10. **Align spec with disk**: fix stale paths, add missing entries, remove deleted files.\n\n### Embedded Templates\n\n#### requirements.md template\n\n```markdown\n# Requirements Document\n\n## Introduction\n<!-- Brief description of what this spec covers and why -->\n\n## Glossary\n\n- **Term_1**: Definition\n- **Term_2**: Definition\n\n## Requirements\n\n### Requirement 1: [Feature area]\n\n**User Story:** As a [role], I want [action], so that [benefit].\n\n#### Acceptance Criteria\n\n1. WHEN [trigger], THE [Component] SHALL [expected behavior]\n2. WHEN [trigger], THE [Component] SHALL [expected behavior]\n\n### Requirement 2: [Feature area]\n\n**User Story:** As a [role], I want [action], so that [benefit].\n\n#### Acceptance Criteria\n\n1. WHEN [trigger], THE [Component] SHALL [expected behavior]\n\n### Non-Functional\n\n**NF 1**: [Performance / reliability / security requirement]\n\n## Out of Scope\n<!-- What this spec explicitly does NOT cover -->\n```\n\n#### design.md template\n\n```markdown\n# Design: [SPEC NAME]\n\n## Tech Stack\n- **Language**:\n- **Framework**:\n- **Testing**:\n- **Linter**:\n\n## Directory Structure\n\\```\nsrc/\ntests/\n\\```\n\n## Architecture Overview\n\n\\```mermaid\ngraph TD\n    A[Module A] --> B[Module B]\n    A --> C[Module C]\n    B --> D[Shared Service]\n    C --> D\n\\```\n\n## Module Design\n\n### [Module 1]\n- **Purpose**: [what it does]\n- **Interface**:\n  \\```\n  [function signatures, class interfaces, API endpoints]\n  \\```\n- **Dependencies**: [what it depends on]\n\n## Data Flow\n\n\\```mermaid\nsequenceDiagram\n    participant User\n    participant CLI\n    participant Service\n    participant Store\n    User->>CLI: command\n    CLI->>Service: process(args)\n    Service->>Store: read/write\n    Store-->>Service: result\n    Service-->>CLI: output\n    CLI-->>User: display\n\\```\n\n## State Management\n<!-- Omit if stateless -->\n\n## Data Models\n<!-- Omit if simple -->\n\n## Error Handling Strategy\n<!-- How errors are propagated and handled -->\n\n## Testing Strategy\n\n- **Property tests**: Verify design invariants, inline with implementation tasks (required)\n- **E2E tests**: Validate user stories end-to-end, as separate tasks (required)\n- **Unit tests**: For complex internal logic only (optional, add when warranted)\n- **Test command**: `[command]`\n- **Lint command**: `[command]`\n- **Coverage target**: [percentage]\n\n## Constraints\n<!-- Important decisions and constraints -->\n\n## Correctness Properties\n\nProperties that must hold true. Each validates one or more requirements.\n\n### Property 1: [Property name]\n- **Statement**: *For any* [condition], when [action], then [expected outcome]\n- **Validates**: Requirement 1.1, 1.2\n- **Example**: [concrete example]\n- **Test approach**: [how to verify]\n\n### Property 2: [Property name]\n- **Statement**: *For any* [condition], when [action], then [expected outcome]\n- **Validates**: Requirement 2.1\n- **Example**: [example]\n- **Test approach**: [approach]\n\n## Edge Cases\n<!-- Known edge cases and how they should be handled -->\n\n## Decisions\n\n### Decision: [Title]\n**Context:** [Situation requiring a decision]\n**Options Considered:**\n1. [Option 1] — Pros: [benefits] / Cons: [drawbacks]\n2. [Option 2] — Pros: [benefits] / Cons: [drawbacks]\n**Decision:** [Chosen option]\n**Rationale:** [Why this was selected]\n\n## Security Considerations\n<!-- If applicable -->\n```\n\n**Diagram guidance**: Include diagrams that match complexity:\n- **Always**: Component diagram (architecture overview)\n- **Multi-actor systems**: Sequence diagram\n- **Stateful systems**: State diagram\n- **Data-heavy systems**: ER diagram\n\nOmit sections that don''t apply. Use Mermaid syntax.\n\n#### tasks.md template\n\n```markdown\n# Tasks: [SPEC NAME]\n\n## Overview\n<!-- Brief description of implementation approach -->\n\n## Tasks\n\n- [ ] 1. [Phase title — REQUIRED, never leave blank]\n  - [ ] 1.1 [Task title]\n    - [What to implement]\n    - **Depends**: —\n    - **Requirements**: 1.1, 1.2\n    - **Properties**: 1\n\n  - [ ] 1.2 [Task title]\n    - [What to implement]\n    - **Depends**: 1.1\n    - **Requirements**: 2.1\n    - **Properties**: 2\n\n  - [ ] 1.3 Write property test for [property name]\n    - Property 1 (validates 1.1, 1.2)\n    - **Depends**: 1.1\n    - **Properties**: 1\n\n  - [ ]* 1.4 [Optional task title]\n    - [What to implement]\n    - **Depends**: 1.1\n\n- [ ] 2. [Phase or group title]\n  - [ ] 2.1 [Task title]\n    - [What to implement]\n    - **Depends**: 1.1, 1.2\n    - **Requirements**: 1.3, 2.2\n    - **Properties**: 1, 2\n\n- [ ] 3. E2E Tests\n  - [ ] 3.1 E2E — [User story scenario]\n    - End-to-end test validating [user story]\n    - **Depends**: 1.1, 1.2\n    - **Requirements**: 1.1, 1.2, 2.1\n\n## Notes\n<!-- Implementation notes, known issues, etc. -->\n```\n\n**Task conventions**:\n- IDs use hierarchical numbering: `1.1`, `1.2`, `2.1`, etc.\n- Parent items (`1.`, `2.`) are phase/group headers — their checkbox tracks phase completion. **Always include a descriptive title** (e.g. `- [ ] 1. Set up project infrastructure`).\n- `[ ]*` marks optional tasks.\n- `[~]` = partial/skipped, `[!]` = blocked.\n- **Depends** is the only required metadata field. **Requirements** and **Properties** for traceability.\n- When a task needs testing, create a **separate sub-task** for writing the test (e.g. `1.3 Write property test for X`). Don''t embed test specs inside implementation tasks.\n\n#### progress.txt template\n\n```\n# Progress Log: [SPEC NAME]\n# Auto-updated by spec-go workflow\n# Format: [TIMESTAMP] [STATUS] [TASK_ID] - [DESCRIPTION]\n# STATUS: DONE | BLOCKED | SKIPPED | IN_PROGRESS\n# SUMMARY: 0/N done | next: 1.1\n```\n\nThe `# SUMMARY:` line is machine-readable. Format: `# SUMMARY: <done>/<total> done | next: <NEXT_TASK_ID or DONE>`\n\n### Parallel Execution\n\nFor independent tasks, use worktree mode:\n1. Open a new Cascade in Worktree mode\n2. Run `/spec-task <name> <task>`\n3. Merge back when done\n\n"},"lastSynced":"2026-03-08T02:10:47.063Z","agentAnalysis":{"suitability":{"en":"Ideal for Windsurf Agents requiring structured development workflows through specs for complex features and team collaborations.","zh":"适用于需要通过规格实现结构化开发工作流的Windsurf Agents，特别是那些具有复杂功能和团队协作的项目。","ja":"Windsurfエージェントが複雑な機能やチームコラボレーションを対象とした構造化された開発ワークフローを必要とする場合に最適です。","ko":"구조화된 개발 워크플로우가 필요한 윈드서핑 에이전트에 적합하며, 특히 복잡한 기능 및 팀 협력을 포함하는 프로젝트에 적합합니다.","es":"Ideal para agentes de Windsurf que requieren flujos de trabajo de desarrollo estructurados a través de especificaciones para características complejas y colaboraciones en equipo.","fr":"Idéal pour les agents Windsurf nécessitant des flux de travail de développement structurés via des spécifications pour des fonctionnalités complexes et des collaborations d''équipe.","de":"Ideal für Windsurf-Agenten, die strukturierte Entwicklungsworkflows durch Spezifikationen für komplexe Funktionen und Teamzusammenarbeit benötigen.","pt":"Ideal para agentes Windsurf que exigem fluxos de desenvolvimento estruturados por meio de especificações para recursos complexos e colaborações em equipe.","ru":"Идеально для агентов Windsurf, требующих структурированных рабочих процессов разработки через спецификации для сложных функций и командной работы.","ar":"مثالي لعمليات Windsurf التي تتطلب سير عمل تطوير منظم من خلال مواصفات لميزات معقدة وتعاونات الفريق."},"recommendation":{"en":"Empowers agents to automate development through specs, utilizing the windloop framework with spec directories like `.windloop/specs/<name>/` or `.kiro/specs/<name>/`, enhancing output quality in AI-assisted development and team traceability.","zh":"使得代理能够通过规格自动化开发，利用windloop框架和规格目录（如`.windloop/specs/<name>/`或`.kiro/specs/<name>/`），从而提高AI辅助开发的输出质量和团队可追溯性。","ja":"エージェントがスペックを使用して開発を自動化できるようにし、windloopフレームワークとスペックディレクトリ（`.windloop/specs/<name>/`または`.kiro/specs/<name>/`）を使用して、AI支援開発の出力品質とチームの追跡可能性を向上させます。","ko":"에이전트가 규격을 사용하여 개발을 자동화할 수 있도록 하며, windloop 프레임워크와 규격 디렉토리(`.windloop/specs/<name>/` 또는 `.kiro/specs/<name>/`)를 사용하여 AI 지원 개발의 출력 품질과 팀의 추적 가능성을 향상시킵니다.","es":"Habilita a los agentes a automatizar el desarrollo a través de especificaciones, utilizando el framework windloop con directorios de especificaciones como `.windloop/specs/<name>/` o `.kiro/specs/<name>/`, mejorando la calidad de la salida en el desarrollo asistido por IA y la trazabilidad del equipo.","fr":"Permet aux agents d''automatiser le développement via des spécifications, en utilisant le framework windloop avec des répertoires de spécifications comme `.windloop/specs/<name>/` ou `.kiro/specs/<name>/`, améliorant la qualité de sortie dans le développement assisté par IA et la traçabilité de l''équipe.","de":"Ermächtigt Agenten, die Entwicklung durch Spezifikationen zu automatisieren, indem sie das windloop-Framework mit Spezifikationsverzeichnissen wie `.windloop/specs/<name>/` oder `.kiro/specs/<name>/` verwenden, wodurch die Ausgabqualität in der von KI unterstützten Entwicklung und die Teamnachvollziehbarkeit verbessert werden.","pt":"Habilita os agentes a automatizar o desenvolvimento por meio de especificações, utilizando o framework windloop com diretórios de especificações como `.windloop/specs/<name>/` ou `.kiro/specs/<name>/`, melhorando a qualidade da saída no desenvolvimento assistido por IA e rastreabilidade da equipe.","ru":"Позволяет агентам автоматизировать разработку через спецификации, используя фреймворк windloop с директориями спецификаций как `.windloop/specs/<name>/` или `.kiro/specs/<name>/`, повышая качество вывода в разработке с помощью ИИ и командную отслеживаемость.","ar":"تمكن العوامل من توفير التطوير الآلي من خلال المواصفات، باستخدام إطار عمل windloop مع مجلدات المواصفات مثل `.windloop/specs/<name>/` أو `.kiro/specs/<name>/` ، وتحسين جودة الإخراج في التطوير بمساعدة الذكاء الاصطناعي وقابلية تتبع الفريق."},"useCases":{"en":["Automating complex feature development with multiple components","Streamlining multi-step projects to reduce rework costs","Enhancing AI-assisted development with structured planning","Facilitating team collaboration through shared spec understanding"],"zh":["自动化具有多个组件的复杂功能开发","通过规范化项目流程减少返工成本","通过结构化规划增强AI辅助开发","通过共享规格理解促进团队协作"],"ja":["複数コンポーネントを持つ複雑な機能開発の自動化","プロジェクトの複数ステップをストリームライン化してリワークコストを削減する","構造化計画によってAI支援開発を強化する","共有スペックの理解によってチームコラボレーションを促進する"],"ko":["여러 구성 요소를 가진 복잡한 기능 개발 자동화","다단계 프로젝트를 스트림 라인화하여 리워크 비용을 줄임","구조화된 계획을 통해 AI 지원 개발 강화","공유 규격 이해를 통해 팀 협력을 촉진"],"es":["Automatizar el desarrollo de características complejas con múltiples componentes","Optimizar proyectos de varias etapas para reducir los costos de reelaboración","Mejorar el desarrollo asistido por IA con planificación estructurada","Facilitar la colaboración en equipo a través de la comprensión compartida de las especificaciones"],"fr":["Automatiser le développement de fonctionnalités complexes avec plusieurs composants","Optimiser les projets à plusieurs étapes pour réduire les coûts de réélaboration","Améliorer le développement assisté par IA avec une planification structurée","Faciliter la collaboration d''équipe via la compréhension partagée des spécifications"],"de":["Automatisieren der Entwicklung komplexer Funktionen mit mehreren Komponenten","Optimieren von Mehrschrittprojekten, um die Kosten für Nacharbeit zu reduzieren","Verbessern der KI-unterstützten Entwicklung mit strukturierter Planung","Erleichtern der Teamzusammenarbeit durch gemeinsames Verständnis der Spezifikationen"],"pt":["Automatizar o desenvolvimento de recursos complexos com vários componentes","Otimizar projetos multi-etapas para reduzir os custos de retrabalho","Melhorar o desenvolvimento assistido por IA com planejamento estruturado","Facilitar a colaboração em equipe por meio de uma compreensão compartilhada das especificações"],"ru":["Автоматизировать разработку сложных функций с несколькими компонентами","Оптимизировать многоэтапные проекты для снижения затрат на переделку","Улучшить разработку с помощью ИИ с структурированным планированием","Облегчить командное сотрудничество посредством общего понимания спецификаций"],"ar":["توفير التطوير الآلي للميزات المعقدة ذات المكونات المتعددة","تحسين مشاريع متعددة المراحل لتقليل تكاليف الأعمال الإضافية","تحسين التطوير بمساعدة الذكاء الاصطناعي بالتخطيط المنظم","تسهيل التعاون الفريق من خلال فهم مشترك للمواصفات"]},"limitations":{"en":["Requires windloop framework integration","Limited to Windsurf Agents","Specs must be stored in designated spec directories"],"zh":["需要集成windloop框架","仅限Windsurf Agents","规格必须存储在指定的规格目录中"],"ja":["windloopフレームワークの統合が必要","Windsurfエージェントのみに限定","スペックは指定されたスペックディレクトリに保存する必要がある"],"ko":["windloop 프레임워크 통합 필요","윈드서핑 에이전트에만限함","규격은 지정된 규격 디렉토리에 저장되어야 함"],"es":["Requiere la integración del framework windloop","Limitado a agentes Windsurf","Las especificaciones deben almacenarse en directorios de especificaciones designados"],"fr":["Nécessite l''intégration du framework windloop","Limité aux agents Windsurf","Les spécifications doivent être stockées dans des répertoires de spécifications désignés"],"de":["Erfordert die Integration des windloop-Frameworks","Begrenzt auf Windsurf-Agenten","Die Spezifikationen müssen in den dafür vorgesehenen Spezifikationsverzeichnissen gespeichert werden"],"pt":["Exige integração com o framework windloop","Limitado a agentes Windsurf","As especificações devem ser armazenadas em diretórios de especificações designados"],"ru":["Требует интеграции с фреймворком windloop","Ограничен агентами Windsurf","Спецификации должны храниться в назначенных директориях спецификаций"],"ar":["يتطلب تكاملًا مع إطار عمل windloop","محدود بالعوامل Windsurf","يجب تخزين المواصفات في مجلدات مواصفات مخصصة"]},"version":4},"contentHash":"a2e96f0a7e6e5a38cc7ba9a766f1eab939ec3b545ab9c15ff79ec45d1470f8fd","qualityScore":65}');
