INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kundeng/windloop/spec-driven-dev', 'spec-driven-dev', 'kundeng', 'windloop', 'community', 'spec-driven-dev kundeng windloop community spec-driven-dev is a framework for Windsurf that enables autonomous development through specs. It benefits developers working on complex features, multi-step projects, and team collaborations. Spec-Driven Dev是一种基于Spec的开发框架，通过`.windloop/specs/<name>/`或`.kiro/specs/<name>/`目录管理Spec Spec-Driven DevはSpecベースの開発フレームワークで、`.windloop/specs/<name>/`または`.kiro/specs/<name>/`ディレクトリを使用してSpecを管理します Spec-Driven Dev는 Spec 기반의 개발 프레임워크로서 `.windloop/specs/<name>/` 또는 `.kiro/specs/<name>/` 디렉토리를 통해 Spec를 관리합니다 El framework de desarrollo autónomo dirigido por especificaciones para Windsurf permite una planificación estructurada y mejora la calidad de los proyectos Le framework de développement autonome piloté par spécifications pour Windsurf permet une planification structurée et améliore la qualité des projets Das Framework für spezifikationsgetriebene autonome Entwicklung von Windsurf ermöglicht eine strukturierte Planung und verbessert die Qualität der Projekte O spec-driven-dev é um framework de desenvolvimento autônomo baseado em especificações para Windsurf. Ele permite a criação de specs em um diretório específico Spec-driven-dev — это фреймворк автономного развития на основе спецификаций для Windsurf. Он позволяет создавать спецификации в определенном каталоге spec-driven-dev هو إطار عمل للتنمية المستقلة القائمة على المواصفات لمنصة Windsurf. يسمح بإنشاء مواصفات في دليل معين how to use spec-driven-dev spec-driven-dev alternative spec-driven-dev setup guide what is spec-driven-dev spec-driven-dev vs windloop spec-driven-dev install autonomous development framework spec-driven development for Windsurf AI-assisted development with spec-driven-dev Spec-Driven Dev AIエージェント开发框架 Spec目录 风格规范 开发效率 开发质量 AI辅助开发 团队协作 Utilizes specs in .windloop/specs/<name>/ or .kiro/specs/<name>/ directories Supports complex features with multiple components or integrations Enables multi-step work with reduced rework costs Facilitates AI-assisted development with structured planning Enhances team collaboration through shared understanding and traceability Allows for resuming work with ease spec-driven-dev is an autonomous development framework that utilizes specs in designated directories for efficient development and collaboration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mamba-mental/rize-mcp-ultimate/Skill Development', 'community', 'mamba-mental', 'rize-mcp-ultimate', 'mamba-mental/rize-mcp-ultimate', 'Skill Development', 0, 0, 65, '2026-03-08T01:57:15.542Z', '2026-03-08T02:11:17.528Z', 'd40080c45d652dd3cc481d1e381cd7e6258091a87351fa1de67c6c8ecec3446e', '{"id":"mamba-mental/rize-mcp-ultimate/Skill Development","name":"Skill Development","description":{"en":"Skill Development provides a comprehensive MCP server for Rize.io productivity tracking, enabling developers to create specialized skills for Claude Code plugins. This skill benefits developers seeking to extend Claude''s capabilities.","zh":"Skill Development是一种增强AIエージェント能力的技能，提供22个工具用于CRUD操作","ja":"スキル開発はAIエージェントの能力を拡張するためのスキルで、22のツールを使用したCRUD操作を提供する","ko":"스킬 개발은 AI 에이전트의 능력을 강화하는 스킬로, 22개의 툴을 사용한 CRUD 연산을 제공합니다","es":"El Skill Development proporciona una guía para crear habilidades efectivas para plugins de Claude Code con un servidor MCP para Rize.io y 22 herramientas para operaciones CRUD","fr":"Le Skill Development fournit un guide pour créer des compétences efficaces pour les plugins Claude Code avec un serveur MCP pour Rize.io et 22 outils pour les opérations CRUD","de":"Der Skill Development bietet eine Anleitung für die Erstellung effektiver Fähigkeiten für Claude-Code-Plugins mit einem MCP-Server für Rize.io und 22 Tools für CRUD-Operationen","pt":"O Skill Development é um servidor MCP completo para Rize.io que fornece 22 ferramentas para operações CRUD","ru":"Skill Development - это комплексный сервер MCP для Rize.io, обеспечивающий 22 инструмента для операций CRUD","ar":"Skill Development هو خادم MCP كامل ل Rize.io يقدم 22 أداة لعمليات CRUD"},"seo":{"title":{"en":"Skill Development: Comprehensive MCP Server Setup Guide |...","zh":"Skill Development Setup Guide - AIエージェント工具","ja":"スキル開発ベストプラクティス - AIエージェントの実装","ko":"스킬 개발 가이드 - AI 에이전트 툴킷","es":"Guía de Configuración de Skill Development para Agentes d...","fr":"Guide de Mise en Place de Skill Development pour Outils d''IA","de":"Einrichtungs-Anleitung für Skill Development bei KI-Agents","pt":"Guia de Configuração do Skill Development para Ferramenta...","ru":"Настройка ИИ Агентов: Skill Development для Продуктивности","ar":"دليل إعداد Skill Development لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock full CRUD operations with 22 tools! Discover how to create effective skills for Claude Code plugins and transform your agent with procedural knowledge.","zh":"了解如何创建有效的Skill Development技能，用于增强AIエージェント的能力，包括22个工具的CRUD操作","ja":"スキル開発のベストプラクティスを学び、AIエージェントの能力を拡張するための22のツールを使用する方法","ko":"스킬 개발 가이드를 통해 AI 에이전트의 능력을 강화하는 방법을 알아보세요. 22개의 툴을 사용한 CRUD 연산 포함","es":"Aprende a crear habilidades efectivas para plugins de Claude Code con nuestro servidor MCP para Rize.io y 22 herramientas para operaciones CRUD","fr":"Découvrez comment créer des compétences efficaces pour les plugins Claude Code avec notre serveur MCP pour Rize.io et 22 outils pour les opérations CRUD","de":"Erfahren Sie, wie Sie effektive Fähigkeiten für Claude-Code-Plugins mit unserem MCP-Server für Rize.io und 22 Tools für CRUD-Operationen erstellen","pt":"Aprenda a configurar o Skill Development para melhorar a produtividade com 22 ferramentas de CRUD","ru":"Узнайте, как настроить Skill Development для повышения производительности с 22 инструментами CRUD","ar":"تعرف على كيفية إعداد Skill Development لتحسين الإنتاجية مع 22 أداة CRUD"},"definition":{"en":"Skill Development is a modular, self-contained package that extends Claude''s capabilities with specialized knowledge, workflows, and tools for specific domains or tasks.","zh":"Skill Development是AIエージェント的模块化技能，提供CRUD操作和工作流程","ja":"スキル開発はAIエージェントのモジュール化されたスキルで、CRUD操作とワークフローを提供する","ko":"스킬 개발은 AI 에이전트의 모듈화된 스킬로, CRUD 연산과 워크플로우를 제공합니다","es":"El Skill Development es un paquete modular que extiende las capacidades de Claude con conocimientos especializados y herramientas para operaciones CRUD","fr":"Le Skill Development est un paquet modulaire qui étend les capacités de Claude avec des connaissances spécialisées et des outils pour les opérations CRUD","de":"Der Skill Development ist ein modulares Paket, das die Fähigkeiten von Claude mit spezialisierten Kenntnissen und Tools für CRUD-Operationen erweitert","pt":"O que é Skill Development? É um servidor MCP que estende as capacidades de Claude com conhecimento especializado","ru":"Что такое Skill Development? Это сервер MCP, расширяющий возможности Claude с помощью специализированных знаний","ar":"ما هو Skill Development؟ هو خادم MCP يوسع قدرات Claude مع المعرفة المتخصصة"},"features":{"en":["Provides 22 tools for full CRUD operations","Supports creation of specialized skills for Claude Code plugins","Enables procedural knowledge for specific domains or tasks","Includes guidance for creating effective skills","Transforms Claude into a specialized agent","Utilizes modular, self-contained packages"],"zh":["22个工具用于CRUD操作","支持AIエージェント的模块化技能","提供工作流程和专用知识","增强AIエージェント的能力","支持React和Python等技术"],"ja":["22のツールを使用したCRUD操作","AIエージェントのモジュール化されたスキルをサポート","ワークフローと専用知識を提供","AIエージェントの能力を拡張","ReactとPythonなどの技術をサポート"],"ko":["22개의 툴을 사용한 CRUD 연산","AI 에이전트의 모듈화된 스킬을 지원","워크플로우와専用 지식을 제공","AI 에이전트의 능력을 강화","React와 Python 등의 기술을 지원"],"es":["Servidor MCP para Rize.io","22 herramientas para operaciones CRUD","Soporte para plugins de Claude Code","Conocimientos especializados para dominios específicos","Capacidades de workflow y herramientas para tareas específicas","Integración con herramientas de productividad"],"fr":["Serveur MCP pour Rize.io","22 outils pour les opérations CRUD","Prise en charge des plugins Claude Code","Connaissances spécialisées pour des domaines spécifiques","Capacités de workflow et d''outils pour des tâches spécifiques","Intégration avec des outils de productivité"],"de":["MCP-Server für Rize.io","22 Tools für CRUD-Operationen","Unterstützung für Claude-Code-Plugins","Spezialisierte Kenntnisse für bestimmte Domänen","Workflows und Tools für spezifische Aufgaben","Integration mit Produktivitätstools"],"pt":["Servidor MCP completo para Rize.io","22 ferramentas para operações CRUD","Extensão das capacidades de Claude com conhecimento especializado","Compatibilidade com plugins de Claude Code","Suporte a workflows e ferramentas especializadas"],"ru":["Комплексный сервер MCP для Rize.io","22 инструмента для операций CRUD","Расширение возможностей Claude с помощью специализированных знаний","Совместимость с плагинами Claude Code","Поддержка рабочих процессов и специализированных инструментов"],"ar":["خادم MCP كامل ل Rize.io","22 أداة لعمليات CRUD","توسيع قدرات Claude مع المعرفة المتخصصة","التوافق مع إضافات Claude Code","دعم سير العمل والأدوات المتخصصة"]},"keywords":{"en":["how to use Skill Development","what is Skill Development","Skill Development alternative","Skill Development vs Claude Code","Skill Development install","Skill Development setup guide","CRUD operations with Skill Development","Rize.io productivity tracking with Skill Development","creating specialized skills for Claude Code plugins"],"zh":["AIエージェント工具","Skill Development","CRUD操作","模块化技能","工作流程","专用知识","React","Python","AI开发"],"ja":["AIエージェント","スキル開発","CRUD操作","モジュール化されたスキル","ワークフロー","専用知識","React","Python","AI開発"],"ko":["AI 에이전트","스킬 개발","CRUD 연산","모듈화된 스킬","워크플로우","専用 지식","React","Python","AI 개발"],"es":["desarrollo de habilidades para agentes de IA","configuración de skill development","servidor MCP para Rize.io","operaciones CRUD","plugins de Claude Code","herramientas de productividad","desarrollo de software","tecnologías de IA","programación de plugins"],"fr":["développement de compétences pour outils d''IA","configuration de skill development","serveur MCP pour Rize.io","opérations CRUD","plugins Claude Code","outils de productivité","développement de logiciels","technologies d''IA","programmation de plugins"],"de":["Fähigkeitsentwicklung für KI-Agents","Einrichtung von Skill Development","MCP-Server für Rize.io","CRUD-Operationen","Claude-Code-Plugins","Produktivitätstools","Softwareentwicklung","KI-Technologien","Plugin-Programmierung"],"pt":["Skill Development","Servidor MCP","Rize.io","Ferramentas de IA","CRUD","Claude Code","Plugins","Produtividade","Desenvolvimento de habilidades"],"ru":["Skill Development","Сервер MCP","Rize.io","ИИ Агенты","CRUD","Claude Code","Плагины","Производительность","Развитие навыков"],"ar":["Skill Development","خادم MCP","Rize.io","أدوات الذكاء الاصطناعي","CRUD","Claude Code","الإضافات","الإنتاجية","تطوير المهارات"]}},"owner":"mamba-mental","repo":"rize-mcp-ultimate","repoPath":"mamba-mental/rize-mcp-ultimate","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.542Z","topics":[],"category":"community","skillMd":{"name":"Skill Development","description":"This skill should be used when the user wants to create a skill, add a skill to plugin, write a new skill, improve skill description, organize skill content, or needs guidance on skill structure, progressive disclosure, or skill development best practices for Claude Code plugins.","version":"0.1.0","bodyPreview":"# Skill Development for Claude Code Plugins\n\nThis skill provides guidance for creating effective skills for Claude Code plugins.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### W","body":"# Skill Development for Claude Code Plugins\n\nThis skill provides guidance for creating effective skills for Claude Code plugins.\n\n## About Skills\n\nSkills are modular, self-contained packages that extend Claude''s capabilities by providing\nspecialized knowledge, workflows, and tools. Think of them as \"onboarding guides\" for specific\ndomains or tasks—they transform Claude from a general-purpose agent into a specialized agent\nequipped with procedural knowledge that no model can fully possess.\n\n### What Skills Provide\n\n1. Specialized workflows - Multi-step procedures for specific domains\n2. Tool integrations - Instructions for working with specific file formats or APIs\n3. Domain expertise - Company-specific knowledge, schemas, business logic\n4. Bundled resources - Scripts, references, and assets for complex and repetitive tasks\n\n### Anatomy of a Skill\n\nEvery skill consists of a required SKILL.md file and optional bundled resources:\n\n```\nskill-name/\n├── SKILL.md (required)\n│   ├── YAML frontmatter metadata (required)\n│   │   ├── name: (required)\n│   │   └── description: (required)\n│   └── Markdown instructions (required)\n└── Bundled Resources (optional)\n    ├── scripts/          - Executable code (Python/Bash/etc.)\n    ├── references/       - Documentation intended to be loaded into context as needed\n    └── assets/           - Files used in output (templates, icons, fonts, etc.)\n```\n\n#### SKILL.md (required)\n\n**Metadata Quality:** The `name` and `description` in YAML frontmatter determine when Claude will use the skill. Be specific about what the skill does and when to use it. Use the third-person (e.g. \"This skill should be used when...\" instead of \"Use this skill when...\").\n\n#### Bundled Resources (optional)\n\n##### Scripts (`scripts/`)\n\nExecutable code (Python/Bash/etc.) for tasks that require deterministic reliability or are repeatedly rewritten.\n\n- **When to include**: When the same code is being rewritten repeatedly or deterministic reliability is needed\n- **Example**: `scripts/rotate_pdf.py` for PDF rotation tasks\n- **Benefits**: Token efficient, deterministic, may be executed without loading into context\n- **Note**: Scripts may still need to be read by Claude for patching or environment-specific adjustments\n\n##### References (`references/`)\n\nDocumentation and reference material intended to be loaded as needed into context to inform Claude''s process and thinking.\n\n- **When to include**: For documentation that Claude should reference while working\n- **Examples**: `references/finance.md` for financial schemas, `references/mnda.md` for company NDA template, `references/policies.md` for company policies, `references/api_docs.md` for API specifications\n- **Use cases**: Database schemas, API documentation, domain knowledge, company policies, detailed workflow guides\n- **Benefits**: Keeps SKILL.md lean, loaded only when Claude determines it''s needed\n- **Best practice**: If files are large (>10k words), include grep search patterns in SKILL.md\n- **Avoid duplication**: Information should live in either SKILL.md or references files, not both. Prefer references files for detailed information unless it''s truly core to the skill—this keeps SKILL.md lean while making information discoverable without hogging the context window. Keep only essential procedural instructions and workflow guidance in SKILL.md; move detailed reference material, schemas, and examples to references files.\n\n##### Assets (`assets/`)\n\nFiles not intended to be loaded into context, but rather used within the output Claude produces.\n\n- **When to include**: When the skill needs files that will be used in the final output\n- **Examples**: `assets/logo.png` for brand assets, `assets/slides.pptx` for PowerPoint templates, `assets/frontend-template/` for HTML/React boilerplate, `assets/font.ttf` for typography\n- **Use cases**: Templates, images, icons, boilerplate code, fonts, sample documents that get copied or modified\n- **Benefits**: Separates output resources from documentation, enables Claude to use files without loading them into context\n\n### Progressive Disclosure Design Principle\n\nSkills use a three-level loading system to manage context efficiently:\n\n1. **Metadata (name + description)** - Always in context (~100 words)\n2. **SKILL.md body** - When skill triggers (<5k words)\n3. **Bundled resources** - As needed by Claude (Unlimited*)\n\n*Unlimited because scripts can be executed without reading into context window.\n\n## Skill Creation Process\n\nTo create a skill, follow the \"Skill Creation Process\" in order, skipping steps only if there is a clear reason why they are not applicable.\n\n### Step 1: Understanding the Skill with Concrete Examples\n\nSkip this step only when the skill''s usage patterns are already clearly understood. It remains valuable even when working with an existing skill.\n\nTo create an effective skill, clearly understand concrete examples of how the skill will be used. This understanding can come from either direct user examples or generated examples that are validated with user feedback.\n\nFor example, when building an image-editor skill, relevant questions include:\n\n- \"What functionality should the image-editor skill support? Editing, rotating, anything else?\"\n- \"Can you give some examples of how this skill would be used?\"\n- \"I can imagine users asking for things like ''Remove the red-eye from this image'' or ''Rotate this image''. Are there other ways you imagine this skill being used?\"\n- \"What would a user say that should trigger this skill?\"\n\nTo avoid overwhelming users, avoid asking too many questions in a single message. Start with the most important questions and follow up as needed for better effectiveness.\n\nConclude this step when there is a clear sense of the functionality the skill should support.\n\n### Step 2: Planning the Reusable Skill Contents\n\nTo turn concrete examples into an effective skill, analyze each example by:\n\n1. Considering how to execute on the example from scratch\n2. Identifying what scripts, references, and assets would be helpful when executing these workflows repeatedly\n\nExample: When building a `pdf-editor` skill to handle queries like \"Help me rotate this PDF,\" the analysis shows:\n\n1. Rotating a PDF requires re-writing the same code each time\n2. A `scripts/rotate_pdf.py` script would be helpful to store in the skill\n\nExample: When designing a `frontend-webapp-builder` skill for queries like \"Build me a todo app\" or \"Build me a dashboard to track my steps,\" the analysis shows:\n\n1. Writing a frontend webapp requires the same boilerplate HTML/React each time\n2. An `assets/hello-world/` template containing the boilerplate HTML/React project files would be helpful to store in the skill\n\nExample: When building a `big-query` skill to handle queries like \"How many users have logged in today?\" the analysis shows:\n\n1. Querying BigQuery requires re-discovering the table schemas and relationships each time\n2. A `references/schema.md` file documenting the table schemas would be helpful to store in the skill\n\n**For Claude Code plugins:** When building a hooks skill, the analysis shows:\n1. Developers repeatedly need to validate hooks.json and test hook scripts\n2. `scripts/validate-hook-schema.sh` and `scripts/test-hook.sh` utilities would be helpful\n3. `references/patterns.md` for detailed hook patterns to avoid bloating SKILL.md\n\nTo establish the skill''s contents, analyze each concrete example to create a list of the reusable resources to include: scripts, references, and assets.\n\n### Step 3: Create Skill Structure\n\nFor Claude Code plugins, create the skill directory structure:\n\n```bash\nmkdir -p plugin-name/skills/skill-name/{references,examples,scripts}\ntouch plugin-name/skills/skill-name/SKILL.md\n```\n\n**Note:** Unlike the generic skill-creator which uses `init_skill.py`, plugin skills are created directly in the plugin''s `skills/` directory with a simpler manual structure.\n\n### Step 4: Edit the Skill\n\nWhen editing the (newly-created or existing) skill, remember that the skill is being created for another instance of Claude to use. Focus on including information that would be beneficial and non-obvious to Claude. Consider what procedural knowledge, domain-specific details, or reusable assets would help another Claude instance execute these tasks more effectively.\n\n#### Start with Reusable Skill Contents\n\nTo begin implementation, start with the reusable resources identified above: `scripts/`, `references/`, and `assets/` files. Note that this step may require user input. For example, when implementing a `brand-guidelines` skill, the user may need to provide brand assets or templates to store in `assets/`, or documentation to store in `references/`.\n\nAlso, delete any example files and directories not needed for the skill. Create only the directories you actually need (references/, examples/, scripts/).\n\n#### Update SKILL.md\n\n**Writing Style:** Write the entire skill using **imperative/infinitive form** (verb-first instructions), not second person. Use objective, instructional language (e.g., \"To accomplish X, do Y\" rather than \"You should do X\" or \"If you need to do X\"). This maintains consistency and clarity for AI consumption.\n\n**Description (Frontmatter):** Use third-person format with specific trigger phrases:\n\n```yaml\n---\nname: Skill Name\ndescription: This skill should be used when the user asks to \"specific phrase 1\", \"specific phrase 2\", \"specific phrase 3\". Include exact phrases users would say that should trigger this skill. Be concrete and specific.\nversion: 0.1.0\n---\n```\n\n**Good description examples:**\n```yaml\ndescription: This skill should be used when the user asks to \"create a hook\", \"add a PreToolUse hook\", \"validate tool use\", \"implement prompt-based hooks\", or mentions hook events (PreToolUse, PostToolUse, Stop).\n```\n\n**Bad description examples:**\n```yaml\ndescription: Use this skill when working with hooks.  # Wrong person, vague\ndescription: Load when user needs hook help.  # Not third person\ndescription: Provides hook guidance.  # No trigger phrases\n```\n\nTo complete SKILL.md body, answer the following questions:\n\n1. What is the purpose of the skill, in a few sentences?\n2. When should the skill be used? (Include this in frontmatter description with specific triggers)\n3. In practice, how should Claude use the skill? All reusable skill contents developed above should be referenced so that Claude knows how to use them.\n\n**Keep SKILL.md lean:** Target 1,500-2,000 words for the body. Move detailed content to references/:\n- Detailed patterns → `references/patterns.md`\n- Advanced techniques → `references/advanced.md`\n- Migration guides → `references/migration.md`\n- API references → `references/api-reference.md`\n\n**Reference resources in SKILL.md:**\n```markdown\n## Additional Resources\n\n### Reference Files\n\nFor detailed patterns and techniques, consult:\n- **`references/patterns.md`** - Common patterns\n- **`references/advanced.md`** - Advanced use cases\n\n### Example Files\n\nWorking examples in `examples/`:\n- **`example-script.sh`** - Working example\n```\n\n### Step 5: Validate and Test\n\n**For plugin skills, validation is different from generic skills:**\n\n1. **Check structure**: Skill directory in `plugin-name/skills/skill-name/`\n2. **Validate SKILL.md**: Has frontmatter with name and description\n3. **Check trigger phrases**: Description includes specific user queries\n4. **Verify writing style**: Body uses imperative/infinitive form, not second person\n5. **Test progressive disclosure**: SKILL.md is lean (~1,500-2,000 words), detailed content in references/\n6. **Check references**: All referenced files exist\n7. **Validate examples**: Examples are complete and correct\n8. **Test scripts**: Scripts are executable and work correctly\n\n**Use the skill-reviewer agent:**\n```\nAsk: \"Review my skill and check if it follows best practices\"\n```\n\nThe skill-reviewer agent will check description quality, content organization, and progressive disclosure.\n\n### Step 6: Iterate\n\nAfter testing the skill, users may request improvements. Often this happens right after using the skill, with fresh context of how the skill performed.\n\n**Iteration workflow:**\n1. Use the skill on real tasks\n2. Notice struggles or inefficiencies\n3. Identify how SKILL.md or bundled resources should be updated\n4. Implement changes and test again\n\n**Common improvements:**\n- Strengthen trigger phrases in description\n- Move long sections from SKILL.md to references/\n- Add missing examples or scripts\n- Clarify ambiguous instructions\n- Add edge case handling\n\n## Plugin-Specific Considerations\n\n### Skill Location in Plugins\n\nPlugin skills live in the plugin''s `skills/` directory:\n\n```\nmy-plugin/\n├── .claude-plugin/\n│   └── plugin.json\n├── commands/\n├── agents/\n└── skills/\n    └── my-skill/\n        ├── SKILL.md\n        ├── references/\n        ├── examples/\n        └── scripts/\n```\n\n### Auto-Discovery\n\nClaude Code automatically discovers skills:\n- Scans `skills/` directory\n- Finds subdirectories containing `SKILL.md`\n- Loads skill metadata (name + description) always\n- Loads SKILL.md body when skill triggers\n- Loads references/examples when needed\n\n### No Packaging Needed\n\nPlugin skills are distributed as part of the plugin, not as separate ZIP files. Users get skills when they install the plugin.\n\n### Testing in Plugins\n\nTest skills by installing plugin locally:\n\n```bash\n# Test with --plugin-dir\ncc --plugin-dir /path/to/plugin\n\n# Ask questions that should trigger the skill\n# Verify skill loads correctly\n```\n\n## Examples from Plugin-Dev\n\nStudy the skills in this plugin as examples of best practices:\n\n**hook-development skill:**\n- Excellent trigger phrases: \"create a hook\", \"add a PreToolUse hook\", etc.\n- Lean SKILL.md (1,651 words)\n- 3 references/ files for detailed content\n- 3 examples/ of working hooks\n- 3 scripts/ utilities\n\n**agent-development skill:**\n- Strong triggers: \"create an agent\", \"agent frontmatter\", etc.\n- Focused SKILL.md (1,438 words)\n- References include the AI generation prompt from Claude Code\n- Complete agent examples\n\n**plugin-settings skill:**\n- Specific triggers: \"plugin settings\", \".local.md files\", \"YAML frontmatter\"\n- References show real implementations (multi-agent-swarm, ralph-wiggum)\n- Working parsing scripts\n\nEach demonstrates progressive disclosure and strong triggering.\n\n## Progressive Disclosure in Practice\n\n### What Goes in SKILL.md\n\n**Include (always loaded when skill triggers):**\n- Core concepts and overview\n- Essential procedures and workflows\n- Quick reference tables\n- Pointers to references/examples/scripts\n- Most common use cases\n\n**Keep under 3,000 words, ideally 1,500-2,000 words**\n\n### What Goes in references/\n\n**Move to references/ (loaded as needed):**\n- Detailed patterns and advanced techniques\n- Comprehensive API documentation\n- Migration guides\n- Edge cases and troubleshooting\n- Extensive examples and walkthroughs\n\n**Each reference file can be large (2,000-5,000+ words)**\n\n### What Goes in examples/\n\n**Working code examples:**\n- Complete, runnable scripts\n- Configuration files\n- Template files\n- Real-world usage examples\n\n**Users can copy and adapt these directly**\n\n### What Goes in scripts/\n\n**Utility scripts:**\n- Validation tools\n- Testing helpers\n- Parsing utilities\n- Automation scripts\n\n**Should be executable and documented**\n\n## Writing Style Requirements\n\n### Imperative/Infinitive Form\n\nWrite using verb-first instructions, not second person:\n\n**Correct (imperative):**\n```\nTo create a hook, define the event type.\nConfigure the MCP server with authentication.\nValidate settings before use.\n```\n\n**Incorrect (second person):**\n```\nYou should create a hook by defining the event type.\nYou need to configure the MCP server.\nYou must validate settings before use.\n```\n\n### Third-Person in Description\n\nThe frontmatter description must use third person:\n\n**Correct:**\n```yaml\ndescription: This skill should be used when the user asks to \"create X\", \"configure Y\"...\n```\n\n**Incorrect:**\n```yaml\ndescription: Use this skill when you want to create X...\ndescription: Load this skill when user asks...\n```\n\n### Objective, Instructional Language\n\nFocus on what to do, not who should do it:\n\n**Correct:**\n```\nParse the frontmatter using sed.\nExtract fields with grep.\nValidate values before use.\n```\n\n**Incorrect:**\n```\nYou can parse the frontmatter...\nClaude should extract fields...\nThe user might validate values...\n```\n\n## Validation Checklist\n\nBefore finalizing a skill:\n\n**Structure:**\n- [ ] SKILL.md file exists with valid YAML frontmatter\n- [ ] Frontmatter has `name` and `description` fields\n- [ ] Markdown body is present and substantial\n- [ ] Referenced files actually exist\n\n**Description Quality:**\n- [ ] Uses third person (\"This skill should be used when...\")\n- [ ] Includes specific trigger phrases users would say\n- [ ] Lists concrete scenarios (\"create X\", \"configure Y\")\n- [ ] Not vague or generic\n\n**Content Quality:**\n- [ ] SKILL.md body uses imperative/infinitive form\n- [ ] Body is focused and lean (1,500-2,000 words ideal, <5k max)\n- [ ] Detailed content moved to references/\n- [ ] Examples are complete and working\n- [ ] Scripts are executable and documented\n\n**Progressive Disclosure:**\n- [ ] Core concepts in SKILL.md\n- [ ] Detailed docs in references/\n- [ ] Working code in examples/\n- [ ] Utilities in scripts/\n- [ ] SKILL.md references these resources\n\n**Testing:**\n- [ ] Skill triggers on expected user queries\n- [ ] Content is helpful for intended tasks\n- [ ] No duplicated information across files\n- [ ] References load when needed\n\n## Common Mistakes to Avoid\n\n### Mistake 1: Weak Trigger Description\n\n❌ **Bad:**\n```yaml\ndescription: Provides guidance for working with hooks.\n```\n\n**Why bad:** Vague, no specific trigger phrases, not third person\n\n✅ **Good:**\n```yaml\ndescription: This skill should be used when the user asks to \"create a hook\", \"add a PreToolUse hook\", \"validate tool use\", or mentions hook events. Provides comprehensive hooks API guidance.\n```\n\n**Why good:** Third person, specific phrases, concrete scenarios\n\n### Mistake 2: Too Much in SKILL.md\n\n❌ **Bad:**\n```\nskill-name/\n└── SKILL.md  (8,000 words - everything in one file)\n```\n\n**Why bad:** Bloats context when skill loads, detailed content always loaded\n\n✅ **Good:**\n```\nskill-name/\n├── SKILL.md  (1,800 words - core essentials)\n└── references/\n    ├── patterns.md (2,500 words)\n    └── advanced.md (3,700 words)\n```\n\n**Why good:** Progressive disclosure, detailed content loaded only when needed\n\n### Mistake 3: Second Person Writing\n\n❌ **Bad:**\n```markdown\nYou should start by reading the configuration file.\nYou need to validate the input.\nYou can use the grep tool to search.\n```\n\n**Why bad:** Second person, not imperative form\n\n✅ **Good:**\n```markdown\nStart by reading the configuration file.\nValidate the input before processing.\nUse the grep tool to search for patterns.\n```\n\n**Why good:** Imperative form, direct instructions\n\n### Mistake 4: Missing Resource References\n\n❌ **Bad:**\n```markdown\n# SKILL.md\n\n[Core content]\n\n[No mention of references/ or examples/]\n```\n\n**Why bad:** Claude doesn''t know references exist\n\n✅ **Good:**\n```markdown\n# SKILL.md\n\n[Core content]\n\n## Additional Resources\n\n### Reference Files\n- **`references/patterns.md`** - Detailed patterns\n- **`references/advanced.md`** - Advanced techniques\n\n### Examples\n- **`examples/script.sh`** - Working example\n```\n\n**Why good:** Claude knows where to find additional information\n\n## Quick Reference\n\n### Minimal Skill\n\n```\nskill-name/\n└── SKILL.md\n```\n\nGood for: Simple knowledge, no complex resources needed\n\n### Standard Skill (Recommended)\n\n```\nskill-name/\n├── SKILL.md\n├── references/\n│   └── detailed-guide.md\n└── examples/\n    └── working-example.sh\n```\n\nGood for: Most plugin skills with detailed documentation\n\n### Complete Skill\n\n```\nskill-name/\n├── SKILL.md\n├── references/\n│   ├── patterns.md\n│   └── advanced.md\n├── examples/\n│   ├── example1.sh\n│   └── example2.json\n└── scripts/\n    └── validate.sh\n```\n\nGood for: Complex domains with validation utilities\n\n## Best Practices Summary\n\n✅ **DO:**\n- Use third-person in description (\"This skill should be used when...\")\n- Include specific trigger phrases (\"create X\", \"configure Y\")\n- Keep SKILL.md lean (1,500-2,000 words)\n- Use progressive disclosure (move details to references/)\n- Write in imperative/infinitive form\n- Reference supporting files clearly\n- Provide working examples\n- Create utility scripts for common operations\n- Study plugin-dev''s skills as templates\n\n❌ **DON''T:**\n- Use second person anywhere\n- Have vague trigger conditions\n- Put everything in SKILL.md (>3,000 words without references/)\n- Write in second person (\"You should...\")\n- Leave resources unreferenced\n- Include broken or incomplete examples\n- Skip validation\n\n## Additional Resources\n\n### Study These Skills\n\nPlugin-dev''s skills demonstrate best practices:\n- `../hook-development/` - Progressive disclosure, utilities\n- `../agent-development/` - AI-assisted creation, references\n- `../mcp-integration/` - Comprehensive references\n- `../plugin-settings/` - Real-world examples\n- `../command-development/` - Clear critical concepts\n- `../plugin-structure/` - Good organization\n\n### Reference Files\n\nFor complete skill-creator methodology:\n- **`references/skill-creator-original.md`** - Full original skill-creator content\n\n## Implementation Workflow\n\nTo create a skill for your plugin:\n\n1. **Understand use cases**: Identify concrete examples of skill usage\n2. **Plan resources**: Determine what scripts/references/examples needed\n3. **Create structure**: `mkdir -p skills/skill-name/{references,examples,scripts}`\n4. **Write SKILL.md**:\n   - Frontmatter with third-person description and trigger phrases\n   - Lean body (1,500-2,000 words) in imperative form\n   - Reference supporting files\n5. **Add resources**: Create references/, examples/, scripts/ as needed\n6. **Validate**: Check description, writing style, organization\n7. **Test**: Verify skill loads on expected triggers\n8. **Iterate**: Improve based on usage\n\nFocus on strong trigger descriptions, progressive disclosure, and imperative writing style for effective skills that load when needed and provide targeted guidance.\n"},"lastSynced":"2026-03-08T02:11:17.528Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents seeking to extend Claude Code capabilities with specialized knowledge and workflows.","zh":"适合开发人员代理寻求通过专门的知识和工作流扩展 Claude Code 的能力。","ja":"Claude Code の機能を専門知識とワークフローで拡張しようとする Developer エージェントに最適です。","ko":"클라우드 코드의 기능을 전문 지식과 워크플로로 확장하려는 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que buscan ampliar las capacidades del código Claude con conocimientos especializados y flujos de trabajo.","fr":"Parfait pour les agents de développement qui cherchent à étendre les capacités du code Claude avec des connaissances spécialisées et des flux de travail.","de":"Perfekt für Entwickleragenten, die die Fähigkeiten des Claude-Codes mit spezialisierten Kenntnissen und Workflows erweitern möchten.","pt":"Perfeito para Agentes de Desenvolvedor que buscam estender as capacidades do Claude Code com conhecimento especializado e fluxos de trabalho.","ru":"Идеально подходит для агентов-разработчиков, стремящихся расширить возможности Claude Code с помощью специализированных знаний и рабочих процессов.","ar":"مثالي للوكلاء المطورين الذين يريدون توسيع قدرات Claude Code مع المعرفة المتخصصة والعمليات"},"recommendation":{"en":"Empowers agents to create modular, self-contained packages for Claude Code plugins, providing specialized knowledge, workflows, and tools through MCP servers for Rize.io productivity tracking, utilizing procedural knowledge and domain-specific onboarding guides.","zh":"赋予代理创建针对 Claude Code 插件的模块化、自包含的包，通过 MCP 服务器为 Rize.io 提供生产力跟踪、利用程序化知识和特定领域的入门指南。","ja":"エージェントが Claude Code プラグイン用のモジュール化された自己完結的なパッケージを作成できるようにし、MCP サーバーを通じて Rize.io の生産性追跡に利用可能な特定の知識、ワークフロー、およびツールを提供し、手続き的知識とドメイン固有のオンボーディング ガイドを利用します。","ko":"에이전트가 클라우드 코드 플러그인용 모듈화된 자체 포함 패키지를 만들 수 있도록 하여 MCP 서버를 통해 Rize.io의 생산성 추적에 활용 가능한 전문 지식, 워크플로 및 도구를 제공하고, 절차적 지식 및 도메인 특정 온보딩 가이드를 활용합니다.","es":"Habilita a los agentes a crear paquetes modulares y autocontenidos para plugins de código Claude, proporcionando conocimientos especializados, flujos de trabajo y herramientas a través de servidores MCP para el seguimiento de productividad de Rize.io, utilizando conocimientos procedimentales y guías de incorporación específicas del dominio.","fr":"Permet aux agents de créer des packages modulaires et auto-contenus pour les plugins de code Claude, fournissant des connaissances spécialisées, des flux de travail et des outils via des serveurs MCP pour le suivi de productivité de Rize.io, en utilisant des connaissances procédurales et des guides d''intégration spécifiques au domaine.","de":"Ermöglicht es Agenten, modulare, selbstenthaltene Pakete für Claude-Code-Plugins zu erstellen, die spezialisierte Kenntnisse, Workflows und Tools über MCP-Server für die Produktivitätsverfolgung von Rize.io bereitstellen, unter Verwendung von prozeduralem Wissen und domänenspezifischen Onboarding-Leitfäden.","pt":"Habilita os agentes a criar pacotes modulares e autocontidos para plugins do Claude Code, fornecendo conhecimento especializado, fluxos de trabalho e ferramentas através de servidores MCP para rastreamento de produtividade do Rize.io, utilizando conhecimento processual e guias de integração específicas de domínio.","ru":"Позволяет агентам создавать модульные,自одостаточные пакеты для плагинов Claude Code, предоставляя специализированные знания, рабочие процессы и инструменты через серверы MCP для отслеживания производительности Rize.io, используя процессуальные знания и руководства по интеграции, специфичные для домена.","ar":"تمكين الوكلاء من إنشاء حزم مُستقلة ومتوافقة لملحقات Claude Code، وتوفير المعرفة المتخصصة والعمليات والأدوات من خلال خادم MCP لتتبع الإنتاجية Rize.io، باستخدام المعرفة الإجرائية ودلائل التوجيه الخاصة بنطاق معين"},"useCases":{"en":["Developing specialized skills for Claude Code plugins","Creating domain-specific onboarding guides for agents","Extending Claude''s capabilities with procedural knowledge and workflows"],"zh":["为 Claude Code 插件开发专门技能","为代理创建特定领域的入门指南","通过程序化知识和工作流扩展 Claude 的功能"],"ja":["Claude Code プラグイン用の専門スキルを開発する","エージェント用の特定のドメインの入門ガイドを作成する","手続き的知識とワークフローを使用して Claude の機能を拡張する"],"ko":["클라우드 코드 플러그인용 전문 스킬 개발","에이전트용 도메인 특정 온보딩 가이드 생성","절차적 지식 및 워크플로를 사용하여 클라우드의 기능 확장"],"es":["Desarrollar habilidades especializadas para plugins de código Claude","Crear guías de incorporación específicas del dominio para agentes","Ampliar las capacidades de Claude con conocimientos procedimentales y flujos de trabajo"],"fr":["Développer des compétences spécialisées pour les plugins de code Claude","Créer des guides d''intégration spécifiques au domaine pour les agents","Étendre les capacités de Claude avec des connaissances procédurales et des flux de travail"],"de":["Spezialisierte Fähigkeiten für Claude-Code-Plugins entwickeln","Domänenspezifische Onboarding-Leitfäden für Agenten erstellen","Claudes Fähigkeiten mit prozeduralem Wissen und Workflows erweitern"],"pt":["Desenvolver habilidades especializadas para plugins do Claude Code","Criar guias de integração específicas de domínio para agentes","Estender as capacidades do Claude com conhecimento processual e fluxos de trabalho"],"ru":["Разработка специализированных навыков для плагинов Claude Code","Создание руководств по интеграции, специфичных для домена, для агентов","Расширение возможностей Claude с помощью процессуальных знаний и рабочих процессов"],"ar":["تطوير مهارات متخصصة لملحقات Claude Code","إنشاء دلائل التوجيه الخاصة بنطاق معين للوكلاء","توسيع قدرات Claude باستخدام المعرفة الإجرائية والعمليات"]},"limitations":{"en":["Requires Claude Code plugin compatibility","MCP server for Rize.io productivity tracking necessary","Specialized knowledge of target domains or tasks required"],"zh":["需要 Claude Code 插件兼容性","需要 MCP 服务器用于 Rize.io 生产力跟踪","需要目标领域或任务的专门知识"],"ja":["Claude Code プラグインの互換性が必要","Rize.io の生産性追跡用の MCP サーバーが必要","対象ドメインまたはタスクの専門知識が必要"],"ko":["클라우드 코드 플러그인 호환성이 필요","Rize.io 생산성 추적을 위한 MCP 서버가 필요","대상 도메인 또는 작업의 전문 지식이 필요"],"es":["Se requiere compatibilidad con plugins de código Claude","Se requiere un servidor MCP para el seguimiento de productividad de Rize.io","Se requiere conocimiento especializado de los dominios o tareas de destino"],"fr":["La compatibilité avec les plugins de code Claude est requise","Un serveur MCP pour le suivi de productivité de Rize.io est nécessaire","Des connaissances spécialisées dans les domaines ou tâches cibles sont requises"],"de":["Kompatibilität mit Claude-Code-Plugins erforderlich","MCP-Server für die Produktivitätsverfolgung von Rize.io erforderlich","Spezialisiertes Wissen über Ziel-Domains oder -Aufgaben erforderlich"],"pt":["Requer compatibilidade com plugin do Claude Code","Servidor MCP para rastreamento de produtividade do Rize.io necessário","Conhecimento especializado de domínios ou tarefas de destino necessário"],"ru":["Требуется совместимость с плагином Claude Code","Необходим сервер MCP для отслеживания производительности Rize.io","Необходимо специализированное знание целевых доменов или задач"],"ar":["يتطلب توافقًا مع ملحقات Claude Code","خادم MCP مطلوب لتتبع الإنتاجية Rize.io","مطلوب معرفة متخصصة في نطاقات أو مهام معينة"]},"version":4},"contentHash":"d40080c45d652dd3cc481d1e381cd7e6258091a87351fa1de67c6c8ecec3446e","qualityScore":65}');
