INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mamba-mental/rize-mcp-ultimate/Skill Development', 'Skill Development', 'mamba-mental', 'rize-mcp-ultimate', 'community', 'Skill Development mamba-mental rize-mcp-ultimate community Skill Development provides a comprehensive MCP server for Rize.io productivity tracking, enabling developers to create specialized skills for Claude Code plugins. This skill benefits developers seeking to extend Claude''s capabilities. Skill Development是一种增强AIエージェント能力的技能，提供22个工具用于CRUD操作 スキル開発はAIエージェントの能力を拡張するためのスキルで、22のツールを使用したCRUD操作を提供する 스킬 개발은 AI 에이전트의 능력을 강화하는 스킬로, 22개의 툴을 사용한 CRUD 연산을 제공합니다 El Skill Development proporciona una guía para crear habilidades efectivas para plugins de Claude Code con un servidor MCP para Rize.io y 22 herramientas para operaciones CRUD Le Skill Development fournit un guide pour créer des compétences efficaces pour les plugins Claude Code avec un serveur MCP pour Rize.io et 22 outils pour les opérations CRUD Der Skill Development bietet eine Anleitung für die Erstellung effektiver Fähigkeiten für Claude-Code-Plugins mit einem MCP-Server für Rize.io und 22 Tools für CRUD-Operationen O Skill Development é um servidor MCP completo para Rize.io que fornece 22 ferramentas para operações CRUD Skill Development - это комплексный сервер MCP для Rize.io, обеспечивающий 22 инструмента для операций CRUD Skill Development هو خادم MCP كامل ل Rize.io يقدم 22 أداة لعمليات CRUD how to use Skill Development what is Skill Development Skill Development alternative Skill Development vs Claude Code Skill Development install Skill Development setup guide CRUD operations with Skill Development Rize.io productivity tracking with Skill Development creating specialized skills for Claude Code plugins AIエージェント工具 Skill Development CRUD操作 模块化技能 工作流程 专用知识 React Python AI开发 Provides 22 tools for full CRUD operations Supports creation of specialized skills for Claude Code plugins Enables procedural knowledge for specific domains or tasks Includes guidance for creating effective skills Transforms Claude into a specialized agent Utilizes modular, self-contained packages Skill Development is a modular, self-contained package that extends Claude''s capabilities with specialized knowledge, workflows, and tools for specific domains or tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stharrold/yuimedi-paper-20250901/agentdb-state-manager', 'community', 'stharrold', 'yuimedi-paper-20250901', 'stharrold/yuimedi-paper-20250901', 'agentdb-state-manager', 0, 0, 65, '2026-03-08T01:57:15.612Z', '2026-03-08T02:13:14.002Z', 'f05d185e6cf85eac6f0b51ea4a8b5071be8318bbffa34a75a6376d20b3d935f4', '{"id":"stharrold/yuimedi-paper-20250901/agentdb-state-manager","name":"agentdb-state-manager","description":{"en":"The agentdb-state-manager skill provides persistent database storage for workflow state tracking, enabling read-only analytics and checkpoint management. It benefits AI agent developers working with healthcare data.","zh":"AgentDB State Manager 提供了持久的数据库存储，用于跟踪工作流状态，支持读取分析、检查点管理和依赖解析","ja":"AgentDB State Manager は、ワークフローの状態を追跡するための永続的なデータベースストレージを提供し、読み取り分析、チェックポイント管理、依存解析をサポートします","ko":"AgentDB 상태 관리자는 워크플로우 상태 추적을 위한 영속적 데이터베이스 저장소를 제공하며 읽기 전용 분석, 체크포인트 관리 및 종속성 해결을 지원합니다","es":"AgentDB State Manager proporciona almacenamiento de base de datos persistente para el seguimiento del estado del flujo de trabajo utilizando DuckDB. Permite análisis de lectura, gestión de puntos de control y resolución de dependencias","fr":"AgentDB State Manager fournit un stockage de base de données persistant pour le suivi de l''état des flux de travail en utilisant DuckDB. Il permet l''analyse de lecture, la gestion des points de contrôle et la résolution des dépendances","de":"AgentDB State Manager bietet persistenten Datenbank-Speicher für die Nachverfolgung des Workflow-Status mithilfe von DuckDB. Es ermöglicht Leseanalysen, Checkpoint-Verwaltung und Abhängigkeitsauflösung","pt":"O AgentDB State Manager fornece armazenamento de dados de workflow de saúde com DuckDB e Gemini Code, permitindo análise de métricas e resolução de dependências","ru":"AgentDB State Manager предоставляет хранение данных рабочего процесса здравоохранения с помощью DuckDB и Gemini Code, позволяя анализировать метрики и разрешать зависимости","ar":"مساعد إدارة حالة AgentDB يوفر تخزين بيانات سير العمل الصحية مع DuckDB و Gemini Code، مما يسمح بتحليل المقاييس و حل الاعتماديات"},"seo":{"title":{"en":"agentdb-state-manager: Persistent Storage for AI Agents |...","zh":"AgentDB 状态管理器集成指南","ja":"AgentDB State Manager のベストプラクティス","ko":"AgentDB 상태 관리자 설정 가이드","es":"Guía de configuración de AgentDB State Manager para análi...","fr":"Guide de mise en route de AgentDB State Manager pour l''an...","de":"Einrichtungsleitfaden für AgentDB State Manager zur Analy...","pt":"Guia de Configuração do AgentDB State Manager para Health...","ru":"ИИ Агенты: Руководство по Настройке AgentDB State Manager","ar":"إعداد مساعد إدارة حالة AgentDB للرعاية الصحية"},"description":{"en":"Discover how agentdb-state-manager simplifies workflow state tracking with DuckDB and Gemini Code''s AgentDB integration. Learn more and get started today!","zh":"使用 AgentDB State Manager 实现自然语言到 SQL 的转换，提高医疗保健数据分析效率","ja":"AgentDB State Manager を使用して、自然言語を SQL に変換し、ヘルスケアデータ分析を最適化する","ko":"AgentDB 상태 관리자를 사용하여 자연어를 SQL로 변환하고 의료 데이터 분석을 최적화합니다","es":"Aprende a utilizar AgentDB State Manager para almacenar y analizar el estado de los flujos de trabajo en DuckDB, incluyendo análisis de lectura, gestión de p...","fr":"Découvrez comment utiliser AgentDB State Manager pour stocker et analyser l''état des flux de travail dans DuckDB, y compris l''analyse de lecture, la gestion ...","de":"Erfahren Sie, wie Sie AgentDB State Manager verwenden können, um den Status von Workflows in DuckDB zu speichern und zu analysieren, einschließlich Leseanaly...","pt":"Aprenda a configurar o AgentDB State Manager para armazenar dados de workflow de saúde com DuckDB e Gemini Code","ru":"Узнайте, как настроить AgentDB State Manager для хранения данных рабочего процесса здравоохранения с помощью DuckDB и Gemini Code","ar":"تعرف على كيفية إعداد مساعد إدارة حالة AgentDB لتخزين بيانات سير العمل الصحية مع DuckDB و Gemini Code"},"definition":{"en":"agentdb-state-manager is a skill that enables persistent database storage for workflow state tracking using DuckDB through Gemini Code''s AgentDB integration.","zh":"AgentDB 状态管理器是通过 DuckDB 和 Gemini Code 的 AgentDB 集成提供的技能","ja":"AgentDB State Manager は、DuckDB と Gemini Code の AgentDB 統合を通じて提供されるスキルです","ko":"AgentDB 상태 관리자는 DuckDB 및 Gemini Code의 AgentDB 통합을 통해 제공되는 스킬입니다","es":"AgentDB State Manager es un componente que proporciona almacenamiento de base de datos persistente para el seguimiento del estado del flujo de trabajo","fr":"AgentDB State Manager est un composant qui fournit un stockage de base de données persistant pour le suivi de l''état des flux de travail","de":"AgentDB State Manager ist ein Komponente, der persistenten Datenbank-Speicher für die Nachverfolgung des Workflow-Status bietet","pt":"O AgentDB State Manager é um skill que fornece armazenamento de dados de workflow de saúde com DuckDB","ru":"AgentDB State Manager - это навык, который предоставляет хранение данных рабочего процесса здравоохранения с помощью DuckDB","ar":"مساعد إدارة حالة AgentDB هو مهارة يوفر تخزين بيانات سير العمل الصحية مع DuckDB"},"features":{"en":["Read-only analytics over workflow history without parsing files","Checkpoint management at 100K token threshold using DuckDB","Dependency resolution through querying task dependencies and critical paths","Metrics analysis for historical trends"],"zh":["读取分析：复杂的工作流历史查询","检查点管理：在 100K 令牌阈值处存储和恢复上下文检查点","依赖解析：查询任务依赖和关键路径","指标分析：历史趋势分析"],"ja":["読み取り分析：ワークフロー履歴の複雑なクエリ","チェックポイント管理：100K トークン閾値でコンテキストチェックポイントを保存および復元","依存解析：タスク依存関係とクリティカルパスのクエリ","メトリクス分析：歴史的傾向分析"],"ko":["읽기 전용 분석: 워크플로우 기록의 복잡한 쿼리","체크포인트 관리: 100K 토큰 임계값에서 컨텍스트 체크포인트를 저장 및 복구","종속성 해결: 태스크 종속성 및 임계 경로 쿼리","메트릭스 분석: 역사적 경향 분석"],"es":["Almacenamiento de base de datos persistente en DuckDB","Análisis de lectura de historial de flujos de trabajo","Gestión de puntos de control y recuperación de contexto","Resolución de dependencias y análisis de caminos críticos","Análisis de tendencias históricas y métricas"],"fr":["Stockage de base de données persistant dans DuckDB","Analyse de lecture de l''historique des flux de travail","Gestion des points de contrôle et récupération de contexte","Résolution des dépendances et analyse des chemins critiques","Analyse des tendances historiques et des métriques"],"de":["Persistenter Datenbank-Speicher in DuckDB","Leseanalyse des Workflow-Historie","Checkpoint-Verwaltung und Kontextwiederherstellung","Abhängigkeitsauflösung und Analyse von kritischen Pfaden","Analyse von historischen Trends und Metriken"],"pt":["Armazenamento de dados de workflow de saúde com DuckDB","Análise de métricas e tendências históricas","Gerenciamento de checkpoints e recuperação de contexto","Resolução de dependências e análise de caminhos críticos","Integração com Gemini Code"],"ru":["Хранение данных рабочего процесса здравоохранения с помощью DuckDB","Анализ метрик и исторических тенденций","Управление контрольными точками и восстановление контекста","Разрешение зависимостей и анализ критических путей","Интеграция с Gemini Code"],"ar":["تخزين بيانات سير العمل الصحية مع DuckDB","تحليل المقاييس و الاتجاهات التاريخية","إدارة نقاط التحكم و استعادة السياق","حل الاعتماديات و تحليل المسارات الحاسمة","التكامل مع Gemini Code"]},"keywords":{"en":["how to use agentdb-state-manager","agentdb-state-manager setup guide","what is agentdb-state-manager","agentdb-state-manager alternative","agentdb-state-manager vs gemini code","installing agentdb-state-manager for healthcare"],"zh":["AgentDB 状态管理器","自然语言到 SQL","医疗保健数据分析","DuckDB","Gemini Code","AI 工具","AgentDB 集成"],"ja":["AgentDB State Manager","自然言語から SQL","ヘルスケアデータ分析","DuckDB","Gemini Code","AI エージェント","AgentDB 統合"],"ko":["AgentDB 상태 관리자","자연어를 SQL로","의료 데이터 분석","DuckDB","Gemini Code","AI 도구","AgentDB 통합"],"es":["AgentDB State Manager","análisis de lenguaje natural en atención médica","almacenamiento de base de datos persistente","DuckDB","gestión de puntos de control","resolución de dependencias","análisis de tendencias históricas","métricas de desempeño","herramientas de AI para atención médica"],"fr":["AgentDB State Manager","analyse de langage naturel en santé","stockage de base de données persistant","DuckDB","gestion des points de contrôle","résolution des dépendances","analyse des tendances historiques","métriques de performance","outils d''IA pour la santé"],"de":["AgentDB State Manager","Analyse von Natürlicher Sprache im Gesundheitswesen","persistenter Datenbank-Speicher","DuckDB","Checkpoint-Verwaltung","Abhängigkeitsauflösung","Analyse von historischen Trends","Leistungsmetriken","KI-Tools für das Gesundheitswesen"],"pt":["AgentDB State Manager","DuckDB","Gemini Code","armazenamento de dados de saúde","análise de métricas","gerenciamento de workflow","integração de dados","soluções de saúde","tecnologias de saúde"],"ru":["AgentDB State Manager","DuckDB","Gemini Code","хранение данных здравоохранения","анализ метрик","управление рабочим процессом","интеграция данных","решения для здравоохранения","технологии здравоохранения"],"ar":["مساعد إدارة حالة AgentDB","DuckDB","Gemini Code","تخزين بيانات الصحة","تحليل المقاييس","إدارة سير العمل","تكامل البيانات","حلول الصحة","تكنولوجيا الصحة"]}},"owner":"stharrold","repo":"yuimedi-paper-20250901","repoPath":"stharrold/yuimedi-paper-20250901","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.612Z","topics":[],"category":"community","skillMd":{"name":"agentdb-state-manager","description":"|","version":"1.0.0","bodyPreview":"# AgentDB State Manager Skill\n\n## Purpose\n\nThe AgentDB State Manager provides persistent database storage for workflow state tracking using DuckDB through Gemini Code''s AgentDB integration. This skill enables:\n\n- **Read-only analytics**: Complex queries over workflow history without parsing files\n- **Checkpoint management**: Store/recover context checkpoints at 100K token threshold\n- **Dependency resolution**: Query task dependencies and critical paths\n- **Metrics analysis**: Historical trends,","body":"# AgentDB State Manager Skill\n\n## Purpose\n\nThe AgentDB State Manager provides persistent database storage for workflow state tracking using DuckDB through Gemini Code''s AgentDB integration. This skill enables:\n\n- **Read-only analytics**: Complex queries over workflow history without parsing files\n- **Checkpoint management**: Store/recover context checkpoints at 100K token threshold\n- **Dependency resolution**: Query task dependencies and critical paths\n- **Metrics analysis**: Historical trends, time-in-phase, bottleneck identification\n\n**Primary source of truth:** TODO_*.md files (AgentDB is an analytics cache)\n\n**Primary purpose:** Data gathering and analysis\n\n**Workflow phase:** Cross-phase (Utilities) - All phases (1-6)\n\n## When to Use\n\nUse this skill when:\n- Querying complex task dependencies or critical paths\n- Analyzing workflow metrics (time-in-phase, completion rates)\n- Storing context checkpoints at 100K tokens\n- Tracking state transitions and historical trends\n- Avoiding repetitive TODO file parsing for analytics\n\n**Triggered by keywords:** \"analyze workflow\", \"query state\", \"checkpoint\", \"workflow metrics\", \"task dependencies\"\n\n## Integration with Workflow\n\n**Phase integration:** Cross-phase (Utilities)\n\nThis skill integrates with all workflow phases:\n\n**Phase 0 (Setup):**\n- Initialize AgentDB schema on first use\n- Load canonical state definitions from workflow-states.json\n\n**Phase 1 (Planning - BMAD):**\n- Track BMAD Q&A responses\n- Store epic definitions and requirements\n\n**Phase 2 (Specification + Implementation):**\n- Sync tasks from TODO_*.md to AgentDB\n- Query task dependencies for parallel execution\n- Track implementation progress\n\n**Phase 3 (Quality):**\n- Store quality gate results\n- Track test coverage trends\n- Historical quality metrics\n\n**Phase 4 (Integration):**\n- Store as-built deviation data\n- Metrics for feedback loop\n- Compare planning vs actual\n\n**Phase 5 (Release):**\n- Release workflow state tracking\n- Final QA checkpoint data\n\n**Phase 6 (Hotfix):**\n- Hotfix-specific state tracking\n- Emergency rollback data\n\n**Context checkpoints (all phases):**\n- Store checkpoint at 100K tokens\n- Faster resume with structured queries vs file parsing\n\n**Orchestrator integration:**\n- workflow-orchestrator optionally calls AgentDB for complex queries\n- Fallback to file parsing if AgentDB unavailable\n- Automatic sync after TODO file updates\n\n## Official Documentation Alignment\n\nThis skill follows the local workflow system patterns which extend official Gemini Code skill specifications:\n\n**Official Gemini Code Skills:**\n- Specification: https://docs.gemini.com/en/docs/agents-and-tools/agent-skills\n- Building Agents: https://docs.gemini.com/en/docs/agents-and-tools/building-agents\n- AgentDB Documentation: (Reference from TODO_agentdb-prompt-template.md)\n\n**Local Pattern Extensions:**\n\n**file_structure:**\n- Local: [''SKILL.md'', ''GEMINI.md'', ''README.md'', ''CHANGELOG.md'', ''ARCHIVED/'', ''scripts/'', ''templates/'']\n- Official: [''skill.md'', ''README.md'']\n- Rationale: Extended structure supports multi-phase workflow with version tracking, context files, and archived materials\n\n**frontmatter:**\n- Local: YAML with ''name'', ''version'', ''description'' fields\n- Official: YAML with ''name'', ''description'' fields only\n- Rationale: ''version'' field enables semantic versioning integration with validate_versions.py and UPDATE_CHECKLIST.md workflow\n\n**directory_organization:**\n- Local: scripts/, templates/ subdirectories\n- Official: Flat structure with skill.md\n- Rationale: Separates Python code (scripts/) from templates (workflow-states.json) for better maintainability\n\nThese extensions support the multi-phase workflow system while maintaining compatibility with core Gemini Code concepts.\n\n## Architecture\n\n### Data Flow (Read-Only Analytics Mode)\n\n```\nTODO_*.md (source of truth)\n    ↓\nsync_todo_to_db.py\n    ↓\nAgentDB (DuckDB)\n    ↓\nquery_state.py / analyze_metrics.py\n    ↓\nAnalytics results\n```\n\n### Session ID Generation\n\nAgentDB requires a session ID for database identification. This skill uses:\n\n**Method: Timestamp-based (reproducible)**\n```python\nfrom datetime import datetime\nimport hashlib\n\n# Generate session ID from current timestamp\ncurrent_time = datetime.utcnow().isoformat()\nsession_id = hashlib.md5(current_time.encode()).hexdigest()[:16]\n# Example: \"f8e7d6c5b4a39281\"\n```\n\n**Rationale:** Provides reproducible session IDs across agent invocations within the same timeframe, balancing uniqueness with reproducibility.\n\n### Schema Design (Immutable Append-Only)\n\n**Core principle:** NEVER UPDATE or DELETE records - always INSERT new records\n\n**Primary table: workflow_records**\n```sql\nCREATE TABLE IF NOT EXISTS workflow_records (\n    record_id UUID PRIMARY KEY DEFAULT uuid(),\n    record_datetimestamp TIMESTAMP DEFAULT current_timestamp,\n    object_id VARCHAR NOT NULL,     -- Stable ID for workflow object\n    object_type VARCHAR NOT NULL,   -- ''feature'', ''task'', ''epic'', etc.\n    object_state VARCHAR NOT NULL,  -- ''20_in-progress'', ''99_done'', etc.\n    object_metadata JSON             -- Framework, dependencies, etc.\n);\n\nCREATE INDEX idx_records_object\nON workflow_records(object_id, record_datetimestamp DESC);\n```\n\n**Current state query pattern:**\n```sql\n-- Get latest state for each object\nSELECT DISTINCT ON (object_id)\n    object_id, object_type, object_state, object_metadata\nFROM workflow_records\nWHERE object_type = ''task''\nORDER BY object_id, record_datetimestamp DESC;\n```\n\n## Usage\n\n### 1. Initialize AgentDB (First Use)\n\n```bash\n# Initialize database schema and load state definitions\npython .gemini/skills/agentdb-state-manager/scripts/init_database.py\n```\n\n**What it does:**\n- Creates workflow_records table\n- Loads workflow-states.json\n- Sets up indexes for efficient queries\n- Stores session metadata\n\n### 2. Sync TODO Files to AgentDB\n\n```bash\n# Sync all TODO_*.md files to database\npython .gemini/skills/agentdb-state-manager/scripts/sync_todo_to_db.py\n\n# Sync specific TODO file\npython .gemini/skills/agentdb-state-manager/scripts/sync_todo_to_db.py \\\n  TODO_feature_20251023T143000Z_my-feature.md\n```\n\n**What it does:**\n- Parses YAML frontmatter from TODO files\n- Converts to immutable append-only records\n- Stores workflow progress, tasks, quality gates\n- Preserves full state history\n\n### 3. Query Current Workflow State\n\n```bash\n# Get current state of all workflows\npython .gemini/skills/agentdb-state-manager/scripts/query_state.py\n\n# Query specific workflow\npython .gemini/skills/agentdb-state-manager/scripts/query_state.py \\\n  --slug my-feature\n\n# Query task dependencies\npython .gemini/skills/agentdb-state-manager/scripts/query_state.py \\\n  --dependencies --task impl_003\n```\n\n**What it does:**\n- Queries latest state for each object\n- Resolves task dependencies\n- Identifies blocked tasks\n- Shows critical path\n\n### 4. Analyze Workflow Metrics\n\n```bash\n# Generate metrics report\npython .gemini/skills/agentdb-state-manager/scripts/analyze_metrics.py\n\n# Historical trends\npython .gemini/skills/agentdb-state-manager/scripts/analyze_metrics.py \\\n  --trends --days 30\n\n# Bottleneck analysis\npython .gemini/skills/agentdb-state-manager/scripts/analyze_metrics.py \\\n  --bottlenecks\n```\n\n**What it does:**\n- Calculates time-in-phase for workflows\n- Identifies bottlenecks and slow phases\n- Tracks quality gate pass/fail rates\n- Compares planning estimates vs actual\n\n### 5. Context Checkpoint Management\n\n```bash\n# Store checkpoint at 100K tokens\npython .gemini/skills/agentdb-state-manager/scripts/checkpoint_manager.py \\\n  store --todo TODO_feature_*.md\n\n# List available checkpoints\npython .gemini/skills/agentdb-state-manager/scripts/checkpoint_manager.py list\n\n# Restore from checkpoint\npython .gemini/skills/agentdb-state-manager/scripts/checkpoint_manager.py \\\n  restore --checkpoint-id <uuid>\n```\n\n**What it does:**\n- Stores complete workflow state to AgentDB\n- Records token count, phase, step, last task\n- Provides resume instructions\n- Faster recovery than parsing TODO files\n\n## Best Practices\n\n### 1. AgentDB as Analytics Cache\n\n**✓ DO:** Treat TODO_*.md files as source of truth\n**✗ DON''T:** Modify TODO files based on AgentDB state\n\n**Rationale:** Files are git-tracked and permanent; AgentDB sessions last 24 hours\n\n### 2. Sync After TODO Updates\n\n**✓ DO:** Run sync_todo_to_db.py after every TODO file update\n**✗ DON''T:** Let AgentDB state drift from file state\n\n**Rationale:** AgentDB is a cache - it must stay synchronized\n\n### 3. Use for Complex Queries Only\n\n**✓ DO:** Use AgentDB for dependency graphs, metrics, historical analysis\n**✗ DON''T:** Use for simple current state queries (parse TODO file instead)\n\n**Rationale:** Minimize token overhead - use database for queries that justify the cost\n\n### 4. Immutable Records\n\n**✓ DO:** Always INSERT new records for state changes\n**✗ DON''T:** UPDATE or DELETE existing records\n\n**Rationale:** Preserves full history for temporal analysis\n\n### 5. Session Lifetime Awareness\n\n**✓ DO:** Re-initialize at session start if needed\n**✗ DON''T:** Assume AgentDB persists across days\n\n**Rationale:** 24-hour auto-deletion - treat as ephemeral cache\n\n## Scripts Reference\n\n### init_database.py\n**Purpose:** Initialize AgentDB schema and load state definitions\n**When to run:** First use in a session, or if schema corrupted\n**Token cost:** ~300-400 tokens\n\n### sync_todo_to_db.py\n**Purpose:** Sync TODO_*.md files to AgentDB\n**When to run:** After every TODO file update\n**Token cost:** ~200-300 tokens per TODO file\n\n### query_state.py\n**Purpose:** Query current workflow state and dependencies\n**When to run:** Complex state queries (dependency graphs, critical paths)\n**Token cost:** ~100-200 tokens per query\n\n### analyze_metrics.py\n**Purpose:** Historical metrics and trend analysis\n**When to run:** End of phase, workflow retrospectives\n**Token cost:** ~400-600 tokens (complex queries)\n\n### checkpoint_manager.py\n**Purpose:** Store/restore context checkpoints\n**When to run:** At 100K token threshold, or before context reset\n**Token cost:** ~200-400 tokens (store + verify)\n\n## Token Efficiency\n\n### Before AgentDB (Manual File Parsing)\n\n**Complex dependency query:**\n1. Read TODO_*.md file (~1,500 tokens)\n2. Parse YAML frontmatter (~500 tokens)\n3. Iterate through tasks (~1,000 tokens)\n4. Resolve dependencies (~800 tokens)\n**Total:** ~3,800 tokens\n\n### After AgentDB (Database Query)\n\n**Same query:**\n1. Run query_state.py --dependencies (~200 tokens)\n2. Parse SQL results (~100 tokens)\n**Total:** ~300 tokens\n\n**Savings:** ~3,500 tokens (92% reduction) for complex queries\n\n### Context Checkpoint Recovery\n\n**Before AgentDB:**\n- Parse TODO_*.md (~1,500 tokens)\n- Reconstruct state (~1,000 tokens)\n- Determine next step (~800 tokens)\n**Total:** ~3,300 tokens\n\n**After AgentDB:**\n- Query checkpoint table (~150 tokens)\n- Load resume instructions (~100 tokens)\n**Total:** ~250 tokens\n\n**Savings:** ~3,050 tokens (92% reduction)\n\n## Integration with Other Skills\n\n### workflow-orchestrator\n- Calls query_state.py for complex next-step determination\n- Uses checkpoint_manager.py at 100K tokens\n- Falls back to file parsing if AgentDB unavailable\n\n### workflow-utilities\n- todo_updater.py triggers sync_todo_to_db.py after updates\n- Dual write: update file + sync to database\n\n### speckit-author\n- Uses AgentDB for as-built metrics (update_asbuilt.py)\n- Queries historical planning accuracy\n\n### quality-enforcer\n- Stores quality gate results to AgentDB\n- Tracks coverage trends over time\n\n### bmad-planner\n- Stores BMAD Q&A responses\n- Epic definition tracking\n\n## Related Documentation\n\n- **[GEMINI.md](GEMINI.md)** - Gemini Code usage context\n- **[README.md](README.md)** - Human-readable overview\n- **[CHANGELOG.md](CHANGELOG.md)** - Version history\n- **[templates/workflow-states.json](templates/workflow-states.json)** - Canonical state definitions\n\n## Related Skills\n\n- **workflow-orchestrator** - Calls AgentDB for complex queries\n- **workflow-utilities** - Triggers sync after TODO updates\n- **speckit-author** - Uses for as-built metrics\n- **quality-enforcer** - Stores quality gate results\n- **bmad-planner** - Stores planning data\n\n## Limitations\n\n1. **Session lifetime:** AgentDB persists for 24 hours, then auto-deleted\n2. **Source of truth:** TODO_*.md files remain authoritative\n3. **Sync overhead:** ~200-300 tokens per sync operation\n4. **DuckDB constraints:** Optimized for OLAP (analytics), not OLTP (transactions)\n5. **No vector search:** Unlike PostgreSQL pgvector\n\n## Academic References\n\nThis skill implements the **MIT Agent Synchronization Pattern** based on:\n\n> **Meng, E., & Jackson, D. (2025).** \"What You See Is What It Does: A Structural Pattern for Legible Software.\"\n> *Onward! at SPLASH 2025*. arXiv:2508.14511v1.\n> https://arxiv.org/abs/2508.14511\n\n**Key concepts from the paper:**\n- **Concepts**: Fully independent services (implemented as agents/worktrees)\n- **Synchronizations**: Event-based rules mediating between services (implemented as `agent_synchronizations` table)\n\nThe pattern improves incrementality, integrity, and transparency in multi-agent workflows.\n\n## Version History\n\n**v1.0.0 (2025-11-02):**\n- Initial release\n- Read-only analytics mode\n- Sync from TODO files to AgentDB\n- Complex query support (dependencies, metrics)\n- Context checkpoint storage\n- All phases (1-6) integration\n"},"lastSynced":"2026-03-08T02:13:14.002Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents working with healthcare data, needing persistent database storage for workflow state tracking and read-only analytics","zh":"适用于处理医疗保健数据的AI代理，需要持久的数据库存储以跟踪工作流状态和只读分析","ja":"ヘルスケアデータを操作するAIエージェントに適しています。ワークフローの状態を追跡し、読み取り専用の分析を行うために、永続的なデータベースストレージが必要です","ko":"건강 관리 데이터를 처리하는 AI 에이전트에게 적합하며, 워크플로우 상태 추적 및 읽기 전용 분석을 위해 지속적인 데이터베이스 저장소가 필요합니다","es":"Ideal para agentes de IA que trabajan con datos de atención médica, necesitan almacenamiento de base de datos persistente para seguimiento de estado de flujo de trabajo y análisis de solo lectura","fr":"Idéal pour les agents IA travaillant avec des données de santé, nécessitant un stockage de base de données persistant pour le suivi de l''état du flux de travail et l''analyse en lecture seule","de":"Ideal für KI-Agents, die mit Gesundheitsdaten arbeiten, persistente Datenbank-Speicherung für Workflow-Zustandsverfolgung und schreibgeschützte Analyse benötigen","pt":"Ideal para agentes de IA que trabalham com dados de saúde, necessitando de armazenamento de banco de dados persistente para rastreamento de estado de fluxo de trabalho e análise somente leitura","ru":"Идеально для агентов ИИ, работающих с данными здравоохранения, требующих постоянного хранилища базы данных для отслеживания состояния рабочего процесса и аналитики только для чтения","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يعملون مع بيانات الرعاية الصحية، وهم بحاجة إلى تخزين قاعدة بيانات مستمر للتعقب حالة سير العمل وتحليل قراءة فقط"},"recommendation":{"en":"Empowers agents to perform complex queries over workflow history using DuckDB, enabling checkpoint management and dependency resolution through Gemini Code''s AgentDB integration, and providing historical metrics analysis","zh":"赋予代理执行复杂的工作流历史查询，使用DuckDB，通过Gemini Code的AgentDB集成实现检查点管理和依赖解析，并提供历史指标分析","ja":"DuckDBを使用して、ワークフローの履歴に対する複雑なクエリを実行することができるため、チェックポイントの管理や依存関係の解決がGemini CodeのAgentDB統合を通じて可能になり、歴史的指標分析も提供されます","ko":"DuckDB를 사용하여 워크플로우 기록에 대한 복잡한 쿼리를 수행할 수 있으므로 Gemini Code의 AgentDB 통합을 통해 체크포인트 관리 및 종속성 해결이 가능하며 역사적 지표 분석도 제공됩니다","es":"Habilita a los agentes a realizar consultas complejas sobre el historial del flujo de trabajo utilizando DuckDB, lo que permite la gestión de puntos de control y la resolución de dependencias a través de la integración de AgentDB de Gemini Code, y proporciona análisis de métricas históricas","fr":"Permet aux agents d''exécuter des requêtes complexes sur l''historique du flux de travail en utilisant DuckDB, ce qui permet la gestion des points de contrôle et la résolution des dépendances via l''intégration d''AgentDB de Gemini Code, et fournit une analyse de métriques historiques","de":"Ermöglicht es Agents, komplexe Abfragen über die Workflow-Historie mit DuckDB durchzuführen, wodurch Checkpoint-Management und Abhängigkeitsauflösung durch die AgentDB-Integration von Gemini Code ermöglicht werden, und historische Metrikanalysen bereitstellt","pt":"Habilita agentes a realizar consultas complexas sobre o histórico do fluxo de trabalho usando DuckDB, permitindo gerenciamento de pontos de verificação e resolução de dependência por meio da integração do AgentDB do Gemini Code, e fornecendo análise de métricas históricas","ru":"Позволяет агентам выполнять сложные запросы над историей рабочего процесса с помощью DuckDB, обеспечивая управление контрольными точками и разрешение зависимостей через интеграцию AgentDB от Gemini Code, и предоставляя анализ исторических метрик","ar":"تمكن الوكلاء من أداء استفسارات معقدة على تاريخ سير العمل باستخدام DuckDB، وتمكين إدارة نقاط التحقق وحل التبعيات من خلال تكامل AgentDB من Gemini Code، وتوفير تحليل المetrics التاريخية"},"useCases":{"en":["Tracking workflow state for healthcare data analysis","Managing checkpoints at 100K token threshold for large-scale workflows","Analyzing historical trends and metrics for workflow optimization"],"zh":["跟踪医疗保健数据分析的工作流状态","在大规模工作流中管理100K令牌阈值的检查点","分析历史趋势和指标以优化工作流"],"ja":["ヘルスケアデータ分析のワークフローの状態を追跡する","大規模なワークフローで100Kトークンしきい値のチェックポイントを管理する","ワークフローの最適化のために歴史的傾向と指標を分析する"],"ko":["건강 관리 데이터 분석을 위한 워크플로우 상태 추적","대규모 워크플로우에서 100K 토큰 임계값의 체크포인트 관리","워크플로우 최적화를 위한 역사적 경향 및 지표 분석"],"es":["Seguimiento del estado del flujo de trabajo para análisis de datos de atención médica","Gestión de puntos de control en el umbral de 100K tokens para flujos de trabajo a gran escala","Análisis de tendencias y métricas históricas para la optimización del flujo de trabajo"],"fr":["Suivi de l''état du flux de travail pour l''analyse de données de santé","Gestion des points de contrôle au seuil de 100K jetons pour les flux de travail à grande échelle","Analyse des tendances et des métriques historiques pour l''optimisation du flux de travail"],"de":["Verfolgung des Workflow-Zustands für die Analyse von Gesundheitsdaten","Verwaltung von Checkpoints bei einer Schwelle von 100K Token für groß angelegte Workflows","Analyse historischer Trends und Metriken für die Workflow-Optimierung"],"pt":["Rastreamento do estado do fluxo de trabalho para análise de dados de saúde","Gerenciamento de pontos de verificação no limiar de 100K tokens para fluxos de trabalho de grande escala","Análise de tendências e métricas históricas para otimização do fluxo de trabalho"],"ru":["Отслеживание состояния рабочего процесса для анализа данных здравоохранения","Управление контрольными точками на пороге 100K токенов для крупномасштабных рабочих процессов","Анализ исторических тенденций и метрик для оптимизации рабочего процесса"],"ar":["تعقب حالة سير العمل لتحليل بيانات الرعاية الصحية","إدارة نقاط التحقق عند عتبة 100K رمز للعمليات المتسلسلة على نطاق واسع","تحليل الاتجاهات والمقاييس التاريخية لتحسين سير العمل"]},"limitations":{"en":["Requires Gemini Code''s AgentDB integration","Dependent on DuckDB for database storage","Limited to read-only analytics"],"zh":["需要Gemini Code的AgentDB集成","依赖于DuckDB进行数据库存储","仅限于读取分析"],"ja":["Gemini CodeのAgentDB統合が必要","DuckDBに依存してデータベースストレージを行う","読み取り専用の分析のみ"],"ko":["Gemini Code의 AgentDB 통합이 필요","DuckDB에 의존하여 데이터베이스 저장소","읽기 전용 분석만"],"es":["Requiere la integración de AgentDB de Gemini Code","Dependiente de DuckDB para el almacenamiento de bases de datos","Limitado a análisis de solo lectura"],"fr":["Nécessite l''intégration d''AgentDB de Gemini Code","Dépendant de DuckDB pour le stockage de bases de données","Limité à l''analyse en lecture seule"],"de":["Benötigt die Integration von AgentDB von Gemini Code","Abhängig von DuckDB für die Datenbank-Speicherung","Begrenzt auf schreibgeschützte Analyse"],"pt":["Requer integração do AgentDB do Gemini Code","Depende do DuckDB para armazenamento de banco de dados","Limitado à análise somente leitura"],"ru":["Требует интеграции AgentDB от Gemini Code","Зависит от DuckDB для хранения базы данных","Ограничен аналитикой только для чтения"],"ar":["يتطلب تكامل AgentDB من Gemini Code","يعتمد على DuckDB لتخزين قاعدة البيانات","محدود بالتحليل القراءة فقط"]},"version":4},"contentHash":"f05d185e6cf85eac6f0b51ea4a8b5071be8318bbffa34a75a6376d20b3d935f4","qualityScore":65}');
