INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stharrold/yuimedi-paper-20250901/agentdb-state-manager', 'agentdb-state-manager', 'stharrold', 'yuimedi-paper-20250901', 'community', 'agentdb-state-manager stharrold yuimedi-paper-20250901 community The agentdb-state-manager skill provides persistent database storage for workflow state tracking, enabling read-only analytics and checkpoint management. It benefits AI agent developers working with healthcare data. AgentDB State Manager 提供了持久的数据库存储，用于跟踪工作流状态，支持读取分析、检查点管理和依赖解析 AgentDB State Manager は、ワークフローの状態を追跡するための永続的なデータベースストレージを提供し、読み取り分析、チェックポイント管理、依存解析をサポートします AgentDB 상태 관리자는 워크플로우 상태 추적을 위한 영속적 데이터베이스 저장소를 제공하며 읽기 전용 분석, 체크포인트 관리 및 종속성 해결을 지원합니다 AgentDB State Manager proporciona almacenamiento de base de datos persistente para el seguimiento del estado del flujo de trabajo utilizando DuckDB. Permite análisis de lectura, gestión de puntos de control y resolución de dependencias AgentDB State Manager fournit un stockage de base de données persistant pour le suivi de l''état des flux de travail en utilisant DuckDB. Il permet l''analyse de lecture, la gestion des points de contrôle et la résolution des dépendances AgentDB State Manager bietet persistenten Datenbank-Speicher für die Nachverfolgung des Workflow-Status mithilfe von DuckDB. Es ermöglicht Leseanalysen, Checkpoint-Verwaltung und Abhängigkeitsauflösung O AgentDB State Manager fornece armazenamento de dados de workflow de saúde com DuckDB e Gemini Code, permitindo análise de métricas e resolução de dependências AgentDB State Manager предоставляет хранение данных рабочего процесса здравоохранения с помощью DuckDB и Gemini Code, позволяя анализировать метрики и разрешать зависимости مساعد إدارة حالة AgentDB يوفر تخزين بيانات سير العمل الصحية مع DuckDB و Gemini Code، مما يسمح بتحليل المقاييس و حل الاعتماديات how to use agentdb-state-manager agentdb-state-manager setup guide what is agentdb-state-manager agentdb-state-manager alternative agentdb-state-manager vs gemini code installing agentdb-state-manager for healthcare AgentDB 状态管理器 自然语言到 SQL 医疗保健数据分析 DuckDB Gemini Code AI 工具 AgentDB 集成 Read-only analytics over workflow history without parsing files Checkpoint management at 100K token threshold using DuckDB Dependency resolution through querying task dependencies and critical paths Metrics analysis for historical trends agentdb-state-manager is a skill that enables persistent database storage for workflow state tracking using DuckDB through Gemini Code''s AgentDB integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rjmurillo/ai-agents/skillforge', 'community', 'rjmurillo', 'ai-agents', 'rjmurillo/ai-agents', 'skillforge', 0, 0, 65, '2026-03-08T01:57:15.614Z', '2026-03-08T02:13:18.538Z', '1b290172e31c21c12abc94e602dc7fff9431e13dffcf06d768f7ce94393b591f', '{"id":"rjmurillo/ai-agents/skillforge","name":"skillforge","description":{"en":"SkillForge is a multi-agent system for software development that intelligently routes input to the right action, creating or recommending skills as needed. It benefits developers by streamlining their workflow","zh":"SkillForge 4.0是一种多代理系统，用于软件开发，提供智能技能路由和创建","ja":"SkillForge 4.0は、ソフトウェア開発用のマルチエージェントシステムであり、スキルルーティングと作成を提供する","ko":"스킬포지 4.0은 소프트웨어 개발을 위한 멀티 에이전트 시스템으로,智能 스킬 라우팅과 생성을 제공합니다","es":"SkillForge es un sistema multiagente para el desarrollo de software que analiza cualquier entrada para encontrar, mejorar o crear habilidades.","fr":"SkillForge est un système multiagent pour le développement de logiciels qui analyse n''importe quelle entrée pour trouver, améliorer ou créer des compétences.","de":"SkillForge ist ein Multiagentensystem für die Softwareentwicklung, das jede Eingabe analysiert, um Fähigkeiten zu finden, zu verbessern oder zu erstellen.","pt":"O SkillForge é um sistema de múltiplos agentes para desenvolvimento de software que analisa qualquer entrada para encontrar, melhorar ou criar a habilidade certa","ru":"SkillForge - это многоагентная система для разработки программного обеспечения, которая анализирует любые входные данные для поиска, улучшения или создания правильного навыка","ar":"SkillForge هو نظام متعدد الوكلاء لتطوير البرمجيات الذي ي分析 أي إدخال لايجاد أو تحسين أو إنشاء المهارة المناسبة"},"seo":{"title":{"en":"SkillForge: Intelligent Skill Router & Creator for AI Agents","zh":"SkillForge 4.0 智能技能路由器与创建工具","ja":"SkillForge 4.0 - AIエージェントによるスキルルーティングと作成","ko":"SkillForge 4.0 - 인공지능 에이전트를 통한 스킬 라우팅 및 생성","es":"Guía de configuración de SkillForge: Herramienta de route...","fr":"Guide de configuration de SkillForge: Outil d''acheminemen...","de":"SkillForge-Setup-Leitfaden: Intelligente Fähigkeits-Route...","pt":"Guia de Configuração do SkillForge - Roteador Inteligente...","ru":"Настройка SkillForge - Интеллектуальный Маршрутизатор Нав...","ar":"إعداد SkillForge - جهاز التوجيه الذكي للمهارات"},"description":{"en":"Discover how SkillForge analyzes input to find, improve, or create skills. Get started with the Quick Start guide and unlock efficient software development","zh":"使用SkillForge 4.0实现智能技能路由和创建，自动化代码审查和调试","ja":"AIエージェントを活用したスキルルーティングと作成。コードレビューとデバッグを自動化する","ko":"스킬포지 4.0을 사용하여智能 스킬 라우팅과 생성을 구현하고 코드 리뷰 및 디버깅을 자동화합니다","es":"Aprende a configurar SkillForge, una herramienta de código abierto que analiza cualquier entrada para encontrar, mejorar o crear habilidades. Descubre sus ca...","fr":"Découvrez comment configurer SkillForge, un outil open source qui analyse n''importe quelle entrée pour trouver, améliorer ou créer des compétences. Explorez ...","de":"Erfahren Sie, wie Sie SkillForge konfigurieren, ein Open-Source-Tool, das jede Eingabe analysiert, um Fähigkeiten zu finden, zu verbessern oder zu erstellen....","pt":"Descubra como o SkillForge pode melhorar o desenvolvimento de software com sua capacidade de análise de entrada e roteamento inteligente","ru":"Узнайте, как SkillForge может улучшить разработку программного обеспечения с помощью своей способности анализировать входные данные и интеллектуального маршр...","ar":"اكتشف كيف يمكن لـ SkillForge تحسين تطوير البرمجيات من خلال قدرته على تحليل المدخلات والتحويل الذكي"},"definition":{"en":"SkillForge is a multi-agent system that analyzes input to find, improve, or create skills, utilizing intelligent routing to optimize software development","zh":"SkillForge 4.0是一种多代理系统，用于分析输入并找到、改进或创建适当的技能","ja":"SkillForge 4.0は、マルチエージェントシステムであり、入力の分析と適切なスキルの検索、改善、作成を行う","ko":"스킬포지 4.0은 입력을 분석하여 적절한 스킬을 찾거나 개선 또는 생성하는 멀티 에이전트 시스템입니다","es":"SkillForge es una herramienta de routeo y creación de habilidades inteligentes que utiliza técnicas de análisis de entrada para mejorar el desarrollo de software.","fr":"SkillForge est un outil d''acheminement et de création de compétences intelligentes qui utilise des techniques d''analyse d''entrée pour améliorer le développement de logiciels.","de":"SkillForge ist ein Tool für die intelligente Weiterleitung und Erstellung von Fähigkeiten, das Techniken der Eingabeanalyse nutzt, um die Softwareentwicklung zu verbessern.","pt":"O que é SkillForge? É um sistema de desenvolvimento de software que usa análise de entrada para rotear ações inteligentes","ru":"Что такое SkillForge? Это система разработки программного обеспечения, которая использует анализ входных данных для интеллектуальной маршрутизации","ar":"ما هو SkillForge? هو نظام تطوير برمجيات يستخدم تحليل الإدخال لتوجيه الإجراءات الذكية"},"features":{"en":["Intelligently routes ANY input to the right action","Creates new skills after checking for duplicates","Recommends existing skills, such as ErrorExplainer","Improves existing skills, like testgen","Supports natural language input for skill creation and improvement","Automates code review with created skills"],"zh":["自动化代码审查","智能技能路由","创建新技能","改进现有技能","支持多种输入格式"],"ja":["コードレビューの自動化","スキルルーティングの智能化","新しいスキルの作成","既存スキルの改善","複数の入力形式のサポート"],"ko":["코드 리뷰 자동화","스킬 라우팅의智能화","새로운 스킬 생성","기존 스킬 개선","여러 입력 형식 지원"],"es":["Análisis de entrada para encontrar habilidades","Creación de habilidades personalizadas","Mejora de habilidades existentes","Compatibilidad con cualquier tipo de entrada","Integración con herramientas de desarrollo de software","Técnicas de routeo inteligente para habilidades"],"fr":["Analyse d''entrée pour trouver des compétences","Création de compétences personnalisées","Amélioration de compétences existantes","Compatibilité avec n''importe quel type d''entrée","Intégration avec des outils de développement de logiciels","Techniques de routage intelligent pour les compétences"],"de":["Eingabeanalyse zur Findung von Fähigkeiten","Erstellung von benutzerdefinierten Fähigkeiten","Verbesserung von bestehenden Fähigkeiten","Kompatibilität mit jedem Eingabetyp","Integration mit Software-Entwicklungstools","Techniken zur intelligenten Weiterleitung von Fähigkeiten"],"pt":["Análise de entrada para roteamento inteligente","Criação de habilidades personalizadas para revisão de código automatizada","Recomendação de habilidades existentes para depuração de erros","Melhoria de habilidades para geração de testes","Integração com tecnologias de desenvolvimento de software"],"ru":["Анализ входных данных для интеллектуальной маршрутизации","Создание пользовательских навыков для автоматического код-ревью","Рекомендация существующих навыков для отладки ошибок","Улучшение навыков для генерации тестов","Интеграция с технологиями разработки программного обеспечения"],"ar":["تحليل الإدخال لتوجيه الإجراءات الذكية","إنشاء مهارات مخصصة لمراجعة الكود التلقائية","توصية بالمهارات الحالية لتصحيح الأخطاء","تحسين المهارات لتوليد الاختبارات","التكامل مع تقنيات تطوير البرمجيات"]},"keywords":{"en":["how to use SkillForge","what is SkillForge","SkillForge alternative","SkillForge vs multi-agent systems","SkillForge install","SkillForge setup guide","intelligent skill routing","software development automation","AI agent skills"],"zh":["SkillForge 4.0","智能技能路由","自动化代码审查","多代理系统","软件开发工具","AIエージェント","代码审查工具"],"ja":["SkillForge 4.0","AIエージェント","コードレビューの自動化","スキルルーティング","マルチエージェントシステム","ソフトウェア開発ツール","コードレビューツール"],"ko":["스킬포지 4.0","인공지능 에이전트","코드 리뷰 자동화","스킬 라우팅","멀티 에이전트 시스템","소프트웨어 개발 도구","코드 리뷰 도구"],"es":["SkillForge","herramienta de routeo de habilidades","creación de habilidades","análisis de entrada","desarrollo de software","multiagente","inteligencia artificial","herramientas de desarrollo","tecnologías de routeo","mejora de habilidades"],"fr":["SkillForge","outil d''acheminement de compétences","création de compétences","analyse d''entrée","développement de logiciels","multiagent","intelligence artificielle","outils de développement","technologies de routage","amélioration de compétences"],"de":["SkillForge","Tool zur Weiterleitung von Fähigkeiten","Erstellung von Fähigkeiten","Eingabeanalyse","Softwareentwicklung","Multiagentensystem","künstliche Intelligenz","Entwicklungstools","Weiterleitetechnologien","Verbesserung von Fähigkeiten"],"pt":["SkillForge","desenvolvimento de software","análise de entrada","roteamento inteligente","revisão de código automatizada","depuração de erros","geração de testes","tecnologias de desenvolvimento de software"],"ru":["SkillForge","разработка программного обеспечения","анализ входных данных","интеллектуальная маршрутизация","автоматическое код-ревью","отладка ошибок","генерация тестов","технологии разработки программного обеспечения"],"ar":["SkillForge","تطوير البرمجيات","تحليل الإدخال","توجيه الإجراءات الذكية","مراجعة الكود التلقائية","تصحيح الأخطاء","توليد الاختبارات","تقنيات تطوير البرمجيات"]}},"owner":"rjmurillo","repo":"ai-agents","repoPath":"rjmurillo/ai-agents","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.614Z","topics":[],"category":"community","skillMd":{"name":"skillforge","description":"Intelligent skill router and creator. Analyzes ANY input to recommend","version":"4.0.0","bodyPreview":"# SkillForge 4.0 - Intelligent Skill Router & Creator\n\nAnalyzes ANY input to find, improve, or create the right skill.\n\n---\n\n## Quick Start\n\n**Any input works.** SkillForge will intelligently route to the right action:\n\n```\n# These all work - SkillForge figures out what you need:\n\nSkillForge: create a skill for automated code review\n→ Creates new skill (after checking no duplicates exist)\n\nhelp me debug this TypeError\n→ Recommends ErrorExplainer skill (existing)\n\nimprove the testgen skill to han","body":"# SkillForge 4.0 - Intelligent Skill Router & Creator\n\nAnalyzes ANY input to find, improve, or create the right skill.\n\n---\n\n## Quick Start\n\n**Any input works.** SkillForge will intelligently route to the right action:\n\n```\n# These all work - SkillForge figures out what you need:\n\nSkillForge: create a skill for automated code review\n→ Creates new skill (after checking no duplicates exist)\n\nhelp me debug this TypeError\n→ Recommends ErrorExplainer skill (existing)\n\nimprove the testgen skill to handle React components better\n→ Enters improvement mode for TestGen\n\ndo I have a skill for database migrations?\n→ Recommends DBSchema, database-migration skills\n\nTypeError: Cannot read property ''map'' of undefined\n→ Routes to debugging skills (error detected)\n```\n\n---\n\n## Triggers\n\n### Creation Triggers\n- `SkillForge: {goal}` - Full autonomous skill creation\n- `create skill` - Natural language activation\n- `design skill for {purpose}` - Purpose-first creation\n- `ultimate skill` - Emphasize maximum quality\n- `skillforge --plan-only` - Generate specification without execution\n\n### Routing Triggers (NEW in v4.0)\n- `{any input}` - Analyzes and routes automatically\n- `do I have a skill for` - Searches existing skills\n- `which skill` / `what skill` - Recommends matching skills\n- `improve {skill-name} skill` - Enters improvement mode\n- `help me with` / `I need to` - Detects task and routes\n\n| Input | Output | Quality Gate |\n|-------|--------|--------------|\n| Any input | Triage → Route → Action | Phase 0 analysis |\n| Explicit create | New skill | Unanimous panel approval |\n| Task/question | Skill recommendation | Match confidence ≥60% |\n\n---\n\n## Process Overview\n\n```\nANY USER INPUT\n(prompt, error, code, URL, question, task request)\n    │\n    ▼\n┌─────────────────────────────────────────────────────┐\n│ Phase 0: SKILL TRIAGE (NEW)                         │\n│ • Classify input type (create/improve/question/task)│\n│ • Scan 250+ skills in ecosystem                     │\n│ • Match against existing skills with confidence %   │\n│ • Route to: USE | IMPROVE | CREATE | COMPOSE        │\n├─────────────────────────────────────────────────────┤\n│         ↓ USE_EXISTING    ↓ IMPROVE      ↓ CREATE   │\n│      [Recommend]      [Load & Enhance] [Continue]   │\n└─────────────────────────────────────────────────────┘\n    │ (if CREATE_NEW or IMPROVE_EXISTING)\n    ▼\n┌─────────────────────────────────────────────────────┐\n│ Phase 1: DEEP ANALYSIS                              │\n│ • Expand requirements (explicit, implicit, unknown) │\n│ • Apply 11 thinking models + Automation Lens        │\n│ • Question until no new insights (3 empty rounds)   │\n│ • Identify automation/script opportunities          │\n├─────────────────────────────────────────────────────┤\n│ Phase 2: SPECIFICATION                              │\n│ • Generate XML spec with all decisions + WHY        │\n│ • Include scripts section (if applicable)           │\n│ • Validate timelessness score ≥ 7                   │\n├─────────────────────────────────────────────────────┤\n│ Phase 3: GENERATION                                 │\n│ • Write SKILL.md with fresh context                 │\n│ • Generate references/, assets/, and scripts/       │\n├─────────────────────────────────────────────────────┤\n│ Phase 4: SYNTHESIS PANEL                            │\n│ • 3-4 Opus agents review independently              │\n│ • Script Agent added when scripts present           │\n│ • All agents must approve (unanimous)               │\n│ • If rejected → loop back with feedback             │\n└─────────────────────────────────────────────────────┘\n    │\n    ▼\nProduction-Ready Agentic Skill\n```\n\n**Key principles:**\n- **Phase 0 prevents duplicates** - Always checks existing skills first\n- Evolution/timelessness is the core lens (score ≥ 7 required)\n- Every decision includes WHY\n- Zero tolerance for errors\n- Autonomous execution at maximum depth\n- Scripts enable self-verification and agentic operation\n\n---\n\n## Commands\n\n| Command | Action |\n|---------|--------|\n| `SkillForge: {goal}` | Full autonomous execution |\n| `SkillForge --plan-only {goal}` | Generate specification only |\n| `SkillForge --quick {goal}` | Reduced depth (not recommended) |\n| `SkillForge --triage {input}` | Run Phase 0 triage only |\n| `SkillForge --improve {skill}` | Enter improvement mode for existing skill |\n\n---\n\n## Phase 0: Skill Triage (NEW in v4.0)\n\nBefore creating anything, SkillForge intelligently analyzes your input to determine the best action.\n\n### How It Works\n\n```\n┌────────────────────────────────────────────────────────────────────┐\n│                        ANY USER INPUT                               │\n│  (prompt, error, code, URL, question, task request, anything)      │\n└────────────────────────────────────────────────────────────────────┘\n                              │\n                              ▼\n┌────────────────────────────────────────────────────────────────────┐\n│  Step 1: INPUT CLASSIFICATION                                       │\n│  ┌─────────────────┐ ┌─────────────────┐ ┌─────────────────┐       │\n│  │ explicit_create │ │ explicit_improve│ │ skill_question  │       │\n│  │ \"create skill\"  │ │ \"improve skill\" │ │ \"do I have...\"  │       │\n│  └─────────────────┘ └─────────────────┘ └─────────────────┘       │\n│  ┌─────────────────┐ ┌─────────────────┐ ┌─────────────────┐       │\n│  │  task_request   │ │  error_message  │ │  code_snippet   │       │\n│  │ \"help me with\"  │ │ \"TypeError...\"  │ │ [pasted code]   │       │\n│  └─────────────────┘ └─────────────────┘ └─────────────────┘       │\n└────────────────────────────────────────────────────────────────────┘\n                              │\n                              ▼\n┌────────────────────────────────────────────────────────────────────┐\n│  Step 2: SKILL ECOSYSTEM SCAN                                       │\n│  • Load index of 250+ skills (discover_skills.py)                  │\n│  • Match input against all skills with confidence scoring          │\n│  • Identify top matches with reasons                               │\n└────────────────────────────────────────────────────────────────────┘\n                              │\n                              ▼\n┌────────────────────────────────────────────────────────────────────┐\n│  Step 3: DECISION MATRIX                                            │\n│                                                                     │\n│  Match ≥80%  + explicit create → CLARIFY (duplicate warning)       │\n│  Match ≥80%  + other input     → USE_EXISTING (recommend skill)    │\n│  Match 50-79%                  → IMPROVE_EXISTING (enhance match)  │\n│  Match <50%  + explicit create → CREATE_NEW (proceed to Phase 1)   │\n│  Multi-domain detected         → COMPOSE (suggest skill chain)     │\n│  Ambiguous input               → CLARIFY (ask for more info)       │\n└────────────────────────────────────────────────────────────────────┘\n```\n\n### Decision Actions\n\n| Action | When | Result |\n|--------|------|--------|\n| **USE_EXISTING** | Match ≥80% | Recommends existing skill(s) to invoke |\n| **IMPROVE_EXISTING** | Match 50-79% | Loads skill and enters enhancement mode |\n| **CREATE_NEW** | Match <50% | Proceeds to Phase 1 (Deep Analysis) |\n| **COMPOSE** | Multi-domain | Suggests skill chain via SkillComposer |\n| **CLARIFY** | Ambiguous or duplicate | Asks user to clarify intent |\n\n### Triage Script\n\n```bash\n# Run triage on any input\npython scripts/triage_skill_request.py \"help me debug this error\"\n\n# JSON output for automation\npython scripts/triage_skill_request.py \"create a skill for payments\" --json\n\n# Examples:\npython scripts/triage_skill_request.py \"TypeError: Cannot read property ''map''\"\n# → USE_EXISTING: Recommends ErrorExplainer (92%)\n\npython scripts/triage_skill_request.py \"create a skill for code review\"\n# → CLARIFY: CodeReview skill exists (85%), create anyway?\n\npython scripts/triage_skill_request.py \"help me with API and auth and testing\"\n# → COMPOSE: Multi-domain, suggests APIDesign + AuthSystem + TestGen chain\n```\n\n### Ecosystem Index\n\nPhase 0 uses a pre-built index of all skills:\n\n```bash\n# Rebuild skill index (run periodically or after installing new skills)\npython scripts/discover_skills.py\n\n# Index location: ~/.cache/skillrecommender/skill_index.json\n# Scans: ~/.claude/skills/, plugins/marketplaces/*, plugins/cache/*\n```\n\n### Integration with Phases 1-4\n\n- **USE_EXISTING**: Exits early, no creation needed\n- **IMPROVE_EXISTING**: Loads existing skill → Phase 1 analyzes gaps → Phase 2-4 enhance\n- **CREATE_NEW**: Full pipeline (Phase 1 → 2 → 3 → 4)\n- **COMPOSE**: Suggests using SkillComposer instead\n- **CLARIFY**: Pauses for user input before proceeding\n\n---\n\n## Validation & Packaging\n\nBefore distribution, validate your skill:\n\n```bash\n# Quick validation (required for packaging)\npython scripts/quick_validate.py ~/.claude/skills/my-skill/\n\n# Full structural validation\npython scripts/validate-skill.py ~/.claude/skills/my-skill/\n\n# Package for distribution\npython scripts/package_skill.py ~/.claude/skills/my-skill/ ./dist\n```\n\n### Frontmatter Requirements\n\nSkills must use only these allowed frontmatter properties:\n\n| Property | Required | Description |\n|----------|----------|-------------|\n| `name` | Yes | Hyphen-case, max 64 chars |\n| `description` | Yes | Max 1024 chars, no angle brackets |\n| `license` | No | MIT, Apache-2.0, etc. |\n| `allowed-tools` | No | Restrict tool access |\n| `metadata` | No | Custom fields (version, model, etc.) |\n\n```yaml\n---\nname: my-skill\ndescription: What this skill does\nlicense: MIT\nmetadata:\n  version: 1.0.0\n  model: claude-opus-4-5-20251101\n---\n```\n\n---\n\n## Skill Output Structure\n\n```\n~/.claude/skills/{skill-name}/\n├── SKILL.md                    # Main entry point (required)\n├── references/                 # Deep documentation (optional)\n│   ├── patterns.md\n│   └── examples.md\n├── assets/                     # Templates (optional)\n│   └── templates/\n└── scripts/                    # Automation scripts (optional)\n    ├── validate.py             # Validation/verification\n    ├── generate.py             # Artifact generation\n    └── state.py                # State management\n```\n\n### Scripts Directory\n\nScripts enable skills to be **agentic** - capable of autonomous operation with self-verification.\n\n| Category | Purpose | When to Include |\n|----------|---------|-----------------|\n| **Validation** | Verify outputs meet standards | Skill produces artifacts |\n| **Generation** | Create artifacts from templates | Repeatable artifact creation |\n| **State Management** | Track progress across sessions | Long-running operations |\n| **Transformation** | Convert/process data | Data processing tasks |\n| **Calculation** | Compute metrics/scores | Scoring or analysis |\n\n**Script Requirements:**\n- Python 3.x with standard library only (graceful fallbacks for extras)\n- `Result` dataclass pattern for structured returns\n- Exit codes: 0=success, 1=failure, 10=validation failure, 11=verification failure\n- Self-verification where applicable\n- Documented in SKILL.md with usage examples\n\nSee: [references/script-integration-framework.md](references/script-integration-framework.md)\n\n---\n\n## Anti-Patterns\n\n| Avoid | Why | Instead |\n|-------|-----|---------|\n| Duplicate skills | Bloats registry | Check existing first |\n| Single trigger | Hard to discover | 3-5 varied phrases |\n| No verification | Can''t confirm success | Measurable outcomes |\n| Over-engineering | Complexity without value | Start simple |\n| Missing WHY | Can''t evolve | Document rationale |\n| Invalid frontmatter | Can''t package | Use allowed properties only |\n\n---\n\n## Verification Checklist\n\nAfter creation:\n\n- [ ] Frontmatter valid (only allowed properties)\n- [ ] Name is hyphen-case, ≤64 chars\n- [ ] Description ≤1024 chars, no `<` or `>`\n- [ ] 3-5 trigger phrases defined\n- [ ] Timelessness score ≥ 7\n- [ ] `python scripts/quick_validate.py` passes\n\n---\n\n## Deep Dives\n\nFor detailed implementation guides, see:\n\n- [Phase 1: Analysis](references/phase1-analysis-deep-dive.md) - Input expansion, multi-lens analysis, regression questioning, automation analysis\n- [Phase 2: Specification](references/phase2-specification-deep-dive.md) - Specification structure and validation\n- [Phase 3: Generation](references/phase3-generation-deep-dive.md) - Generation order and quality checks\n- [Phase 4: Multi-Agent Synthesis](references/phase4-synthesis-deep-dive.md) - Panel composition, evaluation, consensus protocol\n- [Evolution/Timelessness](references/evolution-timelessness.md) - Temporal projection, timelessness scoring, anti-obsolescence patterns\n- [Architecture Patterns](references/architecture-patterns.md) - Pattern selection decision tree\n- [Configuration](references/configuration.md) - SkillForge configuration settings\n\n---\n\n## References\n\n- [Regression Questions](references/regression-questions.md) - Complete question bank (7 categories)\n- [Multi-Lens Framework](references/multi-lens-framework.md) - 11 thinking models guide\n- [Specification Template](references/specification-template.md) - XML spec structure\n- [Evolution Scoring](references/evolution-scoring.md) - Timelessness evaluation\n- [Synthesis Protocol](references/synthesis-protocol.md) - Multi-agent panel details\n- [Script Integration Framework](references/script-integration-framework.md) - When and how to create scripts\n- [Script Patterns Catalog](references/script-patterns-catalog.md) - Standard Python patterns\n\n---\n\n## Related Skills\n\n| Skill | Relationship |\n|-------|--------------|\n| skill-composer | Can orchestrate created skills |\n| claude-authoring-guide | Deeper patterns reference |\n| codereview | Pattern for multi-agent panels |\n| maker-framework | Zero error standard source |\n\n---\n\n## Extension Points\n\n1. **Additional Lenses:** Add new thinking models to `references/multi-lens-framework.md`\n2. **New Synthesis Agents:** Extend panel beyond 4 agents for specific domains\n3. **Custom Patterns:** Add architecture patterns to selection guide\n4. **Domain Templates:** Add domain-specific templates to `assets/templates/`\n5. **Script Patterns:** Add new patterns to `references/script-patterns-catalog.md`\n6. **Script Categories:** Extend the 7 script categories for new use cases\n"},"lastSynced":"2026-03-08T02:13:18.538Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Agent System Developers needing intelligent skill routing and creation capabilities.","zh":"适合需要智能技能路由和创建能力的多智能体系统开发人员。","ja":"マルチエージェントシステム開発者が智能的なスキルルーティングと作成機能を必要とする場合に最適です。","ko":"지능형 스킬 라우팅 및 생성 기능이 필요한 멀티 에이전트 시스템 개발자에게 적합합니다.","es":"Perfecto para desarrolladores de sistemas de multiagentes que necesitan capacidades de enrutamiento y creación de habilidades inteligentes.","fr":"Parfait pour les développeurs de systèmes multi-agents ayant besoin de capacités de routage et de création de compétences intelligentes.","de":"Perfekt für Entwickler von Multi-Agenten-Systemen, die intelligente Fähigkeitsroutingleistungen und Erstellungsfunktionen benötigen.","pt":"Perfeito para desenvolvedores de Sistemas de Múltiplos Agentes que precisam de roteamento de habilidades inteligentes e capacidades de criação.","ru":"Идеально подходит для разработчиков Систем Множественных Агентов, которым необходимы интеллектуальные возможности маршрутизации и создания навыков.","ar":"مثالي لمطوري نظام متعدد الوكلاء الذين يحتاجون إلى مسارات مهارات ذكية وقدرات إنشاء."},"recommendation":{"en":"Empowers agents to analyze any input and intelligently route it to the right action, creating or recommending skills as needed, utilizing advanced routing protocols and multi-agent system architectures.","zh":"赋予智能体分析任何输入并智能地将其路由到正确的操作的能力，根据需要创建或推荐技能，利用高级路由协议和多智能体系统架构。","ja":"エージェントに任意の入力分析し、正しいアクションにインテリジェントにルーティングする機能を与え、必要に応じてスキルを作成または推奨します。高度なルーティングプロトコルとマルチエージェントシステムアーキテクチャを利用します。","ko":"에이전트가任意의 입력을 분석하고 올바른 동작으로 지능형으로 라우팅할 수 있는 기능을 부여하며, 필요에 따라 스킬을 생성하거나 추천합니다. 고급 라우팅 프로토콜과 멀티 에이전트 시스템 아키텍처를 활용합니다.","es":"Habilita a los agentes a analizar cualquier entrada y enrutarla inteligentemente a la acción correcta, creando o recomendando habilidades según sea necesario, utilizando protocolos de enrutamiento avanzados y arquitecturas de sistemas de multiagentes.","fr":"Permet aux agents d''analyser toute entrée et de la router intelligemment vers l''action appropriée, en créant ou en recommandant des compétences selon les besoins, en utilisant des protocoles de routage avancés et des architectures de systèmes multi-agents.","de":"Ermöglicht es Agents, jede Eingabe zu analysieren und sie intelligent an die richtige Aktion zu routen, indem sie Fähigkeiten nach Bedarf erstellt oder empfiehlt, unter Verwendung von fortschrittlichen Routingprotokollen und Multi-Agenten-Systemarchitekturen.","pt":"Habilita os agentes a analisar qualquer entrada e encaminhá-la inteligentemente para a ação certa, criando ou recomendando habilidades conforme necessário, utilizando protocolos de roteamento avançados e arquiteturas de sistema de múltiplos agentes.","ru":"Наделяет агентов возможностью анализировать любые входные данные и интеллектуально маршрутизировать их к правильному действию, создавая или рекомендую навыки по мере необходимости, используя продвинутые протоколы маршрутизации и архитектуры системы множественных агентов.","ar":"يتمكّن الوكلاء من تحليل أي إدخال وتوجيهه ذكاءً إلى الإجراء الصحيح، مما يخلق أو يوصي بالمهارات حسب الحاجة، مستخدماً بروتوكولات التوجيه المتقدمة وعمارة نظام متعدد الوكلاء."},"useCases":{"en":["Automating skill creation for specific tasks","Debugging and improving existing skills","Intelligently routing input to relevant skills"],"zh":["为特定任务自动创建技能","调试和改进现有技能","将输入智能地路由到相关技能"],"ja":["特定タスク用のスキル自動作成","既存スキルのデバッグと改善","入力を関連スキルにインテリジェントにルーティング"],"ko":["특정 작업을 위한 스킬 자동 생성","기존 스킬의 디버깅 및 개선","입력을 관련 스킬로 지능형으로 라우팅"],"es":["Automatización de la creación de habilidades para tareas específicas","Depuración y mejora de habilidades existentes","Enrutamiento inteligente de la entrada a habilidades relevantes"],"fr":["Automation de la création de compétences pour des tâches spécifiques","Débogage et amélioration des compétences existantes","Routage intelligent de l''entrée vers des compétences pertinentes"],"de":["Automatisierung der Erstellung von Fähigkeiten für spezifische Aufgaben","Fehlersuche und Verbesserung bestehender Fähigkeiten","Intelligentes Routen von Eingaben an relevante Fähigkeiten"],"pt":["Automatizar a criação de habilidades para tarefas específicas","Depurar e melhorar habilidades existentes","Encaminhar inteligentemente a entrada para habilidades relevantes"],"ru":["Автоматизировать создание навыков для конкретных задач","Отладить и улучшить существующие навыки","Интеллектуально маршрутизировать входные данные к соответствующим навыкам"],"ar":["توسيع إنشاء المهارات لتasks محددة","تصحيح أخطاء المهارات الحالية وتحسينها","توجيه الإدخال ذكاءً إلى المهارات ذات الصلة"]},"limitations":{"en":["Requires comprehensive input analysis capabilities","Dependent on existing skill library for recommendations"],"zh":["需要综合输入分析能力","依赖于现有技能库进行推荐"],"ja":["包括的入力分析機能が必要","既存のスキルライブラリに依存して推奨"],"ko":["포괄적인 입력 분석 기능이 필요","기존 스킬 라이브러리에 의존하여 추천"],"es":["Requiere capacidades de análisis de entrada comprehensivas","Dependiente de la biblioteca de habilidades existente para recomendaciones"],"fr":["Nécessite des capacités d''analyse d''entrée complètes","Dépend de la bibliothèque de compétences existante pour les recommandations"],"de":["Erfordert umfassende Eingabeanalysefunktionen","Abhängig von der bestehenden Fähigkeitsbibliothek für Empfehlungen"],"pt":["Exige capacidades de análise de entrada abrangente","Depende da biblioteca de habilidades existente para recomendações"],"ru":["Требует всесторонних возможностей анализа входных данных","Зависит от существующей библиотеки навыков для рекомендаций"],"ar":["يتطلب قدرات تحليل إدخال شاملة","يعتمد على مكتبة المهارات الحالية للتوصيات"]},"version":4},"contentHash":"1b290172e31c21c12abc94e602dc7fff9431e13dffcf06d768f7ce94393b591f","qualityScore":65}');
