INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rjmurillo/ai-agents/skillforge', 'skillforge', 'rjmurillo', 'ai-agents', 'community', 'skillforge rjmurillo ai-agents community SkillForge is a multi-agent system for software development that intelligently routes input to the right action, creating or recommending skills as needed. It benefits developers by streamlining their workflow SkillForge 4.0是一种多代理系统，用于软件开发，提供智能技能路由和创建 SkillForge 4.0は、ソフトウェア開発用のマルチエージェントシステムであり、スキルルーティングと作成を提供する 스킬포지 4.0은 소프트웨어 개발을 위한 멀티 에이전트 시스템으로,智能 스킬 라우팅과 생성을 제공합니다 SkillForge es un sistema multiagente para el desarrollo de software que analiza cualquier entrada para encontrar, mejorar o crear habilidades. SkillForge est un système multiagent pour le développement de logiciels qui analyse n''importe quelle entrée pour trouver, améliorer ou créer des compétences. SkillForge ist ein Multiagentensystem für die Softwareentwicklung, das jede Eingabe analysiert, um Fähigkeiten zu finden, zu verbessern oder zu erstellen. O SkillForge é um sistema de múltiplos agentes para desenvolvimento de software que analisa qualquer entrada para encontrar, melhorar ou criar a habilidade certa SkillForge - это многоагентная система для разработки программного обеспечения, которая анализирует любые входные данные для поиска, улучшения или создания правильного навыка SkillForge هو نظام متعدد الوكلاء لتطوير البرمجيات الذي ي分析 أي إدخال لايجاد أو تحسين أو إنشاء المهارة المناسبة how to use SkillForge what is SkillForge SkillForge alternative SkillForge vs multi-agent systems SkillForge install SkillForge setup guide intelligent skill routing software development automation AI agent skills SkillForge 4.0 智能技能路由 自动化代码审查 多代理系统 软件开发工具 AIエージェント 代码审查工具 Intelligently routes ANY input to the right action Creates new skills after checking for duplicates Recommends existing skills, such as ErrorExplainer Improves existing skills, like testgen Supports natural language input for skill creation and improvement Automates code review with created skills SkillForge is a multi-agent system that analyzes input to find, improve, or create skills, utilizing intelligent routing to optimize software development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brazil-bench/pourpoise/pdd', 'community', 'brazil-bench', 'pourpoise', 'brazil-bench/pourpoise', 'pdd', 0, 0, 65, '2026-03-08T01:57:15.644Z', '2026-03-08T02:13:44.788Z', '1e5b1d978a1e8328d9b8f30803a4875b15985d2a3f920af9bc063707eb5c3812', '{"id":"brazil-bench/pourpoise/pdd","name":"pdd","description":{"en":"pdd is a methodology for systematically refining ideas into detailed design documents with implementation plans. It benefits developers and organizations by providing a structured approach to transforming rough concepts into actionable plans.","zh":"PDD 是一种基于 Prompt-Driven Development 的项目开发方法，通过迭代的过程，实现从粗略的想法到详细的设计文档和实施计划的转变","ja":"PDD は、プロンプト駆動開発に基づくプロジェクト開発方法で、反復的なプロセスを通じて、アイデアから詳細な設計書と実装計画までを実現","ko":"PDD는 프롬프트 드리븐 개발을 기반으로 하는 프로젝트 개발 방법으로, 반복적인 과정을 통해 초기 아이디어에서 상세한 설계 문서와 구현 계획까지를 실현","es":"pdd es una metodología de desarrollo que guía la transformación de ideas en documentos de diseño detallados con planes de implementación y listas de tareas","fr":"pdd est une méthodologie de développement qui guide la transformation d''idées en documents de conception détaillés avec des plans de mise en œuvre et des listes de tâches","de":"pdd ist eine Entwicklungsmethode, die die Umwandlung von Ideen in detaillierte Design-Dokumente mit Implementierungsplänen und Todo-Listen unterstützt","pt":"O pdd é uma metodologia de desenvolvimento que transforma ideias em documentos de design detalhados com planos de implementação","ru":"pdd - это методология разработки, которая превращает идеи в подробные документы дизайна с планами реализации для ИИ Агентов","ar":"pdd هو منهجية تطوير تحول الأفكار إلى وثائق تصميم مفصلة مع خطط تنفيذ للآلات الذكية"},"seo":{"title":{"en":"pdd: Setup Guide for AI Agents | Purpose-Driven Development","zh":"PDD Setup Guide: 基于 Prompt-Driven Development 的实现","ja":"PDD 導入ガイド: AIエージェントによるプロンプト駆動開発","ko":"PDD 설정 가이드: 프롬프트 드리븐 개발을 위한 구현 방법","es":"Guía de Configuración de pdd para Desarrolladores","fr":"Configurer pdd pour les Développeurs : Meilleures Pratiques","de":"pdd-Setup-Leitfaden für Entwickler: Prompt-Driven Develop...","pt":"Guia de Configuração do pdd: Desenvolvimento Dirigido por...","ru":"Настройка pdd: Методология Prompt-Driven Development для ...","ar":"دليل إعداد pdd: تطوير مدفوع بالتوجيه للآلات الذكية"},"description":{"en":"Unlock systematic refinement of ideas with pdd. Discover how to transform rough concepts into detailed design documents and implementation plans. Get started...","zh":"了解 PDD 的技术细节和最佳实践，利用 Prompt-Driven Development 方法ology 进行项目开发","ja":"PDD のテクニカルな詳細とベストプラクティスを学び、AIエージェントによるプロンプト駆動開発を実現","ko":"PDD의 기술적인 세부사항과 최적의 사례를 익히고, 프롬프트 드리븐 개발 방법론을 기반으로 프로젝트 개발을 진행","es":"Aprende a implementar pdd con nuestra guía paso a paso para desarrolladores y mejora tus habilidades en Prompt-Driven Development con herramientas de AI como...","fr":"Découvrez comment configurer pdd pour améliorer vos compétences en développement logiciel avec les outils d''IA tels que les Outils d''Intelligence Artificielle","de":"Erfahren Sie, wie Sie pdd mit unserem Schritt-für-Schritt-Leitfaden für Entwickler implementieren und Ihre Fähigkeiten im Prompt-Driven Development mit KI-To...","pt":"Aprenda a transformar ideias em documentos de design detalhados com o pdd, uma metodologia de desenvolvimento iterativa","ru":"Изучите, как превратить идеи в подробные документы дизайна с помощью pdd, итеративной методологии разработки для ИИ Агентов","ar":"تعرف على كيفية تحويل الأفكار إلى وثائق تصميم مفصلة باستخدام pdd، منهجية تطوير مدفوعة بالتوجيه للآلات الذكية"},"definition":{"en":"pdd is a Purpose-Driven Development methodology that guides the transformation of rough ideas into detailed design documents with implementation plans and todo lists.","zh":"PDD 是一种项目开发方法，利用 Prompt-Driven Development 方法ology 进行系统的开发和实施","ja":"PDD は、プロジェクト開発方法で、プロンプト駆動開発に基づいて開発と実装を行う","ko":"PDD는 프로젝트 개발 방법으로, 프롬프트 드리븐 개발 방법론을 기반으로 개발과 구현을 진행","es":"pdd es una metodología de desarrollo asistida por prompts que permite a los desarrolladores refinar sus ideas y crear planes de implementación detallados","fr":"pdd est une méthodologie de développement pilotée par des invites qui permet aux développeurs d''affiner leurs idées et de créer des plans de mise en œuvre détaillés","de":"pdd ist eine promptgesteuerte Entwicklungsmethode, die es Entwicklern ermöglicht, ihre Ideen zu verfeinern und detaillierte Implementierungspläne zu erstellen","pt":"O pdd é uma abordagem de desenvolvimento que usa prompts para refinar ideias e criar documentos de design","ru":"pdd - это подход к разработке, который использует промпты для уточнения идей и создания документов дизайна","ar":"pdd هو نهج تطوير يستخدم التوجيه لتحسين الأفكار وإنشاء وثائق تصميم"},"features":{"en":["Follows the Prompt-Driven Development methodology","Systematically refines ideas through iterative requirements clarification and research","Creates comprehensive design documents with implementation plans","Generates todo lists for actionable next steps","Supports movement between requirements clarification and research as needed"],"zh":["基于 Prompt-Driven Development 方法ology 的开发","迭代的开发过程，实现从粗略的想法到详细的设计文档和实施计划的转变","系统的研究和设计","详细的设计文档和实施计划的创建","支持反复的开发和测试"],"ja":["プロンプト駆動開発に基づく開発","反復的な開発プロセスで、アイデアから詳細な設計書と実装計画までを実現","システムの研究と設計","詳細な設計書と実装計画の作成","反復的な開発とテストのサポート"],"ko":["프롬프트 드리븐 개발을 기반으로 하는 개발","반복적인 개발 과정을 통해 초기 아이디어에서 상세한 설계 문서와 구현 계획까지를 실현","시스템의 연구와 설계","상세한 설계 문서와 구현 계획의 생성","반복적인 개발과 테스트의 지원"],"es":["Transformación de ideas en documentos de diseño detallados","Creación de planes de implementación y listas de tareas","Refinamiento de ideas a través de la investigación y la clarificación de requisitos","Desarrollo de documentos de diseño con implementación planificada","Uso de la metodología Prompt-Driven Development","Integración con herramientas de AI como Agentes de Inteligencia Artificial"],"fr":["Transformation d''idées en documents de conception détaillés","Création de plans de mise en œuvre et de listes de tâches","Affinement d''idées à travers la recherche et la clarification des exigences","Développement de documents de conception avec mise en œuvre planifiée","Utilisation de la méthodologie de développement pilotée par des invites","Intégration avec des outils d''IA tels que les Outils d''Intelligence Artificielle"],"de":["Umwandlung von Ideen in detaillierte Design-Dokumente","Erstellung von Implementierungsplänen und Todo-Listen","Verfeinerung von Ideen durch Recherche und Anforderungsklärung","Entwicklung von Design-Dokumenten mit geplanter Implementierung","Verwendung der promptgesteuerten Entwicklungsmethode","Integration mit KI-Tools wie KI-Agenten"],"pt":["Desenvolvimento iterativo de ideias","Criação de documentos de design detalhados","Plano de implementação com lista de tarefas","Refinamento de requisitos com pesquisa","Uso de prompts para guiar o desenvolvimento"],"ru":["Итеративное развитие идей","Создание подробных документов дизайна","План реализации с списком задач","Уточнение требований с помощью исследования","Использование промптов для руководства разработкой"],"ar":["تطوير متكرر للأفكار","إنشاء وثائق تصميم مفصلة","خطة تنفيذ مع قائمة مهام","تحسين المتطلبات بالبحث","استخدام التوجيه لتوجيه التطوير"]},"keywords":{"en":["how to use pdd","what is pdd","pdd vs agile development","pdd setup guide","pdd implementation plan","prompt-driven development methodology"],"zh":["PDD","Prompt-Driven Development","项目开发","开发方法","系统开发","设计文档","实施计划","迭代开发","系统研究"],"ja":["PDD","プロンプト駆動開発","プロジェクト開発","開発方法","システム開発","設計書","実装計画","反復開発","システム研究"],"ko":["PDD","프롬프트 드리븐 개발","프로젝트 개발","개발 방법","시스템 개발","설계 문서","구현 계획","반복 개발","시스템 연구"],"es":["pdd","desarrollo asistido por prompts","Agentes de Inteligencia Artificial","herramientas de AI para desarrolladores","metodologías de desarrollo de software","transformación de ideas en documentos de diseño","planes de implementación y listas de tareas","investigación y clarificación de requisitos"],"fr":["pdd","développement piloté par des invites","Outils d''Intelligence Artificielle","outils d''IA pour les développeurs","méthodologies de développement de logiciels","transformation d''idées en documents de conception","plans de mise en œuvre et listes de tâches","recherche et clarification des exigences"],"de":["pdd","promptgesteuerte Entwicklung","KI-Agenten","KI-Tools für Entwickler","Entwicklungsmethoden für Software","Umwandlung von Ideen in Design-Dokumente","Implementierungspläne und Todo-Listen","Recherche und Anforderungsklärung"],"pt":["pdd","desenvolvimento dirigido por prompt","metodologia de desenvolvimento","documentos de design","plano de implementação","desenvolvimento iterativo","prompts","requisitos","pesquisa"],"ru":["pdd","методология prompt-driven development","ИИ Агенты","документы дизайна","план реализации","итеративное развитие","промпты","требования","исследование"],"ar":["pdd","منهجية تطوير مدفوع بالتوجيه","آلات ذكية","وثائق تصميم","خطة تنفيذ","تطوير متكرر","التوجيه","متطلبات","بحث"]}},"owner":"brazil-bench","repo":"pourpoise","repoPath":"brazil-bench/pourpoise","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.644Z","topics":[],"category":"community","skillMd":{"name":"pdd","description":"This sop guides you through the process of transforming a rough idea into a detailed design document with an implementation plan and todo list. It follows the Prompt-Driven Development methodology to systematically refine your idea, conduct necessary research, create a comprehensive design, and develop an actionable implementation plan. The process is designed to be iterative, allowing movement between requirements clarification and research as needed.","version":"1.0","bodyPreview":"# Prompt-Driven Development\n\n## Overview\n\nThis sop guides you through the process of transforming a rough idea into a detailed design document with an implementation plan and todo list. It follows the Prompt-Driven Development methodology to systematically refine your idea, conduct necessary research, create a comprehensive design, and develop an actionable implementation plan. The process is designed to be iterative, allowing movement between requirements clarification and research as needed.","body":"# Prompt-Driven Development\n\n## Overview\n\nThis sop guides you through the process of transforming a rough idea into a detailed design document with an implementation plan and todo list. It follows the Prompt-Driven Development methodology to systematically refine your idea, conduct necessary research, create a comprehensive design, and develop an actionable implementation plan. The process is designed to be iterative, allowing movement between requirements clarification and research as needed.\n\n## Parameters\n\n- **rough_idea** (required): The initial concept or idea you want to develop into a detailed design\n- **project_dir** (optional, default: \".sop/planning\"): The base directory where all project files will be stored\n\n**Constraints for parameter acquisition:**\n- You MUST ask for all required parameters upfront in a single prompt rather than one at a time\n- You MUST support multiple input methods including:\n  - Direct input: Text provided directly in the conversation\n  - File path: Path to a local file containing the rough idea\n  - URL: Link to an internal resource (e.g., Quip doc, wiki page)\n  - Other methods: You SHOULD be open to other ways the user might want to provide the idea\n- You MUST use appropriate tools to access content based on the input method\n- You MUST confirm successful acquisition of all parameters before proceeding\n- You SHOULD save the acquired rough idea to a consistent location for use in subsequent steps\n- You MUST NOT overwrite the existing project directory because this could destroy previous work and cause data loss\n- You MUST ask for project_dir if it is not given and default \".sop/planning\" directory already exist and has contents from previous iteration\n\n## Steps\n\n### 1. Create Project Structure\n\nSet up a directory structure to organize all artifacts created during the process.\n\n**Constraints:**\n- You MUST create the specified project directory if it doesn''t already exist\n- You MUST create the following files:\n  - {project_dir}/rough-idea.md (containing the provided rough idea)\n  - {project_dir}/idea-honing.md (for requirements clarification)\n- You MUST create the following subdirectories:\n  - {project_dir}/research/ (directory for research notes)\n  - {project_dir}/design/ (directory for design documents)\n  - {project_dir}/implementation/ (directory for implementation plans)\n- You MUST notify the user when the structure has been created\n- You MUST prompt the user to add all project files to Q''s context using the command: `/context add {project_dir}/**/*.md`\n- You MUST explain that this will ensure all project files remain in context throughout the process\n\n### 2. Initial Process Planning\n\nDetermine the initial approach and sequence for requirements clarification and research.\n\n**Constraints:**\n- You MUST ask the user if they prefer to:\n  - Start with requirements clarification (default)\n  - Start with preliminary research on specific topics\n  - Provide additional context or information before proceeding\n- You MUST adapt the subsequent process based on the user''s preference\n- You MUST explain that the process is iterative and the user can move between requirements clarification and research as needed\n- You MUST wait for explicit user direction before proceeding to any subsequent step\n- You MUST NOT automatically proceed to requirements clarification or research without user confirmation because this could lead the process in a direction the user doesn''t want\n\n### 3. Requirements Clarification\n\nGuide the user through a series of questions to refine the initial idea and develop a thorough specification.\n\n**Constraints:**\n- You MUST create an empty {project_dir}/idea-honing.md file if it doesn''t already exist\n- You MUST ask ONLY ONE question at a time and wait for the user''s response before asking the next question\n- You MUST NOT list multiple questions for the user to answer at once because this overwhelms users and leads to incomplete responses\n- You MUST NOT pre-populate answers to questions without user input because this assumes user preferences without confirmation\n- You MUST NOT write multiple questions and answers to the idea-honing.md file at once because this skips the interactive clarification process\n- You MUST follow this exact process for each question:\n  1. Formulate a single question\n  2. Append the question to {project_dir}/idea-honing.md\n  3. Present the question to the user in the conversation\n  4. Wait for the user''s complete response, which may require brief back-and-forth dialogue across multiple turns.\n  5. Once you have their complete response, append the user''s answer (or final decision) to {project_dir}/idea-honing.md\n  6. Only then proceed to formulating the next question\n- You MAY suggest possible answers when asking a question, but MUST wait for the user''s actual response\n- You MUST format the idea-honing.md document with clear question and answer sections\n- You MUST include the final chosen answer in the answer section\n- You MAY include alternative options that were considered before the final decision\n- You MUST ensure you have the user''s complete response before recording it and moving to the next question\n- You MUST continue asking questions until sufficient detail is gathered\n- You SHOULD ask about edge cases, user experience, technical constraints, and success criteria\n- You SHOULD adapt follow-up questions based on previous answers\n- You MAY suggest options when the user is unsure about a particular aspect\n- You MAY recognize when the requirements clarification process appears to have reached a natural conclusion\n- You MUST explicitly ask the user if they feel the requirements clarification is complete before moving to the next step\n- You MUST offer the option to conduct research if questions arise that would benefit from additional information\n- You MUST be prepared to return to requirements clarification after research if new questions emerge\n- You MUST NOT proceed with any other steps until explicitly directed by the user because this could skip important clarification steps\n\n### 4. Research Relevant Information\n\nConduct research on relevant technologies, libraries, or existing code that could inform the design, while collaborating with the user for guidance.\n\n**Constraints:**\n- You MUST identify areas where research is needed based on the requirements\n- You MUST propose an initial research plan to the user, listing topics to investigate\n- You MUST ask the user for input on the research plan, including:\n  - Additional topics that should be researched\n  - Specific resources (files, websites, internal tools) the user recommends\n  - Areas where the user has existing knowledge to contribute\n- You MUST incorporate user suggestions into the research plan\n- You MUST document research findings in separate markdown files in the {project_dir}/research/ directory\n- You SHOULD organize research by topic (e.g., {project_dir}/research/existing-code.md, {project_dir}/research/technologies.md)\n- You MUST include mermaid diagrams when documenting system architectures, data flows, or component relationships in research\n- You MUST include links to relevant references and sources when research is based on external materials (websites, documentation, articles, etc.)\n- You MAY use tools like search_internal_code, read_internal_website, or fs_read to gather information\n- You MUST ask the user whether other available search tools should also be used.\n- You MUST periodically check with the user during the research process (these check-ins may involve brief dialogue to clarify feedback) to:\n  - Share preliminary findings\n  - Ask for feedback and additional guidance\n  - Confirm if the research direction remains valuable\n- You MUST summarize key findings that will inform the design\n- You SHOULD cite sources and include relevant links in research documents\n- You MUST ask the user if the research is sufficient before proceeding to the next step\n- You MUST offer to return to requirements clarification if research uncovers new questions or considerations\n- You MUST NOT automatically return to requirements clarification after research without explicit user direction because this could disrupt the user''s intended workflow\n- You MUST wait for the user to decide the next step after completing research\n\n### 5. Iteration Checkpoint\n\nDetermine if further requirements clarification or research is needed before proceeding to design.\n\n**Constraints:**\n- You MUST summarize the current state of requirements and research to help the user make an informed decision\n- You MUST explicitly ask the user if they want to:\n  - Proceed to creating the detailed design\n  - Return to requirements clarification based on research findings\n  - Conduct additional research based on requirements\n- You MUST support iterating between requirements clarification and research as many times as needed\n- You MUST ensure that both the requirements and research are sufficiently complete before proceeding to design\n- You MUST NOT proceed to the design step without explicit user confirmation because this could skip important refinement steps\n\n### 6. Create Detailed Design\n\nDevelop a comprehensive design document based on the requirements and research.\n\n**Constraints:**\n- You MUST create a detailed design document at {project_dir}/design/detailed-design.md\n- You MUST write the design as a standalone document that can be understood without reading other project files\n- You MUST include the following sections in the design document:\n  - Overview\n  - Detailed Requirements (consolidated from idea-honing.md)\n  - Architecture Overview\n  - Components and Interfaces\n  - Data Models\n  - Error Handling\n  - Testing Strategy\n  - Appendices (Technology Choices, Research Findings, Alternative Approaches)\n- You MUST consolidate all requirements from the idea-honing.md file into the Detailed Requirements section\n- You MUST include an appendix section that summarizes key research findings, including:\n  - Major technology choices with pros and cons\n  - Existing solutions analysis\n  - Alternative approaches considered\n  - Key constraints and limitations identified during research\n- You SHOULD include diagrams or visual representations when appropriate using mermaid syntax\n- You MUST generate mermaid diagrams for architectural overviews, data flow, and component relationships\n- You MUST ensure the design addresses all requirements identified during the clarification process\n- You SHOULD highlight design decisions and their rationales, referencing research findings where applicable\n- You MUST review the design with the user and iterate based on feedback\n- You MUST offer to return to requirements clarification or research if gaps are identified during design\n\n### 7. Develop Implementation Plan\n\nCreate a structured implementation plan with a series of steps for implementing the design.\n\n**Constraints:**\n- You MUST create an implementation plan at {project_dir}/implementation/plan.md\n- You MUST include a checklist at the beginning of the plan.md file to track implementation progress\n- You MUST use the following specific instructions when creating the implementation plan:\n  ```\n  Convert the design into a series of implementation steps that will build each component in a test-driven manner following agile best practices. Each step must result in a working, demoable increment of functionality. Prioritize best practices, incremental progress, and early testing, ensuring no big jumps in complexity at any stage. Make sure that each step builds on the previous steps, and ends with wiring things together. There should be no hanging or orphaned code that isn''t integrated into a previous step.\n  ```\n- You MUST format the implementation plan as a numbered series of detailed steps\n- Each step in the plan MUST be written as a clear implementation objective\n- Each step MUST begin with \"Step N:\" where N is the sequential number\n- You MUST ensure each step includes:\n  - A clear objective\n  - General implementation guidance\n  - Test requirements where appropriate\n  - How it integrates with previous work\n  - **Demo** - explicit description of the working functionality that can be demonstrated after completing this step\n- You MUST ensure each step results in working, demoable functionality that provides value\n- You MUST sequence steps so that core end-to-end functionality is available as early as possible\n- You MUST NOT include excessive implementation details that are already covered in the design document because this creates redundancy and potential inconsistencies\n- You MUST assume that all context documents (requirements, design, research) will be available during implementation\n- You MUST break down the implementation into a series of discrete, manageable steps\n- You MUST ensure each step builds incrementally on previous steps\n- You SHOULD prioritize test-driven development where appropriate\n- You MUST ensure the plan covers all aspects of the design\n- You SHOULD sequence steps to validate core functionality early\n- You MUST ensure the checklist items correspond directly to the steps in the implementation plan\n\n### 8. Summarize and Present Results\n\nProvide a summary of all artifacts created and next steps.\n\n**Constraints:**\n- You MUST create a summary document at {project_dir}/summary.md\n- You MUST list all artifacts created during the process\n- You MUST provide a brief overview of the design and implementation plan\n- You MUST suggest next steps for the user\n- You SHOULD highlight any areas that may need further refinement\n- You MUST present this summary to the user in the conversation\n\n## Examples\n\n### Example Input\n\n```\nRough idea: I want to build a feature for our team''s internal tool that allows users to create and manage templates for common documents we produce. Users should be able to create, edit, and share templates, as well as use them to generate new documents with custom fields.\n\nProject directory: docs/template-feature\n```\n\n### Example Output\n\n```\n# Research Phase Interaction\n\nBased on your requirements, I''ve identified several areas that would benefit from research:\n\n1. **Existing template solutions** - Understanding what''s already available\n2. **Storage and versioning approaches** - How to handle template versions and sharing\n3. **Custom field validation patterns** - Best practices for dynamic field validation\n\nI notice you have several additional MCP search tools available beyond the standard ones, including ''peccy web search'' and other external search capabilities. Should I incorporate these additional search tools into the research process for broader coverage of template management solutions and industry best practices?\n\n---\n\n# Project Summary\n\nI''ve completed the transformation of your rough idea into a detailed design with an implementation plan. Here''s what was created:\n\n## Directory Structure\n- docs/template-feature/\n  - rough-idea.md (your initial concept)\n  - idea-honing.md (our Q&A requirements clarification)\n  - research/\n    - existing-templates.md\n    - storage-options.md\n    - external-solutions.md\n  - design/\n    - detailed-design.md\n  - implementation/\n    - plan.md (includes implementation checklist)\n  - summary.md (this document)\n\n## Key Design Elements\n- Template management system with CRUD operations\n- Role-based access control for sharing\n- Versioning system for templates\n- Custom fields with validation\n- Document generation engine\n\n## Implementation Approach\nThe implementation plan breaks down the work into 12 incremental steps, starting with core data models and building up to the complete feature set.\n\n## Next Steps\n1. Review the detailed design document at docs/template-feature/design/detailed-design.md\n2. Check the implementation plan and checklist at docs/template-feature/implementation/plan.md\n3. Begin implementation following the checklist in the implementation plan\n\nWould you like me to explain any specific part of the design or implementation plan in more detail?\n```\n\n## Troubleshooting\n\n### Requirements Clarification Stalls\nIf the requirements clarification process seems to be going in circles or not making progress:\n- You SHOULD suggest moving to a different aspect of the requirements\n- You MAY provide examples or options to help the user make decisions\n- You SHOULD summarize what has been established so far and identify specific gaps\n- You MAY suggest conducting research to inform requirements decisions\n\n### Research Limitations\nIf you cannot access needed information:\n- You SHOULD document what information is missing\n- You SHOULD suggest alternative approaches based on available information\n- You MAY ask the user to provide additional context or documentation\n- You SHOULD continue with available information rather than blocking progress\n\n### Design Complexity\nIf the design becomes too complex or unwieldy:\n- You SHOULD suggest breaking it down into smaller, more manageable components\n- You SHOULD focus on core functionality first\n- You MAY suggest a phased approach to implementation\n- You SHOULD return to requirements clarification to prioritize features if needed\n"},"lastSynced":"2026-03-08T02:13:44.788Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code needing structured approach to refine ideas into detailed design documents with implementation plans.","zh":"适合像Cursor、Windsurf和Claude Code这样的AI代理，需要结构化方法来将想法细化为详细的设计文档和实现计划。","ja":"Cursor、Windsurf、Claude CodeなどのAIエージェントに適しており、アイデアを詳細な設計文書と実装計画に洗練するための構造化されたアプローチが必要です。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에게 적합하며, 아이디어를 상세한 설계 문서와 구현 계획으로 정제하기 위한 구조화된 접근법이 필요합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que necesitan un enfoque estructurado para refinar ideas en documentos de diseño detallados con planes de implementación.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code ayant besoin d''une approche structurée pour affiner les idées en documents de conception détaillés avec des plans de mise en œuvre.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die einen strukturierten Ansatz benötigen, um Ideen in detaillierte Design-Dokumente mit Implementierungsplänen zu verfeinern.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que necessitam de uma abordagem estruturada para refinar ideias em documentos de design detalhados com planos de implementação.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, которым необходим структурированный подход для уточнения идей в подробные документы дизайна с планами реализации.","ar":"مثالي لوكلاء الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يحتاجون إلى نهج منظم لتعريف الأفكار في وثائق تصميم مفصلة مع خطط التنفيذ."},"recommendation":{"en":"Empowers agents to systematically refine rough concepts into actionable plans using Prompt-Driven Development methodology, conducting necessary research, creating comprehensive designs, and developing implementation plans with todo lists in iterative processes.","zh":"赋予代理以系统地将粗略概念转化为可执行计划的能力，使用基于提示的开发方法ology，开展必要的研究，创建综合设计，并在迭代过程中制定包含待办事项列表的实现计划。","ja":"プロンプト駆動開発の方法論を使用して、粗略な概念を実行可能な計画に体系的に洗練する能力をエージェントに与え、必要なリサーチを実施し、包括的な設計を作成し、反復的なプロセスでTODOリストを含む実装計画を策定します。","ko":"프롬프트 기반 개발 방법론을 사용하여 粗略한 개념을 실행 가능한 계획으로 체계적으로 정제할 수 있는 능력을 에이전트에게 부여하며, 필요한 연구를 수행하고, 포괄적인 설계를 만들고, 반복적인 프로세스에서 TODO 목록을 포함한 구현 계획을 수립합니다.","es":"Permite a los agentes refinar sistemáticamente conceptos rudimentarios en planes de acción utilizando la metodología de desarrollo basada en prompts, realizando las investigaciones necesarias, creando diseños comprehensivos y desarrollando planes de implementación con listas de tareas en procesos iterativos.","fr":"Permet aux agents de raffiner systématiquement les concepts rudimentaires en plans d''action en utilisant la méthodologie de développement basée sur les prompts, en effectuant les recherches nécessaires, en créant des conceptions complètes et en développant des plans de mise en œuvre avec des listes de tâches dans des processus itératifs.","de":"Ermöglicht es Agents, grobe Konzepte systematisch in aktionsfähige Pläne zu verfeinern, indem sie die Prompt-Driven-Development-Methode verwenden, notwendige Recherchen durchführen, umfassende Entwürfe erstellen und Implementierungspläne mit Todo-Listen in iterativen Prozessen entwickeln.","pt":"Habilita os agentes a refinar sistematicamente conceitos grosseiros em planos de ação usando a metodologia de Desenvolvimento Dirigido por Prompt, realizando as pesquisas necessárias, criando projetos abrangentes e desenvolvendo planos de implementação com listas de tarefas em processos iterativos.","ru":"Наделяет агентов возможностью систематически уточнять грубые концепции в действенные планы, используя методику Prompt-Driven Development, проводя необходимые исследования, создавая комплексные проекты и разрабатывая планы реализации с список дел в итерационных процессах.","ar":"تمكن الوكلاء من تعريف المفاهيم الخشنة بشكل منهجي إلى خطط عمل باستخدام منهجية Prompt-Driven Development ، وإجراء البحوث الضرورية ، وإنشاء تصاميم شاملة ، وتطوير خطط التنفيذ مع قوائم المهام في العمليات التكرارية."},"useCases":{"en":["Transforming rough ideas into detailed design documents","Conducting research for requirements clarification","Generating actionable implementation plans with todo lists"],"zh":["将粗略的想法转化为详细的设计文档","进行研究以澄清需求","生成包含待办事项列表的可执行实现计划"],"ja":["粗略なアイデアを詳細な設計文書に変換する","要件の明確化のためのリサーチを実施する","TODOリストを含む実行可能な実装計画を生成する"],"ko":[" 粗略한 아이디어를 상세한 설계 문서로 변환하는 것","요구사항 명확화를 위한 연구 수행","TODO 목록을 포함한 실행 가능한 구현 계획 생성"],"es":["Transformar ideas rudimentarias en documentos de diseño detallados","Realizar investigaciones para la clarificación de requisitos","Generar planes de implementación con listas de tareas"],"fr":["Transformer les idées rudimentaires en documents de conception détaillés","Effectuer des recherches pour la clarification des exigences","Générer des plans de mise en œuvre avec des listes de tâches"],"de":["Rohideen in detaillierte Design-Dokumente umwandeln","Recherchen zur Anforderungsklärung durchführen","Umsetzungspläne mit Todo-Listen generieren"],"pt":["Transformar ideias grosseiras em documentos de design detalhados","Realizar pesquisas para esclarecimento dos requisitos","Gerar planos de implementação com listas de tarefas"],"ru":["Преобразование грубых идей в подробные документы дизайна","Проведение исследований для уточнения требований","Создание планов реализации с списками дел"],"ar":["تحويل الأفكار الخشنة إلى وثائق تصميم مفصلة","إجراء البحوث لتوضيح المتطلبات","توليد خطط التنفيذ مع قوائم المهام"]},"limitations":{"en":["Requires iterative process allowing movement between requirements clarification and research"],"zh":["需要反复过程以允许在需求澄清和研究之间移动"],"ja":["要件の明確化とリサーチの間を移動することを可能にする反復的なプロセスが必要"],"ko":["요구사항 명확화와 연구 사이를 이동할 수 있는 반복적인 프로세스가 필요"],"es":["Requiere un proceso iterativo que permita el movimiento entre la clarificación de requisitos y la investigación"],"fr":["Nécessite un processus itératif permettant le mouvement entre la clarification des exigences et la recherche"],"de":["Erfordert einen iterativen Prozess, der das Hin- und Herwechseln zwischen der Anforderungsklärung und der Recherche ermöglicht"],"pt":["Exige um processo iterativo que permita o movimento entre esclarecimento dos requisitos e pesquisa"],"ru":["Требует итерационного процесса, позволяющего перемещаться между уточнением требований и исследованием"],"ar":["يتطلب عملية تكرارية تسمح بالتحرك بين توضيح المتطلبات والبحث"]},"version":4},"contentHash":"1e5b1d978a1e8328d9b8f30803a4875b15985d2a3f920af9bc063707eb5c3812","qualityScore":65}');
