INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brazil-bench/pourpoise/pdd', 'pdd', 'brazil-bench', 'pourpoise', 'community', 'pdd brazil-bench pourpoise community pdd is a methodology for systematically refining ideas into detailed design documents with implementation plans. It benefits developers and organizations by providing a structured approach to transforming rough concepts into actionable plans. PDD 是一种基于 Prompt-Driven Development 的项目开发方法，通过迭代的过程，实现从粗略的想法到详细的设计文档和实施计划的转变 PDD は、プロンプト駆動開発に基づくプロジェクト開発方法で、反復的なプロセスを通じて、アイデアから詳細な設計書と実装計画までを実現 PDD는 프롬프트 드리븐 개발을 기반으로 하는 프로젝트 개발 방법으로, 반복적인 과정을 통해 초기 아이디어에서 상세한 설계 문서와 구현 계획까지를 실현 pdd es una metodología de desarrollo que guía la transformación de ideas en documentos de diseño detallados con planes de implementación y listas de tareas pdd est une méthodologie de développement qui guide la transformation d''idées en documents de conception détaillés avec des plans de mise en œuvre et des listes de tâches pdd ist eine Entwicklungsmethode, die die Umwandlung von Ideen in detaillierte Design-Dokumente mit Implementierungsplänen und Todo-Listen unterstützt O pdd é uma metodologia de desenvolvimento que transforma ideias em documentos de design detalhados com planos de implementação pdd - это методология разработки, которая превращает идеи в подробные документы дизайна с планами реализации для ИИ Агентов pdd هو منهجية تطوير تحول الأفكار إلى وثائق تصميم مفصلة مع خطط تنفيذ للآلات الذكية how to use pdd what is pdd pdd vs agile development pdd setup guide pdd implementation plan prompt-driven development methodology PDD Prompt-Driven Development 项目开发 开发方法 系统开发 设计文档 实施计划 迭代开发 系统研究 Follows the Prompt-Driven Development methodology Systematically refines ideas through iterative requirements clarification and research Creates comprehensive design documents with implementation plans Generates todo lists for actionable next steps Supports movement between requirements clarification and research as needed pdd is a Purpose-Driven Development methodology that guides the transformation of rough ideas into detailed design documents with implementation plans and todo lists.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alphaonedev/openclaw-graph/nano-pdf', 'community', 'alphaonedev', 'openclaw-graph', 'alphaonedev/openclaw-graph', 'nano-pdf', 0, 0, 65, '2026-03-08T01:57:15.660Z', '2026-03-08T02:14:03.564Z', 'dce762c7476293d734ce1079780cbfca0a4883f04967c127057d53d08b5f18a7', '{"id":"alphaonedev/openclaw-graph/nano-pdf","name":"nano-pdf","description":{"en":"The nano-pdf skill provides tools for PDF processing, including text extraction and OCR integration, to handle document workflows efficiently for developers and data analysts.","zh":"nano-pdf提供PDF处理工具，包括文本提取、挖掘、表格填充、操作和OCR集成","ja":"nano-pdfはPDF処理ツールを提供し、テキスト抽出、データマイニング、フォーム埋め込み、操作、OCR統合などが可能","ko":"nano-pdf는 PDF 처리 도구를 제공하여 텍스트 추출, 데이터 마이닝, 폼 채우기, 조작 및 OCR 통합 등을 가능하게 함","es":"nano-pdf es una habilidad para procesar PDF, incluyendo extracción de texto, minería, llenado de formularios y OCR","fr":"nano-pdf est une compétence pour traiter les PDF, y compris l''extraction de texte, le mining, le remplissage de formulaires et l''OCR","de":"nano-pdf ist eine Fähigkeit zur PDF-Verarbeitung, einschließlich Textextraktion, Mining, Formularen und OCR","pt":"O nano-pdf é uma ferramenta de processamento de PDF que fornece recursos para extração de texto, mineração de dados e manipulação de PDFs","ru":"nano-pdf - это инструмент для обработки PDF, который предоставляет функции для извлечения текста, добычи данных и манипуляции PDF","ar":"nano-pdf هو أداة لمعالجة المستندات PDF التي توفر أدوات لاستخراج النصوص وتنقيب البيانات وتعديل المستندات PDF"},"seo":{"title":{"en":"nano-pdf: PDF Processing Setup Guide | AI Agent Skill","zh":"nano-pdf_SETUP GUIDE：PDF处理和OCR集成","ja":"nano-pdfのベストプラクティス：PDF処理とOCR統合","ko":"nano-pdf설치 가이드: PDF 처리 및 OCR 통합","es":"Guía de configuración de nano-pdf para procesamiento de PDF","fr":"Guide de mise en place de nano-pdf pour le traitement de PDF","de":"Einrichtungsleitfaden für nano-pdf zur PDF-Verarbeitung","pt":"Guia de Configuração do nano-pdf para Processamento de PDF","ru":"Настройка nano-pdf для обработки PDF: ИИ Агенты","ar":"دليل إعداد nano-pdf لمعالجة المستندات PDF"},"description":{"en":"Unlock efficient document workflows with nano-pdf. Discover how to extract text, fill forms, and apply OCR to PDFs. Get started with our expert guide now!","zh":"使用nano-pdf进行PDF数据提取、文本分析和OCR集成，实现高效的文档工作流","ja":"nano-pdfを使用してPDFデータ抽出、テキスト分析、OCR統合を行い、効率的な文書ワークフローを実現","ko":"nano-pdf를 사용하여 PDF 데이터 추출, 텍스트 분석 및 OCR 통합을 통해 효율적인 문서 작업 흐름을 실현","es":"Descubre cómo nano-pdf simplifica el procesamiento de PDF con extracción de texto, minería, llenado de formularios y OCR","fr":"Découvrez comment nano-pdf simplifie le traitement de PDF avec extraction de texte, mining, remplissage de formulaires et OCR","de":"Erfahren Sie, wie nano-pdf die PDF-Verarbeitung mit Textextraktion, Mining, Formularen und OCR vereinfacht","pt":"Aprenda a utilizar o nano-pdf para extrair texto, minerar dados e manipular PDFs de forma eficiente","ru":"Используйте nano-pdf для извлечения текста, добычи данных и манипуляции PDF с помощью ИИ Агентов","ar":"استخدم nano-pdf لاستخراج النصوص وتنقيب البيانات وتعديل المستندات PDF بفعالية"},"definition":{"en":"nano-pdf is a graph-native workspace backend for OpenClaw, providing embedded Cypher via LadybugDB for zero-flat-file and zero-daemon PDF processing.","zh":"nano-pdf是一种图形本地工作区后端，提供PDF处理和OCR集成能力","ja":"nano-pdfはグラフネイティブワークスペースバックエンドであり、PDF処理とOCR統合能力を提供する","ko":"nano-pdf는 그래프 네이티브 워크스페이스 백엔드로서 PDF 처리 및 OCR 통합 기능을 제공","es":"nano-pdf es una herramienta de procesamiento de PDF que utiliza tecnologías como LadybugDB y Cypher","fr":"nano-pdf est un outil de traitement de PDF qui utilise des technologies comme LadybugDB et Cypher","de":"nano-pdf ist ein Tool zur PDF-Verarbeitung, das Technologien wie LadybugDB und Cypher verwendet","pt":"O que é nano-pdf? É uma ferramenta de processamento de PDF que utiliza tecnologias como LadybugDB e Cypher","ru":"Что такое nano-pdf? Это инструмент для обработки PDF, который использует технологии как LadybugDB и Cypher","ar":"ما هو nano-pdf? هو أداة لمعالجة المستندات PDF التي تستخدم تقنيات مثل LadybugDB و Cypher"},"features":{"en":["Text extraction from PDFs, including scanned documents","Form filling and manipulation of PDF files","OCR integration for non-text PDFs","Merging and splitting of PDF files","Embedded Cypher via LadybugDB for efficient querying"],"zh":["PDF文本提取","PDF数据挖掘","表格填充和操作","OCR集成","零平面文件","零守护进程"],"ja":["PDFテキスト抽出","PDFデータマイニング","フォーム埋め込みと操作","OCR統合","ゼロフラットファイル","ゼロデーモン"],"ko":["PDF 텍스트 추출","PDF 데이터 마이닝","폼 채우기 및 조작","OCR 통합","제로 플랫 파일","제로 데몬"],"es":["Extracción de texto de PDF","Minería de datos en PDF","Llenado de formularios en PDF","Integración de OCR para PDF no textuales","Manipulación de archivos PDF","Uso de LadybugDB y Cypher para la gestión de datos"],"fr":["Extraction de texte de PDF","Mining de données dans les PDF","Remplissage de formulaires dans les PDF","Intégration de l''OCR pour les PDF non textuels","Manipulation de fichiers PDF","Utilisation de LadybugDB et Cypher pour la gestion de données"],"de":["Textextraktion aus PDF","Daten-Mining in PDF","Formulare in PDF ausfüllen","OCR-Integration für nicht-textuelle PDF","Manipulation von PDF-Dateien","Verwendung von LadybugDB und Cypher für die Datenverwaltung"],"pt":["Extração de texto de PDFs","Mineração de dados em relatórios","Preenchimento de formulários automatizado","Manipulação de PDFs com OCR","Integração com LadybugDB e Cypher"],"ru":["Извлечение текста из PDF","Добыча данных в отчетах","Автоматическое заполнение форм","Манипуляция PDF с помощью OCR","Интеграция с LadybugDB и Cypher"],"ar":["استخراج النصوص من المستندات PDF","تنقيب البيانات في التقارير","ملء الاستمارات تلقائيًا","تعديل المستندات PDF باستخدام OCR","التكامل مع LadybugDB و Cypher"]},"keywords":{"en":["how to use nano-pdf","nano-pdf setup guide","nano-pdf alternative","nano-pdf vs OpenClaw","pdf processing with nano-pdf","nano-pdf install","what is nano-pdf","nano-pdf tutorial","nano-pdf and LadybugDB"],"zh":["nano-pdf","PDF处理","OCR集成","AIエージェント","文档工作流","PDF数据提取","文本分析"],"ja":["nano-pdf","PDF処理","OCR統合","AIエージェント","文書ワークフロー","PDFデータ抽出","テキスト分析"],"ko":["nano-pdf","PDF 처리","OCR 통합","AI 에이전트","문서 작업 흐름","PDF 데이터 추출","텍스트 분석"],"es":["procesamiento de PDF","nano-pdf","herramientas de AI para PDF","extracción de texto de PDF","llenado de formularios en PDF","OCR para PDF","LadybugDB","Cypher","desarrollo de software para PDF"],"fr":["traitement de PDF","nano-pdf","outils d''IA pour PDF","extraction de texte de PDF","remplissage de formulaires dans les PDF","OCR pour PDF","LadybugDB","Cypher","développement de logiciels pour PDF"],"de":["PDF-Verarbeitung","nano-pdf","AI-Tools für PDF","Textextraktion aus PDF","Formulare in PDF ausfüllen","OCR für PDF","LadybugDB","Cypher","Software-Entwicklung für PDF"],"pt":["processamento de PDF","extração de texto","mineração de dados","manipulação de PDF","OCR","LadybugDB","Cypher","ferramentas de PDF","tecnologias de PDF"],"ru":["обработка PDF","извлечение текста","добыча данных","манипуляция PDF","OCR","LadybugDB","Cypher","инструменты для PDF","технологии для PDF","ИИ Агенты"],"ar":["معالجة المستندات PDF","استخراج النصوص","تنقيب البيانات","تعديل المستندات PDF","OCR","LadybugDB","Cypher","أدوات لمعالجة المستندات PDF","تقنيات لمعالجة المستندات PDF","أدوات ذكاء اصطناعي"]}},"owner":"alphaonedev","repo":"openclaw-graph","repoPath":"alphaonedev/openclaw-graph","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.660Z","topics":[],"category":"community","skillMd":{"name":"nano-pdf","description":"PDF processing: extraction, text mining, form filling, manipulation, OCR integration","tags":["pdf","document","extraction","ocr"],"bodyPreview":"# nano-pdf\n\n## Purpose\nThis skill provides tools for PDF processing, including text extraction, mining, form filling, manipulation, and OCR integration, to handle document workflows efficiently.\n\n## When to Use\nUse this skill for tasks involving PDF data extraction (e.g., from scanned documents), text analysis in reports, automating form submissions, merging/splitting files, or applying OCR to non-text PDFs. Apply it in data pipelines, document automation scripts, or when integrating with OCR se","body":"# nano-pdf\n\n## Purpose\nThis skill provides tools for PDF processing, including text extraction, mining, form filling, manipulation, and OCR integration, to handle document workflows efficiently.\n\n## When to Use\nUse this skill for tasks involving PDF data extraction (e.g., from scanned documents), text analysis in reports, automating form submissions, merging/splitting files, or applying OCR to non-text PDFs. Apply it in data pipelines, document automation scripts, or when integrating with OCR services for unstructured data.\n\n## Key Capabilities\n- Text extraction: Pulls plain text or structured data from PDFs, supporting encrypted files with passwords; uses OCR via Tesseract integration for image-based PDFs.\n- Text mining: Analyzes extracted text for keywords, sentiment, or patterns; e.g., counts occurrences of phrases in a document.\n- Form filling: Populates interactive PDF forms with JSON data; supports flattening forms to static PDFs.\n- Manipulation: Merges, splits, rotates, or watermarks PDFs; handles up to 500-page documents efficiently.\n- OCR integration: Converts scanned PDFs to searchable text using external APIs; requires Tesseract or similar engine configuration.\n\n## Usage Patterns\nInvoke via CLI for quick scripts or API for server-side integration. For batch processing, chain commands in a shell script; for web apps, use API calls in loops. Always specify input/output paths explicitly. Pattern: Extract text first, then mine or manipulate as needed. For OCR-heavy tasks, preprocess images before PDF operations.\n\n## Common Commands/API\nCLI commands use `nano-pdf` binary; API endpoints are under `https://api.opencclaw.com/nano-pdf/`. Authentication requires `$NANO_PDF_API_KEY` environment variable.\n\n- Extract text: `nano-pdf extract --file input.pdf --output text.txt --ocr true` (adds OCR if text is not selectable).\n- Mine text: `nano-pdf mine --input text.txt --keywords \"AI,robot\" --output results.json` (outputs keyword frequencies).\n- Fill form: `nano-pdf fill --template form.pdf --data ''{\"field1\": \"value\"}'' --output filled.pdf`.\n- Manipulate PDF: `nano-pdf merge --files file1.pdf file2.pdf --output combined.pdf`.\n- API endpoint for extraction: POST /extract with body `{\"file\": \"base64encoded_content\", \"ocr\": true}` and header `Authorization: Bearer $NANO_PDF_API_KEY`.\n- Code snippet (Python):\n  ```\n  import requests\n  response = requests.post(''https://api.opencclaw.com/nano-pdf/extract'', headers={''Authorization'': f''Bearer {os.environ[\"NANO_PDF_API_KEY\"]}''}, json={''file'': ''base64data''})\n  print(response.json()[''text''])\n  ```\n- Config format: JSON for API bodies, e.g., `{\"file\": \"path\", \"options\": {\"ocr_engine\": \"tesseract\", \"language\": \"en\"}}`; CLI uses flag-based configs like `--config config.json`.\n\n## Integration Notes\nIntegrate by setting `$NANO_PDF_API_KEY` for authenticated requests; for local use, install via `pip install nano-pdf` and import as a module. Combine with other tools: pipe CLI output to NLP libraries for mining, or use in Node.js via HTTP requests. For OCR, ensure Tesseract is installed and configured in your environment path. Test integrations in a sandbox to verify API rate limits (e.g., 100 requests/min).\n\n## Error Handling\nCheck for common errors like file not found (exit code 404), invalid API keys (401), or OCR failures (e.g., no Tesseract installed). Use try-except in code: \n```\ntry:\n    result = nano_pdf.extract(''input.pdf'')\nexcept FileNotFoundError:\n    print(\"Error: File does not exist.\")\nexcept Exception as e:\n    print(f\"API Error: {e} - Check $NANO_PDF_API_KEY.\")\n```\nFor CLI, parse stderr output; retry transient errors (e.g., network issues) with exponential backoff. Always validate inputs, like ensuring PDFs are not corrupted before processing.\n\n## Example 1: Extract and Mine Text from a PDF\nTo extract text from a scanned invoice PDF and mine for product names:\n1. Run: `nano-pdf extract --file invoice.pdf --output invoice_text.txt --ocr true`\n2. Then: `nano-pdf mine --input invoice_text.txt --keywords \"product\" --output analysis.json`\nThis produces a JSON with keyword occurrences for further processing.\n\n## Example 2: Fill and Manipulate a Form PDF\nTo fill a job application form and merge it with a cover letter:\n1. Prepare data in JSON: `{\"name\": \"John Doe\", \"position\": \"Engineer\"}`\n2. Execute: `nano-pdf fill --template application.pdf --data application_data.json --output filled_app.pdf`\n3. Merge: `nano-pdf merge --files filled_app.pdf cover_letter.pdf --output final_packet.pdf`\nOutput is a single PDF ready for submission.\n\n## Graph Relationships\n- Related to: \"ocr-tool\" (for enhanced OCR capabilities), \"document-parser\" (for broader file type support), \"text-analyzer\" (for advanced mining integrations).\n- Clusters: Connected via \"community\" cluster to skills like \"data-extraction\" and \"automation-utils\".\n"},"lastSynced":"2026-03-08T02:14:03.564Z","agentAnalysis":{"suitability":{"en":"Ideal for Document Analysis Agents requiring advanced PDF processing and OCR integration capabilities.","zh":"适合需要高级PDF处理和OCR集成能力的文档分析代理。","ja":"高度なPDF処理とOCR統合機能を必要とするドキュメント分析エージェントに適しています。","ko":"고급 PDF 처리 및 OCR 통합 기능을 필요로 하는 문서 분석 에이전트에 적합합니다.","es":"Ideal para Agentes de Análisis de Documentos que requieren procesamiento de PDF avanzado y capacidades de integración de OCR.","fr":"Idéal pour les agents d''analyse de documents nécessitant un traitement de PDF avancé et des capacités d''intégration d''OCR.","de":"Ideal für Document Analysis Agents, die erweiterte PDF-Verarbeitung und OCR-Integration benötigen.","pt":"Ideal para Agentes de Análise de Documentos que exigem processamento de PDF avançado e capacidades de integração de OCR.","ru":"Идеально подходит для агентов анализа документов, требующих продвинутой обработки PDF и возможностей интеграции OCR.","ar":"مثالي لعميلة تحليل الوثائق التي تتطلب معالجة PDF متقدمة وخصائص دمج OCR."},"recommendation":{"en":"Empowers agents to efficiently handle document workflows by providing tools for text extraction, mining, form filling, manipulation, and OCR integration, supporting tasks such as PDF data extraction from scanned documents and text analysis in reports using OCR protocols.","zh":"通过提供文本提取、挖掘、表单填充、操作和OCR集成工具，赋予代理高效处理文档工作流的能力，支持从扫描文档中提取PDF数据和使用OCR协议在报告中进行文本分析等任务。","ja":"テキスト抽出、採掘、フォーム入力、操作、OCR統合などのツールを提供することで、エージェントが文書ワークフローを効率的に処理できるようにし、スキャナ文書からのPDFデータ抽出やOCRプロトコルを使用したレポート内のテキスト分析などのタスクをサポートします。","ko":"텍스트 추출, 마이닝, 양식填充, 조작 및 OCR 통합과 같은 도구를 제공하여 에이전트가 문서 워크플로를 효율적으로 처리할 수 있도록 하며, 스캔된 문서에서 PDF 데이터 추출 및 OCR 프로토콜을 사용한 보고서 내 텍스트 분석 등의 작업을 지원합니다.","es":"Habilita a los agentes a manejar flujos de trabajo de documentos de manera eficiente al proporcionar herramientas para la extracción de texto, la minería, el llenado de formularios, la manipulación y la integración de OCR, y admite tareas como la extracción de datos de PDF de documentos escaneados y el análisis de texto en informes utilizando protocolos de OCR.","fr":"Permet aux agents de gérer efficacement les flux de travail de documents en fournissant des outils pour l''extraction de texte, la mine, le remplissage de formulaires, la manipulation et l''intégration d''OCR, et prend en charge des tâches telles que l''extraction de données de PDF à partir de documents scannés et l''analyse de texte dans des rapports à l''aide de protocoles OCR.","de":"Ermächtigt die Agenten, Dokumenten-Workflows effizient zu verwalten, indem es Tools für Textextraktion, -mining, Formulareingabe, -manipulation und OCR-Integration bereitstellt und unterstützt Aufgaben wie die Extraktion von PDF-Daten aus gescannten Dokumenten und die Textanalyse in Berichten unter Verwendung von OCR-Protokollen.","pt":"Habilita os agentes a lidar eficientemente com fluxos de trabalho de documentos, fornecendo ferramentas para extração de texto, mineração, preenchimento de formulários, manipulação e integração de OCR, apoiando tarefas como extração de dados de PDF de documentos digitalizados e análise de texto em relatórios usando protocolos de OCR.","ru":"Наделяет агентов возможностью эффективно обрабатывать документооборот, предоставляя инструменты для извлечения текста, майнинга, заполнения форм, манипуляций и интеграции OCR, поддерживая задачи, такие как извлечение данных из отсканированных документов в формате PDF и анализ текста в отчетах с использованием протоколов OCR.","ar":"يمنح العميل القدرة على التعامل بفعالية مع تدفقات عمل الوثائق من خلال توفير أدوات لاستخراج النص والتعدين وملء الاستمارات والتعامل ودمج OCR، ودعم المهام مثل استخراج بيانات PDF من المستندات الممسوحة ضوئيًا وتحليل النص في التقارير باستخدام بروتوكولات OCR."},"useCases":{"en":["Automating form submissions in PDF documents","Extracting text from scanned PDFs using OCR","Merging and splitting PDF files for data analysis","Applying OCR to non-text PDFs for enhanced data mining"],"zh":["在PDF文档中自动提交表单","使用OCR从扫描的PDF中提取文本","合并和拆分PDF文件以进行数据分析","将OCR应用于非文本PDF以增强数据挖掘"],"ja":["PDFドキュメントのフォームを自動送信する","OCRを使用してスキャナPDFからテキストを抽出する","データ分析のためにPDFファイルを結合および分割する","非テキストPDFにOCRを適用してデータマイニングを強化する"],"ko":["PDF 문서에서 양식을 자동 제출하는 것","OCR를 사용하여 스캔된 PDF에서 텍스트를 추출하는 것","데이터 분석을 위해 PDF 파일을 합치고 분할하는 것","비텍스트 PDF에 OCR을 적용하여 데이터 마이닝을 강화하는 것"],"es":["Automatización de la presentación de formularios en documentos PDF","Extracción de texto de PDF escaneados utilizando OCR","Fusión y división de archivos PDF para análisis de datos","Aplicación de OCR a PDF no textuales para una minería de datos mejorada"],"fr":["Automatisation de la soumission de formulaires dans des documents PDF","Extraction de texte à partir de PDF scannés en utilisant l''OCR","Fusion et division de fichiers PDF pour l''analyse de données","Application de l''OCR à des PDF non textuels pour une extraction de données améliorée"],"de":["Automatisierung der Formulareingabe in PDF-Dokumenten","Extraktion von Text aus gescannten PDFs unter Verwendung von OCR","Zusammenführung und Aufteilung von PDF-Dateien für die Datenanalyse","Anwendung von OCR auf nicht-textuelle PDFs für eine verbesserte Daten-Mining"],"pt":["Automatizar envios de formulários em documentos PDF","Extrair texto de PDFs digitalizados usando OCR","Mesclar e dividir arquivos PDF para análise de dados","Aplicar OCR a PDFs não textuais para mineração de dados aprimorada"],"ru":["Автоматизация отправки форм в документах PDF","Извлечение текста из отсканированных PDF с помощью OCR","Объединение и разделение файлов PDF для анализа данных","Применение OCR к нетекстовым PDF для улучшения майнинга данных"],"ar":["توفير автомاتي لتقديم الاستمارات في مستندات PDF","استخراج النص من PDFs الممسوحة ضوئيًا باستخدام OCR","دمج وتقسيم ملفات PDF للتحليل البياني","تطبيق OCR على PDFs غير النصية لتعزيز تعدين البيانات"]},"limitations":{"en":["Requires OCR integration for non-text PDF processing","Limited to PDF file format"],"zh":["需要OCR集成来处理非文本PDF","仅限于PDF文件格式"],"ja":["非テキストPDFの処理にはOCR統合が必要","PDFファイル形式のみに限定される"],"ko":["비텍스트 PDF 처리를 위한 OCR 통합이 필요","PDF 파일 형식만 해당"],"es":["Requiere integración de OCR para el procesamiento de PDF no textuales","Limitado al formato de archivo PDF"],"fr":["Nécessite une intégration d''OCR pour le traitement de PDF non textuels","Limité au format de fichier PDF"],"de":["Erfordert OCR-Integration für die Verarbeitung nicht-textueller PDFs","Begrenzt auf das PDF-Dateiformat"],"pt":["Exige integração de OCR para processamento de PDF não textual","Limitado ao formato de arquivo PDF"],"ru":["Требует интеграции OCR для обработки нетекстовых PDF","Ограничен форматом файла PDF"],"ar":["يتطلب دمج OCR لمعالجة PDF غير النصية","محدود بتنسيق ملف PDF"]},"version":4},"contentHash":"dce762c7476293d734ce1079780cbfca0a4883f04967c127057d53d08b5f18a7","qualityScore":65}');
