INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nakafaai/nakafa.com/convex-component-authoring', 'convex-component-authoring', 'nakafaai', 'nakafa.com', 'community', 'convex-component-authoring nakafaai nakafa.com community Convex Component Authoring 是一个支持 K-12 至大学教育的 AI 本地免费高质量学习平台，提供便捷的组件开发体验 Convex Component Authoring は K-12 から大学教育までをサポートする AI エージェントを使用したコンポーネントオーサリングプラットフォームです Convex Component Authoring은 K-12부터 대학 교육까지를 지원하는 AI 에이전트를 사용한 컴포넌트 작성 플랫폼입니다 La creación de componentes convexos es una habilidad de agente de AI que permite a los desarrolladores crear plataformas de aprendizaje en línea de alta calidad La création de composants convexes est une compétence d''agent d''IA qui permet aux développeurs de créer des plateformes d''apprentissage en ligne de haute qualité Die Erstellung von konvexen Komponenten ist eine Fähigkeit von KI-Agents, die es Entwicklern ermöglicht, Online-Lernplattformen von hoher Qualität zu erstellen Plataforma de aprendizado de IA nativa, gratuita e de alta qualidade, do ensino fundamental ao universitário, com recursos de autorização de componentes convexos para desenvolvedores ИИ Native бесплатная высококачественная платформа обучения от начальной школы до университета, с возможностями создания компонентов(Convex Component Authoring) для разработчиков منصة تعلم ذكاء اصطناعي اصطناعي مجانية وعالية الجودة، من المرحلة الابتدائية إلى الجامعية، مع موارد تأليف مكونات محدبة للمطورين AI Native Free High-Quality Learning Platform (K-12 to University) 如何使用 Convex Component Authoring 什么是 AI 组件开发 Convex Component Authoring 替代品 Convex Component Authoring 安装 Convex Component Authoring 教程 AI 学习平台 组件开发工具 免费学习平台 AI Native Free High-Quality Learning Platform (K-12 to University)');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alex-tgk/saasquatch/ffmpeg', 'community', 'alex-tgk', 'saasquatch', 'alex-tgk/saasquatch', 'ffmpeg', 0, 0, 65, '2026-03-05T06:20:06.220Z', '2026-03-05T07:21:17.895Z', '6e597ecb0fbe9c1bb76549ce47060fcc4003a6514abffb2600142de216ad4936', '{"id":"alex-tgk/saasquatch/ffmpeg","name":"ffmpeg","description":{"zh":"SaaSQuatch是一个使用Fastify的生产就绪CLI工具，用于生成完整的微服务架构","ja":"SaaSQuatchはFastifyを使用した、生产就绪のCLIツールであり、完全なマイクロサービスアーキテクチャを生成","ko":"SaaSQuatch는 Fastify를 사용한 생산 준비 CLI 도구로 완전한 마이크로 서비스 아키텍처를 생성","es":"SaaSQuatch es una herramienta de línea de comandos de producción que genera arquitecturas de microservicios completas con Fastify y ffmpeg","fr":"SaaSQuatch est un outil de ligne de commande de production qui génère des architectures de microservices complètes avec Fastify et ffmpeg","de":"SaaSQuatch ist ein Produktions-CLI-Tool, das vollständige Microservice-Architekturen mit Fastify und ffmpeg generiert","pt":"SaaSQuatch é uma ferramenta de linha de comando que gera arquiteturas de microserviços prontas para produção com Fastify e ffmpeg","ru":"SaaSQuatch - это инструмент командной строки, который генерирует готовые микросервисные архитектуры для производства с Fastify и ffmpeg","ar":"SaaSQuatch هي أداة سطر الأوامر التي تولد هياكل микروسيرفيس جاهزة للإنتاج مع Fastify و ffmpeg","en":"SaaSQuatch - A production-ready CLI tool that generates complete microservices architectures using Fastify"},"seo":{"title":{"zh":"ffmpeg AI工具：SaaSQuatch微服务架构生成","ja":"ffmpeg AIエージェント：SaaSQuatchマイクロサービスアーキテクチャ生成","ko":"ffmpeg AI 에이전트: SaaSQuatch 마이크로 서비스 아키텍처 생성","es":"Herramientas de AI: ffmpeg para microservicios con SaaSQu...","fr":"Outils d''IA : ffmpeg pour les microservices avec SaaSQuatch","de":"KI-Tools: ffmpeg für Microservices mit SaaSQuatch","pt":"Ferramentas de IA: SaaSQuatch com ffmpeg","ru":"ИИ Агенты: SaaSQuatch с ffmpeg","ar":"أدوات الذكاء الاصطناعي: SaaSQuatch مع ffmpeg","en":"ffmpeg"},"description":{"zh":"SaaSQuatch是一个使用Fastify的生产就绪CLI工具，用于生成完整的微服务架构","ja":"SaaSQuatchはFastifyを使用した、生产就绪のCLIツールであり、完全なマイクロサービスアーキテクチャを生成","ko":"SaaSQuatch는 Fastify를 사용한 생산 준비 CLI 도구로 완전한 마이크로 서비스 아키텍처를 생성","es":"SaaSQuatch es una herramienta de línea de comandos de producción que genera arquitecturas de microservicios completas con Fastify y ffmpeg","fr":"SaaSQuatch est un outil de ligne de commande de production qui génère des architectures de microservices complètes avec Fastify et ffmpeg","de":"SaaSQuatch ist ein Produktions-CLI-Tool, das vollständige Microservice-Architekturen mit Fastify und ffmpeg generiert","pt":"SaaSQuatch é uma ferramenta de linha de comando que gera arquiteturas de microserviços prontas para produção com Fastify e ffmpeg","ru":"SaaSQuatch - это инструмент командной строки, который генерирует готовые микросервисные архитектуры для производства с Fastify и ffmpeg","ar":"SaaSQuatch هي أداة سطر الأوامر التي تولد هياكل микروسيرفيس جاهزة للإنتاج مع Fastify و ffmpeg","en":"SaaSQuatch - A production-ready CLI tool that generates complete microservices architectures using Fastify"},"definition":{"en":"SaaSQuatch - A production-ready CLI tool that generates complete microservices architectures using Fastify"},"features":{"zh":["生成生产就绪的微服务架构","使用Fastify框架","支持ffmpeg音频和视频处理","CLI工具简化开发流程","快速生成完整的微服务架构"],"ja":["生产就绪のマイクロサービスアーキテクチャを生成","Fastifyフレームワークを使用","ffmpegによる音频とビデオ処理をサポート","CLIツールによる開発プロセスの簡素化","完全なマイクロサービスアーキテクチャを迅速に生成"],"ko":["생산 준비 마이크로 서비스 아키텍처 생성","Fastify 프레임워크 사용","ffmpeg를 통한 오디오 및 비디오 처리 지원","CLI 도구를 통한 개발 프로세스 단순화","완전한 마이크로 서비스 아키텍처를 신속하게 생성"],"es":["Generación de arquitecturas de microservicios completas","Integración con Fastify para un rendimiento óptimo","Procesamiento de video y audio con ffmpeg","Herramienta de línea de comandos de producción lista","Compatibilidad con diferentes formatos de archivo"],"fr":["Génération d''architectures de microservices complètes","Intégration avec Fastify pour des performances optimales","Traitement de la vidéo et de l''audio avec ffmpeg","Outil de ligne de commande de production prêt","Compatibilité avec différents formats de fichiers"],"de":["Erstellung von vollständigen Microservice-Architekturen","Integration mit Fastify für optimale Leistung","Verarbeitung von Video und Audio mit ffmpeg","Produktions-CLI-Tool bereit","Kompatibilität mit verschiedenen Dateiformaten"],"pt":["Geração de arquiteturas de microserviços prontas para produção","Integração com Fastify","Suporte a ffmpeg","Ferramenta de linha de comando","Desenvolvimento rápido de microserviços"],"ru":["Генерация готовых микросервисных архитектур для производства","Интеграция с Fastify","Поддержка ffmpeg","Инструмент командной строки","Быстрая разработка микросервисов"],"ar":["توليد هياكل микروسيرفيس جاهزة للإنتاج","التكامل مع Fastify","دعم ffmpeg","أداة سطر الأوامر","تطوير سريع لميكروسيرفيسات"]},"keywords":{"zh":["ffmpeg工具","SaaSQuatch微服务架构","Fastify框架","CLI工具开发","微服务架构生成","ffmpeg音频处理","ffmpeg视频处理","SaaSQuatch安装","SaaSQuatch教程"],"ja":["ffmpegツール","SaaSQuatchマイクロサービスアーキテクチャ","Fastifyフレームワーク","CLIツール開発","マイクロサービスアーキテクチャ生成","ffmpeg音频処理","ffmpegビデオ処理","SaaSQuatchインストール","SaaSQuatchチュートリアル"],"ko":["ffmpeg 도구","SaaSQuatch 마이크로 서비스 아키텍처","Fastify 프레임워크","CLI 도구 개발","마이크로 서비스 아키텍처 생성","ffmpeg 오디오 처리","ffmpeg 비디오 처리","SaaSQuatch 설치","SaaSQuatch 튜토리얼"],"es":["cómo usar ffmpeg","qué es SaaSQuatch","alternativas a SaaSQuatch","SaaSQuatch vs otros","instalación de SaaSQuatch","guía de configuración de SaaSQuatch","microservicios con Fastify","procesamiento de video con ffmpeg"],"fr":["comment utiliser ffmpeg","quoi est SaaSQuatch","alternatives à SaaSQuatch","SaaSQuatch vs autres","installation de SaaSQuatch","guide de configuration de SaaSQuatch","microservices avec Fastify","traitement de la vidéo avec ffmpeg"],"de":["wie man ffmpeg verwendet","was ist SaaSQuatch","Alternativen zu SaaSQuatch","SaaSQuatch vs andere","Installation von SaaSQuatch","Konfigurationshandbuch für SaaSQuatch","Microservices mit Fastify","Verarbeitung von Video mit ffmpeg"],"pt":["como usar SaaSQuatch","o que é SaaSQuatch","SaaSQuatch vs outras ferramentas","instalar SaaSQuatch","guia de configuração do SaaSQuatch","desenvolvimento de microserviços com Fastify","ffmpeg para microserviços","ferramentas de IA para desenvolvedores"],"ru":["как использовать SaaSQuatch","что такое SaaSQuatch","SaaSQuatch vs другие инструменты","установить SaaSQuatch","руководство по настройке SaaSQuatch","разработка микросервисов с Fastify","ffmpeg для микросервисов","инструменты ИИ для разработчиков"],"ar":["كيفية استخدام SaaSQuatch","ما هو SaaSQuatch","SaaSQuatch مقابل أدوات أخرى","تثبيت SaaSQuatch","دليل إعداد SaaSQuatch","تطوير микروسيرفيسات مع Fastify","ffmpeg لميكروسيرفيسات","أدوات الذكاء الاصطناعي للمطورين"]}},"owner":"alex-tgk","repo":"saasquatch","repoPath":"alex-tgk/saasquatch","stars":0,"forks":0,"updatedAt":"2026-03-05T06:20:06.220Z","topics":[],"category":"community","skillMd":{"name":"ffmpeg","description":"Guide for using FFmpeg - a comprehensive multimedia framework for video/audio encoding, conversion, streaming, and filtering. Use when processing media files, converting formats, extracting audio, creating streams, applying filters, or optimizing video/audio quality.","version":"1.0.0","bodyPreview":"# FFmpeg Skill\n\nFFmpeg is a comprehensive open-source multimedia framework that handles video, audio, and other multimedia files and streams. It provides command-line tools and libraries for recording, converting, and streaming audio and video.\n\n## When to Use This Skill\n\nUse this skill when:\n- Converting media files between formats (MP4, MKV, WebM, AVI, etc.)\n- Encoding/decoding video with different codecs (H.264, H.265, VP9, AV1)\n- Processing audio files (AAC, MP3, FLAC, Opus)\n- Live streaming","body":"# FFmpeg Skill\n\nFFmpeg is a comprehensive open-source multimedia framework that handles video, audio, and other multimedia files and streams. It provides command-line tools and libraries for recording, converting, and streaming audio and video.\n\n## When to Use This Skill\n\nUse this skill when:\n- Converting media files between formats (MP4, MKV, WebM, AVI, etc.)\n- Encoding/decoding video with different codecs (H.264, H.265, VP9, AV1)\n- Processing audio files (AAC, MP3, FLAC, Opus)\n- Live streaming to platforms (Twitch, YouTube, RTMP servers)\n- Creating HLS/DASH adaptive streams\n- Extracting audio from video files\n- Applying video/audio filters (scale, crop, denoise, volume)\n- Screen recording and capture\n- Optimizing video quality and file size\n- Batch processing media files\n- Analyzing media file properties\n\n## Core Components\n\n### Command-Line Tools\n\n**ffmpeg**: Primary tool for transcoding, conversion, and streaming\n**ffprobe**: Media analysis and inspection tool\n**ffplay**: Minimalist multimedia player for testing\n\n### Libraries\n\n- **libavcodec**: Encoding/decoding codecs\n- **libavformat**: Container formats and I/O\n- **libavfilter**: Audio/video filtering framework\n- **libavutil**: Utility functions\n- **libswscale**: Video scaling and color conversion\n- **libswresample**: Audio resampling and mixing\n\n## Common Video Codecs\n\n### Modern Codecs\n\n**H.264 (libx264)**: Most widely supported, excellent compression/quality balance\n- Best for: Universal compatibility, streaming, web video\n- Quality range: CRF 17-28 (lower = better quality)\n\n**H.265/HEVC (libx265)**: 25-50% better compression than H.264\n- Best for: 4K video, file size reduction\n- Slower encoding, limited browser support\n\n**VP9**: Royalty-free, WebM format\n- Best for: YouTube, open-source projects\n- Good quality/compression, Chrome/Firefox support\n\n**AV1 (libaom-av1, libsvtav1)**: Next-generation codec, best compression\n- Best for: Future-proofing, ultimate quality/size ratio\n- Very slow encoding (improving with SVT-AV1)\n\n### Legacy Codecs\n- MPEG-4 (Xvid/DivX)\n- MPEG-2\n- VP8\n\n## Common Audio Codecs\n\n**AAC**: Industry standard, excellent quality\n**MP3**: Universal compatibility, good quality\n**Opus**: Best quality at low bitrates, ideal for voice/streaming\n**FLAC**: Lossless compression, archival quality\n**Vorbis**: Open-source, good quality\n**AC-3/DTS**: Surround sound formats\n\n## Container Formats\n\n**MP4**: Universal compatibility, streaming-friendly\n**MKV (Matroska)**: Feature-rich, supports multiple tracks/subtitles\n**WebM**: Web-optimized (VP8/VP9 + Vorbis/Opus)\n**AVI**: Legacy format, broad compatibility\n**MOV**: Apple QuickTime format\n**TS**: Transport stream for broadcasting\n**FLV**: Flash video (legacy streaming)\n\n## Basic Operations\n\n### Format Conversion\n\nSimple format conversion without re-encoding:\n```bash\nffmpeg -i input.mkv -c copy output.mp4\n```\n\nConvert with specific codecs:\n```bash\nffmpeg -i input.avi -c:v libx264 -c:a aac output.mp4\n```\n\n### Quality-Based Encoding (CRF)\n\nConstant Rate Factor - best for quality-focused encoding:\n\n```bash\n# H.264 encoding (CRF 23 = default, 17-28 recommended range)\nffmpeg -i input.mkv -c:v libx264 -preset slow -crf 22 -c:a copy output.mp4\n\n# H.265 encoding (higher compression)\nffmpeg -i input.mkv -c:v libx265 -preset medium -crf 24 -c:a copy output.mp4\n\n# VP9 encoding (WebM)\nffmpeg -i input.mkv -c:v libvpx-vp9 -crf 30 -b:v 0 -c:a libopus output.webm\n```\n\n**CRF Scale:**\n- 0 = Lossless (huge file size)\n- 17-18 = Visually lossless\n- 20-23 = High quality (recommended)\n- 24-28 = Medium quality\n- 30+ = Low quality\n- 51 = Worst quality\n\n**Presets** (speed vs compression):\n- ultrafast, superfast, veryfast, faster, fast\n- medium (default)\n- slow, slower, veryslow (better compression)\n- placebo (not recommended - minimal gains)\n\n### Bitrate-Based Encoding (Two-Pass)\n\nFor targeting specific file sizes:\n\n```bash\n# Pass 1 (analysis)\nffmpeg -y -i input.mkv -c:v libx264 -b:v 2600k -pass 1 -an -f null /dev/null\n\n# Pass 2 (encoding)\nffmpeg -i input.mkv -c:v libx264 -b:v 2600k -pass 2 -c:a aac -b:a 128k output.mp4\n```\n\n### Audio Extraction\n\nExtract audio without re-encoding:\n```bash\nffmpeg -i video.mp4 -vn -c:a copy audio.m4a\n```\n\nExtract and convert to MP3:\n```bash\nffmpeg -i video.mp4 -vn -q:a 0 audio.mp3\n```\n\nExtract with specific bitrate:\n```bash\nffmpeg -i video.mp4 -vn -c:a libmp3lame -b:a 192k audio.mp3\n```\n\n### Video Scaling/Resizing\n\nScale to specific dimensions:\n```bash\nffmpeg -i input.mp4 -vf scale=1280:720 output.mp4\n```\n\nScale maintaining aspect ratio:\n```bash\n# Width 1280, height auto-calculated\nffmpeg -i input.mp4 -vf scale=1280:-1 output.mp4\n\n# Height 720, width auto-calculated\nffmpeg -i input.mp4 -vf scale=-1:720 output.mp4\n```\n\nScale to half resolution:\n```bash\nffmpeg -i input.mp4 -vf scale=iw/2:ih/2 output.mp4\n```\n\n### Trimming/Cutting Video\n\nCut without re-encoding (fast but less precise):\n```bash\nffmpeg -i input.mp4 -ss 00:01:30 -to 00:03:00 -c copy output.mp4\n```\n\nCut with re-encoding (precise):\n```bash\nffmpeg -i input.mp4 -ss 00:01:30 -t 00:01:30 -c:v libx264 -c:a aac output.mp4\n```\n\nParameters:\n- `-ss`: Start time (HH:MM:SS or seconds)\n- `-to`: End time\n- `-t`: Duration (instead of end time)\n\n### Concatenation\n\n**Method 1: Concat demuxer (same codec/format)**\n\nCreate `concat.txt`:\n```\nfile ''input1.mp4''\nfile ''input2.mp4''\nfile ''input3.mp4''\n```\n\nRun:\n```bash\nffmpeg -f concat -safe 0 -i concat.txt -c copy output.mp4\n```\n\n**Method 2: Concat filter (different formats)**\n```bash\nffmpeg -i input1.mp4 -i input2.mp4 -i input3.mp4 \\\n  -filter_complex \"[0:v][0:a][1:v][1:a][2:v][2:a]concat=n=3:v=1:a=1[v][a]\" \\\n  -map \"[v]\" -map \"[a]\" output.mp4\n```\n\n## Advanced Filtering\n\n### Video Filters\n\n**Multiple filters (chain with comma):**\n```bash\nffmpeg -i input.mp4 -vf \"scale=1280:720,hqdn3d\" output.mp4\n```\n\n**Denoise:**\n```bash\nffmpeg -i input.mp4 -vf hqdn3d output.mp4\n```\n\n**Deinterlace:**\n```bash\nffmpeg -i input.mp4 -vf yadif output.mp4\n```\n\n**Crop:**\n```bash\n# Crop to 1280x720 from top-left (0,0)\nffmpeg -i input.mp4 -vf \"crop=1280:720:0:0\" output.mp4\n\n# Auto-detect and remove black borders\nffmpeg -i input.mp4 -vf \"cropdetect\" output.mp4\n```\n\n**Rotate:**\n```bash\n# Rotate 90 degrees clockwise\nffmpeg -i input.mp4 -vf \"transpose=1\" output.mp4\n\n# Rotate 180 degrees\nffmpeg -i input.mp4 -vf \"transpose=1,transpose=1\" output.mp4\n```\n\n**Watermark/Logo:**\n```bash\nffmpeg -i video.mp4 -i logo.png \\\n  -filter_complex \"overlay=10:10\" output.mp4\n```\n\n**Speed adjustment:**\n```bash\n# 2x speed\nffmpeg -i input.mp4 -vf \"setpts=0.5*PTS\" -af \"atempo=2.0\" output.mp4\n\n# 0.5x speed (slow motion)\nffmpeg -i input.mp4 -vf \"setpts=2.0*PTS\" -af \"atempo=0.5\" output.mp4\n```\n\n### Audio Filters\n\n**Volume adjustment:**\n```bash\n# Increase volume by 10dB\nffmpeg -i input.mp4 -af \"volume=10dB\" output.mp4\n\n# Set to 50% volume\nffmpeg -i input.mp4 -af \"volume=0.5\" output.mp4\n```\n\n**Normalize audio:**\n```bash\nffmpeg -i input.mp4 -af loudnorm output.mp4\n```\n\n**Crossfade between audio:**\n```bash\nffmpeg -i audio1.mp3 -i audio2.mp3 \\\n  -filter_complex \"[0][1]acrossfade=d=5\" output.mp3\n```\n\n**Mix multiple audio tracks:**\n```bash\nffmpeg -i input1.mp3 -i input2.mp3 \\\n  -filter_complex \"[0:a][1:a]amix=inputs=2:duration=longest\" output.mp3\n```\n\n## Streaming\n\n### RTMP Streaming (Twitch/YouTube)\n\n**Basic stream:**\n```bash\nffmpeg -re -i input.mp4 -c:v libx264 -preset veryfast \\\n  -maxrate 3000k -bufsize 6000k -pix_fmt yuv420p -g 50 \\\n  -c:a aac -b:a 128k -ar 44100 \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Screen capture + stream (Linux):**\n```bash\nffmpeg -f x11grab -s 1920x1080 -framerate 30 -i :0.0 \\\n  -f pulse -ac 2 -i default \\\n  -c:v libx264 -preset veryfast -tune zerolatency \\\n  -maxrate 2500k -bufsize 5000k -pix_fmt yuv420p \\\n  -c:a aac -b:a 128k -ar 44100 \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Screen capture (Windows DirectShow):**\n```bash\nffmpeg -f dshow -i video=\"screen-capture-recorder\":audio=\"Stereo Mix\" \\\n  -c:v libx264 -preset ultrafast -tune zerolatency \\\n  -maxrate 750k -bufsize 3000k \\\n  -f flv rtmp://live.twitch.tv/app/YOUR_STREAM_KEY\n```\n\n**Important streaming parameters:**\n- `-re`: Read input at native frame rate (real-time)\n- `-tune zerolatency`: Optimize for low latency\n- `-g 50`: Keyframe every 50 frames (2 seconds @ 25fps)\n- `-maxrate`: Maximum bitrate\n- `-bufsize`: Rate control buffer (typically 2x maxrate)\n\n### HLS Streaming\n\nGenerate adaptive HLS stream:\n```bash\nffmpeg -i input.mp4 \\\n  -c:v libx264 -preset fast -crf 22 -g 48 -sc_threshold 0 \\\n  -c:a aac -b:a 128k \\\n  -f hls -hls_time 6 -hls_playlist_type vod \\\n  -hls_segment_filename \"segment_%03d.ts\" \\\n  playlist.m3u8\n```\n\n**Multi-bitrate HLS:**\n```bash\nffmpeg -i input.mp4 \\\n  -map 0:v -map 0:a -map 0:v -map 0:a \\\n  -c:v libx264 -crf 22 -c:a aac -b:a 128k \\\n  -b:v:0 2000k -s:v:0 1280x720 -b:v:1 5000k -s:v:1 1920x1080 \\\n  -var_stream_map \"v:0,a:0 v:1,a:1\" \\\n  -master_pl_name master.m3u8 \\\n  -f hls -hls_time 6 -hls_list_size 0 \\\n  stream_%v/index.m3u8\n```\n\n### UDP/RTP Streaming\n\n**UDP stream:**\n```bash\nffmpeg -re -i input.mp4 -c copy -f mpegts udp://192.168.1.100:1234\n```\n\n**RTP audio stream:**\n```bash\nffmpeg -re -i audio.mp3 -c:a libopus -f rtp rtp://192.168.1.100:5004\n```\n\n## Hardware Acceleration\n\n### NVIDIA NVENC\n\n```bash\n# H.264 with NVENC\nffmpeg -hwaccel cuda -i input.mp4 -c:v h264_nvenc -preset fast -crf 22 output.mp4\n\n# H.265 with NVENC\nffmpeg -hwaccel cuda -i input.mp4 -c:v hevc_nvenc -preset fast -crf 24 output.mp4\n```\n\n### Intel QuickSync (QSV)\n\n```bash\nffmpeg -hwaccel qsv -c:v h264_qsv -i input.mp4 \\\n  -c:v h264_qsv -preset fast -global_quality 22 output.mp4\n```\n\n### AMD VCE\n\n```bash\nffmpeg -hwaccel auto -i input.mp4 \\\n  -c:v h264_amf -quality balanced -rc cqp -qp 22 output.mp4\n```\n\n## Media Analysis\n\n### Inspect media file\n\n```bash\n# Detailed information\nffprobe -v quiet -print_format json -show_format -show_streams input.mp4\n\n# Human-readable format\nffprobe input.mp4\n\n# Get duration\nffprobe -v error -show_entries format=duration \\\n  -of default=noprint_wrappers=1:nokey=1 input.mp4\n\n# Get resolution\nffprobe -v error -select_streams v:0 \\\n  -show_entries stream=width,height \\\n  -of csv=s=x:p=0 input.mp4\n\n# Get bitrate\nffprobe -v error -show_entries format=bit_rate \\\n  -of default=noprint_wrappers=1:nokey=1 input.mp4\n```\n\n## Batch Processing\n\n### Bash loop for batch conversion\n\n```bash\n# Convert all MKV files to MP4\nfor file in *.mkv; do\n  ffmpeg -i \"$file\" -c:v libx264 -crf 22 -c:a aac \"${file%.mkv}.mp4\"\ndone\n\n# Resize all videos to 720p\nfor file in *.mp4; do\n  ffmpeg -i \"$file\" -vf scale=-1:720 \"720p_${file}\"\ndone\n```\n\n### Parallel processing with GNU Parallel\n\n```bash\n# Install: sudo apt-get install parallel\n\n# Process multiple files in parallel\nls *.mkv | parallel ffmpeg -i {} -c:v libx264 -crf 22 -c:a aac {.}.mp4\n```\n\n## Common Patterns\n\n### Create GIF from video\n\n```bash\n# High quality GIF\nffmpeg -i input.mp4 -vf \"fps=15,scale=640:-1:flags=lanczos,split[s0][s1];[s0]palettegen[p];[s1][p]paletteuse\" output.gif\n\n# Simple GIF\nffmpeg -i input.mp4 -vf \"fps=10,scale=320:-1\" output.gif\n```\n\n### Extract frames as images\n\n```bash\n# Extract all frames\nffmpeg -i input.mp4 frame_%04d.png\n\n# Extract 1 frame per second\nffmpeg -i input.mp4 -vf fps=1 frame_%04d.png\n\n# Extract single frame at 5 seconds\nffmpeg -ss 00:00:05 -i input.mp4 -frames:v 1 frame.png\n```\n\n### Create video from images\n\n```bash\n# From numbered images\nffmpeg -framerate 30 -i frame_%04d.png -c:v libx264 -crf 22 -pix_fmt yuv420p output.mp4\n\n# From pattern\nffmpeg -framerate 24 -pattern_type glob -i ''*.png'' -c:v libx264 output.mp4\n```\n\n### Add subtitles\n\n```bash\n# Burn subtitles into video\nffmpeg -i video.mp4 -vf subtitles=subtitles.srt output.mp4\n\n# Embed subtitle track (soft subtitles)\nffmpeg -i video.mp4 -i subtitles.srt -c copy -c:s mov_text output.mp4\n```\n\n### Remove audio\n\n```bash\nffmpeg -i input.mp4 -an -c:v copy output.mp4\n```\n\n### Replace audio\n\n```bash\nffmpeg -i video.mp4 -i audio.mp3 -c:v copy -c:a aac -map 0:v:0 -map 1:a:0 output.mp4\n```\n\n### Create thumbnail\n\n```bash\n# Single thumbnail at 5 seconds\nffmpeg -i input.mp4 -ss 00:00:05 -vframes 1 -vf scale=320:-1 thumb.jpg\n\n# Multiple thumbnails (one per minute)\nffmpeg -i input.mp4 -vf fps=1/60,scale=320:-1 thumb_%03d.jpg\n```\n\n## Performance Optimization\n\n### Speed vs Quality Trade-offs\n\n**Fast encoding (real-time processing):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset ultrafast -crf 23 output.mp4\n```\n\n**Balanced (default):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset medium -crf 22 output.mp4\n```\n\n**High quality (archival):**\n```bash\nffmpeg -i input.mp4 -c:v libx264 -preset veryslow -crf 18 output.mp4\n```\n\n### Multi-threading\n\nFFmpeg automatically uses multiple CPU cores. Override with:\n```bash\nffmpeg -threads 8 -i input.mp4 -c:v libx264 output.mp4\n```\n\n## Best Practices\n\n1. **Use CRF for quality-focused encoding** - Better than bitrate for most use cases\n2. **Two-pass for size targets** - When file size is critical\n3. **Copy streams when possible** - Use `-c copy` to avoid re-encoding\n4. **Choose appropriate presets** - Balance speed vs compression\n5. **Match output to source** - Don''t upscale or use higher quality than source\n6. **Test short clips first** - Verify settings before batch processing\n7. **Hardware acceleration** - Use GPU encoding for faster processing\n8. **Audio matters** - Don''t neglect audio codec/bitrate choices\n9. **Use filters efficiently** - Chain multiple filters with commas\n10. **Verify output** - Always check quality after encoding\n\n## Common Parameters Reference\n\n### Video Parameters\n- `-c:v` or `-vcodec`: Video codec\n- `-b:v`: Video bitrate (e.g., `2M`, `2500k`)\n- `-crf`: Constant Rate Factor (0-51)\n- `-preset`: Encoding speed/quality (ultrafast to veryslow)\n- `-tune`: Encoding optimization (film, animation, zerolatency)\n- `-pix_fmt`: Pixel format (yuv420p for compatibility)\n- `-r`: Frame rate (e.g., `30`, `60`)\n- `-g`: GOP size (keyframe interval)\n\n### Audio Parameters\n- `-c:a` or `-acodec`: Audio codec\n- `-b:a`: Audio bitrate (e.g., `128k`, `192k`)\n- `-ar`: Audio sample rate (e.g., `44100`, `48000`)\n- `-ac`: Audio channels (1=mono, 2=stereo)\n- `-q:a`: Audio quality for VBR (0=best for MP3)\n\n### General Parameters\n- `-i`: Input file\n- `-y`: Overwrite output without asking\n- `-n`: Never overwrite output\n- `-t`: Duration to encode\n- `-ss`: Start time offset\n- `-to`: End time\n- `-vf`: Video filters\n- `-af`: Audio filters\n- `-map`: Stream selection\n- `-metadata`: Set metadata\n- `-f`: Force format\n\n## Troubleshooting\n\n### \"Unknown encoder\" errors\nInstall codec libraries:\n```bash\n# Ubuntu/Debian\nsudo apt-get install ffmpeg libx264-dev libx265-dev libvpx-dev\n\n# Check available encoders\nffmpeg -encoders\n```\n\n### Output compatibility issues\nUse safe defaults for maximum compatibility:\n```bash\nffmpeg -i input.mkv -c:v libx264 -profile:v high -level 4.0 \\\n  -pix_fmt yuv420p -c:a aac -b:a 128k output.mp4\n```\n\n### Performance issues\n- Use hardware acceleration (`-hwaccel`)\n- Choose faster presets (`-preset fast`)\n- Reduce resolution with scale filter\n- Use multiple threads explicitly\n\n### Quality issues\n- Lower CRF value (18-22 for high quality)\n- Use slower preset (`-preset slow`)\n- Use two-pass encoding for better bitrate distribution\n- Match or exceed source bitrate\n\n## Resources\n\n- Official Documentation: https://ffmpeg.org/documentation.html\n- FFmpeg Wiki: https://trac.ffmpeg.org/\n- Codec Guides: https://trac.ffmpeg.org/wiki/Encode\n- Filter Documentation: https://ffmpeg.org/ffmpeg-filters.html\n- GitHub Repository: https://github.com/ffmpeg/ffmpeg\n- Community Examples: https://trac.ffmpeg.org/wiki/\n\n## Implementation Checklist\n\nWhen using FFmpeg:\n\n- [ ] Verify FFmpeg installation (`ffmpeg -version`)\n- [ ] Check available codecs for your use case\n- [ ] Test encoding settings on short clip first\n- [ ] Choose appropriate codec for target platform\n- [ ] Set quality level (CRF or bitrate)\n- [ ] Configure audio codec and bitrate\n- [ ] Apply necessary filters (scale, crop, etc.)\n- [ ] Consider hardware acceleration if available\n- [ ] Verify output quality and file size\n- [ ] Test output compatibility on target devices\n- [ ] Document settings for reproducibility\n- [ ] Create batch scripts for repetitive tasks\n"},"lastSynced":"2026-03-05T07:21:17.895Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Processing Agents needing advanced video and audio conversion capabilities with FFmpeg.","zh":"Perfect for Media Processing Agents needing advanced video and audio conversion capabilities with FFmpeg.","ja":"Perfect for Media Processing Agents needing advanced video and audio conversion capabilities with FFmpeg.","ko":"Perfect for Media Processing Agents needing advanced video and audio conversion capabilities with FFmpeg.","es":"Perfecto para Agentes de Procesamiento de Medios que necesitan capacidades avanzadas de conversión de video y audio con FFmpeg.","fr":"Parfait pour les Agents de Traitement des Médias nécessitant des capacités de conversion de vidéo et d''audio avancées avec FFmpeg.","de":"Perfekt für Medienverarbeitungsagenten, die erweiterte Video- und Audio-Konvertierungsfunktionen mit FFmpeg benötigen.","pt":"Perfeito para Agentes de Processamento de Mídia que necessitam de capacidades avançadas de conversão de vídeo e áudio com FFmpeg.","ru":"Идеально подходит для агентов обработки медиа, которым требуются продвинутые возможности преобразования видео и аудио с помощью FFmpeg.","ar":"مثالي للوكلاء معالجة الوسائط التي تحتاج إلى قابليات متقدمة لتحويل الفيديو والصوت مع FFmpeg."},"recommendation":{"en":"Empowers agents to convert media files between formats like MP4, MKV, and WebM, encode and decode video with codecs such as H.264 and H.265, and process audio files in formats like AAC and MP3, enabling seamless live streaming and multimedia handling.","zh":"Empowers agents to convert media files between formats like MP4, MKV, and WebM, encode and decode video with codecs such as H.264 and H.265, and process audio files in formats like AAC and MP3, enabling seamless live streaming and multimedia handling.","ja":"Empowers agents to convert media files between formats like MP4, MKV, and WebM, encode and decode video with codecs such as H.264 and H.265, and process audio files in formats like AAC and MP3, enabling seamless live streaming and multimedia handling.","ko":"Empowers agents to convert media files between formats like MP4, MKV, and WebM, encode and decode video with codecs such as H.264 and H.265, and process audio files in formats like AAC and MP3, enabling seamless live streaming and multimedia handling.","es":"Habilita a los agentes a convertir archivos de medios entre formatos como MP4, MKV y WebM, codificar y decodificar video con codecs como H.264 y H.265, y procesar archivos de audio en formatos como AAC y MP3, lo que permite una transmisión en vivo y un manejo de multimedia sin problemas.","fr":"Permet aux agents de convertir des fichiers multimédias entre des formats tels que MP4, MKV et WebM, de coder et de décoder la vidéo avec des codecs tels que H.264 et H.265, et de traiter des fichiers audio dans des formats tels que AAC et MP3, permettant ainsi une diffusion en direct et une gestion multimedia sans interruption.","de":"Ermöglicht es Agenten, Mediadateien zwischen Formaten wie MP4, MKV und WebM zu konvertieren, Video mit Codecs wie H.264 und H.265 zu codieren und zu decodieren und Audiodateien in Formaten wie AAC und MP3 zu verarbeiten, was ein nahtloses Live-Streaming und Multimedia-Handling ermöglicht.","pt":"Habilita os agentes a converter arquivos de mídia entre formatos como MP4, MKV e WebM, codificar e decodificar vídeo com codecs como H.264 e H.265, e processar arquivos de áudio em formatos como AAC e MP3, permitindo transmissão ao vivo e manipulação de multimídia sem interrupções.","ru":"Предоставляет агентам возможность конвертировать медиафайлы между форматами, такими как MP4, MKV и WebM, кодировать и декодировать видео с помощью кодеков, таких как H.264 и H.265, и обрабатывать аудиофайлы в форматах, таких как AAC и MP3, обеспечивая бесперебойную трансляцию и обработку мультимедиа.","ar":"تمكّن الوكلاء من تحويل ملفات الوسائط بين صيغ مثل MP4 و MKV و WebM، وتشفير وفك تشفير الفيديو باستخدام ترميزات مثل H.264 و H.265، ومعالجة ملفات الصوت بصيغ مثل AAC و MP3، مما يسمح بالبث المباشر والمعالجة المتعددة الوسائط دون انقطاع."},"useCases":{"en":["Converting video files from MP4 to WebM for web compatibility","Encoding audio files to AAC for efficient streaming","Streaming live video content using FFmpeg''s robust encoding capabilities"],"zh":["Converting video files from MP4 to WebM for web compatibility","Encoding audio files to AAC for efficient streaming","Streaming live video content using FFmpeg''s robust encoding capabilities"],"ja":["Converting video files from MP4 to WebM for web compatibility","Encoding audio files to AAC for efficient streaming","Streaming live video content using FFmpeg''s robust encoding capabilities"],"ko":["Converting video files from MP4 to WebM for web compatibility","Encoding audio files to AAC for efficient streaming","Streaming live video content using FFmpeg''s robust encoding capabilities"],"es":["Convertir archivos de video de MP4 a WebM para compatibilidad web","Codificar archivos de audio a AAC para un streaming eficiente","Transmitir contenido de video en vivo utilizando las capacidades de codificación robustas de FFmpeg"],"fr":["Convertir des fichiers vidéo de MP4 en WebM pour la compatibilité web","Coder des fichiers audio en AAC pour un streaming efficace","Diffuser du contenu vidéo en direct en utilisant les capacités de codage robustes de FFmpeg"],"de":["Konvertieren von Videodateien von MP4 in WebM für die Webkompatibilität","Codieren von Audiodateien in AAC für ein effizientes Streaming","Übertragen von Live-Videoinhalten mit den robusten Codierungsfunktionen von FFmpeg"],"pt":["Conversão de arquivos de vídeo do MP4 para WebM para compatibilidade na web","Codificação de arquivos de áudio para AAC para transmissão eficiente","Transmissão de conteúdo de vídeo ao vivo usando as capacidades de codificação robustas do FFmpeg"],"ru":["Преобразование видеофайлов из MP4 в WebM для совместимости с веб-страницами","Кодирование аудиофайлов в AAC для эффективного потокового вещания","Трансляция видеоконтента в прямом эфире с использованием прочных возможностей кодирования FFmpeg"],"ar":["تحويل ملفات الفيديو من MP4 إلى WebM لتوافق الويب","تشفير ملفات الصوت إلى AAC من أجل البث الفعال","بث محتوى الفيديو المباشر باستخدام إمكانيات التشفير القوية لبرنامج FFmpeg"]},"limitations":{"en":["Requires command-line interface access","Dependent on system resources for processing power","Limited to multimedia file formats supported by FFmpeg"],"zh":["Requires command-line interface access","Dependent on system resources for processing power","Limited to multimedia file formats supported by FFmpeg"],"ja":["Requires command-line interface access","Dependent on system resources for processing power","Limited to multimedia file formats supported by FFmpeg"],"ko":["Requires command-line interface access","Dependent on system resources for processing power","Limited to multimedia file formats supported by FFmpeg"],"es":["Requiere acceso a la interfaz de línea de comandos","Depende de los recursos del sistema para la potencia de procesamiento","Limitado a los formatos de archivos multimedia compatibles con FFmpeg"],"fr":["Nécessite un accès à l''interface de ligne de commande","Dépend des ressources du système pour la puissance de traitement","Limité aux formats de fichiers multimédia pris en charge par FFmpeg"],"de":["Benötigt Zugriff auf die Kommandozeilenoberfläche","Hängt von den Systemressourcen für die Verarbeitungsleistung ab","Begrenzt auf die von FFmpeg unterstützten Multimediadateiformate"],"pt":["Requer acesso à interface de linha de comando","Dependente de recursos do sistema para processamento","Limitado a formatos de arquivos de mídia suportados pelo FFmpeg"],"ru":["Требует доступа к командной строке","Зависит от системных ресурсов для обработки","Ограничен форматами медиафайлов, поддерживаемыми FFmpeg"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر","يعتمد على موارد النظام للتحويل","محدود بالصيغ الملفات الوسائط التي يدعمها برنامج FFmpeg"]},"version":3},"contentHash":"6e597ecb0fbe9c1bb76549ce47060fcc4003a6514abffb2600142de216ad4936","qualityScore":65}');
