INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kimmyxpow/recallable/convex-component-authoring', 'convex-component-authoring', 'kimmyxpow', 'recallable', 'community', 'convex-component-authoring kimmyxpow recallable community Convex Component Authoring是一款集成AI助手的笔记应用，帮助开发者提高效率 Convex Component AuthoringはAIエージェントを搭載したノートアプリで、開発者の生産性を向上させます Convex Component Authoring는 AI를 활용한 노트 애플리케이션으로 개발자 생산성을 향상합니다 Convex-component-authoring es una aplicación de notas con asistente de IA para mejorar la productividad Convex-component-authoring est une application de prise de notes avec assistant IA pour améliorer la productivité Convex-component-authoring ist eine Notiz-Anwendung mit KI-Assistenten für erhöhte Produktivität A habilidade de autorias de componentes convexos é uma aplicação de notas com assistente de IA para desenvolvedores Навык авторства конвексных компонентов - это приложение для заметок с ИИ Агентом для разработчиков مهارة كتابة المكونات المحدبة هي تطبيق ملاحظات مع مساعد الذكاء الاصطناعي للمطورين A note-taking application with AI assistant 如何使用Convex Component Authoring 什么是AI笔记应用 Convex Component Authoring替代品 Convex Component Authoring vs 其他工具 Convex Component Authoring安装 Convex Component Authoring设置指南 基于AI的笔记应用开发 Convex Component Authoring API A note-taking application with AI assistant');
