INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tenequm/claude-plugins/gh-cli', 'gh-cli', 'tenequm', 'claude-plugins', 'community', 'gh-cli tenequm claude-plugins community GitHub CLI 是一个插件市场，用于 Claude Code，提供远程仓库操作、代码库比较和代码发现功能 GitHub CLI は Claude Code 用のプラグイン マーケットで、リモート リポジトリ操作、コード ベースの比較、コードの発見機能を提供します GitHub CLI는 Claude Code용 플러그인 마켓플레이스로서 원격 저장소 운영, 코드베이스 비교, 코드 발견 기능을 제공 El CLI de GitHub es una herramienta para análisis y descubrimiento remoto de repositorios y código en GitHub. Le CLI GitHub est un outil pour l''analyse et la découverte à distance de référentiels et de code sur GitHub. Die GitHub CLI ist ein Tool für die Remote-Analyse und -Entdeckung von Repositorys und Code auf GitHub. A gh-cli é uma ferramenta de linha de comando para operações remotas no GitHub, permitindo análise e descoberta de repositórios sem clonar gh-cli - это инструмент командной строки для удаленных операций в GitHub, позволяющий анализировать и обнаруживать репозитории без клонирования غ-سي أل آي هي أداة سطر الأوامر للعمليات عن بُعد في غيت هاب، مما يسمح بالتحليل واكتشاف المستودعات دون استنساخ Plugin marketplace for Claude Code GitHub CLI 远程分析 代码发现 代码库比较 命令行工具 开发者工具 代码搜索 GitHub 搜索 Plugin marketplace for Claude Code');
