INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Lordsisodia/siso-agency-internal/github-cli', 'github-cli', 'Lordsisodia', 'siso-agency-internal', 'community', 'github-cli Lordsisodia siso-agency-internal community GitHub CLI 身份验证和 GraphQL 使用可以帮助开发者安全地访问 GitHub API 和执行 GraphQL 查询 GitHub CLI 認証と GraphQL 使用は、開発者が安全に GitHub API にアクセスし、GraphQL クエリを実行するのに役立ちます GitHub CLI 인증 및 GraphQL 사용은 개발자가 안전하게 GitHub API에 액세스하고 GraphQL 쿼리를 실행하도록 도와줍니다 La autenticación GitHub CLI permite el acceso seguro a la API de GitHub para buscar repositorios, recuperar metadatos y ejecutar consultas GraphQL L''authentification GitHub CLI permet un accès sécurisé à l''API GitHub pour rechercher des référentiels, récupérer des métadonnées et exécuter des requêtes GraphQL Die Authentifizierung von GitHub CLI ermöglicht den sicheren Zugriff auf die GitHub-API, um Repositories zu suchen, Metadaten abzurufen und GraphQL-Abfragen auszuführen O GitHub CLI é uma ferramenta para gerenciar tarefas e rastrear dias de trabalho com integração LifeLock GitHub CLI — это инструмент для управления задачами и отслеживания рабочих дней с интеграцией LifeLock جيت هب CLI هو أداة لإدارة المهام وتتبع أيام العمل مع تكامل LifeLock SISO Agency Internal Platform - Task management and day tracking system with LifeLock integration GitHub CLI GraphQL GitHub API 开发效率 安全访问 命令行工具 开源仓库 仓库元数据 SISO Agency Internal Platform - Task management and day tracking system with LifeLock integration');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pkking/dotfiles/skill-from-github', 'community', 'pkking', 'dotfiles', 'pkking/dotfiles', 'skill-from-github', 0, 0, 65, '2026-02-20T04:13:19.571Z', '2026-02-20T04:22:17.065Z', '3a5c1312f05fdf3e74e9edc2759cfb2ac7ecf61ce01b7ebe687853c1cf8ed156', '{"id":"pkking/dotfiles/skill-from-github","name":"skill-from-github","description":{"zh":"该技能从 GitHub 中学习 Linux 配置文件，帮助开发者快速找到解决问题的方法","ja":"このスキルは GitHub から Linux 設定ファイルを学び、開発者が問題を解決する方法を迅速に探すのに役立ちます","ko":"이 스킬은 GitHub에서 리눅스 구성 파일을 학습하여 개발자가 문제를 해결하는 방법을迅速하게 찾아주는 역할을 합니다","es":"La habilidad ''skill-from-github'' permite a los usuarios buscar proyectos de calidad en GitHub para resolver problemas y crear habilidades personalizadas","fr":"La compétence ''skill-from-github'' permet aux utilisateurs de rechercher des projets de qualité sur GitHub pour résoudre des problèmes et créer des compétences personnalisées","de":"Die Fähigkeit ''skill-from-github'' ermöglicht es Benutzern, qualitativ hochwertige Projekte auf GitHub zu suchen, um Probleme zu lösen und benutzerdefinierte Fähigkeiten zu erstellen","pt":"O skill-from-github permite que os desenvolvedores criem habilidades personalizadas com base em projetos de qualidade do GitHub","ru":"Навык skill-from-github позволяет разработчикам создавать индивидуальные навыки на основе качественных проектов GitHub","ar":"المهارة skill-from-github تمكن المطورين من إنشاء مهارات مخصصة باستخدام مشاريع GitHub الجودة","en":"my linux config files"},"seo":{"title":{"zh":"GitHub 技能：Linux 配置文件","ja":"GitHub スキル：Linux 設定ファイル","ko":"GitHub 스킬: 리눅스 구성 파일","es":"Herramienta de configuración de Linux desde GitHub","fr":"Outil de configuration Linux depuis GitHub","de":"Linux-Konfigurations-Tool von GitHub","pt":"Desenvolvimento de Habilidades com GitHub","ru":"Разработка навыков с GitHub","ar":"تطوير المهارات مع GitHub","en":"skill-from-github"},"description":{"zh":"该技能从 GitHub 中学习 Linux 配置文件，帮助开发者快速找到解决问题的方法","ja":"このスキルは GitHub から Linux 設定ファイルを学び、開発者が問題を解決する方法を迅速に探すのに役立ちます","ko":"이 스킬은 GitHub에서 리눅스 구성 파일을 학습하여 개발자가 문제를 해결하는 방법을迅速하게 찾아주는 역할을 합니다","es":"La habilidad ''skill-from-github'' permite a los usuarios buscar proyectos de calidad en GitHub para resolver problemas y crear habilidades personalizadas","fr":"La compétence ''skill-from-github'' permet aux utilisateurs de rechercher des projets de qualité sur GitHub pour résoudre des problèmes et créer des compétence...","de":"Die Fähigkeit ''skill-from-github'' ermöglicht es Benutzern, qualitativ hochwertige Projekte auf GitHub zu suchen, um Probleme zu lösen und benutzerdefinierte ...","pt":"O skill-from-github permite que os desenvolvedores criem habilidades personalizadas com base em projetos de qualidade do GitHub","ru":"Навык skill-from-github позволяет разработчикам создавать индивидуальные навыки на основе качественных проектов GitHub","ar":"المهارة skill-from-github تمكن المطورين من إنشاء مهارات مخصصة باستخدام مشاريع GitHub الجودة","en":"my linux config files"},"definition":{"en":"my linux config files"},"features":{"zh":["从 GitHub 中学习 Linux 配置文件","快速找到解决问题的方法","提升开发效率","支持多种编程语言","易于使用和集成"],"ja":["GitHub から Linux 設定ファイルを学ぶ","問題を解決する方法を迅速に探す","開発効率を向上させる","複数のプログラミング言語をサポート","簡単に使用して統合できる"],"ko":["GitHub에서 리눅스 구성 파일을 학습","문제를 해결하는 방법을迅速하게 찾아라","개발 효율성을 향상","다중 프로그래밍 언어 지원","사용과 통합이 쉽다"],"es":["Búsqueda de proyectos de calidad en GitHub","Creación de habilidades personalizadas para resolver problemas","Automatización de tareas y mejora de la productividad","Integración con herramientas de desarrollo","Personalización de configuraciones de Linux"],"fr":["Recherche de projets de qualité sur GitHub","Création de compétences personnalisées pour résoudre des problèmes","Automatisation de tâches et amélioration de la productivité","Intégration avec des outils de développement","Personnalisation de configurations Linux"],"de":["Suche nach qualitativ hochwertigen Projekten auf GitHub","Erstellung benutzerdefinierter Fähigkeiten zur Lösung von Problemen","Automatisierung von Aufgaben und Verbesserung der Produktivität","Integration mit Entwicklungstools","Anpassung von Linux-Konfigurationen"],"pt":["Criação de habilidades personalizadas com projetos do GitHub","Entendimento profundo de projetos de qualidade","Desenvolvimento de soluções para problemas específicos","Integração com ferramentas de desenvolvimento","Aumento da produtividade com soluções personalizadas"],"ru":["Создание индивидуальных навыков с помощью проектов GitHub","Глубокое понимание качественных проектов","Разработка решений для конкретных задач","Интеграция с инструментами разработки","Повышение производительности с помощью индивидуальных решений"],"ar":["إنشاء مهارات مخصصة باستخدام مشاريع GitHub","فهم عميق لمشاريع الجودة","تطوير حلول للمشاكل المحددة","التكامل مع أدوات التطوير","زيادة الإنتاجية مع حلول مخصصة"]},"keywords":{"zh":["GitHub 技能","Linux 配置文件","开源项目","开发效率","问题解决","编程语言"],"ja":["GitHub スキル","Linux 設定ファイル","オープンソースプロジェクト","開発効率","問題解決","プログラミング言語"],"ko":["GitHub 스킬","리눅스 구성 파일","오픈소스 프로젝트","개발 효율성","문제 해결","프로그래밍 언어"],"es":["github","configuración de linux","automatización de tareas","productividad","desarrollo de software","herramientas de desarrollo","proyectos de código abierto"],"fr":["github","configuration linux","automatisation de tâches","productivité","développement de logiciels","outils de développement","projets de code source ouvert"],"de":["github","linux-konfiguration","automatisierung von aufgaben","produktivität","software-entwicklung","entwicklungstools","open-source-projekte"],"pt":["desenvolvimento de habilidades","projetos github","soluções personalizadas","ferramentas de desenvolvimento","produtividade","github","skill-from-github"],"ru":["разработка навыков","проекты github","индивидуальные решения","инструменты разработки","производительность","github","skill-from-github"],"ar":["تطوير المهارات","مشاريع github","حلول مخصصة","أدوات التطوير","الإنتاجية","github","skill-from-github"]}},"owner":"pkking","repo":"dotfiles","repoPath":"pkking/dotfiles","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.571Z","topics":[],"category":"community","skillMd":{"name":"skill-from-github","description":"Create skills by learning from high-quality GitHub projects","bodyPreview":"# Skill from GitHub\n\nWhen users want to accomplish something, search GitHub for quality projects that solve the problem, understand them deeply, then create a skill based on that knowledge.\n\n## When to Use\n\nWhen users describe a task and you want to find existing tools/projects to learn from:\n\n- \"I want to be able to convert markdown to PDF\"\n- \"Help me analyze sentiment in customer reviews\"\n- \"I need to generate API documentation from code\"\n\n## Workflow\n\n### Step 1: Understand User Intent\n\nClari","body":"# Skill from GitHub\n\nWhen users want to accomplish something, search GitHub for quality projects that solve the problem, understand them deeply, then create a skill based on that knowledge.\n\n## When to Use\n\nWhen users describe a task and you want to find existing tools/projects to learn from:\n\n- \"I want to be able to convert markdown to PDF\"\n- \"Help me analyze sentiment in customer reviews\"\n- \"I need to generate API documentation from code\"\n\n## Workflow\n\n### Step 1: Understand User Intent\n\nClarify what the user wants to achieve:\n- What is the input?\n- What is the expected output?\n- Any constraints (language, framework, etc.)?\n\n### Step 2: Search GitHub\n\nSearch for projects that solve this problem:\n\n```\n{task keywords} language:{preferred} stars:>100 sort:stars\n```\n\n**Search tips:**\n- Start broad, then narrow down\n- Try different keyword combinations\n- Include \"cli\", \"tool\", \"library\" if relevant\n\n**Quality filters (must meet ALL):**\n- Stars > 100 (community validated)\n- Updated within last 12 months (actively maintained)\n- Has README with clear documentation\n- Has actual code (not just awesome-list)\n\n### Step 3: Present Options to User\n\nShow top 3-5 candidates:\n\n```markdown\n## Found X projects that can help\n\n### Option 1: [project-name](github-url)\n- Stars: xxx | Last updated: xxx\n- What it does: one-line description\n- Why it''s good: specific strength\n\n### Option 2: ...\n\nWhich one should I dive into? Or should I search differently?\n```\n\n**Wait for user confirmation before proceeding.**\n\n### Step 4: Deep Dive into Selected Project\n\nOnce user selects a project, thoroughly understand it:\n\n1. **Read README** - Understand purpose, features, usage\n2. **Read core source files** - Understand how it works\n3. **Check examples** - See real usage patterns\n4. **Note dependencies** - What it relies on\n5. **Identify key concepts** - The mental model behind it\n\nExtract:\n- Core algorithm/approach\n- Input/output formats\n- Error handling patterns\n- Best practices encoded in the code\n\n### Step 5: Summarize Understanding\n\nPresent what you learned to user:\n\n```markdown\n## Understanding [project-name]\n\n### Core Approach\nHow it solves the problem...\n\n### Key Techniques\n1. ...\n2. ...\n\n### Limitations\n- ...\n\n### What I''ll encode in the skill\n- ...\n\nDoes this look right? Should I proceed to create the skill?\n```\n\n**Wait for user confirmation.**\n\n### Step 6: Create Skill via skill-creator\n\nHand off to skill-creator with:\n\n1. **Clear purpose** - What the skill does\n2. **Methodology** - The approach learned from the project\n3. **Step-by-step process** - Concrete instructions\n4. **Quality criteria** - What good output looks like\n5. **Common pitfalls** - What to avoid (learned from project issues/docs)\n\n**Important:** The skill should encode the *knowledge* from the project, not just wrap the tool. The skill should work even without the original project installed.\n\n## Example\n\n**User:** \"I want to write better commit messages\"\n\n**Step 2 - Search:**\n```\ncommit message convention stars:>100 sort:stars\n```\n\n**Step 3 - Present:**\n```\n## Found 4 projects\n\n### Option 1: conventional-commits/conventionalcommits.org (4.2k ⭐)\n- Specification for human and machine readable commit messages\n- Why: Industry standard, used by Angular, Vue, etc.\n\n### Option 2: commitizen/cz-cli (15k ⭐)\n- CLI tool for creating conventional commits\n- Why: Battle-tested, lots of adapters\n\n### Option 3: carloscuesta/gitmoji (14k ⭐)\n- Emoji guide for commit messages\n- Why: Visual, fun approach\n\nWhich one interests you?\n```\n\n**User:** \"Let''s go with conventional commits\"\n\n**Step 4 - Deep dive:**\n- Read the specification\n- Understand types (feat, fix, docs, etc.)\n- Learn about scopes, breaking changes\n- Study real-world examples\n\n**Step 5 - Summarize:**\n```\n## Understanding Conventional Commits\n\n### Core Approach\nStructured format: <type>(<scope>): <description>\n\n### Key Types\n- feat: new feature\n- fix: bug fix\n- docs: documentation\n- ...\n\n### Benefits Learned\n- Automated changelog generation\n- Semantic versioning\n- Clear history\n\nReady to create a commit message skill based on this?\n```\n\n**Step 6 - Create skill with these principles encoded**\n\n## Important Notes\n\n1. **Always get user confirmation** - At step 3 (project selection) and step 5 (before creating)\n2. **Prefer learning over wrapping** - Encode the knowledge, not just \"run this tool\"\n3. **Check license** - Mention if project has restrictive license\n4. **Credit the source** - Include attribution in generated skill\n5. **Quality over speed** - Take time to truly understand the project\n\n## What This Skill is NOT\n\n- NOT a package installer\n- NOT a tool wrapper\n- It''s about **learning from the best projects** and encoding that knowledge into a reusable skill\n"},"lastSynced":"2026-02-20T04:22:17.065Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing GitHub project integration and open-source solution implementation.","zh":"非常适合需要GitHub项目集成和开源解决方案实现的AI代理。","ja":"GitHubプロジェクト統合とオープンソースソリューションの実装が必要なAIエージェントに最適です。","ko":"GitHub 프로젝트 통합 및 오픈 소스 솔루션 구현이 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan integración de proyectos de GitHub y implementación de soluciones de código abierto.","fr":"Parfait pour les agents IA ayant besoin d''une intégration de projet GitHub et d''une mise en œuvre de solutions open source.","de":"Perfekt für AI-Agents, die eine GitHub-Projektintegration und eine Implementierung von Open-Source-Lösungen benötigen.","pt":"Perfeito para Agentes de IA que precisam de integração de projetos do GitHub e implementação de soluções de código aberto.","ru":"Идеально для агентов ИИ, которым требуется интеграция с проектами GitHub и реализация решения с открытым исходным кодом.","ar":"مثالي للوكلاء الذكيين الذين يحتاجون إلى دمج مشاريع GitHub وتنفيذ حلول مفتوحة المصدر."},"recommendation":{"en":"Empowers agents to search GitHub for quality projects, understand them deeply, and create skills based on that knowledge, utilizing tools like markdown and API documentation generators.","zh":"赋予代理搜索GitHub的高质量项目、深入理解它们并基于此知识创建技能的能力，利用工具如markdown和API文档生成器。","ja":"エージェントがGitHubで高品質のプロジェクトを検索し、それらを深く理解し、その知識に基づいてスキルを作成する能力を付与します。マークダウンやAPIドキュメント生成ツールなどのツールを利用します。","ko":"에이전트가 GitHub에서 고품질 프로젝트를 검색하고, 이를 깊이 이해하여, 이러한 지식에 기반하여 스킬을 생성할 수 있는 능력을 부여합니다. 마크다운이나 API 문서 생성기와 같은 도구를 활용합니다.","es":"Permite a los agentes buscar proyectos de calidad en GitHub, comprenderlos profundamente y crear habilidades basadas en ese conocimiento, utilizando herramientas como generadores de documentación de markdown y API.","fr":"Permet aux agents de rechercher des projets de qualité sur GitHub, de les comprendre en profondeur et de créer des compétences basées sur ces connaissances, en utilisant des outils tels que des générateurs de documentation markdown et d''API.","de":"Ermächtigt Agents, GitHub nach qualitativ hochwertigen Projekten zu durchsuchen, diese tief zu verstehen und Fähigkeiten basierend auf diesem Wissen zu erstellen, unter Nutzung von Tools wie Markdown- und API-Dokumentationsgeneratoren.","pt":"Habilita os agentes a pesquisar o GitHub por projetos de qualidade, compreendê-los profundamente e criar habilidades com base nesse conhecimento, utilizando ferramentas como markdown e geradores de documentação de API.","ru":"Наделяет агентов возможностью искать в GitHub качественные проекты, глубоко понимать их и создавать навыки на основе этих знаний, используя инструменты seperti markdown и генераторы документации API.","ar":"يمنح الوكلاء القدرة على البحث في GitHub عن مشاريع جيدة، وفهمها بعمق، وإنشاء مهارات على أساس هذه المعرفة، باستخدام أدوات مثل markdown وأدوات إنشاء توثيق واجهة برمجة التطبيقات."},"useCases":{"en":["Automating project research on GitHub","Generating API documentation from open-source code","Converting markdown to PDF for reporting"],"zh":["自动化GitHub上的项目研究","从开源代码生成API文档","将markdown转换为PDF用于报告"],"ja":["GitHubでのプロジェクト研究の自動化","オープンソースコードからAPIドキュメントを生成","マークダウンをPDFに変換して報告する"],"ko":["GitHub上的 프로젝트 연구 자동화","오픈소스 코드에서 API 문서 생성","마크다운을 PDF로 변환하여 보고서 작성"],"es":["Automatización de la investigación de proyectos en GitHub","Generación de documentación de API a partir de código de código abierto","Conversión de markdown a PDF para informes"],"fr":["Automatisation de la recherche de projets sur GitHub","Génération de documentation d''API à partir de code open source","Conversion de markdown en PDF pour les rapports"],"de":["Automatisierung der Projektforschung auf GitHub","Generierung von API-Dokumentation aus Open-Source-Code","Umwandlung von Markdown in PDF für Berichte"],"pt":["Automatizar a pesquisa de projetos no GitHub","Gerar documentação de API a partir de código de código aberto","Converter markdown para PDF para relatórios"],"ru":["Автоматизация研究а проектов на GitHub","Генерация документации API из открытого исходного кода","Преобразование markdown в PDF для отчетов"],"ar":["أتمتة البحث عن المشاريع على GitHub","إنشاء توثيق واجهة برمجة التطبيقات من الشفرة المفتوحة المصدر","تحويل markdown إلى PDF لتقارير"]},"limitations":{"en":["Requires GitHub access","Dependent on quality of GitHub projects found"],"zh":["需要GitHub访问权限","依赖于找到的GitHub项目的质量"],"ja":["GitHubへのアクセスが必要","見つかったGitHubプロジェクトの品質に依存する"],"ko":["GitHub 접근 권한 필요","발견된 GitHub 프로젝트의 품질에 의존함"],"es":["Requiere acceso a GitHub","Dependiente de la calidad de los proyectos de GitHub encontrados"],"fr":["Nécessite un accès à GitHub","Dépend de la qualité des projets GitHub trouvés"],"de":["Benötigt Zugriff auf GitHub","Abhängig von der Qualität der gefundenen GitHub-Projekte"],"pt":["Requer acesso ao GitHub","Dependente da qualidade dos projetos do GitHub encontrados"],"ru":["Требуется доступ к GitHub","Зависит от качества проектов GitHub, найденных"],"ar":["يتطلب الوصول إلى GitHub","يعتمد على جودة مشاريع GitHub التي تم العثور عليها"]},"version":3},"contentHash":"3a5c1312f05fdf3e74e9edc2759cfb2ac7ecf61ce01b7ebe687853c1cf8ed156","qualityScore":65}');
