INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('regenrek/agent-skills/shadcn-vite-iconify-landing-page', 'shadcn-vite-iconify-landing-page', 'regenrek', 'agent-skills', 'community', 'shadcn-vite-iconify-landing-page regenrek agent-skills community Shadcn Vite Iconify, 5 Shadcn Vite Iconify, 5 Shadcn Vite Iconify, 5 Shadcn + Vite ofrece una forma efectiva de crear páginas de destino que convierten, con Iconify para una experiencia de usuario mejorada Shadcn + Vite propose une façon efficace de créer des pages de destination qui convertissent, avec Iconify pour une expérience utilisateur améliorée Shadcn + Vite bietet eine effektive Möglichkeit, konvertierende Landingpages zu erstellen, mit Iconify für eine verbesserte Benutzererfahrung O Shadcn + Vite é uma combinação poderosa para criar páginas de destino que convertem. Aprenda a criar uma experiência de usuário atraente e funcional. Shadcn + Vite - это мощная комбинация для создания страниц приземления, которые конвертируют. Узнайте, как создать привлекательный и функциональный опыт пользователя. Shadcn + Vite هو مزيج قوي لإنشاء صفحات هبوط تتحول. تعلم كيفية إنشاء تجربة مستخدم جذابة و وظيفية. A curated collection of my agent-skills Shadcn Vite Iconify Vite Shadcn Tailwind SEO A curated collection of my agent-skills');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('aiskillstore/marketplace/zimage-skill', 'community', 'aiskillstore', 'marketplace', 'aiskillstore/marketplace', 'zimage-skill', 0, 0, 65, '2026-02-20T04:13:19.574Z', '2026-02-20T04:33:57.093Z', 'bb701b20b8e5a0044cdfe4ae3c35e7fb22e01941abcc5fdb699585ebab01528c', '{"id":"aiskillstore/marketplace/zimage-skill","name":"zimage-skill","description":{"zh":"Z-Image 技术是使用 ModelScope 的 Tongyi-MAI/Z-Image-Turbo 模型生成图像的技能","ja":"Z-Image スキルは、ModelScope の Tongyi-MAI/Z-Image-Turbo モデルを使用して画像を生成する技術です","ko":"Z-Image 기술은 ModelScope의 Tongyi-MAI/Z-Image-Turbo 모델을 사용하여 이미지 생성을 수행하는 스킬입니다","es":"Z-Image es una habilidad de seguridad auditada que permite generar imágenes utilizando el modelo Tongyi-MAI/Z-Image-Turbo de ModelScope","fr":"Z-Image est une compétence de sécurité auditée qui permet de générer des images en utilisant le modèle Tongyi-MAI/Z-Image-Turbo de ModelScope","de":"Z-Image ist eine sicherheitsgeprüfte Fähigkeit, die die Generierung von Bildern mithilfe des Tongyi-MAI/Z-Image-Turbo-Modells von ModelScope ermöglicht","pt":"A habilidade zimage-skill gera imagens usando o modelo Tongyi-MAI/Z-Image-Turbo. É fácil de instalar e usar.","ru":"Навык zimage-skill генерирует изображения с помощью модели Tongyi-MAI/Z-Image-Turbo. Легко устанавливать и использовать.","ar":"المهارة zimage-skill تولد صورًا باستخدام نموذج Tongyi-MAI/Z-Image-Turbo. من السهل تثبيتها واستخدامها.","en":"Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified."},"seo":{"title":{"zh":"Z-Image 技术：一键生成安全审计图像","ja":"Z-Image スキル：セキュリティ監査済みの画像生成","ko":"Z-Image 기술: 하나의 클릭으로 안전한 이미지 생성","es":"Generación de Imágenes con Z-Image","fr":"Génération d''Images avec Z-Image","de":"Bildgenerierung mit Z-Image","pt":"Geração de Imagens Z-Image - Desenvolvedores","ru":"Згенерировать изображения Z-Image - Разработчики","ar":"تول