INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sickn33/antigravity-awesome-skills/cpp-pro', 'cpp-pro', 'sickn33', 'antigravity-awesome-skills', 'community', 'cpp-pro sickn33 antigravity-awesome-skills community Cpp Pro 技术技能是高性能 AI 代理的终极集合，提供最佳实践和检查清单 Cpp Pro 技術スキルは、高パフォーマンス AI エージェントのための究極のコレクションであり、ベストプラクティスとチェックリストを提供する Cpp Pro 기술 스킬은 고성능 AI 에이전트를 위한 궁극의 모음으로, 베스트 프랙티스와 체크리스트를 제공한다 La colección de habilidades de C++ Pro ofrece una amplia gama de skills de alto rendimiento para desarrolladores de C++ La collection de compétences C++ Pro propose une large gamme de skills haute performance pour les développeurs C++ Die Sammlung von C++-Pro-Fähigkeiten bietet eine breite Palette von Hochleistungs-Skills für C++-Entwickler A Cpp Pro é uma coleção de habilidades de agente para desenvolvedores, com recursos para tarefas e fluxos de trabalho relacionados a Cpp. Cpp Pro — коллекция навыков агента для разработчиков, с ресурсами для задач и рабочих процессов, связанных с Cpp. Cpp Pro هي مجموعة مهارات الوكيل للمطورين، مع موارد لعمليات و مهام متعلقة بـ Cpp. The Ultimate Collection of 800+ Agentic Skills for Claude Code/Antigravity/Cursor. Battle-tested, high-performance skills for AI agents including official skills from Anthropic and Vercel. Cpp Pro AI 代理 高性能开发 最佳实践 检查清单 技术技能 开发效率 The Ultimate Collection of 800+ Agentic Skills for Claude Code/Antigravity/Cursor. Battle-tested, high-performance skills for AI agents including official skills from Anthropic and Vercel.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jeremylongshore/claude-code-plugins-plus-skills/cron-job-scheduler', 'community', 'jeremylongshore', 'claude-code-plugins-plus-skills', 'jeremylongshore/claude-code-plugins-plus-skills', 'cron-job-scheduler', 0, 0, 65, '2026-02-20T04:13:19.577Z', '2026-02-20T04:45:12.074Z', 'ef93a1f48f1c3e64e62461bebb5d33c2b9053cc8c7057baacb17dbef0c9a6551', '{"id":"jeremylongshore/claude-code-plugins-plus-skills/cron-job-scheduler","name":"cron-job-scheduler","description":{"zh":"Cron Job 调度器提供自动化任务调度和 Backend 开发优化方案，支持 Node.js、Python、Go 等语言","ja":"Cron Job スケジューラーは自動化タスクスケジュールと Backend 開発の最適化ソリューションを提供し、Node.js、Python、Go などをサポート","ko":"Cron Job 스케줄러는 자동화 태스크 스케줄링과 Backend 개발 최적화를 위한 솔루션을 제공하며 Node.js, Python, Go 등을 지원","es":"Este skill proporciona asistencia automática para tareas de programación de cron job en el dominio de desarrollo backend.","fr":"Ce skill fournit une assistance automatisée pour les tâches de planification de tâches cron job dans le domaine du développement backend.","de":"Dieses Skill bietet automatisierte Unterstützung für Aufgaben zur Planung von Cron Jobs im Bereich der Backend-Entwicklung.","pt":"O agendador de tarefas Cron Job fornece assistência automatizada para tarefas de agendamento de tarefas no domínio do desenvolvimento de backend.","ru":"Планировщик заданий Cron Job предоставляет автоматизированную помощь для заданий планирования заданий в области разработки бэкенда.","ar":"مجدول المهام Cron Job يوفر مساعدة آلية لمهام جدولة المهام في مجال تطوير الباك اند.","en":"270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0"},"seo":{"title":{"zh":"Cron Job 调度器 - 自动化任务调度","ja":"Cron Job スケジューラー - 自動化タスクスケジュール","ko":"Cron Job 스케줄러 - 자동화 태스크 스케줄링","es":"Programador de Tareas Cron Job","fr":"Pl