INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeremylongshore/claude-code-plugins-plus-skills/cron-job-scheduler', 'cron-job-scheduler', 'jeremylongshore', 'claude-code-plugins-plus-skills', 'community', 'cron-job-scheduler jeremylongshore claude-code-plugins-plus-skills community Cron Job 调度器提供自动化任务调度和 Backend 开发优化方案，支持 Node.js、Python、Go 等语言 Cron Job スケジューラーは自動化タスクスケジュールと Backend 開発の最適化ソリューションを提供し、Node.js、Python、Go などをサポート Cron Job 스케줄러는 자동화 태스크 스케줄링과 Backend 개발 최적화를 위한 솔루션을 제공하며 Node.js, Python, Go 등을 지원 Este skill proporciona asistencia automática para tareas de programación de cron job en el dominio de desarrollo backend. Ce skill fournit une assistance automatisée pour les tâches de planification de tâches cron job dans le domaine du développement backend. Dieses Skill bietet automatisierte Unterstützung für Aufgaben zur Planung von Cron Jobs im Bereich der Backend-Entwicklung. O agendador de tarefas Cron Job fornece assistência automatizada para tarefas de agendamento de tarefas no domínio do desenvolvimento de backend. Планировщик заданий Cron Job предоставляет автоматизированную помощь для заданий планирования заданий в области разработки бэкенда. مجدول المهام Cron Job يوفر مساعدة آلية لمهام جدولة المهام في مجال تطوير الباك اند. 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0 Cron Job 调度器 自动化任务调度 Backend 开发 Node.js Python Go 数据库设计 缓存 消息队列 微服务架构 270+ Claude Code plugins with 739 agent skills. Production orchestration patterns, interactive tutorials (11 Jupyter notebooks), and CCPI package manager. 4.13.0');
